    #[test]
    fn cooperative_poll_runs_in_a_pure_ir_method() {
        use std::sync::atomic::{AtomicUsize, Ordering};

        static FLAG: u8 = 1;
        static HITS: AtomicUsize = AtomicUsize::new(0);
        // The real helper's shape: a verdict of 0 keeps the body running.
        extern "C" fn slow_poll(_flag_addr: i64, _body_id: i64) -> i64 {
            HITS.fetch_add(1, Ordering::SeqCst);
            0
        }

        let code = [0x04, 0xac]; // iconst_1; ireturn
        let builder = IrBuilder::new(0, 0);
        let graph = builder.build(&code, code.len()).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
        helpers.safepoint_slow_path = slow_poll as *const () as usize;
        HITS.store(0, Ordering::SeqCst);
        let compiled =
            lower(&graph, &schedule, 0, 0, &helpers).expect("pure IR method should lower");

        // SAFETY: the generated function has no arguments and returns int 1.
        assert_eq!(unsafe { compiled.try_call(&[]) }, Ok(1));
        assert_eq!(HITS.load(Ordering::SeqCst), 1);
    }

    /// Round 9 (irlower): a loop latch whose back edge carries phi copies and
    /// whose exit edge carries none lowers through the one-sided arm of
    /// `lower_terminator` — the Jcc names the copy-free exit directly and the
    /// copies run on straight-line code after it. Executed, not byte-matched:
    /// the risk in that arm is sending an outcome down the wrong edge, and only
    /// running the loop shows that. Both an unoptimized and an optimized graph
    /// are driven, so the fused-compare (`cc`) and boolean (`TEST`) shapes are
    /// both likely to be reached.
    #[test]
    fn do_while_latch_with_one_sided_phi_copies_runs_correctly() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        // static int f(int n) { int s = 0, i = 0; do { s += i; i++; } while (i < n); return s; }
        let code: [u8; 18] = [
            0x03, // 0: iconst_0
            0x3c, // 1: istore_1
            0x03, // 2: iconst_0
            0x3d, // 3: istore_2
            0x1b, // 4: iload_1
            0x1c, // 5: iload_2
            0x60, // 6: iadd
            0x3c, // 7: istore_1
            0x84, 0x02, 0x01, // 8: iinc 2, 1
            0x1c, // 11: iload_2
            0x1a, // 12: iload_0
            0xa1, 0xff, 0xf7, // 13: if_icmplt -9 (-> 4)
            0x1b, // 16: iload_1
            0xac, // 17: ireturn
        ];
        for optimize in [false, true] {
            let builder = IrBuilder::new(1, 3);
            let mut graph = builder.build(&code, code.len()).expect("IR build");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
            helpers.safepoint_slow_path = slow_poll as *const () as usize;
            let compiled = lower(&graph, &schedule, 1, 3, &helpers)
                .unwrap_or_else(|| panic!("do-while loop must lower (optimize={optimize})"));
            for (n, want) in [(0i64, 0i32), (1, 0), (2, 1), (5, 10), (100, 4950)] {
                // SAFETY: the lowered body takes one int argument and returns an
                // int; the poll flag is a static zero, so the slow path never runs.
                let got = unsafe { compiled.try_call(&[n]) }.expect("call");
                // Cast: this tier's `int` result is the low 32 bits of RAX.
                assert_eq!(got as i32, want, "f({n}) with optimize={optimize}");
            }
        }
    }

    // ── Round 9 wave 2 (irlower2) ─────────────────────────────────────

    /// Compile `code` (one `int` or `long` parameter) through the IR tier and
    /// call it with each input. `optimize` runs the full scalar pipeline, which
    /// is what folds the builder's `Guard(Cmp(Ne)[c, 0])` for a constant
    /// divisor away and leaves the lowering's own guards to decide.
    fn r9w2_compile_one_arg(code: &[u8], long_param: bool, optimize: bool) -> CompiledMethod {
        let (params, locals) = if long_param { (1, 2) } else { (1, 1) };
        let mut builder = IrBuilder::new(params, locals);
        if long_param {
            builder.set_param_types(&[IrType::Long]);
        }
        let mut graph = builder.build(code, code.len()).expect("IR build");
        if optimize {
            ir_optimize::optimize(&mut graph);
        }
        let schedule = ir_schedule::schedule(&graph);
        lower(&graph, &schedule, params, locals, &no_helpers())
            .unwrap_or_else(|| panic!("must lower (optimize={optimize})"))
    }

    /// Round 9 wave 2 (iropt X1/X2, isel #2): a division by a non-zero
    /// constant emits no zero test and no deopt point, a constant other than
    /// -1 skips the overflow guard, and the variable-divisor guard now tests
    /// the DIVISOR alone (`CMP ECX,-1; JNE; NEG/XOR`). Executed against Java's
    /// own semantics for every divisor class, `MIN / -1` included.
    #[test]
    fn r9w2_divisions_match_java_semantics_for_every_divisor_class() {
        let xs: [i32; 8] = [i32::MIN, i32::MIN + 1, -11, -1, 0, 9, 123_456, i32::MAX];
        // iload_0 ; bipush c ; idiv|irem ; ireturn
        for c in [7i8, 10, -1, -7, 3] {
            for (op, is_rem) in [(0x6cu8, false), (0x70u8, true)] {
                // Cast: the bipush operand byte.
                let code = [0x1a, 0x10, c as u8, op, 0xac];
                for optimize in [false, true] {
                    let cm = r9w2_compile_one_arg(&code, false, optimize);
                    for &x in &xs {
                        let want = if is_rem {
                            x.wrapping_rem(i32::from(c))
                        } else {
                            x.wrapping_div(i32::from(c))
                        };
                        // SAFETY: an `int f(int)` body compiled by this test,
                        // with the no-helper table; no path reaches a helper
                        // (the divisor is a non-zero constant).
                        let got = unsafe { cm.try_call(&[i64::from(x)]) }.expect("call");
                        // Cast: this tier's `int` result is the low 32 bits.
                        assert_eq!(
                            got as i32,
                            want,
                            "{x} {} {c} (optimize={optimize})",
                            if is_rem { "%" } else { "/" }
                        );
                    }
                    if optimize {
                        assert!(
                            !cm._deopt_point_boxes
                                .iter()
                                .any(|p| p.reason == DeoptReason::DivByZero),
                            "a constant divisor {c} must not plant a DivByZero deopt"
                        );
                    }
                }
            }
        }
        // long: lload_0 ; bipush c ; i2l ; ldiv|lrem ; lreturn
        let ls: [i64; 6] = [i64::MIN, -11, -1, 0, 0x1_0000_0007, i64::MAX];
        for c in [7i8, -1, -3] {
            for (op, is_rem) in [(0x6du8, false), (0x71u8, true)] {
                // Cast: the bipush operand byte.
                let code = [0x1e, 0x10, c as u8, 0x85, op, 0xad];
                for optimize in [false, true] {
                    let cm = r9w2_compile_one_arg(&code, true, optimize);
                    for &x in &ls {
                        let want = if is_rem {
                            x.wrapping_rem(i64::from(c))
                        } else {
                            x.wrapping_div(i64::from(c))
                        };
                        // SAFETY: as above, a `long f(long)` body.
                        let got = unsafe { cm.try_call(&[x]) }.expect("call");
                        assert_eq!(got, want, "{x}L op {c}L (optimize={optimize})");
                    }
                }
            }
        }
        // A VARIABLE divisor keeps its guards: int f(int a, int b) { return a / b; }
        // and a % b, over the MIN/-1 corner and ordinary pairs (no zero: that
        // deopts, which `test_lower_div_by_zero_deopts` covers).
        for (op, is_rem) in [(0x6cu8, false), (0x70u8, true)] {
            let code = [0x1a, 0x1b, op, 0xac, 0, 0];
            let cm = compile_via_ir(&code, 4, 2, 2).expect("a / b compiles via IR");
            for (a, b) in [
                (i32::MIN, -1),
                (7, -1),
                (-7, 2),
                (i32::MAX, -1),
                (-9, 4),
                (0, -1),
            ] {
                let want = if is_rem {
                    a.wrapping_rem(b)
                } else {
                    a.wrapping_div(b)
                };
                // SAFETY: an `int f(int, int)` body with a non-zero divisor.
                let got = unsafe { cm.try_call(&[i64::from(a), i64::from(b)]) }.expect("call");
                // Cast: this tier's `int` result is the low 32 bits.
                assert_eq!(got as i32, want, "{a} op {b}");
            }
        }
    }

    /// X2's prediction half: a graph whose only possible trap was a division
    /// by a non-zero constant is trap-free; a zero or variable divisor is not.
    #[test]
    fn r9w2_a_division_by_a_nonzero_constant_cannot_deopt() {
        let build = |divisor: Option<i64>| {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            g.entry = start;
            let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let a = g.add(Op::Param(0), IrType::Int, vec![start], None);
            let d = match divisor {
                Some(c) => g.add(Op::Const(c), IrType::Int, vec![], None),
                None => g.add(Op::Param(1), IrType::Int, vec![start], None),
            };
            let q = g.add(Op::Div, IrType::Int, vec![a, d], Some(2));
            g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, q], Some(3));
            g
        };
        assert!(graph_cannot_deopt(&build(Some(10))));
        assert!(
            graph_cannot_deopt(&build(Some(-1))),
            "MIN/-1 is inline, not a trap"
        );
        // `1 << 32` is ZERO at int width: the low 32 bits are what IDIV ECX sees.
        assert!(!graph_cannot_deopt(&build(Some(1i64 << 32))));
        assert!(!graph_cannot_deopt(&build(Some(0))));
        assert!(!graph_cannot_deopt(&build(None)));
    }

    // ── Round 9 wave 3 (irlower3) ─────────────────────────────────────

    /// `signed_div_magic` against its own contract, in exact `i128`
    /// arithmetic: `m < 2^width`, and for every sampled `n`,
    /// `floor(n * m / 2^(width + s)) + (n < 0)` is Rust's truncating `n / a`.
    /// Covers every `2^k ± 1`, the width's `MAX`, and the divisors the
    /// benchmarks use.
    #[test]
    fn r9w3_signed_div_magic_matches_brute_force() {
        for width in [32u32, 64] {
            let max: i128 = (1i128 << (width - 1)) - 1;
            let min: i128 = -(1i128 << (width - 1));
            let mut divisors: Vec<u64> = vec![
                3,
                5,
                6,
                7,
                9,
                10,
                11,
                12,
                13,
                25,
                100,
                125,
                641,
                1000,
                1_000_000_007,
            ];
            for k in 2..(width - 1) {
                divisors.push((1u64 << k) + 1);
                divisors.push((1u64 << k) - 1);
            }
            // Cast: MAX of the width, positive, fits u64.
            divisors.push(max as u64);
            if width == 64 {
                divisors.extend([
                    274_177u64,
                    6_700_417,
                    10_000_000_019,
                    1_000_000_000_000_000_003,
                ]);
            }
            let mut dividends: Vec<i128> = vec![
                min,
                min + 1,
                -1_000_000,
                -7,
                -1,
                0,
                1,
                7,
                1_000_000,
                max - 1,
                max,
            ];
            let mut x: u64 = 0x9E37_79B9_7F4A_7C15;
            for _ in 0..64 {
                x ^= x << 13;
                x ^= x >> 7;
                x ^= x << 17;
                let v = if width == 32 {
                    // Cast: the low 32 bits, as a signed int.
                    i128::from(x as u32 as i32)
                } else {
                    // Cast: the bit pattern, as a signed long.
                    i128::from(x as i64)
                };
                dividends.push(v);
            }
            for &a in &divisors {
                if a < 3 || a.is_power_of_two() {
                    continue;
                }
                let (m, s) = signed_div_magic(a, width);
                assert!(
                    width == 64 || m < (1u64 << 32),
                    "magic for {a} at width {width} is {m:#x}, not below 2^{width}"
                );
                let m = i128::from(m);
                let ai = i128::from(a);
                let check = |n: i128| {
                    let q = ((n * m) >> (width + s)) + i128::from(n < 0);
                    assert_eq!(q, n / ai, "{n} / {a} at width {width} (m={m:#x}, s={s})");
                };
                for &n in &dividends {
                    check(n);
                }
                // The divisor's own multiples, where an off-by-one magic shows.
                for mult in [1i128, 2, 3] {
                    for n in [ai * mult, ai * mult - 1, -(ai * mult), -(ai * mult) + 1] {
                        if n >= min && n <= max {
                            check(n);
                        }
                    }
                }
            }
        }
    }

    /// `f(x) = x / d` or `x % d` over a hand-built graph: `Param(0)` of the
    /// given width, a constant divisor, one division, one return.
    fn r9w3_const_div_method(long: bool, d: i64, is_rem: bool) -> CompiledMethod {
        let ty = if long { IrType::Long } else { IrType::Int };
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let x = g.add(Op::Param(0), ty, vec![start], None);
        let c = g.add(Op::Const(d), ty, vec![], None);
        let op = if is_rem { Op::Rem } else { Op::Div };
        let r = g.add(op, ty, vec![x, c], Some(2));
        g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, r], Some(3));
        let schedule = ir_schedule::schedule(&g);
        let locals = if long { 2 } else { 1 };
        lower(&g, &schedule, 1, locals, &no_helpers()).unwrap_or_else(|| {
            panic!(
                "x {} {d} must lower (long={long})",
                if is_rem { "%" } else { "/" }
            )
        })
    }

    /// Round 9 wave 3 (irlower3), item 4 of
    /// `ir-constant-divisor-still-pays-the-zero-and-overflow-tests`: a
    /// division or remainder by a constant is shifts / multiply-high, and it
    /// is EXECUTED here against Rust's wrapping (= Java's) semantics for every
    /// divisor class -- ±1, ±2^k up to the width's top power, `MIN` (which
    /// keeps the `IDIV`), `MAX`, `MIN + 1`, magic numbers that wrap negative
    /// as a signed 64-bit multiplier and ones that do not, and 64-bit
    /// divisors past `i32` -- over dividends including `MIN`, `MAX`, `-1`, `0`
    /// and the divisor's own neighbourhood.
    #[test]
    fn r9w3_constant_divisions_execute_with_java_semantics() {
        let sym = |is_rem: bool| if is_rem { "%" } else { "/" };
        let mut ints: Vec<i32> = vec![
            3,
            -3,
            5,
            6,
            7,
            -7,
            9,
            10,
            -10,
            11,
            12,
            13,
            25,
            100,
            125,
            641,
            1000,
            65_535,
            1_000_000_007,
            -1_000_000_007,
            i32::MAX,
            i32::MIN + 1,
            i32::MIN,
            0x7FFF_FFFE,
        ];
        for k in 0..31 {
            ints.push(1 << k);
            ints.push(-(1 << k));
        }
        let mut int_xs: Vec<i32> = vec![
            i32::MIN,
            i32::MIN + 1,
            i32::MIN + 7,
            -(1 << 30),
            -1_000_000_007,
            -65_537,
            -100,
            -11,
            -8,
            -7,
            -2,
            -1,
            0,
            1,
            2,
            7,
            8,
            9,
            100,
            65_535,
            123_456_789,
            i32::MAX - 1,
            i32::MAX,
        ];
        let mut x: u32 = 0x2545_F491;
        for _ in 0..24 {
            x ^= x << 13;
            x ^= x >> 17;
            x ^= x << 5;
            // Cast: a pseudo-random bit pattern, as a signed int.
            int_xs.push(x as i32);
        }
        for &d in &ints {
            for is_rem in [false, true] {
                let cm = r9w3_const_div_method(false, i64::from(d), is_rem);
                if d != i32::MIN && ir_const_div_enabled() {
                    // CDQ ; IDIV ECX -- gone for every reducible divisor.
                    assert!(
                        !contains_seq(cm.code_bytes(), &[0x99, 0xF7, 0xF9]),
                        "int x {} {d} still emits IDIV",
                        sym(is_rem)
                    );
                }
                let mut probe = int_xs.clone();
                probe.extend([d, d.wrapping_add(1), d.wrapping_sub(1), d.wrapping_neg()]);
                probe.extend([d.wrapping_mul(3), d.wrapping_mul(3).wrapping_add(1)]);
                for &n in &probe {
                    let want = if is_rem {
                        n.wrapping_rem(d)
                    } else {
                        n.wrapping_div(d)
                    };
                    // SAFETY: an `int f(int)` body with no call and no deopt
                    // point (the divisor is a non-zero constant).
                    let got = unsafe { cm.try_call(&[i64::from(n)]) }.expect("call");
                    // Cast: this tier's `int` result is the low 32 bits.
                    assert_eq!(got as i32, want, "int {n} {} {d}", sym(is_rem));
                }
            }
        }

        let mut longs: Vec<i64> = vec![
            3,
            -3,
            5,
            6,
            7,
            -7,
            10,
            -10,
            11,
            13,
            25,
            100,
            641,
            1000,
            274_177,
            6_700_417,
            1_000_000_007,
            0x7FFF_FFFF,
            0x8000_0001,
            0xFFFF_FFFF,
            0x1_0000_0001,
            10_000_000_000,
            1_000_000_000_000_000_003,
            -10_000_000_019,
            i64::MAX,
            i64::MIN + 1,
            i64::MIN,
        ];
        for k in 0..63 {
            longs.push(1i64 << k);
            longs.push(-(1i64 << k));
        }
        let mut long_xs: Vec<i64> = vec![
            i64::MIN,
            i64::MIN + 1,
            i64::MIN + 7,
            -(1i64 << 62),
            -(1i64 << 32) - 1,
            -100,
            -8,
            -7,
            -1,
            0,
            1,
            7,
            8,
            1i64 << 31,
            (1i64 << 32) + 5,
            1_000_000_000_000,
            i64::MAX - 1,
            i64::MAX,
            i64::from(i32::MIN),
            i64::from(i32::MAX),
        ];
        let mut y: u64 = 0x9E37_79B9_7F4A_7C15;
        for _ in 0..24 {
            y ^= y << 13;
            y ^= y >> 7;
            y ^= y << 17;
            // Cast: a pseudo-random bit pattern, as a signed long.
            long_xs.push(y as i64);
        }
        for &d in &longs {
            for is_rem in [false, true] {
                let cm = r9w3_const_div_method(true, d, is_rem);
                if d != i64::MIN && ir_const_div_enabled() {
                    // CQO ; IDIV RCX
                    assert!(
                        !contains_seq(cm.code_bytes(), &[0x48, 0x99, 0x48, 0xF7, 0xF9]),
                        "long x {} {d} still emits IDIV",
                        sym(is_rem)
                    );
                }
                let mut probe = long_xs.clone();
                probe.extend([d, d.wrapping_add(1), d.wrapping_sub(1), d.wrapping_neg()]);
                probe.extend([d.wrapping_mul(3), d.wrapping_mul(3).wrapping_sub(1)]);
                for &n in &probe {
                    let want = if is_rem {
                        n.wrapping_rem(d)
                    } else {
                        n.wrapping_div(d)
                    };
                    // SAFETY: a `long f(long)` body with no call and no deopt
                    // point (the divisor is a non-zero constant).
                    let got = unsafe { cm.try_call(&[n]) }.expect("call");
                    assert_eq!(got, want, "long {n} {} {d}", sym(is_rem));
                }
            }
        }
    }

    /// The `CratonBench arithmetic` / `ArithProbe` kernel, through the IR
    /// tier with and without the scalar pipeline, EXECUTED:
    ///
    /// ```java
    /// static long f(long n) { long s = 0; for (long i = 0; i < n; i++) s += i*3 - i/2 + i%7; return s; }
    /// ```
    ///
    /// Optimized, the divisors fold to constants, so the body must hold no
    /// `IDIV` at all -- the 2x regression wave 2 introduced was exactly this
    /// loop paying two `IDIV r64` per iteration in the optimizing OSR body.
    #[test]
    fn r9w3_the_arithmetic_kernel_runs_without_idiv() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        let code: [u8; 44] = [
            0x09, // 0: lconst_0
            0x41, // 1: lstore_2         s = 0
            0x09, // 2: lconst_0
            0x37, 0x04, // 3: lstore 4   i = 0
            0x16, 0x04, // 5: lload 4    <- loop header
            0x1e, // 7: lload_0
            0x94, // 8: lcmp
            0x9c, 0x00, 0x21, // 9: ifge +33 -> 42
            0x20, // 12: lload_2
            0x16, 0x04, // 13: lload 4
            0x06, // 15: iconst_3
            0x85, // 16: i2l
            0x69, // 17: lmul
            0x16, 0x04, // 18: lload 4
            0x05, // 20: iconst_2
            0x85, // 21: i2l
            0x6d, // 22: ldiv
            0x65, // 23: lsub
            0x16, 0x04, // 24: lload 4
            0x10, 0x07, // 26: bipush 7
            0x85, // 28: i2l
            0x71, // 29: lrem
            0x61, // 30: ladd
            0x61, // 31: ladd
            0x41, // 32: lstore_2
            0x16, 0x04, // 33: lload 4
            0x0a, // 35: lconst_1
            0x61, // 36: ladd
            0x37, 0x04, // 37: lstore 4
            0xa7, 0xff, 0xde, // 39: goto -34 -> 5
            0x20, // 42: lload_2
            0xad, // 43: lreturn
        ];
        for optimize in [false, true] {
            let mut builder = IrBuilder::new(1, 6);
            builder.set_param_types(&[IrType::Long]);
            let mut graph = builder.build(&code, code.len()).expect("IR build");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
            helpers.safepoint_slow_path = slow_poll as *const () as usize;
            let cm = lower(&graph, &schedule, 1, 6, &helpers)
                .unwrap_or_else(|| panic!("the kernel must lower (optimize={optimize})"));
            if optimize && ir_const_div_enabled() {
                assert!(
                    !contains_seq(cm.code_bytes(), &[0x48, 0x99, 0x48, 0xF7, 0xF9]),
                    "the optimized kernel still divides with IDIV"
                );
            }
            for n in [0i64, 1, 2, 7, 13, 1000, 100_003] {
                let mut want = 0i64;
                for i in 0..n {
                    want = want.wrapping_add(i.wrapping_mul(3) - i / 2 + i % 7);
                }
                // SAFETY: a `long f(long)` body; the poll flag is a static
                // zero, so the slow path never runs, and no path reaches a
                // helper or a deopt (the only divisors are non-zero).
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                assert_eq!(got, want, "f({n}) with optimize={optimize}");
            }
        }
    }

    /// Round 9 wave 3 (irlower3), the IR half of
    /// `perf-long-counted-loops-lose-the-optimizing-osr-body`: `lcmp; if<cc>`
    /// is ONE `CMP r64, r64; Jcc` -- the `lcmp` arm emits no
    /// `SETG/SETL/MOVZX/SUB/MOVSXD` and writes no home word. Executed for all
    /// six conditions over pairs that differ only in the high word, only in
    /// the low word, and at `MIN`/`MAX` (where `a - b` overflows, which is why
    /// the compare has to be the flags of `CMP`, never of a subtraction).
    #[test]
    fn r9w3_lcmp_branches_fuse_into_one_compare() {
        // long a, long b: lload_0 ; lload_2 ; lcmp ; if<cc> +5 ; iconst_1 ;
        // ireturn ; iconst_0 ; ireturn  -- 0 when the branch is taken.
        let pairs: [(i64, i64); 12] = [
            (0, 0),
            (1, 2),
            (2, 1),
            (-1, 0),
            (0, -1),
            (i64::MIN, i64::MAX),
            (i64::MAX, i64::MIN),
            (i64::MIN, i64::MIN),
            (1i64 << 32, 1),
            (1, 1i64 << 32),
            (-(1i64 << 32), 0xFFFF_FFFF),
            (0x1_0000_0005, 0x2_0000_0005),
        ];
        for op in 0x99u8..=0x9e {
            let code = [0x1e, 0x20, 0x94, op, 0x00, 0x05, 0x04, 0xac, 0x03, 0xac];
            for optimize in [false, true] {
                let mut builder = IrBuilder::new(2, 4);
                builder.set_param_types(&[IrType::Long, IrType::Long]);
                let mut graph = builder.build(&code, code.len()).expect("IR build");
                if optimize {
                    ir_optimize::optimize(&mut graph);
                }
                let schedule = ir_schedule::schedule(&graph);
                let cm = lower(&graph, &schedule, 2, 4, &no_helpers())
                    .unwrap_or_else(|| panic!("lcmp branch must lower (op={op:#x})"));
                if ir_fused_branch_enabled() && ir_register_authoritative_enabled() {
                    // SETG AL -- the `lcmp` materialisation.
                    assert!(
                        !contains_seq(cm.code_bytes(), &[0x0F, 0x9F, 0xC0]),
                        "op {op:#x} (optimize={optimize}): the lcmp was not fused into its branch"
                    );
                }
                for &(a, b) in &pairs {
                    let taken = match op {
                        0x99 => a == b,
                        0x9a => a != b,
                        0x9b => a < b,
                        0x9c => a >= b,
                        0x9d => a > b,
                        _ => a <= b,
                    };
                    // SAFETY: an `int f(long, long)` body with no call and no
                    // trap.
                    let got = unsafe { cm.try_call(&[a, b]) }.expect("call");
                    // Cast: this tier's `int` result is the low 32 bits.
                    assert_eq!(
                        got as i32,
                        i32::from(!taken),
                        "op {op:#x} a={a} b={b} (optimize={optimize})"
                    );
                }
            }
        }
    }

    /// Round 9 wave 10 (irl10): the byte encoders behind the three-operand
    /// `IMUL RAX, r, imm` and the register-register `LEA dst, [base + index]`,
    /// checked against hand-assembled bytes -- including the three silent SIB
    /// traps (R13/RBP base needs a disp8, RSP cannot be an index, R12 as an
    /// index needs REX.X).
    #[test]
    fn r9w10_irl10_three_operand_encoders() {
        let lea = |d: u8, b: u8, i: u8, w: bool| {
            let (bytes, n) = lea_reg_base_index_bytes(d, b, i, w);
            bytes[..n].to_vec()
        };
        // lea rax,[r14+rcx]
        assert_eq!(lea(RAX, 14, RCX, true), vec![0x49, 0x8D, 0x04, 0x0E]);
        // lea r12,[r14+rcx]
        assert_eq!(lea(12, 14, RCX, true), vec![0x4D, 0x8D, 0x24, 0x0E]);
        // lea rax,[r13+rcx+0] -- R13 as a SIB base takes mod=01 and a disp8.
        assert_eq!(lea(RAX, 13, RCX, true), vec![0x49, 0x8D, 0x44, 0x0D, 0x00]);
        // lea rax,[rsp+rbx] -- an RSP index is swapped into the base.
        assert_eq!(lea(RAX, 3, 4, true), vec![0x48, 0x8D, 0x04, 0x1C]);
        // lea eax,[rbx+r12] -- R12 is a real index with REX.X.
        assert_eq!(lea(RAX, 3, 12, false), vec![0x42, 0x8D, 0x04, 0x23]);
        // lea eax,[rbx+rsi] -- no REX at all in the 32-bit form.
        assert_eq!(lea(RAX, 3, 6, false), vec![0x8D, 0x04, 0x33]);

        let imul = |s: u8, k: i32, w: bool| {
            let (bytes, n) = imul_rax_reg_imm_bytes(s, k, w);
            bytes[..n].to_vec()
        };
        // imul rax,r15,3
        assert_eq!(imul(15, 3, true), vec![0x49, 0x6B, 0xC7, 0x03]);
        // imul rax,rbx,-1
        assert_eq!(imul(3, -1, true), vec![0x48, 0x6B, 0xC3, 0xFF]);
        // imul eax,ebx,3
        assert_eq!(imul(3, 3, false), vec![0x6B, 0xC3, 0x03]);
        // imul rax,r15,1000 -- the imm32 form.
        assert_eq!(
            imul(15, 1000, true),
            vec![0x49, 0x69, 0xC7, 0xE8, 0x03, 0x00, 0x00]
        );
        // imul eax,r8d,-129
        assert_eq!(
            imul(8, -129, false),
            vec![0x41, 0x69, 0xC0, 0x7F, 0xFF, 0xFF, 0xFF]
        );
    }

    /// Round 9 wave 10 (irl10), `perf-long-counted-loops-lose-the-optimizing-osr-body`:
    /// the counted loop `s += i * 3 + (i >> 1)` -- the page's `mulOnly`
    /// shape -- EXECUTED in its `int` and `long` forms against a reference,
    /// with and without the optimizer, over trip counts 0..=1000. The `int`
    /// form must also show the three-operand `IMUL r, r/m, imm` reading the
    /// resident counter (a `6B` whose ModRM `r/m` is not RAX), i.e. the new
    /// form actually ran rather than the test comparing the old one with
    /// itself.
    #[test]
    fn r9w10_irl10_counted_loop_three_operand_forms_execute() {
        // static int f(int n) { int s = 0; for (int i = 0; i < n; i++) s += i * 3 + (i >> 1); return s; }
        let int_code = [
            0x03, 0x3C, 0x03, 0x3D, // s = 0; i = 0
            0x1C, 0x1A, 0xA2, 0x00, 0x13, // 4: iload_2; iload_0; if_icmpge 25
            0x1B, 0x1C, 0x06, 0x68, // 9: s, i*3
            0x1C, 0x04, 0x7A, // 13: i >> 1
            0x60, 0x60, 0x3C, // 16: + ; + ; istore_1
            0x84, 0x02, 0x01, // 19: iinc 2 1
            0xA7, 0xFF, 0xEE, // 22: goto 4
            0x1B, 0xAC, // 25: iload_1; ireturn
            0, 0,
        ];
        // static long g(long n) { long s = 0; for (long i = 0; i < n; i++) s += i * 3L + (i >> 1); return s; }
        // (`3L` as `iconst_3; i2l`, so the fixture needs no `ldc2_w` row.)
        let long_code = [
            0x09, 0x41, 0x09, 0x37, 0x04, // s = 0; i = 0
            0x16, 0x04, 0x1E, 0x94, 0x9C, 0x00, 0x19, // 5: i ? n; ifge 34
            0x20, 0x16, 0x04, 0x06, 0x85, 0x69, // 12: s, i * 3L
            0x16, 0x04, 0x04, 0x7B, // 18: i >> 1
            0x61, 0x61, 0x41, // 22: + ; + ; lstore_2
            0x16, 0x04, 0x0A, 0x61, 0x37, 0x04, // 25: i = i + 1
            0xA7, 0xFF, 0xE6, // 31: goto 5
            0x20, 0xAD, // 34: lload_2; lreturn
            0, 0,
        ];
        let ns: [i64; 8] = [0, 1, 2, 3, 7, 64, 101, 1000];
        for optimize in [false, true] {
            // int
            let mut graph = IrBuilder::new(1, 3)
                .build(&int_code, 27)
                .expect("int loop builds");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let cm = lower(&graph, &schedule, 1, 3, &no_helpers()).expect("int loop lowers");
            for &n in &ns {
                let mut s: i32 = 0;
                for i in 0..(n as i32) {
                    s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                }
                // SAFETY: an `int f(int)` body with no call and no trap.
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                // Cast: this tier's `int` result is the low 32 bits.
                assert_eq!(got as i32, s, "int n={n} optimize={optimize}");
            }
            if optimize && ir_alu_imm_enabled() && ir_register_authoritative_enabled() {
                let engaged = cm
                    .code_bytes()
                    .windows(3)
                    .any(|w| w[0] == 0x6B && (w[1] & 0xF8) == 0xC0 && w[1] != 0xC0 && w[2] == 3);
                assert!(
                    engaged,
                    "the resident counter's `* 3` still routes through RAX \
                     (no three-operand IMUL in the body)"
                );
            }

            // long
            let mut builder = IrBuilder::new(1, 6);
            builder.set_param_types(&[IrType::Long]);
            let mut graph = builder.build(&long_code, 36).expect("long loop builds");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let cm = lower(&graph, &schedule, 1, 6, &no_helpers()).expect("long loop lowers");
            for &n in &ns {
                let mut s: i64 = 0;
                for i in 0..n {
                    s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                }
                // SAFETY: a `long g(long)` body with no call and no trap.
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                assert_eq!(got, s, "long n={n} optimize={optimize}");
            }
        }
    }

    /// Round 9 wave 11 (irl11), `RcxTwin`: an RCX carry whose home is dropped
    /// is installed by the twin of the run that computed it (`ADD RCX, RAX`,
    /// `MOV RCX, r; SAR RCX, imm`, ...) instead of that run plus `MOV RCX,
    /// RAX`. EXECUTED against a reference, optimized and not, over trip counts
    /// 0..=1000, for the page's `long` `mulOnly` loop and for an `int` loop
    /// that puts every twinned op (`*`, `^`, `<<`, `|`, `&`, `>>>`, `+`) on a
    /// carry chain.
    ///
    /// The byte half: with the twin on (the default; the test sets no flag),
    /// the untwinned pair `ADD RAX, RCX; MOV RCX, RAX` can no longer appear
    /// ADJACENT in a body -- adjacency means `store_rax` emitted no home store,
    /// i.e. the home was dropped and the value is an RCX carry, which is
    /// exactly when `apply_rcx_twin` fires.
    #[test]
    fn r9w11_irl11_rcx_carry_twins_execute() {
        // static long g(long n) { long s = 0; for (long i = 0; i < n; i++) s += i * 3L + (i >> 1); return s; }
        let long_code = [
            0x09, 0x41, 0x09, 0x37, 0x04, // s = 0; i = 0
            0x16, 0x04, 0x1E, 0x94, 0x9C, 0x00, 0x19, // 5: i ? n; ifge 34
            0x20, 0x16, 0x04, 0x06, 0x85, 0x69, // 12: s, i * 3L
            0x16, 0x04, 0x04, 0x7B, // 18: i >> 1
            0x61, 0x61, 0x41, // 22: + ; + ; lstore_2
            0x16, 0x04, 0x0A, 0x61, 0x37, 0x04, // 25: i = i + 1
            0xA7, 0xFF, 0xE6, // 31: goto 5
            0x20, 0xAD, // 34: lload_2; lreturn
            0, 0,
        ];
        // static int h(int n) {
        //   int s = 0;
        //   for (int i = 0; i < n; i++) s += ((i * i) ^ (i << 3)) + ((i | 5) & (i >>> 2));
        //   return s;
        // }
        let int_code = [
            0x03, 0x3C, 0x03, 0x3D, // 0: s = 0; i = 0
            0x1C, 0x1A, 0xA2, 0x00, 0x1B, // 4: iload_2; iload_0; if_icmpge 33
            0x1B, // 9: s
            0x1C, 0x1C, 0x68, // 10: i * i
            0x1C, 0x06, 0x78, // 13: i << 3
            0x82, // 16: ^
            0x1C, 0x08, 0x80, // 17: i | 5
            0x1C, 0x05, 0x7C, // 20: i >>> 2
            0x7E, // 23: &
            0x60, 0x60, 0x3C, // 24: + ; + ; istore_1
            0x84, 0x02, 0x01, // 27: iinc 2 1
            0xA7, 0xFF, 0xE6, // 30: goto 4
            0x1B, 0xAC, // 33: iload_1; ireturn
            0, 0,
        ];
        let ns: [i64; 8] = [0, 1, 2, 3, 7, 64, 101, 1000];
        let untwinned_add: [u8; 6] = [0x48, 0x01, 0xC8, 0x48, 0x89, 0xC1];
        for optimize in [false, true] {
            let mut builder = IrBuilder::new(1, 6);
            builder.set_param_types(&[IrType::Long]);
            let mut graph = builder.build(&long_code, 36).expect("long loop builds");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let cm = lower(&graph, &schedule, 1, 6, &no_helpers()).expect("long loop lowers");
            for &n in &ns {
                let mut s: i64 = 0;
                for i in 0..n {
                    s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                }
                // SAFETY: a `long g(long)` body with no call and no trap.
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                assert_eq!(got, s, "long n={n} optimize={optimize}");
            }
            assert!(
                !contains_seq(cm.code_bytes(), &untwinned_add),
                "optimize={optimize}: `add rax,rcx; mov rcx,rax` survived next to each \
                 other -- an RCX carry with a dropped home that was not twinned"
            );

            let mut graph = IrBuilder::new(1, 3)
                .build(&int_code, 35)
                .expect("int loop builds");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let cm = lower(&graph, &schedule, 1, 3, &no_helpers()).expect("int loop lowers");
            for &n in &ns {
                let mut s: i32 = 0;
                for i in 0..(n as i32) {
                    let a = i.wrapping_mul(i) ^ i.wrapping_shl(3);
                    // Cast: `>>>` is a logical shift of the int's bits.
                    let b = (i | 5) & ((i as u32 >> 2) as i32);
                    s = s.wrapping_add(a.wrapping_add(b));
                }
                // SAFETY: an `int h(int)` body with no call and no trap.
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                // Cast: this tier's `int` result is the low 32 bits.
                assert_eq!(got as i32, s, "int n={n} optimize={optimize}");
            }
        }
    }

    /// Round 9 wave 10 (irl10): the register-register `LEA` form of
    /// `Op::Add` is held to the same source-level contract as
    /// `emit_add_lea`'s direct form (see
    /// `the_lea_add_form_publishes_what_it_does_not_store`): on the path that
    /// may skip the home store it publishes the register first and says so,
    /// and its accumulator form publishes nothing.
    #[test]
    fn r9w10_irl10_the_reg_reg_lea_form_publishes_what_it_does_not_store() {
        let src = include_str!("ir_lower.rs").replace("\r\n", "\n");
        let body = src
            .split("fn emit_add_lea_reg_reg(\n")
            .nth(1)
            .expect("emit_add_lea_reg_reg is in this file")
            .split("\n    fn ")
            .next()
            .expect("the function ends");
        let direct = body
            .split("if let Some(dst) = self.assigned_gpr(id) {")
            .nth(1)
            .expect("the direct form gates on an assigned register")
            .split("AddForm::Done")
            .next()
            .expect("the direct form returns AddForm::Done");
        for required in [
            "self.mark_gp_reg_live(id);",
            "self.cur_def_published = true;",
            "self.store_abi_reg(dst, slot);",
        ] {
            assert!(direct.contains(required), "direct form lacks `{required}`");
        }
        let publish = direct
            .find("self.mark_gp_reg_live(id);")
            .expect("checked above");
        let decide = direct.find("home_dropped").expect("the drop test is here");
        assert!(
            publish < decide,
            "publishes after deciding to skip the home store"
        );
        let acc = body
            .split("return AddForm::Done;")
            .nth(1)
            .expect("the direct form returns")
            .split("AddForm::InRax")
            .next()
            .expect("the accumulator form returns");
        assert!(!acc.contains("mark_gp_reg_live"));
        // Every check precedes the first emitted byte: the only emission sites
        // are the two `LEA`s, and nothing before the carry retirement emits.
        let first_emit = body.find("self.buf.emit(").expect("it emits");
        for gate in [
            "self.carry_names(x)",
            "self.resident_gpr(x)",
            "self.gp_load_value(RCX, y);",
        ] {
            let at = body
                .find(gate)
                .unwrap_or_else(|| panic!("`{gate}` is in the helper"));
            assert!(
                at < first_emit,
                "`{gate}` comes after the first emitted byte"
            );
        }
    }

    /// Round 9 wave 8 (irl8), the `FCmp` half of
    /// `perf-long-counted-loops-lose-the-optimizing-osr-body`:
    /// `fcmp<l|g>`/`dcmp<l|g>; if<lt|le|gt|ge>` is ONE `UCOMIS; Jcc` (no
    /// `SETA/SETB` materialisation), and `if<eq|ne>` keeps the three-way value.
    /// EXECUTED for all four opcodes, all six conditions, over pairs including
    /// NaN on either side, both zeros and the infinities -- the NaN answer of
    /// the `l`/`g` bias is the whole point of `fcmp_fused_branch`.
    #[test]
    fn r9w8_fcmp_branches_fuse_into_one_ucomis() {
        let vals: [f64; 8] = [
            0.0,
            -0.0,
            1.0,
            -1.0,
            1.5,
            f64::NAN,
            f64::INFINITY,
            f64::NEG_INFINITY,
        ];
        for cmp_op in [0x95u8, 0x96, 0x97, 0x98] {
            let double = cmp_op >= 0x97;
            let nan_greater = cmp_op == 0x96 || cmp_op == 0x98;
            for br in 0x99u8..=0x9e {
                // a, b: load ; load ; [fd]cmp[lg] ; if<cc> +5 ; iconst_1 ;
                // ireturn ; iconst_0 ; ireturn  -- 0 when the branch is taken.
                let (l0, l1, locals, ty) = if double {
                    (0x26u8, 0x28u8, 4usize, IrType::Double)
                } else {
                    (0x22u8, 0x23u8, 2usize, IrType::Float)
                };
                let code = [l0, l1, cmp_op, br, 0x00, 0x05, 0x04, 0xac, 0x03, 0xac];
                for optimize in [false, true] {
                    let mut builder = IrBuilder::new(2, locals);
                    builder.set_param_types(&[ty, ty]);
                    let mut graph = builder.build(&code, code.len()).expect("IR build");
                    if optimize {
                        ir_optimize::optimize(&mut graph);
                    }
                    let schedule = ir_schedule::schedule(&graph);
                    let cm =
                        lower(&graph, &schedule, 2, locals, &no_helpers()).unwrap_or_else(|| {
                            panic!("fcmp branch must lower (cmp={cmp_op:#x} br={br:#x})")
                        });
                    let ordering = !matches!(br, 0x99 | 0x9a);
                    if ordering
                        && ir_fused_branch_enabled()
                        && ir_fused_fcmp_enabled()
                        && ir_register_authoritative_enabled()
                    {
                        // SETA AL / SETB AL -- the `FCmp` materialisation.
                        let code_bytes = cm.code_bytes();
                        assert!(
                            !contains_seq(code_bytes, &[0x0F, 0x97, 0xC0])
                                && !contains_seq(code_bytes, &[0x0F, 0x92, 0xC0]),
                            "cmp {cmp_op:#x} br {br:#x} (optimize={optimize}): the fcmp \
                             was not fused into its branch"
                        );
                    }
                    for &a in &vals {
                        for &b in &vals {
                            let three_way: i32 = if a > b {
                                1
                            } else if a < b {
                                -1
                            } else if a == b {
                                0
                            } else if nan_greater {
                                1
                            } else {
                                -1
                            };
                            let taken = match br {
                                0x99 => three_way == 0,
                                0x9a => three_way != 0,
                                0x9b => three_way < 0,
                                0x9c => three_way >= 0,
                                0x9d => three_way > 0,
                                _ => three_way <= 0,
                            };
                            // Raw bits in integer ABI registers, as
                            // `Op::Param` expects; a float's bits are
                            // zero-extended (`f.to_bits() as i64`).
                            let (xa, xb) = if double {
                                (a.to_bits() as i64, b.to_bits() as i64)
                            } else {
                                // Cast: `f64 -> f32` of these values is exact
                                // (NaN stays NaN).
                                ((a as f32).to_bits() as i64, (b as f32).to_bits() as i64)
                            };
                            // SAFETY: an `int f(T, T)` body with no call and
                            // no trap.
                            let got = unsafe { cm.try_call(&[xa, xb]) }.expect("call");
                            // Cast: this tier's `int` result is the low 32 bits.
                            assert_eq!(
                                got as i32,
                                i32::from(!taken),
                                "cmp {cmp_op:#x} br {br:#x} a={a} b={b} (optimize={optimize})"
                            );
                        }
                    }
                }
            }
        }
    }

    /// The flags table itself, independent of any emission: for every
    /// ordering condition and both biases, `fcmp_fused_branch`'s Jcc over the
    /// `UCOMIS` flags of every ordered/unordered outcome agrees with the JVMS
    /// three-way result, and its `^ 1` complement is the exact negation.
    #[test]
    fn r9w8_the_fused_fcmp_flag_table_matches_the_three_way_result() {
        // (CF, ZF) of `UCOMIS p, q` for p>q, p<q, p==q, unordered.
        let flags = |gt: bool, lt: bool, eq: bool| -> (bool, bool) {
            if gt {
                (false, false)
            } else if lt {
                (true, false)
            } else if eq {
                (false, true)
            } else {
                (true, true)
            }
        };
        let taken = |jcc: u8, (cf, zf): (bool, bool)| -> bool {
            match jcc {
                0x82 => cf,
                0x83 => !cf,
                0x86 => cf || zf,
                0x87 => !cf && !zf,
                other => panic!("unexpected jcc {other:#x}"),
            }
        };
        // Outcomes of `a` vs `b` as (a>b, a<b, a==b); all false is NaN.
        let outcomes = [
            (true, false, false),
            (false, true, false),
            (false, false, true),
            (false, false, false),
        ];
        for nan_greater in [false, true] {
            for cc in [
                CmpOp::Lt,
                CmpOp::Le,
                CmpOp::Gt,
                CmpOp::Ge,
                CmpOp::Eq,
                CmpOp::Ne,
            ] {
                let Some((swap, jcc)) = fcmp_fused_branch(cc, nan_greater) else {
                    assert!(matches!(cc, CmpOp::Eq | CmpOp::Ne), "{cc:?} must fold");
                    continue;
                };
                assert_eq!(swap, nan_greater);
                for &(gt, lt, eq) in &outcomes {
                    let r: i32 = if gt {
                        1
                    } else if lt {
                        -1
                    } else if eq {
                        0
                    } else if nan_greater {
                        1
                    } else {
                        -1
                    };
                    let want = match cc {
                        CmpOp::Lt => r < 0,
                        CmpOp::Le => r <= 0,
                        CmpOp::Gt => r > 0,
                        _ => r >= 0,
                    };
                    // `UCOMIS b, a` swaps which of gt/lt the flags see.
                    let f = if swap {
                        flags(lt, gt, eq)
                    } else {
                        flags(gt, lt, eq)
                    };
                    assert_eq!(
                        taken(jcc, f),
                        want,
                        "{cc:?} ng={nan_greater} {gt}/{lt}/{eq}"
                    );
                    assert_eq!(taken(jcc ^ 1, f), !want, "negated {cc:?} ng={nan_greater}");
                }
            }
        }
    }

    /// Round 9 wave 8 (irl8), the IR half of
    /// `perf-mutual-recursion-forces-every-call-through-invoke-dispatch`: an
    /// `invokestatic` planned as a cycle-edge CELL site runs the stack-floor
    /// guard, then calls the cell's entry directly when the word is set and
    /// `jit_invoke_dispatch` when it is `0`. EXECUTED both ways on one body
    /// (the word is flipped between calls, as `JitCache::put` / `clear` do),
    /// and the no-cell control keeps plain dispatch.
    #[test]
    fn r9w8_a_cycle_edge_cell_site_calls_through_the_cell_or_dispatches() {
        crate::x64::set_moving_young_override(Some(false));
        extern "C" fn dispatch(_vm: i64, _info: i64, args: i64, _n: i64) -> i64 {
            // SAFETY: `args` is the frame's staging block; arg 0 sits at its
            // base (`args_stage_top_off`), written just before this call.
            5000 + unsafe { *(args as *const i64) }
        }
        extern "C" fn callee(_vm: i64, x: i64) -> i64 {
            7000 + x
        }
        extern "C" fn guard_ok(_vm: i64) -> i64 {
            0
        }
        // static int f(int x) { return g(x); }  iload_0 ; invokestatic #2 ; ireturn
        let code = [0x1a, 0xb8, 0x00, 0x02, 0xac, 0x00, 0x00];
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/B",
            method_name: "a",
            descriptor: "(I)I",
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: 3, // static
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let lower_with = |cells: &HashMap<usize, usize>| {
            let mut builder = IrBuilder::new(1, 1);
            builder.set_param_types(&[IrType::Int]);
            let mut invoke_info = HashMap::new();
            invoke_info.insert(
                1usize,
                (info as *const JitInvokeInfo as usize, 1usize, b'I'),
            );
            builder.set_invoke_info(invoke_info);
            let graph = builder
                .build(&code, 5)
                .expect("IR build of the static call");
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.invoke_dispatch = dispatch as *const () as usize;
            helpers.self_call_stack_guard = guard_ok as *const () as usize;
            let empty_hints: HashMap<usize, bool> = HashMap::new();
            let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
            let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
            let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
            lower_inner_with_cycle_cells(
                &crate::DirectHelperTable::EMPTY,
                &graph,
                &schedule,
                1,
                1,
                &helpers,
                &empty_hints,
                &[],
                None,
                &no_direct,
                &no_ic,
                &no_compact,
                &crate::ir::IrInlineFrameSites::default(),
                cells,
                &std::collections::HashSet::new(),
            )
            .expect("the call site lowers")
        };
        // The cell: its entry word at `JIT_CYCLE_EDGE_CELL_ENTRY_OFFSET` (0).
        let mut cell = [0u64; 4];
        let cell_addr = cell.as_mut_ptr() as usize;
        let word = cell_addr as *mut u64;

        // Control: no cell row, plain dispatch, the cell address baked nowhere.
        let plain = lower_with(&HashMap::new());
        assert!(!contains_seq(
            plain.code_bytes(),
            &(cell_addr as u64).to_le_bytes()
        ));
        // SAFETY: an `int f(int)` body whose only call is the stub above.
        let got = unsafe { plain.try_call_with_context(0, &[3]) }.expect("call");
        assert_eq!(got as i32, 5003);

        let mut cells = HashMap::new();
        cells.insert(1usize, cell_addr);
        let cm = lower_with(&cells);
        if !crate::direct_jit_callee_calls_enabled() {
            return;
        }
        assert!(
            contains_seq(cm.code_bytes(), &(cell_addr as u64).to_le_bytes()),
            "the site bakes the cell"
        );
        // Empty word: dispatch.
        // SAFETY: the stubs above; `cell` outlives every call.
        let got = unsafe { cm.try_call_with_context(0, &[4]) }.expect("call");
        assert_eq!(got as i32, 5004, "an empty cell dispatches");
        // Filled word: the direct call, context ABI.
        // SAFETY: a plain write to a live local through its own address.
        unsafe { std::ptr::write_volatile(word, callee as *const () as usize as u64) };
        // SAFETY: as above.
        let got = unsafe { cm.try_call_with_context(0, &[5]) }.expect("call");
        assert_eq!(got as i32, 7005, "a filled cell calls its entry");
        // Cleared again: dispatch again, same body.
        // SAFETY: as above.
        unsafe { std::ptr::write_volatile(word, 0) };
        // SAFETY: as above.
        let got = unsafe { cm.try_call_with_context(0, &[6]) }.expect("call");
        assert_eq!(got as i32, 5006, "a cleared cell dispatches again");
    }

    /// Round 9 wave 8 (irl8), request G of
    /// `perf-compiled-ldc-string-is-a-helper-call-per-execution`: an
    /// `Op::ConstString` / `Op::ConstClass` with a GC-maintained slot reads the
    /// slot first and calls its helper only while the slot is empty; with no
    /// slot the body is the plain helper call. EXECUTED: a filled slot answers
    /// its word without the helper, an empty one falls through to the helper's
    /// answer, and a rewritten slot (what the collector does in place) is
    /// read afresh by the same code.
    #[test]
    fn r9w8_an_ldc_with_a_constant_slot_reads_it_before_calling() {
        extern "C" fn ldc_helper(_vm: i64, _holder: i64, _cp: i64) -> i64 {
            0x7777_0000
        }
        let build = |string: bool, slot_addr: usize| {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            g.entry = start;
            let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let op = if string {
                Op::ConstString {
                    holder_class_id: 7,
                    cp_idx: 1,
                    slot_addr,
                }
            } else {
                Op::ConstClass {
                    holder_class_id: 7,
                    cp_idx: 1,
                    slot_addr,
                }
            };
            let c = g.add(op, IrType::Ref, vec![ctrl, mem], Some(0));
            g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, c], Some(2));
            g
        };
        let mut helpers = no_helpers();
        helpers.ldc_string_cp = ldc_helper as *const () as usize;
        helpers.ldc_class_cp = ldc_helper as *const () as usize;
        // MOV RAX,[RAX] ; TEST RAX,RAX ; JNZ rel32 -- the probe's tail.
        const PROBE: [u8; 8] = [0x48, 0x8B, 0x00, 0x48, 0x85, 0xC0, 0x0F, 0x85];
        for string in [true, false] {
            // No slot: the plain helper call, no probe.
            let g = build(string, 0);
            let sch = ir_schedule::schedule(&g);
            let cm = lower(&g, &sch, 0, 0, &helpers).expect("an ldc site lowers");
            assert!(
                !contains_seq(cm.code_bytes(), &PROBE),
                "string={string}: no slot, no probe"
            );
            // SAFETY: the synthetic helper ignores its arguments.
            let got = unsafe { cm.try_call_with_context(0, &[]) }.expect("call");
            assert_eq!(got, 0x7777_0000, "string={string}: the helper answers");

            // With a slot. `word` outlives every call below.
            let mut word: i64 = 0x0000_ABCD_0000;
            let slot_addr = std::ptr::addr_of_mut!(word) as usize;
            let g = build(string, slot_addr);
            let sch = ir_schedule::schedule(&g);
            let cm = lower(&g, &sch, 0, 0, &helpers).expect("a slotted ldc site lowers");
            assert!(
                contains_seq(cm.code_bytes(), &PROBE),
                "string={string}: a slot is probed"
            );
            // SAFETY: the probe reads `word`, which is live; the helper
            // ignores its arguments.
            let got = unsafe { cm.try_call_with_context(0, &[]) }.expect("call");
            assert_eq!(
                got, 0x0000_ABCD_0000,
                "string={string}: a hit skips the helper"
            );
            // The collector rewrites the word in place; the code re-reads it.
            // SAFETY: a plain write to a live local through its own address.
            unsafe { std::ptr::write_volatile(slot_addr as *mut i64, 0x0000_BEEF_0000) };
            // SAFETY: as above.
            let got = unsafe { cm.try_call_with_context(0, &[]) }.expect("call");
            assert_eq!(got, 0x0000_BEEF_0000, "string={string}: the rewritten word");
            // SAFETY: as above.
            unsafe { std::ptr::write_volatile(slot_addr as *mut i64, 0) };
            // SAFETY: as above.
            let got = unsafe { cm.try_call_with_context(0, &[]) }.expect("call");
            assert_eq!(
                got, 0x7777_0000,
                "string={string}: an empty slot calls the helper"
            );
        }
    }

    /// Round 9 wave 8 (irl8), the IR half of
    /// `compiled-bastore-to-boolean-array-is-not-masked`: `bastore` into a
    /// `boolean[]` stores `value & 1` (the interpreter's
    /// `write_prim_element` `Boolean` arm), into a `byte[]` the low byte.
    /// EXECUTED against a hand-made array header: only the kind byte, the
    /// length word and the data matter to this body. Every pre-data header
    /// byte is filled with 0x7F so the length reads as a large positive
    /// `int` without this test naming the inventoried length-offset constant
    /// (`layout_const_inventory.rs` counts code uses in this file).
    #[test]
    fn r9w8_bastore_into_a_boolean_array_stores_the_low_bit() {
        // static int f(<array> a, int v) { a[0] = v; return a[0]; }
        // aload_0 ; iconst_0 ; iload_1 ; bastore ; aload_0 ; iconst_0 ;
        // baload ; ireturn
        let code = [0x2a, 0x03, 0x1b, 0x54, 0x2a, 0x03, 0x33, 0xac];
        let bool_tag = cratonvm_types::primitive_array_kind_tags_byte("[Z").expect("[Z tag");
        let byte_tag = cratonvm_types::primitive_array_kind_tags_byte("[B").expect("[B tag");
        assert!(
            cratonvm_types::KIND_TAGS_BYTE_OFFSET < cratonvm_types::ARRAY_DATA_OFFSET,
            "precondition: the kind byte lies in the header"
        );
        for optimize in [false, true] {
            let mut builder = IrBuilder::new(2, 2);
            builder.set_param_types(&[IrType::Ref, IrType::Int]);
            let mut graph = builder.build(&code, code.len()).expect("IR build");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let cm = lower(&graph, &schedule, 2, 2, &no_helpers())
                .unwrap_or_else(|| panic!("bastore must lower (optimize={optimize})"));
            for (tag, is_bool) in [(bool_tag, true), (byte_tag, false)] {
                for v in [0i32, 1, 2, 3, -1, -2, 255, 256, 0x17F, i32::MIN, i32::MAX] {
                    // 64 bytes, 8-aligned: header plus data.
                    let mut obj = [0u64; 8];
                    let base = obj.as_mut_ptr().cast::<u8>();
                    // SAFETY: every offset written is below 64, inside `obj`.
                    unsafe {
                        for off in 0..cratonvm_types::ARRAY_DATA_OFFSET {
                            *base.add(off) = 0x7F;
                        }
                        *base.add(cratonvm_types::KIND_TAGS_BYTE_OFFSET) = tag;
                    }
                    // SAFETY: an `int f(ref, int)` body with no call; the
                    // array is non-null and index 0 is in bounds, so no
                    // guard fires. Cast: the raw pointer is the reference.
                    let got = unsafe { cm.try_call(&[base as i64, i64::from(v)]) }.expect("call");
                    // Cast: `(byte) v` is the JVMS `byte[]` truncation.
                    let want = if is_bool { v & 1 } else { i32::from(v as i8) };
                    assert_eq!(
                        got as i32, want,
                        "v={v} boolean[]={is_bool} (optimize={optimize})"
                    );
                }
            }
        }
    }

    /// Round 9 wave 12: the two causes
    /// `perf-long-counted-loops-lose-the-optimizing-osr-body-20260918.md`
    /// named, pinned on every loop shape that page measures.
    ///
    /// The page opened on `CratonBench.benchArithmetic` running its OSR body in
    /// single-pass code. A constant `/` or `%` still emitted a zero-divisor
    /// deopt point, which made the optimizing body non-sentinel-free, which
    /// made `lower_inner` skip the OSR entry emission, which made
    /// `jit_bridge::try_osr` refuse the body (cause 1); and `lcmp; if<cc>` was
    /// materialised to {-1,0,1} and round-tripped through a home instead of
    /// being fused into the branch (cause 2). Wave 2 fixed the first and waves
    /// 3 and 6 the second, in three files, and no single test has ever held the
    /// five shapes together.
    ///
    /// So, for `mul` / `div` / `rem` / `full` (the page's `long` shapes) and
    /// its `int`-induction twin: the body lowers, it is `ir_osr_sentinel_free`,
    /// it carries an OSR entry AT THE LOOP HEADER -- the exact conjunction
    /// `try_osr` admits on, `ir_osr_entry_addr(pc).is_some() &&
    /// ir_osr_sentinel_free` -- it contains no `SETG AL` (the `lcmp`
    /// materialisation), and it EXECUTES the loop correctly over counts
    /// including the edges.
    ///
    /// This is a REACHABILITY guard, not a measurement. Which body is faster is
    /// a policy (`jit_bridge::osr_optimizing_not_known_better`), re-measured in
    /// the page's closing status; what must not rot is that the optimizing body
    /// is still admissible at all, because each of the three fixes above lives
    /// in a file the others do not.
    #[test]
    fn r9w12_the_long_counted_loop_shapes_all_admit_an_optimizing_osr_body() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}

        struct Shape {
            name: &'static str,
            code: &'static [u8],
            /// `true` for the four `long`-induction shapes, `false` for the
            /// `int` twin (whose parameter and induction variable are `int`).
            long_shape: bool,
            locals: usize,
            /// The bci the loop header sits at -- the `entry_pc` `try_osr`
            /// asks `ir_osr_entry_addr` for.
            header_bci: u32,
            /// Does this shape contain a constant `/` or `%`? Those are the
            /// ones whose admission `CRATONVM_JIT_IR_CONST_DIV` decides.
            const_div: bool,
            reference: fn(i64) -> i64,
        }

        // `s += i * 3 + (i >> 1)`
        const MUL: &[u8] = &[
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x19, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x04, 0x7b, 0x61, 0x61, 0x41, 0x16, 0x04, 0x0a,
            0x61, 0x37, 0x04, 0xa7, 0xff, 0xe6, 0x20, 0xad,
        ];
        // `s += i * 3 - i / 2`
        const DIV: &[u8] = &[
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x1a, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x05, 0x85, 0x6d, 0x65, 0x61, 0x41, 0x16, 0x04,
            0x0a, 0x61, 0x37, 0x04, 0xa7, 0xff, 0xe5, 0x20, 0xad,
        ];
        // `s += i * 3 + i % 7`
        const REM: &[u8] = &[
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x1b, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x10, 0x07, 0x85, 0x71, 0x61, 0x61, 0x41, 0x16,
            0x04, 0x0a, 0x61, 0x37, 0x04, 0xa7, 0xff, 0xe4, 0x20, 0xad,
        ];
        // `s += i * 3 - i / 2 + i % 7` -- `CratonBench.benchArithmetic`'s body,
        // the expression the page's headline number is one call of.
        const FULL: &[u8] = &[
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x21, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x05, 0x85, 0x6d, 0x65, 0x16, 0x04, 0x10, 0x07,
            0x85, 0x71, 0x61, 0x61, 0x41, 0x16, 0x04, 0x0a, 0x61, 0x37, 0x04, 0xa7, 0xff, 0xde,
            0x20, 0xad,
        ];
        // The same expression with an `int` induction variable and an `int`
        // division: `idiv`/`irem`, no `lcmp`, and the one row the page measured
        // the optimizing body winning.
        const INT: &[u8] = &[
            0x09, 0x40, 0x03, 0x3e, 0x1d, 0x1a, 0xa2, 0x00, 0x19, 0x1f, 0x1d, 0x06, 0x68, 0x1d,
            0x05, 0x6c, 0x64, 0x1d, 0x10, 0x07, 0x70, 0x60, 0x85, 0x61, 0x40, 0x84, 0x03, 0x01,
            0xa7, 0xff, 0xe8, 0x1f, 0xad,
        ];

        fn mul_ref(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                i += 1;
            }
            s
        }
        fn div_ref(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                s = s.wrapping_add(i.wrapping_mul(3).wrapping_sub(i / 2));
                i += 1;
            }
            s
        }
        fn rem_ref(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i % 7));
                i += 1;
            }
            s
        }
        fn full_ref(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                s = s.wrapping_add(i.wrapping_mul(3).wrapping_sub(i / 2).wrapping_add(i % 7));
                i += 1;
            }
            s
        }
        fn int_ref(n: i64) -> i64 {
            // Cast: this shape is only called with counts that fit `i32`.
            let n = n as i32;
            let mut s = 0i64;
            let mut i = 0i32;
            while i < n {
                let t = i.wrapping_mul(3).wrapping_sub(i / 2).wrapping_add(i % 7);
                s = s.wrapping_add(i64::from(t));
                i = i.wrapping_add(1);
            }
            s
        }

        let shapes = [
            Shape {
                name: "mul",
                code: MUL,
                long_shape: true,
                locals: 6,
                header_bci: 5,
                const_div: false,
                reference: mul_ref,
            },
            Shape {
                name: "div",
                code: DIV,
                long_shape: true,
                locals: 6,
                header_bci: 5,
                const_div: true,
                reference: div_ref,
            },
            Shape {
                name: "rem",
                code: REM,
                long_shape: true,
                locals: 6,
                header_bci: 5,
                const_div: true,
                reference: rem_ref,
            },
            Shape {
                name: "full",
                code: FULL,
                long_shape: true,
                locals: 6,
                header_bci: 5,
                const_div: true,
                reference: full_ref,
            },
            Shape {
                name: "int",
                code: INT,
                long_shape: false,
                locals: 4,
                header_bci: 4,
                const_div: true,
                reference: int_ref,
            },
        ];

        // Collected rather than asserted one at a time: five shapes x two
        // pipelines is ten independent claims, and a test that aborts on the
        // first hides the other nine (every shape here was fixed in a
        // different wave, so they fail independently).
        let mut problems: Vec<String> = Vec::new();

        for shape in &shapes {
            for optimize in [false, true] {
                let mut builder = IrBuilder::new(1, shape.locals);
                builder.set_param_types(&[if shape.long_shape {
                    IrType::Long
                } else {
                    IrType::Int
                }]);
                let mut graph = builder
                    .build(shape.code, shape.code.len())
                    .unwrap_or_else(|| panic!("IR build ({}, optimize={optimize})", shape.name));
                if optimize {
                    ir_optimize::optimize(&mut graph);
                }
                let schedule = ir_schedule::schedule(&graph);
                let mut helpers = no_helpers();
                helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
                helpers.safepoint_slow_path = slow_poll as *const () as usize;
                let cm = lower(&graph, &schedule, 1, shape.locals, &helpers)
                    .unwrap_or_else(|| panic!("{} must lower (optimize={optimize})", shape.name));

                // Cause 1: no deopt stub and no call-exception stub, and
                // therefore an OSR entry at the loop header.
                //
                // Asked of the OPTIMIZED pipeline only, because that is the
                // only one `try_osr` ever sees -- `compile_optimizing_artifact`
                // always runs `ir_optimize` -- and because this test cannot
                // build a constant pool. `javac` writes the divisor as
                // `ldc2_w`, which is a `Const` in the raw graph; the bodies
                // below have to spell the same constant `iconst_2; i2l`, and
                // `reducible_const_divisor` sees a `Const` there only after
                // constant folding has run. In the raw graph the divisor is a
                // runtime value, so the division keeps its zero-divisor guard
                // and the body is legitimately not sentinel-free.
                //
                // The flag gate is for the shapes WITH a constant divisor;
                // `mul` has none, so its admission does not depend on
                // `CRATONVM_JIT_IR_CONST_DIV` and is checked whatever it says.
                if optimize && (!shape.const_div || ir_const_div_enabled()) {
                    if !cm.ir_osr_sentinel_free {
                        problems.push(format!(
                            "{} (optimize={optimize}): the optimizing body is not \
                             sentinel-free, so try_osr refuses it and the loop runs \
                             single-pass OSR code",
                            shape.name,
                        ));
                    }
                    // In the raw graph the header block also carries no
                    // safepoint snapshot of its own, so `emit_osr_entry_stubs`
                    // refuses it ("no safepoint snapshot at this block start")
                    // and the body's only entry is the loop EXIT bci -- a
                    // second reason this half belongs to the optimized arm.
                    if ir_osr_entry_enabled() {
                        if cm.ir_osr_entry_addr(shape.header_bci).is_none() {
                            problems.push(format!(
                                "{} (optimize={optimize}): no OSR entry at the loop \
                                 header bci {} (entries={:?})",
                                shape.name,
                                shape.header_bci,
                                cm.ir_osr_entries
                                    .iter()
                                    .map(|(b, _, _)| *b)
                                    .collect::<Vec<_>>(),
                            ));
                        }
                    }
                }

                // Cause 2: no `SETG AL` -- the `lcmp` materialisation the four
                // `long` shapes used to pay per iteration. The `int` shape has
                // no `lcmp`, so it is not asked.
                if shape.long_shape
                    && ir_fused_branch_enabled()
                    && ir_register_authoritative_enabled()
                    && contains_seq(cm.code_bytes(), &[0x0F, 0x9F, 0xC0])
                {
                    problems.push(format!(
                        "{} (optimize={optimize}): the loop's lcmp was not fused \
                         into its exit test",
                        shape.name,
                    ));
                }

                // And it still computes the loop. One report per shape: a
                // wrong body is wrong for every count.
                for n in [0i64, 1, 2, 3, 7, 8, 100, 4_001] {
                    // SAFETY: a static body with no call (the poll's slow path
                    // is a no-op) and no trap -- every divisor is a non-zero
                    // constant.
                    let got = unsafe { cm.try_call(&[n]) }.expect("call");
                    let want = (shape.reference)(n);
                    if got != want {
                        problems.push(format!(
                            "{} (optimize={optimize}): n={n} gave {got}, want {want}",
                            shape.name,
                        ));
                        break;
                    }
                }
            }
        }

        assert!(
            problems.is_empty(),
            "the long-counted-loop shapes no longer admit an optimizing OSR \
             body, or no longer compute their loop:\n  {}",
            problems.join("\n  "),
        );
    }

    /// Round 9 wave 6 (irlower6): a `long`-counted loop whose `lcmp` result's
    /// frame colour is reused by a later node in the block still fuses its
    /// exit test. `ArithOsr.mulOnly` (`s += i * 3 + (i >> 1)`): on the wave-5
    /// binary the compare's clobber test refused the compare (the `lcmp`'s word
    /// went to the body's first temporary), which also skipped the `lcmp`
    /// fusion, so every iteration materialised `lcmp` with `SETG; SETL; SUB`
    /// and the boolean with `SETGE`. EXECUTED over counts around the edges.
    #[test]
    fn r9w6_a_long_counted_loop_fuses_its_lcmp_exit_test() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        let code: [u8; 36] = [
            0x09, // 0: lconst_0
            0x41, // 1: lstore_2         s = 0
            0x09, // 2: lconst_0
            0x37, 0x04, // 3: lstore 4   i = 0
            0x16, 0x04, // 5: lload 4    <- loop header
            0x1e, // 7: lload_0
            0x94, // 8: lcmp
            0x9c, 0x00, 0x19, // 9: ifge +25 -> 34
            0x20, // 12: lload_2
            0x16, 0x04, // 13: lload 4
            0x06, // 15: iconst_3
            0x85, // 16: i2l
            0x69, // 17: lmul
            0x16, 0x04, // 18: lload 4
            0x04, // 20: iconst_1
            0x7b, // 21: lshr
            0x61, // 22: ladd
            0x61, // 23: ladd
            0x41, // 24: lstore_2
            0x16, 0x04, // 25: lload 4
            0x0a, // 27: lconst_1
            0x61, // 28: ladd
            0x37, 0x04, // 29: lstore 4
            0xa7, 0xff, 0xe6, // 31: goto -26 -> 5
            0x20, // 34: lload_2
            0xad, // 35: lreturn
        ];
        for optimize in [false, true] {
            let mut builder = IrBuilder::new(1, 6);
            builder.set_param_types(&[IrType::Long]);
            let mut graph = builder.build(&code, code.len()).expect("IR build");
            if optimize {
                ir_optimize::optimize(&mut graph);
            }
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
            helpers.safepoint_slow_path = slow_poll as *const () as usize;
            let cm = lower(&graph, &schedule, 1, 6, &helpers)
                .unwrap_or_else(|| panic!("the kernel must lower (optimize={optimize})"));
            if ir_fused_branch_enabled() && ir_register_authoritative_enabled() {
                // SETG AL -- the `lcmp` materialisation.
                assert!(
                    !contains_seq(cm.code_bytes(), &[0x0F, 0x9F, 0xC0]),
                    "the loop's lcmp was not fused into its exit test (optimize={optimize})"
                );
            }
            for n in [i64::MIN, -1, 0, 1, 2, 3, 7, 1000, 100_003] {
                let mut want = 0i64;
                let mut i = 0i64;
                while i < n {
                    want = want.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                    i += 1;
                }
                // SAFETY: a `long f(long)` body with no call (the poll's slow
                // path is a no-op) and no trap.
                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                assert_eq!(got, want, "n={n} (optimize={optimize})");
            }
        }
    }

    /// Round 9 wave 6 (irlower6): the emission half of split-residency edge
    /// resolution. One copy on one edge is one `MOV r64, [rbp - home]` into the
    /// planned register, it marks the edge done (the post-lowering check
    /// refuses a method with an edge whose copies never ran), it makes
    /// `edge_has_phi_copies` answer `true` so every `If` arm gives the edge
    /// straight-line code of its own, and it does NOT touch the residency
    /// tables (the next block in layout order is not on this edge's path).
    #[test]
    fn r9w6_an_edge_resolution_copy_is_one_home_load_on_its_own_edge() {
        let code: [u8; 36] = [
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x19, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x04, 0x7b, 0x61, 0x61, 0x41, 0x16, 0x04, 0x0a,
            0x61, 0x37, 0x04, 0xa7, 0xff, 0xe6, 0x20, 0xad,
        ];
        let mut builder = IrBuilder::new(1, 6);
        builder.set_param_types(&[IrType::Long]);
        let graph = builder.build(&code, code.len()).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        assert!(
            schedule.blocks.len() >= 2,
            "precondition: a loop schedules into several blocks"
        );
        let plan = plan_slots(&graph, &schedule, None);
        // Cast: an index into the node arena is a `NodeId`.
        let param = graph
            .nodes
            .iter()
            .position(|node| matches!(node.op, Op::Param(0)))
            .expect("the parameter is in the graph") as NodeId;
        let graph: &'static Graph = Box::leak(Box::new(graph));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan));
        let mut lo = lowerer_over(graph, schedule, plan, 4096);
        lo.alloc_slot_checked(param)
            .expect("the parameter has a planned home word");
        // Edge 0 -> 1 is the loop's entry edge and carries the header's phis,
        // whose sources `gather_phi_copies` resolves to home words: give every
        // planned value its word, as the block walk would have by now.
        for id in 0..graph.nodes.len() {
            // Cast: an index into the node arena is a `NodeId`.
            let _ = lo.alloc_slot_checked(id as NodeId);
        }
        let (pred, succ) = (0usize, 1usize);
        lo.ls_edge_copies = vec![LsEdgeCopies {
            pred,
            succ,
            copies: vec![(param, RBX, true)],
        }];
        lo.ls_edge_copies_done = vec![false];
        assert!(
            lo.edge_has_phi_copies(pred, succ),
            "an edge with a resolution copy must get a copy site of its own"
        );
        assert_eq!(
            lo.edge_has_phi_copies(succ, pred),
            !lo.gather_phi_copies(succ, pred).is_empty(),
            "and no other edge changes its answer"
        );

        // Another edge: nothing.
        let before = lo.buf.pos();
        lo.ls_emit_edge_copies(succ, pred);
        assert_eq!(lo.buf.pos(), before, "an edge with no copy emits nothing");
        assert_eq!(lo.ls_edge_copies_done, vec![false]);

        lo.ls_emit_edge_copies(pred, succ);
        let emitted = lo.buf.as_slice()[before..].to_vec();
        let refused = lo.take_latched_bailout();
        assert!(
            refused.is_none(),
            "a copy with no phi on its edge must not be refused: {refused:?}"
        );
        assert_eq!(
            emitted.first().copied(),
            Some(0x48),
            "REX.W: {emitted:02x?}"
        );
        assert_eq!(
            emitted.get(1).copied(),
            Some(0x8B),
            "MOV r64, r/m64: {emitted:02x?}"
        );
        assert_eq!(
            emitted.get(2).map(|modrm| (modrm >> 3) & 7),
            Some(RBX),
            "into RBX: {emitted:02x?}"
        );
        assert_eq!(
            lo.ls_edge_copies_done,
            vec![true],
            "the edge is marked done"
        );
        assert_eq!(lo.ls_edge_loads, 1);
        assert_eq!(
            lo.resident_gpr(param),
            None,
            "the copy is not a publish: the emitter's tables describe the next \
             block in LAYOUT order, which this edge does not reach"
        );
    }

    /// Round 9 wave 6 (irlower6): two call-free `long` loops -- the straight
    /// counted kernel and one with a diamond in the body (a join whose
    /// non-fall-through arm a split timeline can leave a value on in the wrong
    /// place) -- compute the same answers with split residency off, on behind
    /// the wave-1 edge gate, and on with edge resolution. EXECUTED. Whether the
    /// allocator splits anything here depends on the file size; the point of
    /// the test is that no configuration of the two flags changes an answer.
    #[test]
    fn r9w6_split_residency_with_edge_resolution_computes_the_same_loops() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        const STRAIGHT: [u8; 36] = [
            0x09, 0x41, 0x09, 0x37, 0x04, 0x16, 0x04, 0x1e, 0x94, 0x9c, 0x00, 0x19, 0x20, 0x16,
            0x04, 0x06, 0x85, 0x69, 0x16, 0x04, 0x04, 0x7b, 0x61, 0x61, 0x41, 0x16, 0x04, 0x0a,
            0x61, 0x37, 0x04, 0xa7, 0xff, 0xe6, 0x20, 0xad,
        ];
        const DIAMOND: [u8; 50] = [
            0x09, // 0: lconst_0
            0x41, // 1: lstore_2         s = 0
            0x09, // 2: lconst_0
            0x37, 0x04, // 3: lstore 4   i = 0
            0x16, 0x04, // 5: lload 4    <- loop header
            0x1e, // 7: lload_0
            0x94, // 8: lcmp
            0x9c, 0x00, 0x27, // 9: ifge +39 -> 48
            0x16, 0x04, // 12: lload 4
            0x0a, // 14: lconst_1
            0x7f, // 15: land
            0x09, // 16: lconst_0
            0x94, // 17: lcmp
            0x9a, 0x00, 0x0e, // 18: ifne +14 -> 32
            0x20, // 21: lload_2
            0x16, 0x04, // 22: lload 4
            0x06, // 24: iconst_3
            0x85, // 25: i2l
            0x69, // 26: lmul
            0x61, // 27: ladd
            0x41, // 28: lstore_2
            0xa7, 0x00, 0x0a, // 29: goto +10 -> 39
            0x20, // 32: lload_2         <- odd arm
            0x16, 0x04, // 33: lload 4
            0x04, // 35: iconst_1
            0x7b, // 36: lshr
            0x65, // 37: lsub
            0x41, // 38: lstore_2
            0x16, 0x04, // 39: lload 4   <- join
            0x0a, // 41: lconst_1
            0x61, // 42: ladd
            0x37, 0x04, // 43: lstore 4
            0xa7, 0xff, 0xd8, // 45: goto -40 -> 5
            0x20, // 48: lload_2
            0xad, // 49: lreturn
        ];
        fn straight(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                s = s.wrapping_add(i.wrapping_mul(3).wrapping_add(i >> 1));
                i += 1;
            }
            s
        }
        fn diamond(n: i64) -> i64 {
            let (mut s, mut i) = (0i64, 0i64);
            while i < n {
                if i & 1 == 0 {
                    s = s.wrapping_add(i.wrapping_mul(3));
                } else {
                    s = s.wrapping_sub(i >> 1);
                }
                i += 1;
            }
            s
        }
        let kernels: [(&[u8], fn(i64) -> i64, &str); 2] = [
            (&STRAIGHT[..], straight as fn(i64) -> i64, "straight"),
            (&DIAMOND[..], diamond as fn(i64) -> i64, "diamond"),
        ];
        let configs: [(Option<&str>, Option<&str>); 3] =
            [(None, None), (Some("1"), None), (Some("1"), Some("1"))];
        for (splits, resolution) in configs {
            cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JIT_IR_LS_SPLITS", splits),
                    ("CRATONVM_JIT_IR_LS_EDGE_RESOLUTION", resolution),
                ],
                || {
                    for (code, want_fn, name) in kernels {
                        for optimize in [false, true] {
                            let mut builder = IrBuilder::new(1, 6);
                            builder.set_param_types(&[IrType::Long]);
                            let mut graph = builder.build(code, code.len()).expect("IR build");
                            if optimize {
                                ir_optimize::optimize(&mut graph);
                            }
                            let schedule = ir_schedule::schedule(&graph);
                            let mut helpers = no_helpers();
                            helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
                            helpers.safepoint_slow_path = slow_poll as *const () as usize;
                            let cm =
                                lower(&graph, &schedule, 1, 6, &helpers).unwrap_or_else(|| {
                                    panic!(
                                        "{name} must lower (splits={splits:?} \
                                     resolution={resolution:?} optimize={optimize})"
                                    )
                                });
                            for n in [-1i64, 0, 1, 2, 3, 4, 7, 1000, 100_003] {
                                // SAFETY: a `long f(long)` body with no call
                                // (the poll's slow path is a no-op) and no trap.
                                let got = unsafe { cm.try_call(&[n]) }.expect("call");
                                assert_eq!(
                                    got,
                                    want_fn(n),
                                    "{name} n={n} splits={splits:?} \
                                     resolution={resolution:?} optimize={optimize}"
                                );
                            }
                        }
                    }
                },
            );
        }
    }

    /// Round 9 wave 2 (isel #3): the d2i/d2l/f2i/f2l fixup ported from
    /// `x64::arith::emit_fp_to_int_nan_fixup` (`CMP r,1; JNO` / `NOT` for MAX).
    /// `x / 0.0` drives every arm from an int parameter: +inf → MAX, -inf →
    /// MIN, NaN (0/0) → 0; plain `(T) x` covers the in-range fast path,
    /// including `(int)(double)MIN`, whose correct answer IS the indefinite
    /// pattern.
    #[test]
    fn r9w2_fp_to_int_conversions_saturate_and_zero_nan() {
        // (code, is_long)
        let shapes: [(&[u8], bool); 4] = [
            // iload_0 i2d dconst_0 ddiv d2i ireturn
            (&[0x1a, 0x87, 0x0e, 0x6f, 0x8e, 0xac], false),
            // iload_0 i2d dconst_0 ddiv d2l lreturn
            (&[0x1a, 0x87, 0x0e, 0x6f, 0x8f, 0xad], true),
            // iload_0 i2f fconst_0 fdiv f2i ireturn
            (&[0x1a, 0x86, 0x0b, 0x6e, 0x8b, 0xac], false),
            // iload_0 i2f fconst_0 fdiv f2l lreturn
            (&[0x1a, 0x86, 0x0b, 0x6e, 0x8c, 0xad], true),
        ];
        for (code, is_long) in shapes {
            let cm = r9w2_compile_one_arg(code, false, false);
            for (x, want_i, want_l) in [
                (5i32, i64::from(i32::MAX), i64::MAX),
                (-5, i64::from(i32::MIN), i64::MIN),
                (0, 0, 0),
            ] {
                // SAFETY: a one-int-argument body with no helper calls.
                let got = unsafe { cm.try_call(&[i64::from(x)]) }.expect("call");
                if is_long {
                    assert_eq!(got, want_l, "{code:02x?} x={x}");
                } else {
                    // Cast: this tier's `int` result is the low 32 bits.
                    assert_eq!(i64::from(got as i32), want_i, "{code:02x?} x={x}");
                }
            }
        }
        // In range: iload_0 i2d d2i ireturn / iload_0 i2d d2l lreturn.
        let d2i = r9w2_compile_one_arg(&[0x1a, 0x87, 0x8e, 0xac], false, false);
        let d2l = r9w2_compile_one_arg(&[0x1a, 0x87, 0x8f, 0xad], false, false);
        for x in [i32::MIN, -1, 0, 1, 123_456, i32::MAX] {
            // SAFETY: as above.
            let got = unsafe { d2i.try_call(&[i64::from(x)]) }.expect("call");
            // Cast: this tier's `int` result is the low 32 bits.
            assert_eq!(got as i32, x, "(int)(double){x}");
            // SAFETY: as above.
            let got = unsafe { d2l.try_call(&[i64::from(x)]) }.expect("call");
            assert_eq!(got, i64::from(x), "(long)(double){x}");
        }
    }

    thread_local! {
        static R9W2_AASTORES: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
        static R9W2_TYPE_CHECKS: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
    }

    /// Round 11 wave 3 (lane lower): `a[i] = a[j]` stores a value loaded from
    /// the same array, so it skips `jit_aastore_type_check`; a value of
    /// unknown origin (`a[0] = v`) keeps it.
    #[test]
    fn r11w3_an_element_moved_within_one_array_skips_the_covariance_call() {
        const AASTORE: u64 = 0x1111_2222_3333_5550;
        const TYPE_CHECK: u64 = 0x1111_2222_3333_5551;
        let mut helpers = no_helpers();
        helpers.aastore = AASTORE as usize;
        helpers.aastore_type_check = TYPE_CHECK as usize;
        let lower_code = |code: &[u8], params: &[IrType]| -> Option<Vec<u8>> {
            let mut builder = IrBuilder::new(params.len(), params.len());
            builder.set_param_types(params);
            let graph = builder.build(code, code.len()).expect("IR build");
            let schedule = ir_schedule::schedule(&graph);
            lower(&graph, &schedule, params.len(), params.len(), &helpers)
                .map(|cm| cm.code_bytes().to_vec())
        };
        // static int f(Object[] a) { a[0] = a[1]; return 1; }
        //   aload_0 iconst_0 aload_0 iconst_1 aaload aastore iconst_1 ireturn
        let moved = lower_code(
            &[0x2a, 0x03, 0x2a, 0x04, 0x32, 0x53, 0x04, 0xac],
            &[IrType::Ref],
        );
        // static int g(Object[] a, Object v) { a[0] = v; return 1; }
        let foreign = lower_code(
            &[0x2a, 0x03, 0x2b, 0x53, 0x04, 0xac],
            &[IrType::Ref, IrType::Ref],
        );
        let (Some(moved), Some(foreign)) = (moved, foreign) else {
            // `CRATONVM_JIT_IR_AASTORE=0` refuses the arm; nothing to test.
            assert!(!ir_aastore_enabled(), "the aastore graphs must lower");
            return;
        };
        assert!(
            contains_seq(&moved, &AASTORE.to_le_bytes()),
            "the store itself stays"
        );
        assert!(
            !contains_seq(&moved, &TYPE_CHECK.to_le_bytes()),
            "a same-array element move must not call the covariance check"
        );
        assert!(
            contains_seq(&foreign, &TYPE_CHECK.to_le_bytes()),
            "a value of unknown origin keeps the covariance check"
        );
    }

    /// Round 11 wave 4 (lane lower): a store into a `new C[n]` array of a value
    /// bounded by the same `C` -- a `new C` object, or an element of another
    /// `new C[n]` -- skips `jit_aastore_type_check`; the same stores with a
    /// different class keep it.
    #[test]
    fn r11w4_a_store_bounded_by_the_arrays_own_component_skips_the_covariance_call() {
        const AASTORE: u64 = 0x1111_2222_3333_5560;
        const TYPE_CHECK: u64 = 0x1111_2222_3333_5561;
        const C: u32 = 41;
        const D: u32 = 42;
        let mut helpers = no_helpers();
        helpers.aastore = AASTORE as usize;
        helpers.aastore_type_check = TYPE_CHECK as usize;
        // Never called: nothing here executes, the bytes are only inspected.
        helpers.new_object = 0x1111_2222_3333_5562;
        helpers.anewarray_object = 0x1111_2222_3333_5563;
        // `news`: `new` pc -> class id; `arrays`: `anewarray` pc -> component.
        let lower_code =
            |code: &[u8], news: &[(usize, u32)], arrays: &[(usize, u32)]| -> Option<Vec<u8>> {
                let mut builder = IrBuilder::new(1, 1);
                builder.set_param_types(&[IrType::Int]);
                builder.set_new_info(
                    news.iter().map(|&(pc, id)| (pc, (id, 0usize))).collect(),
                    std::collections::HashSet::new(),
                );
                builder.set_anewarray_info(arrays.iter().copied().collect());
                let graph = builder.build(code, code.len()).expect("IR build");
                let schedule = ir_schedule::schedule(&graph);
                lower(&graph, &schedule, 1, 1, &helpers).map(|cm| cm.code_bytes().to_vec())
            };
        // static int f(int n) { C[] a = new C[n]; a[0] = new C(); return 1; }
        //   iload_0 anewarray#1 iconst_0 new#2 aastore iconst_1 ireturn
        let new_obj = [
            0x1a, 0xbd, 0x00, 0x01, 0x03, 0xbb, 0x00, 0x02, 0x53, 0x04, 0xac,
        ];
        // static int g(int n) { C[] a = new C[n]; a[0] = new C[n][1]; return 1; }
        //   iload_0 anewarray#1 iconst_0 iload_0 anewarray#1 iconst_1 aaload
        //   aastore iconst_1 ireturn
        let moved = [
            0x1a, 0xbd, 0x00, 0x01, 0x03, 0x1a, 0xbd, 0x00, 0x01, 0x04, 0x32, 0x53, 0x04, 0xac,
        ];
        let cases = [
            (
                lower_code(&new_obj, &[(5, C)], &[(1, C)]),
                false,
                "new C into new C[]",
            ),
            (
                lower_code(&new_obj, &[(5, D)], &[(1, C)]),
                true,
                "new D into new C[]",
            ),
            (
                lower_code(&moved, &[], &[(1, C), (6, C)]),
                false,
                "C[] element into C[]",
            ),
            (
                lower_code(&moved, &[], &[(1, C), (6, D)]),
                true,
                "D[] element into C[]",
            ),
        ];
        for (bytes, wants_check, what) in cases {
            let Some(bytes) = bytes else {
                // `CRATONVM_JIT_IR_AASTORE=0` refuses the arm; nothing to test.
                assert!(
                    !ir_aastore_enabled(),
                    "{what}: the aastore graph must lower"
                );
                return;
            };
            assert!(
                contains_seq(&bytes, &AASTORE.to_le_bytes()),
                "{what}: the store stays"
            );
            assert_eq!(
                contains_seq(&bytes, &TYPE_CHECK.to_le_bytes()),
                wants_check,
                "{what}: covariance check emitted?"
            );
        }
    }

    /// Round 9 wave 2: an `aastore` whose covariance check refuses leaves the
    /// body through the exception epilogue at the store — `jit_aastore` is
    /// never called and nothing after the store runs — and a null value skips
    /// the check entirely.
    #[test]
    fn r9w2_a_refused_aastore_stops_the_body_at_the_store() {
        const REFUSED: u64 = 0x0BAD_0000;
        extern "C" fn type_check(_vm: i64, _array: i64, val: i64) -> i64 {
            R9W2_TYPE_CHECKS.with(|c| c.set(c.get() + 1));
            // SAFETY: every non-null value these tests pass is a leaked
            // `r11w14_fake_value`, four words long.
            if unsafe { (val as *const u64).add(3).read() } == REFUSED {
                i64::MIN
            } else {
                0
            }
        }
        extern "C" fn aastore(_vm: i64, _array: i64, _index: i64, _val: i64) {
            R9W2_AASTORES.with(|c| c.set(c.get() + 1));
        }
        // static int f(Object[] a, Object v) { a[0] = v; return 1; }
        //   aload_0 iconst_0 aload_1 aastore iconst_1 ireturn
        let code = [0x2a, 0x03, 0x2b, 0x53, 0x04, 0xac];
        let mut builder = IrBuilder::new(2, 2);
        builder.set_param_types(&[IrType::Ref, IrType::Ref]);
        let graph = builder.build(&code, code.len()).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.aastore = aastore as *const () as usize;
        helpers.aastore_type_check = type_check as *const () as usize;
        let Some(cm) = lower(&graph, &schedule, 2, 2, &helpers) else {
            // `CRATONVM_JIT_IR_AASTORE=0` in the environment refuses the arm;
            // nothing to test then.
            assert!(!ir_aastore_enabled(), "the aastore graph must lower");
            return;
        };
        // A fake array: only its length word is read (the inline bounds
        // check). Every aligned 32-bit word of it reads 4, so the length is 4
        // wherever the header keeps it -- and the layout constant is not named
        // here, which would move `layout_const_inventory`'s count for this
        // file. Leaked so the address stays valid for the calls below.
        // Its first `u32`, the header class id, is 4 as well.
        let array: &'static [u64; 8] = Box::leak(Box::new([0x0000_0004_0000_0004u64; 8]));
        let arr = array.as_ptr() as i64;
        // SAFETY (both closures): the synthetic helpers read only a fake
        // value's mark word, and the body reads only the fake array's length
        // and class-id words and a fake value's header.
        let call_on = |array: i64, v: i64| {
            // SAFETY: see above.
            unsafe { cm.try_call_with_context(0, &[array, v]) }.expect("call")
        };
        let call = |v: i64| call_on(arr, v);
        let before = (
            R9W2_TYPE_CHECKS.with(|c| c.get()),
            R9W2_AASTORES.with(|c| c.get()),
        );
        // Class 5 into an array whose header names class 4: not the
        // exact component, so the check is asked.
        assert_eq!(
            call(r11w14_fake_value(5, 0, 0)) as i32,
            1,
            "a legal store completes"
        );
        assert_eq!(
            (
                R9W2_TYPE_CHECKS.with(|c| c.get()),
                R9W2_AASTORES.with(|c| c.get())
            ),
            (before.0 + 1, before.1 + 1),
            "one check, one store"
        );
        assert_eq!(
            call(r11w14_fake_value(5, 0, REFUSED)),
            i64::MIN,
            "a refused store exits with the sentinel"
        );
        assert_eq!(
            (
                R9W2_TYPE_CHECKS.with(|c| c.get()),
                R9W2_AASTORES.with(|c| c.get())
            ),
            (before.0 + 2, before.1 + 1),
            "the refused store must not reach `jit_aastore`"
        );
        assert_eq!(call(0) as i32, 1, "a null store completes");
        assert_eq!(
            R9W2_TYPE_CHECKS.with(|c| c.get()),
            before.0 + 2,
            "a null value skips the covariance check"
        );

        // Round 11 wave 14 (lane hashmap): the exact-component path. A PLAIN
        // value of the array header's own class skips the check and still
        // stores; an ARRAY value with that id still asks; an array of class
        // id 0 (`Object[]`) asks for nothing. Under
        // `CRATONVM_JIT_CHECKCAST_INLINE=0` every one asks.
        let exact_on = crate::x64::checkcast_inline_enabled();
        let counts = || {
            (
                R9W2_TYPE_CHECKS.with(|c| c.get()),
                R9W2_AASTORES.with(|c| c.get()),
            )
        };
        let (tc, aa) = counts();
        assert_eq!(call(r11w14_fake_value(4, 0, 0)) as i32, 1);
        assert_eq!(
            counts(),
            (tc + u32::from(!exact_on), aa + 1),
            "the exact component is stored without the check"
        );
        // A refusal mark the check would act on if it were asked: the
        // exact path must not be reached by a value that is not plain.
        let (tc, aa) = counts();
        assert_eq!(
            call(r11w14_fake_value(4, 1, REFUSED)),
            i64::MIN,
            "an array value with the component's id is still checked"
        );
        assert_eq!(counts(), (tc + 1, aa), "checked, refused, not stored");
        // Class id 0 (and a zero mark word) in the first header word, 4 in
        // every `u32` after it, the length word included (named nowhere, as
        // above; the 8-byte header moved it from the second `u32` to the
        // third).
        let mut zero_words = [0x0000_0004_0000_0004u64; 8];
        zero_words[0] = 0;
        let zero_id: &'static [u64; 8] = Box::leak(Box::new(zero_words));
        // Class id 0 on the array is `java/lang/Object`: the helper answers
        // "legal" for every value there, so no value is sent to it -- not
        // even an array, or one carrying the refusal mark the fake check
        // would act on.
        for v in [
            r11w14_fake_value(5, 0, REFUSED),
            r11w14_fake_value(0, 1, REFUSED),
        ] {
            let (tc, aa) = counts();
            let got = call_on(zero_id.as_ptr() as i64, v);
            if exact_on {
                assert_eq!(got as i32, 1, "an Object[] store completes");
                assert_eq!(counts(), (tc, aa + 1), "an Object[] store is not checked");
            } else {
                assert_eq!(got, i64::MIN, "the fake check refuses it");
                assert_eq!(counts(), (tc + 1, aa), "checked when the lever is off");
            }
        }
    }

    /// A leaked, header-shaped fake VALUE for the executed `aastore` tests:
    /// `class_id` in the header's first `u32`, `kind` at the KIND_TAGS byte
    /// (0 = a plain object), `mark` in word 3 for the fake type checks to
    /// read. Round 11 wave 14: the arm now reads a non-null value's header
    /// (the exact-component path), so a bare integer no longer stands in for
    /// one.
    fn r11w14_fake_value(class_id: u32, kind: u8, mark: u64) -> i64 {
        const _: () = assert!(cratonvm_types::KIND_TAGS_BYTE_OFFSET < 24);
        let words: &'static mut [u64; 4] = Box::leak(Box::new([u64::from(class_id), 0, 0, mark]));
        let base = words.as_mut_ptr();
        // SAFETY: the KIND_TAGS byte lies inside the leaked 32-byte block
        // (the assertion above), below the mark word.
        unsafe {
            (base as *mut u8) // Cast: word block → byte cursor
                .add(cratonvm_types::KIND_TAGS_BYTE_OFFSET)
                .write(kind)
        };
        base as i64 // Cast: leaked address
    }

    /// Round 11 wave 5 (lane lower, proposal W4-2): with a published barrier
    /// plan, an `aastore` whose barriers the gates rule out stores INLINE and
    /// never calls `jit_aastore`; a non-null value into an old array, or an
    /// armed SATB gate, still takes the helper; a null value into an old array
    /// stays inline. A same-array element move makes no call at all. Executed,
    /// not inspected, and located without naming a layout constant: the fake
    /// array's element words start out distinct, so a store is the one word
    /// that changes.
    #[test]
    fn r11w5_a_gated_aastore_stores_inline_and_keeps_the_helper_for_barriers() {
        extern "C" fn type_check(_vm: i64, _array: i64, _val: i64) -> i64 {
            R9W2_TYPE_CHECKS.with(|c| c.set(c.get() + 1));
            0
        }
        extern "C" fn aastore(_vm: i64, _array: i64, _index: i64, _val: i64) {
            R9W2_AASTORES.with(|c| c.set(c.get() + 1));
        }
        if !ir_aastore_enabled()
            || !crate::x64::ir_gated_ref_store_enabled()
            || !crate::x64::gated_ref_store_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
        {
            // A kill switch or narrow oops in the environment: the gated
            // store declines and the r9w2 test covers the helper route.
            return;
        }
        // `[pre, post]` gate bytes, leaked so the baked addresses stay valid.
        let gates: *mut u8 = Box::leak(Box::new([0u8, 1u8])).as_mut_ptr();
        let mut helpers = no_helpers();
        helpers.aastore = aastore as *const () as usize;
        helpers.aastore_type_check = type_check as *const () as usize;
        helpers.ref_store_pre_gate = gates as usize; // Cast: leaked address
        helpers.ref_store_post_gate = gates as usize + 1; // Cast: leaked address
        helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;
        let lower_code = |code: &[u8], params: &[IrType]| {
            let mut builder = IrBuilder::new(params.len(), params.len());
            builder.set_param_types(params);
            let graph = builder.build(code, code.len()).expect("IR build");
            let schedule = ir_schedule::schedule(&graph);
            lower(&graph, &schedule, params.len(), params.len(), &helpers).expect("lowers")
        };
        // A fake young array of length 4 (every aligned 32-bit header word
        // reads 4, see the r9w2 test), flags byte 0, element words distinct.
        let fresh_array = || -> *mut u64 {
            let mut words = [0x0000_0004_0000_0004u64; 8];
            for (w, word) in words.iter_mut().enumerate().skip(2) {
                // Cast: a word index below 8.
                *word = 0x5000 + 8 * w as u64;
            }
            Box::leak(Box::new(words)).as_mut_ptr()
        };
        let snapshot = |arr: *mut u64| -> Vec<u64> {
            // SAFETY: `arr` is a leaked 8-word array.
            (0..8)
                .map(|w| unsafe { arr.add(w).read_volatile() })
                .collect()
        };
        let set_old = |arr: *mut u64, old: bool| {
            let flags = if old {
                cratonvm_types::GC_FLAG_OLD_GEN
            } else {
                0
            };
            // SAFETY: the flags byte is inside the leaked header.
            unsafe {
                (arr as *mut u8) // Cast: word array → byte cursor
                    .add(cratonvm_types::GC_FLAGS_BYTE_OFFSET)
                    .write_volatile(flags)
            };
        };
        let counts = || {
            (
                R9W2_TYPE_CHECKS.with(|c| c.get()),
                R9W2_AASTORES.with(|c| c.get()),
            )
        };

        // static int f(Object[] a, Object v) { a[0] = v; return 1; }
        let f = lower_code(
            &[0x2a, 0x03, 0x2b, 0x53, 0x04, 0xac],
            &[IrType::Ref, IrType::Ref],
        );
        let arr = fresh_array();
        let call = |v: i64| {
            // SAFETY: the synthetic helpers never dereference their arguments,
            // and the body touches only the fake array and a fake value's
            // header (`r11w14_fake_value`).
            unsafe { f.try_call_with_context(0, &[arr as i64, v]) }.expect("call")
        };
        let base = snapshot(arr);
        // Round 11 wave 14: header-shaped values (the arm reads a non-null
        // value's header). Class 5 is not the array header's class 4, so
        // each of these is still checked; `exact` is, and is not.
        let v1 = r11w14_fake_value(5, 0, 0);
        let v2 = r11w14_fake_value(5, 0, 0);
        let v3 = r11w14_fake_value(5, 0, 0);
        let exact = r11w14_fake_value(4, 0, 0);
        let exact_on = crate::x64::checkcast_inline_enabled();

        let (tc, aa) = counts();
        assert_eq!(call(v1) as i32, 1);
        assert_eq!(
            counts(),
            (tc + 1, aa),
            "young array: checked, stored inline"
        );
        let after = snapshot(arr);
        let changed: Vec<usize> = (0..8).filter(|&w| after[w] != base[w]).collect();
        assert_eq!(changed.len(), 1, "exactly one element word written");
        let elem = changed[0];
        // Cast: a leaked address, compared as the element word it became.
        assert_eq!(after[elem], v1 as u64, "the inline store wrote the value");

        let (tc, aa) = counts();
        assert_eq!(call(exact) as i32, 1);
        assert_eq!(
            counts(),
            (tc + u32::from(!exact_on), aa),
            "young array, exact component: no check, stored inline"
        );
        // Cast: as above.
        assert_eq!(snapshot(arr)[elem], exact as u64, "the exact value stored");
        assert_eq!(call(v1) as i32, 1);

        set_old(arr, true);
        let (tc, aa) = counts();
        assert_eq!(call(v2) as i32, 1);
        assert_eq!(
            counts(),
            (tc + 1, aa + 1),
            "old array: the helper owns the card"
        );
        assert_eq!(
            snapshot(arr)[elem],
            v1 as u64, // Cast: as above.
            "the fake helper stores nothing"
        );
        let (tc, aa) = counts();
        assert_eq!(call(exact) as i32, 1);
        assert_eq!(
            counts(),
            (tc + u32::from(!exact_on), aa + 1),
            "old array, exact component: no check, the helper owns the card"
        );

        let (tc, aa) = counts();
        assert_eq!(call(0) as i32, 1);
        assert_eq!(counts(), (tc, aa), "a null value needs no post barrier");
        assert_eq!(snapshot(arr)[elem], 0, "null stored inline");

        set_old(arr, false);
        // SAFETY: the leaked pre-gate byte.
        unsafe { gates.write_volatile(1) };
        let (tc, aa) = counts();
        assert_eq!(call(v3) as i32, 1);
        assert_eq!(counts(), (tc + 1, aa + 1), "armed SATB gate: the helper");
        // SAFETY: as above.
        unsafe { gates.write_volatile(0) };

        // static int g(Object[] a) { a[0] = a[1]; return 1; }: no covariance
        // call, so no call on the fast path at all.
        let g = lower_code(
            &[0x2a, 0x03, 0x2a, 0x04, 0x32, 0x53, 0x04, 0xac],
            &[IrType::Ref],
        );
        let arr = fresh_array();
        let base = snapshot(arr);
        let (tc, aa) = counts();
        // SAFETY: as above.
        assert_eq!(
            unsafe { g.try_call_with_context(0, &[arr as i64]) }.expect("call") as i32,
            1
        );
        assert_eq!(counts(), (tc, aa), "an element move calls nothing");
        let after = snapshot(arr);
        let changed: Vec<usize> = (0..8).filter(|&w| after[w] != base[w]).collect();
        assert_eq!(changed.len(), 1, "exactly one element word written");
        assert!(
            base.contains(&after[changed[0]]),
            "the stored value is another element's"
        );
    }

    /// Round 13 wave 2 (lane irhash, W7-2): with the inline card check on
    /// (`CRATONVM_JIT_INLINE_CARD_MARK=1`), a gated `aastore` of a young value
    /// into an OLD array stores inline when the element's card is already
    /// dirty and still calls `jit_aastore` on a clean one; an old value into an
    /// old array needs no card at all; an armed SATB gate still takes the
    /// helper. Executed against a real card table over a simulated old space.
    #[cfg(target_arch = "x86_64")]
    #[test]
    fn r13w2_irhash_a_dirty_card_spares_the_aastore_helper() {
        use cratonvm_gc::card_table::{CardTable, CardTableOptions, CARD_SIZE};
        extern "C" fn type_check(_vm: i64, _array: i64, _val: i64) -> i64 {
            R9W2_TYPE_CHECKS.with(|c| c.set(c.get() + 1));
            0
        }
        extern "C" fn aastore(_vm: i64, _array: i64, _index: i64, _val: i64) {
            R9W2_AASTORES.with(|c| c.set(c.get() + 1));
        }
        if !ir_aastore_enabled()
            || !crate::x64::ir_gated_ref_store_enabled()
            || !crate::x64::gated_ref_store_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
            || !cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_INLINE_CARD_CHECK")
        {
            return;
        }
        // A simulated old generation (32 KiB, 8-aligned) and a card table over
        // exactly it, with element-precise marks as the VM's default.
        let old: &'static mut [u64] = Box::leak(vec![0u64; 4096].into_boxed_slice());
        let base = old.as_mut_ptr() as usize; // Cast: leaked address
        let end = base + old.len() * 8;
        let ct = CardTable::with_options(
            base,
            end - base,
            CardTableOptions {
                summary: false,
                precise_ref_array_marks: true,
            },
        );
        // `[pre, post]` gate bytes, leaked so the baked addresses stay valid.
        let gates: *mut u8 = Box::leak(Box::new([0u8, 1u8])).as_mut_ptr();
        let mut helpers = no_helpers();
        helpers.aastore = aastore as *const () as usize;
        helpers.aastore_type_check = type_check as *const () as usize;
        helpers.ref_store_pre_gate = gates as usize; // Cast: leaked address
        helpers.ref_store_post_gate = gates as usize + 1; // Cast: leaked address
        helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;
        helpers.jit_card_table_addr = ct.jit_card_view_addr();
        helpers.jit_card_old_base = base;
        helpers.jit_card_old_end = end;
        // static int f(Object[] a, Object v) { a[0] = v; return 1; }
        let code = [0x2a, 0x03, 0x2b, 0x53, 0x04, 0xac];
        let f = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_INLINE_CARD_MARK", Some("1"))],
            || {
                let mut builder = IrBuilder::new(2, 2);
                builder.set_param_types(&[IrType::Ref, IrType::Ref]);
                let graph = builder.build(&code, code.len()).expect("IR build");
                let schedule = ir_schedule::schedule(&graph);
                lower(&graph, &schedule, 2, 2, &helpers).expect("lowers")
            },
        );
        // The array: eight words at byte 1024 of the old space, every aligned
        // 32-bit header word reading 4 (length 4; see the r9w2 test), element
        // words distinct, then flagged old.
        let first = 1024 / 8;
        for w in 0..8usize {
            old[first + w] = if w < 2 {
                0x0000_0004_0000_0004u64
            } else {
                // Cast: a word index below 8.
                0x5000 + 8 * w as u64
            };
        }
        let arr = base + 1024;
        // SAFETY: the flags byte lies inside the array's header, in the leaked
        // old space.
        unsafe {
            ((arr + cratonvm_types::GC_FLAGS_BYTE_OFFSET) as *mut u8)
                .write_volatile(cratonvm_types::GC_FLAG_OLD_GEN)
        };
        let element = arr + HEADER_SIZE;
        let card = (element - base) / CARD_SIZE;
        // SAFETY: `element` is a word of the leaked old space.
        let read_element = || unsafe { (element as *const u64).read_volatile() };
        // An OLD value: a plain-object header (class 5) at byte 8192.
        old[8192 / 8] = 5;
        let old_value = (base + 8192) as i64; // Cast: leaked address
        let call = |v: i64| {
            // SAFETY: the synthetic helpers never dereference their arguments,
            // and the body touches only the fake array, the fake value's header
            // and the card table's own byte map.
            unsafe { f.try_call_with_context(0, &[arr as i64, v]) }.expect("call")
        };
        let aastores = || R9W2_AASTORES.with(|c| c.get());

        // Clean card: the helper owns the card (the fake one stores nothing).
        let before = read_element();
        let v1 = r11w14_fake_value(5, 0, 0);
        let aa = aastores();
        assert_eq!(call(v1) as i32, 1);
        assert_eq!(aastores(), aa + 1, "clean card: jit_aastore");
        assert_eq!(read_element(), before, "the fake helper stores nothing");

        // Dirty card: stored inline, no call, the card stays dirty.
        ct.mark_dirty_lockfree(element);
        assert!(ct.is_dirty(card));
        let v2 = r11w14_fake_value(5, 0, 0);
        let aa = aastores();
        assert_eq!(call(v2) as i32, 1);
        assert_eq!(aastores(), aa, "dirty card: no call");
        assert_eq!(read_element(), v2 as u64, "stored inline"); // Cast: the stored word
        assert!(ct.is_dirty(card));

        // Old -> old: no card needed, clean or not.
        ct.clear_all();
        let aa = aastores();
        assert_eq!(call(old_value) as i32, 1);
        assert_eq!(aastores(), aa, "old value: no call");
        assert_eq!(read_element(), old_value as u64, "stored inline"); // Cast: as above
        assert!(!ct.is_dirty(card), "compiled code never dirties a card");

        // An armed SATB gate takes the helper even over a dirty card.
        ct.mark_dirty_lockfree(element);
        // SAFETY: the leaked pre-gate byte.
        unsafe { gates.write_volatile(1) };
        let aa = aastores();
        assert_eq!(call(r11w14_fake_value(5, 0, 0)) as i32, 1);
        assert_eq!(aastores(), aa + 1, "armed SATB gate: the helper");
        // SAFETY: as above.
        unsafe { gates.write_volatile(0) };
    }

    /// Round 9 wave 2 (deopt #3 + the callee-deopt ordering page): the
    /// service's cold side copies the site's shadow words back into their
    /// homes — without consuming the publication or retracting `top` — BEFORE
    /// it loads the service helper, and its sentinel test is `CMP RAX,1; JNO`.
    #[test]
    fn r9w2_the_callee_deopt_service_copies_back_before_it_stages() {
        const SERVICE: u64 = 0x7fff_0000_0000_5000;
        let mut lo = lowerer_with_resident_xmm(4096, None);
        lo.service_callee_deopt = SERVICE as usize;
        lo.get_current_thread = 0x7fff_0000_0000_6000;
        lo.shadow_thread_slot_off = 16;
        lo.shadow_savebase_slot_off = 24;
        lo.pending_shadow = vec![40, 48];
        let pos = |hay: &[u8], needle: &[u8]| hay.windows(needle.len()).position(|w| w == needle);

        let start = lo.buf.pos();
        lo.emit_inline_callee_deopt_service(0x1234, 0, &[], false);
        let code = lo.buf.as_slice()[start..].to_vec();
        assert!(
            code.starts_with(&[0x48, 0x83, 0xF8, 0x01, 0x0F, 0x81]),
            "the sentinel test must be `CMP RAX, 1; JNO rel32`: {:02x?}",
            &code[..code.len().min(8)]
        );
        let copy_at = pos(&code, &[0x49, 0x8B, 0x0B]).expect("MOV RCX, [R11]: the copy-back");
        let svc_at = pos(&code, &SERVICE.to_le_bytes()).expect("the service helper is called");
        assert!(copy_at < svc_at, "copy back first, then service");
        assert_eq!(
            count_seq(&code, &[0x49, 0x8B, 0x0B]),
            2,
            "one copy per published word"
        );
        assert!(
            !contains_seq(&code, &[0x4D, 0x89, 0x9A]),
            "the cold copy-back must not retract `top` (`MOV [R10+ss_top], R11`)"
        );
        assert_eq!(
            lo.pending_shadow,
            vec![40, 48],
            "the site's own reload still owns it"
        );
        assert_eq!(lo.shadow_reloads, 0, "not a reload for the balance check");

        // The merged route has already reloaded: nothing copied again.
        let start = lo.buf.pos();
        lo.emit_inline_callee_deopt_service(0x1234, 0, &[], true);
        let code = lo.buf.as_slice()[start..].to_vec();
        assert!(!contains_seq(&code, &[0x49, 0x8B, 0x0B]));
    }

    /// Round 11 wave 10 (lane irexc,
    /// `r11w9-lower-ir-tier-never-compiles-a-javac-synchronized-block`): a
    /// call-exception exit inside a protected range gets a reason-9 rethrow
    /// pad — a `PendingException` box at the THROW bci, RETHROW semantics, an
    /// empty operand stack — and NOT a `call_exc_patches` row; an exit at the
    /// range's exclusive end keeps the plain bail. The pad stamps the bci, loads
    /// its point and jumps to the shared deopt stub.
    #[test]
    fn r11w10_a_protected_call_exit_gets_a_rethrow_pad_not_the_bail_stub() {
        const SET_THROW_BCI: u64 = 0x7fff_0000_0000_7000;
        let mut lo = lowerer_with_resident_xmm(4096, None);
        lo.set_throw_bci = SET_THROW_BCI as usize;
        lo.protected_ranges = vec![(4, 14)];

        lo.cur_bci = 9;
        lo.buf.emit(&[0x0F, 0x80]); // JO rel32
        let inside = lo.buf.pos();
        lo.buf.emit(&[0, 0, 0, 0]);
        let boxes_before = lo.deopt_boxes.len();
        lo.push_call_exc_patch(inside);
        assert!(
            lo.call_exc_patches.is_empty(),
            "a protected exit must not reach the params-only bail stub"
        );
        assert_eq!(lo.rethrow_pads.len(), 1);
        assert_eq!(lo.deopt_boxes.len(), boxes_before + 1);
        let point = lo.deopt_boxes.last().expect("the pad's point is boxed");
        assert_eq!(point.bci, 9, "keyed on the throwing bci, not its successor");
        assert_eq!(point.frame_state.bci, 9);
        assert_eq!(point.reason, DeoptReason::PendingException);
        assert!(point.semantics.rethrow_exception);
        assert!(
            point.frame_state.stack.is_empty(),
            "JVMS 2.10: handler entry"
        );
        assert_eq!(
            lo.rethrow_points.len(),
            1,
            "a by-value copy for `deopt_points`"
        );
        assert!(lo.transfer_bcis.contains(&9));

        lo.cur_bci = 14;
        lo.buf.emit(&[0x0F, 0x80]);
        let outside = lo.buf.pos();
        lo.buf.emit(&[0, 0, 0, 0]);
        lo.push_call_exc_patch(outside);
        assert_eq!(
            lo.call_exc_patches,
            vec![(outside, 14)],
            "end_pc is exclusive: the plain exit"
        );
        assert_eq!(lo.rethrow_pads.len(), 1);

        let point_ptr = lo.rethrow_pads[0].point_ptr;
        let start = lo.buf.pos();
        lo.emit_rethrow_pads();
        let code = lo.buf.as_slice()[start..].to_vec();
        assert!(lo.rethrow_pads.is_empty());
        assert_eq!(
            lo.deopt_stub_patches.len(),
            1,
            "one JMP to the shared deopt stub"
        );
        assert!(
            contains_seq(&code, &SET_THROW_BCI.to_le_bytes()),
            "the pad stamps this method's throw bci: {code:02x?}"
        );
        assert!(
            contains_seq(&code, &point_ptr.to_le_bytes()),
            "the pad hands the stub its own point: {code:02x?}"
        );
        let mut rel = [0u8; 4];
        rel.copy_from_slice(&lo.buf.as_slice()[inside..inside + 4]);
        assert_eq!(
            inside as i64 + 4 + i64::from(i32::from_le_bytes(rel)),
            start as i64,
            "the site's exceptional branch lands on the pad"
        );
    }

    /// Round 11 wave 10 (lane irexc): the frames the reason-9 consumers would
    /// propagate past a matching handler are refused at compile time, and a
    /// lock the compiled code holds itself is not one of them.
    #[test]
    fn r11w10_a_rethrow_frame_the_consumers_cannot_take_is_refused() {
        let held = crate::deopt::MonitorInfo {
            object: FrameValue::StackSlotRef(-16),
            lock_depth: 1,
            relock: false,
        };
        let base = FrameState {
            method_key: String::new(),
            bci: 3,
            locals: vec![FrameValue::Int(1), FrameValue::StackSlotRef(-16)],
            stack: Vec::new(),
            monitors: vec![held],
            caller: None,
        };
        assert_eq!(
            rethrow_frame_refusal(&base),
            None,
            "a held lock is released once, by the handler's own monitorexit"
        );
        let mut relock = base.clone();
        relock.monitors[0].relock = true;
        assert!(rethrow_frame_refusal(&relock).is_some());
        let mut unsupported = base.clone();
        unsupported.locals[0] = FrameValue::Unsupported;
        assert!(rethrow_frame_refusal(&unsupported).is_some());
        let mut virtual_local = base.clone();
        virtual_local.locals[1] = FrameValue::VirtualObjectRef(7);
        assert!(rethrow_frame_refusal(&virtual_local).is_some());
        let mut lost_lock = base.clone();
        lost_lock.monitors[0].object = FrameValue::Unsupported;
        assert!(rethrow_frame_refusal(&lost_lock).is_some());
        let mut chain = base.clone();
        chain.caller = Some(Box::new(base.clone()));
        assert!(rethrow_frame_refusal(&chain).is_some());
    }

    /// Round 11 wave 11 (lane irexc,
    /// `r11w10-orch-osr-exc-exits-loses-handler-updated-locals`):
    /// `R11SyncCallerHoldsCalleeLock.throwLoop`'s shape — a counted loop whose
    /// protected call's `catch` bumps a counter and falls back into the loop —
    /// lowered on the precise-frame route. The call gets its rethrow pad; the
    /// header, which the handler reaches, gets NO OSR entry, because the
    /// graph's header facts (`caught` is `φ(0, itself)`, collapsed to the
    /// constant 0) exclude the handler's path. The control lowers the same
    /// graph with no handler reach and keeps the entry, which is what every
    /// body did before the fix — so the second half fails without it.
    #[test]
    fn r11w11_a_header_a_handler_reaches_gets_no_osr_entry_beside_a_rethrow_pad() {
        crate::x64::set_moving_young_override(Some(false));
        let _osr = OsrEntryForce::on();
        //  0 iconst_0; 1 istore_1; 2 iconst_0; 3 istore_2
        //  4 iload_2  <- header;  5 iload_0; 6 if_icmpge 27
        //  9 iload_2  <- try [9, 14); 10 invokestatic #1; 13 pop; 14 goto 21
        // 17 astore_3 <- handler;   18 iinc 1, 1
        // 21 iinc 2, 1; 24 goto 4;  27 iload_1; 28 ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x15, 0x1c, 0xb8, 0x00, 0x01, 0x57,
            0xa7, 0x00, 0x07, 0x4e, 0x84, 0x01, 0x01, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xec, 0x1b,
            0xac, 0x00, 0x00,
        ];
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/T",
            method_name: "divSync",
            descriptor: "(I)I",
            num_jit_args: 1,
            return_type: b'I',
            invoke_kind: 3, // static
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let lower_with = |reachable: Option<&[u32]>| {
            let mut builder = IrBuilder::new(1, 4);
            builder.set_param_types(&[IrType::Int]);
            let mut invoke_info = HashMap::new();
            invoke_info.insert(
                10usize,
                (info as *const JitInvokeInfo as usize, 1usize, b'I'),
            );
            builder.set_invoke_info(invoke_info);
            let mut graph = builder.build(&code, 29).expect("IR build of the loop");
            ir_optimize::optimize(&mut graph);
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.invoke_dispatch = 0x1111_2222_3333_4440;
            helpers.dispatch_threw = 0x1111_2222_3333_4442;
            let empty_hints: HashMap<usize, bool> = HashMap::new();
            let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
            let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
            let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
            lower_inner_with_protected_ranges(
                &crate::DirectHelperTable::EMPTY,
                &graph,
                &schedule,
                1,
                4,
                &helpers,
                &empty_hints,
                &[],
                None,
                &no_direct,
                &no_ic,
                &no_compact,
                &crate::ir::IrInlineFrameSites::default(),
                &HashMap::new(),
                &std::collections::HashSet::new(),
                None,
                &[(9, 14)],
                reachable,
            )
            .expect("the loop lowers on the precise-frame route")
        };
        let has_pad = |cm: &CompiledMethod| {
            cm.deopt_points
                .iter()
                .any(|p| p.bci == 10 && p.reason == DeoptReason::PendingException)
        };

        let control = lower_with(Some(&[][..]));
        assert!(
            has_pad(&control),
            "the protected call exits through a rethrow pad"
        );
        assert!(
            control.ir_osr_entry_addr(4).is_some(),
            "control: with no handler reach the header keeps its entry (if this \
             fails the fixture lost its entry for another reason — see the \
             `CRATONVM_DBG_IR_LINEAR_SCAN` refusal census — not the fix)"
        );

        let reach = crate::deopt::pcs_reachable_from_handlers(&code, &[17]);
        let fixed = lower_with(reach.as_deref());
        assert!(has_pad(&fixed));
        assert!(
            fixed.ir_osr_entry_addr(4).is_none(),
            "the handler at 17 falls back to the header: re-entering there would \
             read `caught` as the collapsed constant"
        );
        // Unanalysable handler reach withholds every entry of such a body.
        let unknown = lower_with(None);
        assert!(unknown.ir_osr_entries.is_empty());
    }

    /// Round 11 wave 13 (lane irexc), item 3 of
    /// `r11w9-tier-optimizing-osr-exception-exits-door-contract-patch`: the
    /// zero-divisor `Op::Guard` `add_div_zero_guard` plants at an
    /// `idiv`/`lrem` is EXACT (the re-executed bytecode throws), so it no
    /// longer withdraws `ir_osr_guard_exit_bcis`. Asked at any other bci —
    /// where the snapshot's top of stack is not the divisor — it is not.
    #[test]
    fn r11w13_a_zero_divisor_guard_is_exact_at_its_division_only() {
        let lowered = |code: &[u8], params: &[IrType], locals: usize| {
            let mut builder = IrBuilder::new(params.len(), locals);
            builder.set_param_types(params);
            let graph = builder
                .build(code, code.len())
                .expect("IR build of the division");
            let graph: &'static Graph = Box::leak(Box::new(graph));
            let schedule: &'static Schedule = Box::leak(Box::new(ir_schedule::schedule(graph)));
            let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
            let lo = lowerer_over(graph, schedule, plan, 4096);
            let guard = graph
                .nodes
                .iter()
                .position(|n| matches!(n.op, Op::Guard { bci: 2 }))
                .expect("the zero-divisor guard at the division's bci");
            // Cast: a node index is a `NodeId`.
            (lo, guard as NodeId)
        };
        // 0 iload_0; 1 iload_1; 2 idiv; 3 ireturn
        let int_params = [IrType::Int, IrType::Int];
        let (lo, guard) = lowered(&[0x1au8, 0x1b, 0x6c, 0xac][..], &int_params[..], 2);
        assert!(lo.op_guard_is_exact(guard, 2));
        assert!(
            !lo.op_guard_is_exact(guard, 3),
            "the divisor is not on top at 3"
        );
        assert!(!lo.op_guard_is_exact(guard, 0), "empty stack at 0");
        // 0 lload_0; 1 lload_2; 2 lrem; 3 lreturn
        let long_params = [IrType::Long, IrType::Long];
        let (lo, guard) = lowered(&[0x1eu8, 0x20, 0x71, 0xad][..], &long_params[..], 4);
        assert!(lo.op_guard_is_exact(guard, 2));
    }

    /// Round 9 wave 2 (`ir-bailouts-latched-after-the-latch-check-are-dropped`):
    /// a dropped home no register describes latches `UnallocatedValue` — except
    /// while `build_deopt_points` resolves a point no deopt can arrive at.
    #[test]
    fn r9w2_a_dropped_home_latches_only_where_a_deopt_can_arrive() {
        let mut lo = lowerer_with_resident_xmm(4096, None);
        // `add_one_graph`: n5 is the `Add`.
        let sum: NodeId = 5;
        assert!(matches!(lo.graph.nodes[sum as usize].op, Op::Add));
        lo.home_dropped = vec![false; lo.graph.nodes.len()];
        lo.home_dropped[sum as usize] = true;

        lo.quiet_dropped_home.set(true);
        assert!(matches!(lo.frame_value_for(sum), FrameValue::Unsupported));
        assert!(
            lo.take_latched_bailout().is_none(),
            "quiet: nothing latched"
        );

        lo.quiet_dropped_home.set(false);
        assert!(matches!(lo.frame_value_for(sum), FrameValue::Unsupported));
        let b = lo.take_latched_bailout().expect("enforced: latched");
        assert!(matches!(b.reason, BailoutReason::UnallocatedValue { node } if node == sum));
    }

    /// …and `build_deopt_points` is what sets the quiet flag: a by-bci point at
    /// a bci the body cannot transfer from resolves quietly, the same point at
    /// a bci it CAN transfer from latches (for `lower_inner`'s second check).
    #[test]
    fn r9w2_build_deopt_points_enforces_the_latch_only_at_transfer_bcis() {
        let (mut graph, _) = add_one_graph();
        graph
            .safepoints
            .push(SafepointSnapshot::new(3, vec![5], Vec::new(), Vec::new()));
        let schedule = ir_schedule::schedule(&graph);
        let graph: &'static Graph = Box::leak(Box::new(graph));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
        let mut lo = lowerer_over(graph, schedule, plan, 4096);
        lo.home_dropped = vec![false; graph.nodes.len()];
        lo.home_dropped[5] = true;
        lo.bci_native.insert(3, 0);

        let points = lo.build_deopt_points(false);
        assert_eq!(points.len(), 1);
        assert!(lo.take_latched_bailout().is_none(), "bci 3 cannot transfer");

        lo.transfer_bcis.insert(3);
        let _ = lo.build_deopt_points(false);
        assert!(
            lo.take_latched_bailout().is_some(),
            "at a transfer bci the undescribable value must refuse the compile"
        );
        assert!(
            !lo.quiet_dropped_home.get(),
            "the flag is reset after each point"
        );
    }

    /// Round 9 wave 2 (`ir-scalar-deopt-sites-keyed-by-raw-pc-inside-splices`):
    /// a guard inside a spliced body fires the deopt at the ENCLOSING invoke,
    /// so `deopt_block_for_snapshot(_, invoke)` must find it; a division is judged
    /// anchored by ITS OWN raw pc, not by the invoke.
    #[test]
    fn r9w2_spliced_guards_and_divisions_are_indexed_at_their_resume_bci() {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let a = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let b = g.add(Op::Param(1), IrType::Int, vec![start], None);
        let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
        let cond = g.add(
            Op::Cmp(crate::ir::CmpOp::Ne),
            IrType::Int,
            vec![b, zero],
            Some(40),
        );
        // The builder's div-zero guard for the division at raw pc 40.
        let guard = g.add(
            Op::Guard { bci: 40 },
            IrType::Void,
            vec![ctrl, cond],
            Some(40),
        );
        let anchored_div = g.add(Op::Div, IrType::Int, vec![a, b], Some(40));
        // A second division in the same splice with NO guard at its own pc.
        let lone_div = g.add(Op::Div, IrType::Int, vec![anchored_div, b], Some(41));
        g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, lone_div], Some(42));
        let schedule = ir_schedule::schedule(&g);
        let graph: &'static Graph = Box::leak(Box::new(g));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
        let mut lo = lowerer_over(graph, schedule, plan, 4096);
        // The relocated body 9..43 stands in for the invoke at bci 5.
        let spliced: &'static [(usize, usize, usize)] =
            Box::leak(Box::new([(9usize, 43usize, 5usize)]));
        lo.spliced_ranges = spliced;
        lo.deopt_sites_by_bci = Lowerer::index_deopt_sites(graph, spliced);

        assert!(
            lo.deopt_sites_by_bci
                .get(&5)
                .is_some_and(|v| v.contains(&guard) && v.contains(&lone_div)),
            "both sites resume at the invoke and must be indexed there: {:?}",
            lo.deopt_sites_by_bci
        );
        assert!(
            lo.deopt_sites_by_bci.get(&40).is_none(),
            "nothing is keyed by a raw pc"
        );
        assert!(lo.fires_deopt_at(&graph.nodes[guard as usize], 5));
        assert!(
            !lo.fires_deopt_at(&graph.nodes[anchored_div as usize], 5),
            "the guard at the division's own pc owns its trap"
        );
        assert!(
            lo.fires_deopt_at(&graph.nodes[lone_div as usize], 5),
            "a division with no guard at ITS pc traps itself, whatever else the splice holds"
        );
    }

    /// Round 9 wave 2 (`ir-code-buffer-overflow-is-a-permanent-fallback`): a
    /// first attempt that overflows is lowered again at `wanted()` and the
    /// method still gets a correct body.
    #[test]
    fn r9w2_a_code_buffer_overflow_is_retried_at_the_exact_size() {
        // The do-while loop of `do_while_latch_with_one_sided_phi_copies_runs_correctly`.
        let code: [u8; 18] = [
            0x03, 0x3c, 0x03, 0x3d, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01, 0x1c, 0x1a, 0xa1,
            0xff, 0xf7, 0x1b, 0xac,
        ];
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        let graph = IrBuilder::new(1, 3)
            .build(&code, code.len())
            .expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
        helpers.safepoint_slow_path = slow_poll as *const () as usize;
        let retries_before = ir_buffer_overflow_retries();
        IR_FIRST_ATTEMPT_CAPACITY_FOR_TEST.with(|c| c.set(Some(16)));
        let compiled = lower(&graph, &schedule, 1, 3, &helpers);
        IR_FIRST_ATTEMPT_CAPACITY_FOR_TEST.with(|c| c.set(None));
        let compiled = compiled.expect("an overflowed first attempt must be retried, not refused");
        assert!(
            ir_buffer_overflow_retries() > retries_before,
            "the retry path ran"
        );
        for (n, want) in [(0i64, 0i32), (1, 0), (5, 10), (100, 4950)] {
            // SAFETY: one int argument, int result; the poll flag is a static zero.
            let got = unsafe { compiled.try_call(&[n]) }.expect("call");
            // Cast: this tier's `int` result is the low 32 bits.
            assert_eq!(got as i32, want, "f({n})");
        }
    }

    /// Round 9 wave 2: a volatile static LOAD emits no `MFENCE` unless
    /// `CRATONVM_JIT_VOLATILE_LOAD_FENCE=1` asks for the old fence back.
    #[test]
    fn r9w2_a_volatile_static_load_has_no_fence_unless_asked() {
        extern "C" fn getstatic(_vm: i64, _class_id: i64, _field_index: i64) -> i64 {
            42
        }
        let build = || {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            g.entry = start;
            let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let load = g.add(
                Op::LoadStatic {
                    class_id: 3,
                    field_index: 1,
                    type_tag: b'I',
                    is_volatile: true,
                },
                IrType::Int,
                vec![ctrl, mem],
                Some(0),
            );
            g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, load], Some(3));
            g
        };
        let mut helpers = no_helpers();
        helpers.getstatic = getstatic as *const () as usize;
        let lower_it = || {
            let g = build();
            let sch = ir_schedule::schedule(&g);
            lower(&g, &sch, 0, 0, &helpers).expect("volatile getstatic lowers")
        };
        const MFENCE: [u8; 3] = [0x0F, 0xAE, 0xF0];
        let plain = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_VOLATILE_LOAD_FENCE", None)],
            || lower_it(),
        );
        assert!(
            !contains_seq(plain.code_bytes(), &MFENCE),
            "no load-side fence by default"
        );
        // SAFETY: the synthetic helper ignores its arguments.
        let got = unsafe { plain.try_call_with_context(0, &[]) }.expect("call");
        // Cast: this tier's `int` result is the low 32 bits.
        assert_eq!(got as i32, 42);
        let fenced = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_VOLATILE_LOAD_FENCE", Some("1"))],
            || lower_it(),
        );
        assert!(
            contains_seq(fenced.code_bytes(), &MFENCE),
            "the kill switch restores it"
        );
    }

    /// Round 11 wave 10 (lane irstatic, `r11w9-lower-ir-putstatic-patch`): an
    /// `Op::StoreStatic` calls its width's `jit_putstatic_*` helper with
    /// `(vm, class_id, field_index, value)`; a sentinel answer leaves through
    /// the exception stub instead of falling through to the rest of the body;
    /// a volatile write is followed by the StoreLoad `LOCK ADD` and a plain one
    /// is not; and a graph whose helper is absent is refused.
    #[test]
    fn r11w10_a_store_static_calls_its_helper_and_fences_only_when_volatile() {
        // Answers 0 only for the exact arguments the graph below bakes, so a
        // wrong marshal shows up as the sentinel exit.
        extern "C" fn putstatic_checks(_vm: i64, class_id: i64, field_index: i64, val: i64) -> i64 {
            if class_id == 3 && field_index == 1 && val as i32 == 42 {
                0
            } else {
                i64::MIN
            }
        }
        extern "C" fn putstatic_throws(_vm: i64, _c: i64, _f: i64, _v: i64) -> i64 {
            i64::MIN
        }
        let build = |type_tag: u8, is_volatile: bool| {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            g.entry = start;
            let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let value = g.add(Op::Const(42), IrType::Int, vec![], None);
            let _store = g.add(
                Op::StoreStatic {
                    class_id: 3,
                    field_index: 1,
                    type_tag,
                    is_volatile,
                },
                IrType::Memory,
                vec![ctrl, mem, value],
                Some(1),
            );
            let seven = g.add(Op::Const(7), IrType::Int, vec![], None);
            g.exit = g.add(Op::Return, IrType::Void, vec![ctrl, seven], Some(4));
            g
        };
        let lower_with = |g: &Graph, helpers: &JitRuntimeHelpers| {
            let sch = ir_schedule::schedule(g);
            lower(g, &sch, 0, 0, helpers)
        };
        const LOCK_ADD: [u8; 5] = [0xF0, 0x83, 0x04, 0x24, 0x00];

        let mut helpers = no_helpers();
        helpers.putstatic_int = putstatic_checks as *const () as usize;
        let plain = lower_with(&build(b'I', false), &helpers).expect("putstatic lowers");
        assert!(
            !contains_seq(plain.code_bytes(), &LOCK_ADD),
            "a plain static write owes no fence"
        );
        // SAFETY: the synthetic helper ignores the context argument.
        let got = unsafe { plain.try_call_with_context(0, &[]) }.expect("call");
        // Cast: this tier's `int` result is the low 32 bits.
        assert_eq!(
            got as i32, 7,
            "the helper accepted the marshalled arguments"
        );

        let fenced = lower_with(&build(b'I', true), &helpers).expect("volatile putstatic lowers");
        assert!(
            contains_seq(fenced.code_bytes(), &LOCK_ADD),
            "a volatile static write is followed by the StoreLoad fence"
        );

        // A `<clinit>` failure: the helper answers the sentinel and the body
        // must leave through the exception stub rather than return 7.
        helpers.putstatic_int = putstatic_throws as *const () as usize;
        let throwing = lower_with(&build(b'I', false), &helpers).expect("lowers");
        // SAFETY: as above.
        let got = unsafe { throwing.try_call_with_context(0, &[]) }.expect("call");
        assert_eq!(got, i64::MIN, "a failed putstatic must not fall through");

        // An absent helper refuses the graph rather than CALL address zero.
        helpers.putstatic_int = 0;
        assert!(
            lower_with(&build(b'I', false), &helpers).is_none(),
            "no putstatic_int helper -> refuse"
        );
    }

    /// Round 9 wave 2 (`ir-safepoint-maps-publish-ref-slots-this-path-never-wrote`):
    /// a reference defined outside the entry block has its colour zeroed in the
    /// prologue; one defined IN the entry block (every path writes it before
    /// any map can name it) does not, except in an OSR stub, which skips that
    /// block.
    #[test]
    fn r9w2_reference_colours_outside_the_entry_block_are_zeroed() {
        // `if (c != 0) r = a[c]; else r = a; return r;` with `a` an Object[].
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let arr = g.add(Op::Param(0), IrType::Ref, vec![start], None);
        let c = g.add(Op::Param(1), IrType::Int, vec![start], None);
        let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
        let cmp = g.add(
            Op::Cmp(crate::ir::CmpOp::Ne),
            IrType::Int,
            vec![c, zero],
            Some(1),
        );
        let iff = g.add(Op::If, IrType::Control, vec![ctrl, cmp], Some(1));
        let t = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
        let f = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
        let elem = g.add(
            Op::ArrayLoad(MemKind::Ref),
            IrType::Ref,
            vec![t, mem, arr, c],
            Some(4),
        );
        let merge = g.add(Op::Merge, IrType::Control, vec![t, f], None);
        let phi = g.add(Op::Phi, IrType::Ref, vec![merge, elem, arr], None);
        g.exit = g.add(Op::Return, IrType::Void, vec![merge, phi], Some(9));
        let schedule = ir_schedule::schedule(&g);
        let graph: &'static Graph = Box::leak(Box::new(g));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
        let entry_block = schedule.node_to_block[start as usize];
        assert_ne!(
            schedule.node_to_block[elem as usize], entry_block,
            "the fixture's reference must be defined outside the entry block"
        );
        let Some(color) = plan.node_color[elem as usize] else {
            panic!("the element load must have a planned colour");
        };
        let mut lo = lowerer_over(graph, schedule, plan, 4096);
        // Cast: a colour index times 8, the `planned_slot_off` arithmetic.
        let off = lo.first_spill + (color as i32) * 8;
        let store = {
            let mut v = vec![0x48, 0xC7, 0x85];
            v.extend_from_slice(&(-off).to_le_bytes());
            v.extend_from_slice(&0i32.to_le_bytes());
            v
        };
        let start_pos = lo.buf.pos();
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_ZERO_REF_SLOTS", None)],
            || lo.zero_ref_value_slots(true),
        );
        let code = lo.buf.as_slice()[start_pos..].to_vec();
        assert!(
            contains_seq(&code, &store),
            "the non-entry reference's word is zeroed"
        );

        let start_pos = lo.buf.pos();
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_ZERO_REF_SLOTS", Some("0"))],
            || lo.zero_ref_value_slots(true),
        );
        assert_eq!(lo.buf.pos(), start_pos, "the kill switch emits nothing");
    }

    /// Round 9 (irlower): `clobbered_within` is the binary-searched form of
    /// the linear `any(pos in lo..=hi && regs.contains(reg))` scans it
    /// replaced. Checked against that scan over every window of a small list.
    #[test]
    fn clobbered_within_agrees_with_the_linear_scan() {
        use crate::regalloc::PhysReg;
        let rbx = PhysReg::gp(3);
        let r12 = PhysReg::gp(12);
        let clobbers: Vec<(usize, Vec<PhysReg>)> = vec![
            (2, vec![rbx]),
            (5, vec![r12]),
            (9, vec![rbx, r12]),
            (14, vec![r12]),
        ];
        for lo in 0..16usize {
            for hi in lo..16usize {
                for reg in [rbx, r12, PhysReg::gp(13)] {
                    let linear = clobbers
                        .iter()
                        .any(|(p, regs)| *p >= lo && *p <= hi && regs.contains(&reg));
                    assert_eq!(
                        super::clobbered_within(&clobbers, lo, hi, reg),
                        linear,
                        "window {lo}..={hi}, {reg:?}"
                    );
                }
            }
        }
    }

    /// Round 9 (irlower): a guard's deopt path is OUT OF LINE. At the guard
    /// site there is exactly one `Jcc rel32` on the FAILING condition and
    /// nothing else — the passing path falls straight through — and the pad
    /// (`MOV DEOPT_ARG0, point; JMP stub`) appears only when
    /// `emit_deopt_pads` runs, with the `Jcc` patched to its first byte and
    /// its `JMP` queued for the shared stub.
    #[test]
    fn a_guard_falls_through_on_success_and_its_deopt_pad_is_out_of_line() {
        let mut lo = lowerer_with_resident_xmm(4096, None);
        lo.buf.emit(&[0x48, 0x85, 0xC0]); // TEST RAX, RAX
        let guard_at = lo.buf.pos();
        lo.emit_deopt_if_zero(0, DeoptReason::NullCheck);
        let after_guard = lo.buf.pos();
        assert_eq!(
            after_guard - guard_at,
            6,
            "the guard site must be one `Jcc rel32` and nothing else"
        );
        let code = lo.buf.as_slice().to_vec();
        assert_eq!(
            &code[guard_at..guard_at + 2],
            &[0x0F, 0x84],
            "deopt on ZF (JZ): the inverse of `emit_deopt_if_zero`'s JNZ-continue"
        );
        assert!(
            lo.deopt_stub_patches.is_empty(),
            "no stub JMP until the pads are emitted"
        );
        assert_eq!(lo.deopt_pads.len(), 1);

        lo.emit_deopt_pads();
        assert!(lo.deopt_pads.is_empty());
        assert_eq!(
            lo.deopt_stub_patches.len(),
            1,
            "the pad's JMP targets the shared stub"
        );
        let code = lo.buf.as_slice().to_vec();
        let mut rel_bytes = [0u8; 4];
        rel_bytes.copy_from_slice(&code[guard_at + 2..guard_at + 6]);
        assert_eq!(
            i32::from_le_bytes(rel_bytes),
            0,
            "the Jcc lands on the pad, which here is the next byte after the guard"
        );
        let jmp_patch = *lo.deopt_stub_patches.last().expect("one patch");
        assert_eq!(code[jmp_patch - 1], 0xE9, "the pad ends in JMP rel32");
    }

    /// Round 13 wave 11 (lane chain5, CH-1): the forced chain deopt block is
    /// emitted only under its switch, counts in a counter the lowerer owns,
    /// preserves RAX and the flags on the path that continues, and jumps to a
    /// pad for the SAME point (so the stub gets the chain the guard publishes).
    #[test]
    fn a_forced_chain_deopt_counts_and_shares_the_points_pad() {
        let mut lo = lowerer_with_resident_xmm(4096, None);
        lo.forced_chain_deopts = false;
        let at = lo.buf.pos();
        lo.emit_forced_chain_deopt(0x1234);
        assert_eq!(lo.buf.pos(), at, "switch off: nothing is emitted");
        assert!(lo.deopt_pads.is_empty());
        assert!(lo.forced_chain_deopt_counters.is_empty());

        lo.forced_chain_deopts = true;
        lo.emit_forced_chain_deopt(0x1234);
        let code = lo.buf.as_slice()[at..].to_vec();
        assert_eq!(code.len(), 25);
        assert_eq!(&code[..4], &[0x9C, 0x50, 0x48, 0xB8], "PUSHFQ; PUSH RAX; MOV RAX, imm64");
        let counter = lo
            .forced_chain_deopt_counters
            .last()
            .expect("one counter per chain point");
        let addr = counter.as_ref() as *const std::sync::atomic::AtomicU8 as u64;
        assert_eq!(&code[4..12], &addr.to_le_bytes(), "the counter is the one owned");
        assert_eq!(
            &code[12..],
            &[0x80, 0x00, 0x04, 0x58, 0x75, 0x06, 0x9D, 0xE9, 0, 0, 0, 0, 0x9D],
            "ADD BYTE [RAX], 4; POP RAX; JNZ keep; POPFQ; JMP pad; keep: POPFQ"
        );
        assert_eq!(lo.deopt_pads, vec![(at + 20, 0x1234)], "the point's own pad");
    }

    /// The shared deopt stub retracts a frame block, and only a frame block.
    ///
    /// A guard is never inside a call, so under per-call publication nothing is
    /// outstanding when one fails and the stub has always skipped the restore.
    /// A block is outstanding from the first safepoint to the return — and a
    /// block left above `top` is a set of tagged addresses into a frame that
    /// is dead the moment the stub returns.
    #[test]
    fn the_deopt_stub_retracts_a_frame_block() {
        let savetop_load = |lo: &Lowerer<'_>| {
            let mut n = vec![0x4C, 0x8B, 0x9D];
            n.extend_from_slice(&(-lo.shadow_savetop_slot_off).to_le_bytes());
            n
        };
        for block in [false, true] {
            let mut lo = lowerer_with_resident_xmm(4096, None);
            lo.get_current_thread = 0x7fff_0000_0000_3000;
            lo.shadow_off_in_thread = 0x40;
            assert!(lo.shadow_thread_slot_off > 0 && lo.shadow_savetop_slot_off > 0);
            if block {
                lo.frame_block = vec![8];
            }
            lo.buf.emit_byte(0xE9);
            lo.deopt_stub_patches.push(lo.buf.pos());
            lo.buf.emit(&[0, 0, 0, 0]);
            let stub = lo.buf.pos();
            lo.emit_deopt_stub();
            let code = lo.buf.as_slice()[stub..].to_vec();
            assert_eq!(
                count_seq(&code, &savetop_load(&lo)),
                usize::from(block),
                "block={block}: the stub restores the entry watermark exactly when a block can be outstanding"
            );
        }
    }

    /// Finding #84 on the optimizing tier: JVMS §6.5 `ireturn` narrows a
    /// `Z`/`B`/`C`/`S` return. The builder inserts the same nodes `i2b`/`i2c`/
    /// `i2s`/`iand` build, so only the low 32 bits of RAX are this tier's
    /// `int` and that is what is compared.
    #[test]
    fn ireturn_narrows_boolean_byte_char_short_returns() {
        static FLAG: u8 = 0;
        extern "C" fn slow_poll() {}
        let cases: [(&[u8], usize, &str, &[i64], i32); 6] = [
            (&[0x05, 0xac], 0, "()Z", &[], 0),               // iconst_2
            (&[0x11, 0x00, 0xC8, 0xac], 0, "()B", &[], -56), // sipush 200
            (&[0x02, 0xac], 0, "()C", &[], 65535),           // iconst_m1
            (&[0x1a, 0xac], 1, "(I)S", &[70000], 4464),      // iload_0
            (&[0x1a, 0xac], 1, "(I)S", &[-70000], -4464),    // iload_0
            (&[0x1a, 0xac], 1, "(I)I", &[70000], 70000),     // control
        ];
        for (code, n, desc, args, want) in cases {
            let mut builder = IrBuilder::new(n, n);
            builder.set_return_descriptor(desc);
            let graph = builder.build(code, code.len()).expect("IR build");
            let schedule = ir_schedule::schedule(&graph);
            let mut helpers = no_helpers();
            helpers.safepoint_flag_addr = &FLAG as *const u8 as usize;
            helpers.safepoint_slow_path = slow_poll as *const () as usize;
            let compiled = lower(&graph, &schedule, n, n, &helpers)
                .unwrap_or_else(|| panic!("{desc} must lower"));
            // SAFETY: the lowered body takes exactly `n` int arguments and
            // returns an int; the poll flag is a static zero.
            let got = unsafe { compiled.try_call(args) }.expect("call");
            // Cast: this tier's `int` result is the low 32 bits of RAX.
            assert_eq!(got as i32, want, "{desc} with {args:?}");
        }
    }

    /// Round 13 wave 1 (lane callcost): the METHOD-ENTRY poll is outlined by
    /// default (`CRATONVM_JIT_IR_ENTRY_POLL_OUTLINE`), stops exactly as the
    /// inline one does, and never stops on a clear flag (a `JZ`/`JNZ` mix-up
    /// would call the slow path on every entry and still return 1).
    #[test]
    fn r13_the_entry_poll_is_outlined_and_stops_exactly_as_the_inline_one() {
        // No `static` (the JIT statics ratchet counts test ones too): the poll
        // word is word 0 of a heap pair -- its low byte is the flag the poll
        // tests -- and the slow path counts its stops in word 1, reached
        // through the flag address it is handed.
        extern "C" fn slow_poll(flag_addr: i64, _body_id: i64) -> i64 {
            // SAFETY: `flag_addr` is word 0 of a live `[u64; 2]` the test owns.
            unsafe {
                let hits = (flag_addr as *mut u64).add(1);
                hits.write_volatile(hits.read_volatile() + 1);
            }
            0
        }

        let code = [0x04u8, 0xac]; // iconst_1; ireturn
        // One poll pair per compile: `(flag set?, stop count)`.
        let build = |entry_outline: Option<&'static str>, set: bool| {
            let pair: &'static mut [u64; 2] = Box::leak(Box::new([u64::from(set), 0]));
            let before = ir_poll_census_local();
            let flag_addr = pair.as_mut_ptr() as usize;
            let cm = cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_ENTRY_POLL_OUTLINE", entry_outline)],
                || {
                    let graph = IrBuilder::new(0, 0).build(&code, code.len()).expect("IR build");
                    let schedule = ir_schedule::schedule(&graph);
                    let mut helpers = no_helpers();
                    helpers.safepoint_flag_addr = flag_addr;
                    helpers.safepoint_slow_path = slow_poll as *const () as usize;
                    lower(&graph, &schedule, 0, 0, &helpers).expect("the body must lower")
                },
            );
            let after = ir_poll_census_local();
            (cm, flag_addr, (after.0 - before.0, after.1 - before.1))
        };
        let run = |(cm, flag_addr, _): &(CompiledMethod, usize, (u64, u64))| -> (i64, u64) {
            let hits = (*flag_addr as *mut u64).wrapping_add(1);
            // SAFETY: `hits` is word 1 of the leaked pair `build` made for
            // this body; the body takes no argument and returns an int, and
            // its only helper is `slow_poll`, which writes only that word.
            unsafe {
                hits.write_volatile(0);
                let got = cm.try_call(&[]).expect("call");
                (got, hits.read_volatile())
            }
        };

        let on = build(None, true);
        let off = build(Some("0"), true);
        let (on_census, off_census) = (on.2, off.2);
        // `>= 1`, not `== 1`: a buffer retry re-emits and re-counts a body.
        assert!(
            on_census.0 >= 1 && on_census.1 == 0,
            "default: the entry poll is outlined, got {on_census:?}"
        );
        assert!(
            off_census.0 == 0 && off_census.1 >= 1,
            "switched off: the entry poll is inline, got {off_census:?}"
        );
        assert_eq!(run(&on), (1, 1), "a set flag stops once, outlined");
        assert_eq!(run(&off), (1, 1), "a set flag stops once, inline");
        assert_eq!(run(&build(None, false)), (1, 0), "a clear flag never stops");
        assert_eq!(run(&build(Some("0"), false)), (1, 0));
    }

    /// An argument past the entry ABI's register file arrives on the CALLER'S
    /// stack, and `emit_prologue` must load it from there.
    ///
    /// This used to be a whole-method REFUSAL (`ir_lower_refuses_more_incoming_
    /// slots_than_abi_registers`), because the prologue read registers and
    /// nothing else. It was the commonest refusal an ordinary accessor hit — an
    /// instance method with three parameters is four incoming slots, and
    /// touching one field turns `needs_context` on, which is the fifth — so on
    /// Win64 a three-argument getter could not be lowered at this tier at all.
    ///
    /// Tested through the RETURNED VALUE rather than the emitted bytes: the
    /// body is `iload_<last>; ireturn`, so a prologue that dropped the argument
    /// answers with whatever the frame slot happened to hold, which is exactly
    /// the silent wrong value the old refusal existed to prevent. Each argument
    /// is given a distinct value, so reading the WRONG stack slot is a
    /// different failure from reading none.
    #[test]
    fn ir_lower_loads_incoming_arguments_past_the_entry_abi_registers() {
        let cap = incoming_abi_reg_capacity();
        // `CompiledMethod::try_call` dispatches through one
        // `extern "C" fn(i64, …)` thunk per arity and has thunks up to
        // `TRY_CALL_MAX_ARGS`; past that it answers `Err(TooManyArgs)`.
        // That is a limit of this HARNESS, not of the lowering under test,
        // and the two ABIs sit on opposite sides of it: Win64 has four
        // entry registers, so `cap + 3` is 7 and callable, while SysV has
        // six, so `cap + 3` is 9 and comes back `Err(TooManyArgs(9))` —
        // which is how this test read RED on Linux and green on Windows
        // while the prologue it exercises was working on both.
        //
        // Clamp to what the harness can call, and assert the clamp still
        // leaves a stack argument to test: a bound that silently collapsed
        // to `0..=0` would turn this into a registers-only test that always
        // passes, which is the failure mode worth guarding.
        const TRY_CALL_MAX_ARGS: usize = 8;
        let max_extra = TRY_CALL_MAX_ARGS.saturating_sub(cap).min(3);
        assert!(
            max_extra >= 1,
            "the entry ABI takes {cap} arguments in registers and \
             `try_call` can pass at most {TRY_CALL_MAX_ARGS}, so this test \
             can no longer place ANY argument on the caller's stack. Give \
             `try_call` a wider thunk before trusting this test again."
        );
        for extra in 0..=max_extra {
            let slots = cap + extra;
            let last = slots - 1;
            // `iload <last>; ireturn` — `iload` (0x15) takes a one-byte index,
            // which covers every slot count this test uses.
            let code = [0x15, last as u8, 0xac];
            let compiled = compile_via_ir(&code, code.len(), slots, slots)
                .unwrap_or_else(|| panic!("a graph with {slots} incoming slots must lower"));
            let args: Vec<i64> = (0..slots).map(|i| 1000 + i as i64).collect();
            // SAFETY: the lowered body reads one int local and returns it; the
            // argument vector has exactly the arity the body was compiled for,
            // and every value is a plain integer.
            let got = unsafe { compiled.try_call(&args) };
            assert_eq!(
                got,
                Ok(1000 + last as i64),
                "with {slots} incoming slots ({cap} in registers, {extra} on the \
                 caller's stack), reading slot {last} must answer the argument \
                 that was passed there",
            );
        }
    }

    /// The same shape for a method that also takes the hidden VM context in
    /// ABI[0], which is what shifts an ordinary accessor over the edge: the
    /// context spends one register, so a method with `cap` Java arguments
    /// already has one on the stack.
    #[test]
    fn ir_lower_loads_stack_arguments_when_the_context_spends_a_register() {
        let cap = incoming_abi_reg_capacity();
        // A body with an `Op::Call` turns `needs_context` on. `invokestatic`
        // through a helper is the smallest one this harness can build, so this
        // test asserts the ARITHMETIC of the shift rather than re-deriving it:
        // with the context in ABI[0], `cap` Java arguments leave exactly one on
        // the caller's stack.
        assert_eq!(
            cap.saturating_sub(1),
            incoming_abi_reg_capacity() - 1,
            "one register is spent on the context"
        );
        // And the register/stack split the prologue computes for that case.
        let base = 1usize; // needs_context
        let num_params = cap;
        let reg_count = num_params.min(ENTRY_ABI_REGS.len().saturating_sub(base));
        assert_eq!(reg_count, cap - 1);
        assert_eq!(
            num_params - reg_count,
            1,
            "exactly one argument on the stack"
        );
    }

    fn compile_via_ir(
        code: &[u8],
        code_len: usize,
        num_params: usize,
        num_locals: usize,
    ) -> Option<CompiledMethod> {
        let builder = IrBuilder::new(num_params, num_locals);
        let mut graph = builder.build(code, code_len)?;
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        lower(&graph, &schedule, num_params, num_locals, &no_helpers())
    }

    /// A block whose successor the layout already placed next must FALL
    /// THROUGH, not jump.
    ///
    /// Two assertions, because either alone can pass on a broken emitter. The
    /// census says the elision ran at all — without it, a method that happens
    /// to need every jump is indistinguishable from an elision that never
    /// fires. The byte scan says no `JMP rel32` survives with a displacement of
    /// zero, which is a jump to the very next instruction and therefore always
    /// dead weight; `E9 00 00 00 00` at the head of the loop body is exactly
    /// what this emitter used to produce, and is the shape the fix exists to
    /// remove.
    ///
    /// The census counters are process-global and monotone, so a strict
    /// increase is sound even when other tests run concurrently: a parallel
    /// lowering can only push the count further up.
    #[test]
    fn a_successor_placed_next_is_reached_by_falling_through() {
        // int f(int x) { return x == 0 ? 2 : 1; }
        //   0: iload_0
        //   1: ifeq -> 8
        //   4: iconst_1
        //   5: goto -> 9
        //   8: iconst_2
        //   9: ireturn
        let code = [
            0x1a, // iload_0
            0x99, 0x00, 0x07, // ifeq +7 -> 8
            0x04, // iconst_1
            0xa7, 0x00, 0x04, // goto +4 -> 9
            0x05, // iconst_2
            0xac, // ireturn
            0, 0, 0,
        ];
        let before = ir_fallthrough_census();
        let compiled = compile_via_ir(&code, 10, 1, 1).expect("a two-armed select must lower");
        let after = ir_fallthrough_census();
        assert!(
            after.0 > before.0,
            "no block-exit edge fell through: census went {before:?} -> {after:?}",
        );

        let code_bytes = compiled.code_bytes();
        assert!(
            !code_bytes
                .windows(5)
                .any(|w| w == [0xE9, 0x00, 0x00, 0x00, 0x00]),
            "emitted a JMP rel32 with displacement 0 -- a jump to the next \
             instruction; {} bytes of code",
            code_bytes.len(),
        );

        // The body must still compute the right answer: an elision that drops a
        // jump the layout did NOT make redundant is wrong code, not a smaller
        // body, and the census cannot tell the difference.
        // SAFETY: one int parameter, no context, no helpers reachable.
        for (arg, want) in [(0i64, 2i64), (1, 1), (-7, 1)] {
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            let got = unsafe { compiled.try_call(&[arg]).expect("call") };
            assert_eq!(got, want, "f({arg})");
        }
    }

    /// Build → schedule → lower WITHOUT the optimizer, so safepoint NodeIds
    /// stay stable (DCE/GVN safepoint preservation is a later concern; the
    /// emit-and-discard points are validated on the un-optimized graph).
    /// A synchronized region now reaches the IR tier instead of bailing.
    ///
    /// Two halves, and both matter. With NO monitor helper the compile must be
    /// REFUSED — `lower_data_node`'s catch-all would otherwise emit nothing for
    /// the monitor and the lock would silently disappear. With a helper present
    /// it must compile, and the emitted code must actually CALL that helper
    /// twice (enter + exit), not merely accept the graph.
    #[test]
    fn a_synchronized_region_lowers_through_the_monitor_helper() {
        // aload_0; monitorenter; aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc3, 0xb1, 0, 0];
        let builder = IrBuilder::new(1, 1);
        let graph = builder
            .build(&code, 5)
            .expect("builder must accept monitors");
        assert!(
            graph.nodes.iter().any(|n| matches!(n.op, Op::MonitorEnter)),
            "the builder must emit a MonitorEnter node"
        );
        let schedule = ir_schedule::schedule(&graph);

        // No helper -> refuse, rather than drop the lock.
        assert!(
            lower(&graph, &schedule, 1, 1, &no_helpers()).is_none(),
            "a monitor graph with no helper must be REFUSED, never lowered to \
             nothing"
        );

        // Helper present -> compiles, and both monitor calls are emitted.
        extern "C" fn fake_monitor(_vm: i64, obj: i64) -> i64 {
            obj
        }
        let mut helpers = no_helpers();
        helpers.monitor_enter = fake_monitor as *const () as usize;
        // The real `jit_monitor_exit` returns 1 on success, NOT the object.
        // A fake that echoed `obj` for exit as well hid the lowering writing
        // that return value back into the object's home slot.
        extern "C" fn fake_monitor_exit(_vm: i64, _obj: i64) -> i64 {
            1
        }
        helpers.monitor_exit = fake_monitor_exit as *const () as usize;
        let cm = lower(&graph, &schedule, 1, 1, &helpers)
            .expect("a monitor graph with a helper must compile");
        let bytes = cm.code_bytes();
        let calls_to = |f: usize| {
            let target = f.to_le_bytes();
            bytes.windows(8).filter(|w| *w == target).count()
        };
        assert_eq!(
            calls_to(fake_monitor as *const () as usize),
            1,
            "monitorenter must call the enter helper"
        );
        assert_eq!(
            calls_to(fake_monitor_exit as *const () as usize),
            1,
            "monitorexit must call the exit helper"
        );

        // The deopt metadata now names the held lock. Before 2026-09-12 every
        // lowered frame state hard-coded `monitors: Vec::new()`.
        let at = |bci: u32| {
            cm.deopt_points
                .iter()
                .find(|p| p.bci == bci)
                .unwrap_or_else(|| panic!("a deopt point at bci {bci}"))
        };
        let exit_point = at(3);
        assert_eq!(
            exit_point.frame_state.monitors.len(),
            1,
            "the frame at the monitorexit holds the lock the monitorenter took"
        );
        let m = &exit_point.frame_state.monitors[0];
        assert_eq!(m.lock_depth, 1);
        assert!(
            !m.relock,
            "the compiled code took this lock itself; the resume must not take it again"
        );
        assert!(
            matches!(m.object, FrameValue::StackSlotRef(_)),
            "the locked object is described as a reference slot even though the \
             hand-built Param is Int-typed, got {:?}",
            m.object
        );
        assert!(
            at(1).frame_state.monitors.is_empty(),
            "at the monitorenter itself nothing is held yet: resuming there \
             re-executes the enter"
        );
    }

    /// Round 11 wave 7 (lane lower,
    /// `r11w6-lock-ir-tier-monitor-still-calls-the-helper`): with the monitor
    /// block wired, each monitor op carries the inline thin-lock CAS in front
    /// of its helper call, which stays as the slow path; unwired, the code is
    /// the helper sequence alone. (The sequence itself is run against a
    /// hand-built lock stack by `runtime_lowering`'s
    /// `inline_thin_lock_takes_only_the_uncontended_case`.)
    #[test]
    fn a_synchronized_region_takes_the_inline_thin_lock_when_wired() {
        // aload_0; monitorenter; aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc3, 0xb1, 0, 0];
        let graph = IrBuilder::new(1, 1)
            .build(&code, 5)
            .expect("builder must accept monitors");
        let schedule = ir_schedule::schedule(&graph);
        extern "C" fn fake_monitor(_vm: i64, obj: i64) -> i64 {
            obj
        }
        extern "C" fn fake_monitor_exit(_vm: i64, _obj: i64) -> i64 {
            1
        }
        let mut helpers = no_helpers();
        helpers.monitor_enter = fake_monitor as *const () as usize;
        helpers.monitor_exit = fake_monitor_exit as *const () as usize;
        // LOCK CMPXCHG DWORD [R11 + MARK_WORD_OFFSET], ECX -- the acquisition
        // and the release, on the 8-byte header's 32-bit mark word.
        let cas = [0xF0u8, 0x41, 0x0F, 0xB1, 0x4B, 0x04];
        let cas_count = |bytes: &[u8]| bytes.windows(cas.len()).filter(|w| *w == cas).count();
        let calls_to = |bytes: &[u8], f: usize| {
            let target = f.to_le_bytes();
            bytes.windows(8).filter(|w| *w == target).count()
        };

        let unwired = lower(&graph, &schedule, 1, 1, &helpers).expect("lower");
        assert_eq!(
            cas_count(unwired.code_bytes()),
            0,
            "offset 0 emits no inline path"
        );

        helpers.monitor_block_offset_in_thread = 64;
        let wired = lower(&graph, &schedule, 1, 1, &helpers).expect("lower");
        let bytes = wired.code_bytes();
        // Round 13 wave 8 (lane sync5): the recursion arm
        // (`CRATONVM_JIT_INLINE_THIN_LOCK_RECURSION`) adds one more mark-word
        // CAS to each op, its `recursion +/- 1`.
        let per_op = if crate::runtime_lowering::inline_thin_lock_recursion_enabled() {
            2
        } else {
            1
        };
        let expected = if crate::runtime_lowering::inline_thin_lock_enabled()
            && crate::x64::jit_thread_tls_disp() != 0
        {
            2 * per_op
        } else {
            0
        };
        assert_eq!(
            cas_count(bytes),
            expected,
            "the inline mark-word CAS(es) of each monitor op"
        );
        assert_eq!(calls_to(bytes, fake_monitor as *const () as usize), 1);
        assert_eq!(calls_to(bytes, fake_monitor_exit as *const () as usize), 1);
    }

    /// gcd d1/mon (2026-09-27): every op whose lowering reads the VM-context
    /// slot (`context_slot_off`) must be one `scan_frame_needs` reserves the
    /// slot for. An op the scan misses compiles with `context_slot_off == 0`,
    /// and its helper call loads `[rbp - 0]` -- the saved caller RBP -- as its
    /// `SharedVm`: the compiled-monitor crash of
    /// `docs/internal/gc/gengc-r5w6-orch-jit-monitor-enter-gets-a-stack-address-as-its-vm-pointer-FIXED-20260928.md`.
    ///
    /// Each row is one op and the functions in this file through which its
    /// lowering reads the slot (the audit behind
    /// [`the_context_slot_readers_are_the_audited_set`]). `Op::MonitorEnter` /
    /// `Op::MonitorExit` (the `lower_data_node` monitor arm and
    /// `emit_sync_exit_then_throw`'s stub) are that page's own fix, which JIT
    /// round 13 lands, and are deliberately not rows here.
    #[test]
    fn every_op_whose_lowering_reads_the_context_reserves_it() {
        let mut helpers = no_helpers();
        // `Op::Load` reads the context only through the `jit_getfield` arms,
        // which a zero helper declines; the scan keys on the same field.
        helpers.getfield = 0x1000;
        let rows: Vec<(Op, &str)> = vec![
            (
                Op::Call { info_ptr: 0 },
                "the Call arm; emit_direct_cross_call, emit_inline_cache_call, \
                 emit_ic_*_marshal, emit_self_call_*, emit_cycle_edge_cell_call, \
                 emit_callee_deopt_service_cold, try_emit_ir_*_value_of_prefix",
            ),
            (Op::LambdaIntToDouble, "the LambdaIntToDouble arm"),
            (Op::Load(MemKind::Int), "the Load arm; emit_inline_compact_getfield"),
            (Op::Load(MemKind::Ref), "the Load arm; emit_inline_compact_getfield"),
            (
                Op::Store(MemKind::Ref),
                "the Store arm; emit_gated_ir_ref_putfield, emit_g1_ir_ref_putfield",
            ),
            (Op::ArrayStore(MemKind::Ref), "the ArrayStore arm (jit_aastore)"),
            (
                Op::New {
                    class_id: 1,
                    num_fields: 0,
                },
                "the New arm (InlineTlabPlan::context_off, the allocation stub)",
            ),
            (
                Op::NewArray {
                    element_type: 10,
                    component_class_id: 0,
                },
                "the NewArray arm",
            ),
            (
                Op::ConstString {
                    holder_class_id: 1,
                    cp_idx: 1,
                    slot_addr: 0,
                },
                "the ConstString arm",
            ),
            (
                Op::ConstClass {
                    holder_class_id: 1,
                    cp_idx: 1,
                    slot_addr: 0,
                },
                "the ConstClass arm",
            ),
            (
                Op::CheckCast {
                    name_ptr: 0,
                    name_len: 0,
                },
                "the CheckCast arm",
            ),
            (
                Op::InstanceOf {
                    name_ptr: 0,
                    name_len: 0,
                },
                "the InstanceOf arm",
            ),
            (
                Op::LoadStatic {
                    class_id: 1,
                    field_index: 0,
                    type_tag: b'I',
                    is_volatile: false,
                },
                "the LoadStatic arm",
            ),
            (
                Op::StoreStatic {
                    class_id: 1,
                    field_index: 0,
                    type_tag: b'I',
                    is_volatile: false,
                },
                "the StoreStatic arm",
            ),
        ];
        for (op, readers) in rows {
            let mut graph = Graph::empty(0);
            let start = graph.add(Op::Start, IrType::Control, vec![], None);
            graph.entry = start;
            let _ = graph.add(op.clone(), IrType::Void, vec![], None);
            assert!(
                scan_frame_needs(&graph, &helpers).needs_context,
                "{op:?} reads the context slot ({readers}) but `scan_frame_needs` \
                 reserves none: its helper would get the saved caller RBP as the VM",
            );
        }
        // The control: a body of pure arithmetic reserves nothing, so the
        // assertions above are not satisfied by a scan that always says yes.
        let (plain, _) = add_one_graph();
        assert!(!scan_frame_needs(&plain, &helpers).needs_context);
    }

    /// gcd d1/mon: the functions in this file that read the VM-context slot
    /// are exactly the audited ones. A new reader must first get its op a row
    /// in [`every_op_whose_lowering_reads_the_context_reserves_it`] (and, if
    /// the scan misses it, a `scan_frame_needs` entry), then be added here.
    /// `emit_prologue` and `emit_osr_entry_stubs` are the two WRITERS, both
    /// under `if self.needs_context`; `emit_sync_exit_then_throw` and the
    /// monitor arm of `lower_data_node` are the monitor readers JIT round 13
    /// reserves for.
    #[test]
    fn the_context_slot_readers_are_the_audited_set() {
        const AUDITED: &[&str] = &[
            "emit_prologue",
            "try_emit_ir_integer_value_of_prefix",
            "try_emit_ir_long_value_of_prefix",
            "emit_gated_ir_ref_putfield",
            "emit_g1_ir_ref_putfield",
            "emit_inline_compact_getfield",
            "emit_self_call_stack_sample",
            "emit_self_call_marshal_and_call",
            // JIT round 13 wave 8 (the self-call cold tails): emits only the
            // tails the two functions above pushed, i.e. only for a compile
            // whose Call row already reserved the slot.
            "emit_deferred_self_call_tails",
            "emit_direct_cross_call",
            "emit_sync_exit_then_throw",
            "emit_callee_deopt_service_cold",
            "emit_ic_abi_marshal",
            // JIT round 13 wave 2 (the IC recursion stack guard): reached only
            // from `emit_inline_cache_call`, i.e. from the Call arm's row.
            "emit_ic_stack_sample",
            "emit_ic_shift_for_context",
            "emit_ic_wide_marshal",
            "emit_cycle_edge_cell_call",
            "emit_inline_cache_call",
            "lower_data_node",
            "emit_osr_entry_stubs",
        ];
        // Built, so this function's own text does not contain the needle.
        let needle = format!("self.{}", "context_slot_off");
        let fn_name = |line: &str| -> Option<String> {
            let mut rest = line.trim_start();
            for prefix in ["pub(crate) ", "pub(super) ", "pub ", "unsafe ", "const "] {
                if let Some(r) = rest.strip_prefix(prefix) {
                    rest = r;
                }
            }
            let name: String = rest
                .strip_prefix("fn ")?
                .chars()
                .take_while(|c| c.is_ascii_alphanumeric() || *c == '_')
                .collect();
            (!name.is_empty()).then_some(name)
        };
        let mut current: Option<String> = None;
        let mut readers = std::collections::BTreeSet::new();
        for line in include_str!("ir_lower.rs").lines() {
            if let Some(name) = fn_name(line) {
                current = Some(name);
            }
            if line.trim_start().starts_with("//") || !line.contains(&needle) {
                continue;
            }
            if let Some(name) = &current {
                readers.insert(name.clone());
            }
        }
        assert!(
            readers.contains("lower_data_node"),
            "the source scan found no reader at all; it is broken, not clean: {readers:?}",
        );
        let unaudited: Vec<&String> = readers
            .iter()
            .filter(|r| !AUDITED.contains(&r.as_str()))
            .collect();
        assert!(
            unaudited.is_empty(),
            "{unaudited:?} read the VM-context slot but are not in the audited set: \
             make sure `scan_frame_needs` reserves the slot for every op that reaches \
             them, give that op a row in \
             `every_op_whose_lowering_reads_the_context_reserves_it`, then add the \
             function here",
        );
    }

    /// gcd d1/mon: the context slot is a word of its own. It sits directly
    /// above the locals, is never `[rbp - 0]` (the saved caller RBP), and no
    /// local, bookkeeping word or colour of the spill band can land on it, for
    /// any local count. A frame that reserves none reports offset 0, which is
    /// exactly the saved caller RBP -- why every context reader must be under
    /// a reservation (the two tests above).
    #[test]
    fn the_context_slot_overlaps_no_other_frame_word() {
        // `Object f() { return new X(); }`: `Op::New` reserves the context.
        let mut new_graph = Graph::empty(0);
        let start = new_graph.add(Op::Start, IrType::Control, vec![], None);
        new_graph.entry = start;
        let ctrl = new_graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = new_graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let allocation = new_graph.add(
            Op::New {
                class_id: 23,
                num_fields: 7,
            },
            IrType::Ref,
            vec![ctrl, mem],
            Some(0),
        );
        new_graph.exit = new_graph.add(Op::Return, IrType::Void, vec![ctrl, allocation], Some(3));
        let new_schedule = ir_schedule::schedule(&new_graph);
        let (plain_graph, plain_schedule) = add_one_graph();
        for &num_locals in &[1usize, 2, 5, 9] {
            for (graph, schedule, wants_context) in [
                (&new_graph, &new_schedule, true),
                (&plain_graph, &plain_schedule, false),
            ] {
                let plan = plan_slots(graph, schedule, None);
                let empty: HashMap<usize, bool> = HashMap::new();
                let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
                let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
                let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
                let no_frame_sites = crate::ir::IrInlineFrameSites::default();
                let buf = ExecutableBuffer::new(4096).expect("executable buffer");
                let helpers = no_helpers();
                let lowerer = Lowerer::new(
                    graph,
                    schedule,
                    buf,
                    0,
                    num_locals,
                    &plan,
                    &helpers,
                    &empty,
                    &[],
                    None,
                    &no_direct,
                    &no_ic,
                    &no_compact,
                    &no_frame_sites,
                );
                assert_eq!(lowerer.needs_context, wants_context);
                let locals_top = (num_locals as i32) * 8;
                if !wants_context {
                    assert_eq!(
                        lowerer.context_slot_off, 0,
                        "no reservation reads as offset 0, the saved caller RBP"
                    );
                    assert_eq!(lowerer.sp_id_slot_off, locals_top + 8);
                    continue;
                }
                let ctx = lowerer.context_slot_off;
                assert_eq!(ctx, locals_top + 8, "the slot directly above the locals");
                assert!(ctx > 0, "`[rbp - 0]` is the saved caller RBP, not a slot");
                for local in 0..num_locals as i32 {
                    assert_ne!((local + 1) * 8, ctx, "local {local} overlaps the context slot");
                }
                for (name, off) in [
                    ("sp_id", lowerer.sp_id_slot_off),
                    ("shadow_thread", lowerer.shadow_thread_slot_off),
                    ("shadow_savebase", lowerer.shadow_savebase_slot_off),
                    ("shadow_savetop", lowerer.shadow_savetop_slot_off),
                    ("phi_copy_scratch", lowerer.phi_copy_scratch_slot_off),
                ] {
                    assert!(off > ctx, "{name} word at {off} is not above the context slot {ctx}");
                }
                assert_eq!(lowerer.sp_id_slot_off, ctx + 8);
                assert!(lowerer.first_spill > ctx);
                for color in 0..plan.slots as i32 {
                    assert_ne!(lowerer.first_spill + color * 8, ctx);
                }
                assert!(lowerer.spill_cap_off > ctx);
                assert!(lowerer.frame_size > ctx);
            }
        }
    }

    /// Round 11 wave 2 (lane lower,
    /// `r11-tier-ir-monitor-body-trap-reruns-from-entry`): a body with a
    /// `synchronized` block and a trapping bytecode inside it sets
    /// `can_deopt_resume`. Its frame states carry the monitor stack, and
    /// without the flag the sinks' other arm (`sink_precise_resume_allowed`)
    /// refuses any body holding a monitor, so the trap re-ran the method from
    /// entry and repeated every side effect before it.
    #[test]
    fn a_monitor_body_with_a_trap_vouches_for_its_frames() {
        // aload_0; monitorenter; iload_1; iload_2; idiv; istore_1;
        // aload_0; monitorexit; iload_1; ireturn
        let code = [
            0x2a, 0xc2, 0x1b, 0x1c, 0x6c, 0x3c, 0x2a, 0xc3, 0x1b, 0xac, 0, 0,
        ];
        let graph = IrBuilder::new(3, 3)
            .build(&code, 10)
            .expect("builder must accept a division under a monitor");
        let schedule = ir_schedule::schedule(&graph);
        extern "C" fn fake_monitor(_vm: i64, obj: i64) -> i64 {
            obj
        }
        extern "C" fn fake_monitor_exit(_vm: i64, _obj: i64) -> i64 {
            1
        }
        let mut helpers = no_helpers();
        helpers.monitor_enter = fake_monitor as *const () as usize;
        helpers.monitor_exit = fake_monitor_exit as *const () as usize;
        let cm = lower(&graph, &schedule, 3, 3, &helpers).expect("lower");
        assert!(
            cm._deopt_point_boxes
                .iter()
                .any(|p| !p.frame_state.monitors.is_empty()),
            "the division's zero guard deopts with the lock in its frame"
        );
        assert!(
            cm.can_deopt_resume,
            "a body whose frames describe its monitors must vouch for precise resume"
        );
    }
    /// COV-03 — build the one-line `void set(Corpus o, X v) { o.f = v; }` graph
    /// for field descriptor `tag`, with both wide-field gates on.
    ///   aload_0; <x>load_1; putfield #2; return
    fn ref_or_wide_putfield_graph(tag: u8, load_op: u8, param_ty: IrType) -> Graph {
        let code = [0x2a, load_op, 0x01, 0xb5, 0x00, 0x02, 0xb1, 0, 0];
        let mut b = IrBuilder::new(2, 4);
        b.set_param_types(&[IrType::Ref, param_ty]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(3usize, (0usize, tag));
        b.set_field_info(fi);
        b.set_wide_field_gates(true, true);
        b.build(&code, 7)
            .unwrap_or_else(|| panic!("the builder must accept a {} putfield", tag as char))
    }

    /// COV-03, the soundness half. A reference field store has exactly ONE
    /// correct lowering — `jit_putfield_object`, which carries the SATB
    /// pre-barrier on the overwritten reference and the collector's post-write
    /// barrier. With no helper address the graph must be REFUSED, never lowered
    /// to a barrier-free store: a missing barrier is invisible until a
    /// concurrent or generational collection, and it surfaces as a lost object
    /// rather than as a fault at the store.
    ///
    /// The second half is the one a refusal test cannot give you: with the
    /// helper wired, the emitted artifact must actually CALL it. "The graph was
    /// accepted" and "the barrier is in the code" are different claims.
    #[test]
    fn a_reference_putfield_lowers_only_through_the_barrier_helper() {
        // aload_0; aload_1; putfield #2; return
        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        assert!(
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::Store(MemKind::Ref))),
            "the builder must emit Op::Store(MemKind::Ref)"
        );
        let schedule = ir_schedule::schedule(&graph);

        assert!(
            lower(&graph, &schedule, 2, 4, &no_helpers()).is_none(),
            "a reference store with no `putfield_object` helper must be REFUSED, \
             never lowered to a store without its write barrier"
        );

        unsafe extern "C" fn fake_putfield_object(_vm: i64, _obj: i64, _idx: i64, _val: i64) {}
        let mut helpers = no_helpers();
        helpers.putfield_object = fake_putfield_object as *const () as usize;
        // `putfield_int` too: with compact layout on, `lower_inner` refuses an
        // INT store without it — and the `Const(field_index)` offset node this
        // graph carries is not an int store, so this only proves the refusal is
        // per-kind rather than blanket.
        helpers.putfield_int = fake_putfield_object as *const () as usize;
        let cm = lower(&graph, &schedule, 2, 4, &helpers)
            .expect("a reference store WITH the barrier helper must compile");
        assert!(
            contains_seq(
                cm.code_bytes(),
                &(helpers.putfield_object as u64).to_le_bytes()
            ),
            "the artifact must bake the `jit_putfield_object` address — the write \
             barrier is the whole reason this store has no inline lowering"
        );
        // The helper takes the VM context pointer as arg0, so the frame must
        // reserve and the ABI must demand it. Without this the lowering would
        // load arg0 from an unreserved slot and hand the helper a stack address
        // to dereference as a `SharedVm` (the single-pass backend's identical
        // `needs_heap` bug on `Catalina.setParentClassLoader`).
        assert!(
            cm.needs_context(),
            "a reference putfield must make the artifact `needs_context`"
        );
    }

    /// Lower `void set(Corpus o, X v) { o.f = v; }` with a resolved compact
    /// slot for the store site, and return the emitted bytes.
    ///
    /// `plan` publishes the collector's reference-store barrier gates; without
    /// it the helpers describe a collector that published none, which is the
    /// control arm for every assertion below.
    const COMPACT_REF_PUTFIELD_HELPER: usize = 0x1111_2222_3333_4450;

    fn lower_compact_ref_putfield(plan: bool, c_off: u32) -> Vec<u8> {
        // Static gate bytes and a read-bounds table. Real addresses of real
        // storage: the emitter bakes them as imm64 and the assertions read the
        // same values back, so a wrong one shows up as a missing sequence
        // rather than as a fault (nothing executes this code).
        static PRE_GATE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
        static POST_GATE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(1);
        static READ_BOUNDS: [u64; 6] = [0; 6];

        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.putfield_object = COMPACT_REF_PUTFIELD_HELPER;
        helpers.putfield_int = COMPACT_REF_PUTFIELD_HELPER ^ 0xF;
        helpers.read_bounds_addr = std::ptr::addr_of!(READ_BOUNDS) as usize;
        if plan {
            helpers.ref_store_pre_gate = std::ptr::addr_of!(PRE_GATE) as usize;
            helpers.ref_store_post_gate = std::ptr::addr_of!(POST_GATE) as usize;
            helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;
        }

        // The builder puts the `putfield` at pc 3 (`aload_0; aload_1;
        // putfield`), which is the key `set_field_info` uses above.
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        compact.insert((3usize, true), (c_off, true, b'L'));
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        lower_inner(
            &graph,
            &schedule,
            2,
            4,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("a reference putfield with its helper wired must compile")
        .code_bytes()
        .to_vec()
    }

    /// The optimizing tier emits the BARRIER-FREE store only when a collector
    /// published a barrier plan — and emits none without one.
    ///
    /// This is the pair, not the positive alone. Until 2026-09-02 this tier
    /// lowered every reference store to `jit_putfield_object` unconditionally,
    /// so a test that only asserted "the helper address is baked" passed both
    /// before and after the arm existed and could not tell them apart. The
    /// control arm here is a helper table with no plan, which is what G1 and
    /// ZGC actually present, and it must produce no inline store at all.
    #[test]
    fn the_optimizing_tier_stores_inline_only_behind_a_published_barrier_plan() {
        let c_off = 8u32;
        // MOV [RAX + disp32], RDX — the barrier-free compact reference store.
        let mut store_seq: Vec<u8> = vec![0x48, 0x89, 0x90];
        store_seq.extend_from_slice(&(c_off as i32).to_le_bytes());

        let without = lower_compact_ref_putfield(false, c_off);
        assert!(
            !contains_seq(&without, &store_seq),
            "with NO published barrier plan the optimizing tier must emit no \
             inline reference store — a store whose barrier nothing ruled out \
             is a lost card, invisible until the next collection"
        );

        let with = lower_compact_ref_putfield(true, c_off);
        assert!(
            contains_seq(&with, &store_seq),
            "with a published plan the optimizing tier must emit the inline \
             compact store at the RESOLVED offset — that offset is the whole \
             plumbing this arm needed, and the uniform slot displacement the \
             fallback derives is one a compact object does not obey"
        );
        // The helper is still the fallback. Every gate that cannot rule a
        // barrier out branches to it, so its address must remain baked: an arm
        // that inlined the store and dropped the fallback would be exactly the
        // missing-barrier defect this whole sequence is built to avoid.
        assert!(
            contains_seq(&with, &(COMPACT_REF_PUTFIELD_HELPER as u64).to_le_bytes()),
            "the gated arm must keep `jit_putfield_object` as its fallback"
        );
    }

    /// The baked compact cell offset is guarded against a layout REPLACEMENT,
    /// and the guard is proven to fire.
    ///
    /// Every emitter that bakes `HEADER_SIZE + packed_body_offset` claims at
    /// compile time something the class manager can change at run time. The two
    /// ALLOCATION emitters have guarded that since perf/halfgap-20260717, whose
    /// comment calls an unguarded baked layout "confirmed heap corruption"; the
    /// FIELD-ACCESS emitters had no guard at all until 2026-09-04, and the
    /// compact TLAB default made their unguarded path the common one.
    ///
    /// Asserted by EXECUTION, not by inspecting bytes: the compiled body is run
    /// against a receiver, then the process-wide replacement epoch is bumped by
    /// actually replacing a layout, and the same body is run again. The first
    /// run must store inline; the second must reach the helper. A guard that
    /// compares against a counter nothing ever bumps would pass an
    /// inspection-only test and protect nothing.
    #[test]
    fn a_replaced_layout_routes_the_gated_store_to_the_helper() {
        use std::sync::atomic::{AtomicU64, AtomicUsize, Ordering};

        static HELPER_CALLS: AtomicUsize = AtomicUsize::new(0);
        unsafe extern "C" fn marker_putfield_object(_vm: i64, _obj: i64, _idx: i64, _val: i64) {
            HELPER_CALLS.fetch_add(1, Ordering::SeqCst);
        }
        static PRE_GATE: AtomicU64 = AtomicU64::new(0);
        static POST_GATE: AtomicU64 = AtomicU64::new(1);
        static READ_BOUNDS: [AtomicUsize; 6] = [
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
            AtomicUsize::new(0),
        ];

        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.putfield_object = marker_putfield_object as *const () as usize; // Cast: fn → slot
        helpers.read_bounds_addr = READ_BOUNDS.as_ptr() as usize; // Cast: static address
        helpers.ref_store_pre_gate = std::ptr::addr_of!(PRE_GATE) as usize; // Cast: static address
        helpers.ref_store_post_gate = std::ptr::addr_of!(POST_GATE) as usize; // Cast: static
        helpers.ref_store_post_young_floor = 0;
        helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;

        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        compact.insert((3usize, true), (8u32, true, b'L'));
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let compiled = lower_inner(
            &graph,
            &schedule,
            2,
            4,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("the gated reference store must compile");

        // A young, compact receiver with one slot.
        let mut obj = Box::new([0u64; 8]);
        // SAFETY: `obj` is 64 bytes, 8-byte aligned; both writes land inside it.
        unsafe {
            let p = obj.as_mut_ptr() as *mut u8; // Cast: array base → byte cursor
            *p.add(cratonvm_types::GC_FLAGS_BYTE_OFFSET) = cratonvm_types::GC_FLAG_COMPACT;
        }
        let obj_addr = obj.as_mut_ptr() as usize; // Cast: receiver address
        let page = obj_addr & !0xFFF;
        READ_BOUNDS[0].store(page, Ordering::Release);
        READ_BOUNDS[1].store(page + 0x10000, Ordering::Release);
        let val = Box::new([0u64; 8]);
        let val_addr = val.as_ptr() as usize; // Cast: stored reference

        HELPER_CALLS.store(0, Ordering::SeqCst);
        // SAFETY: JIT-compiled code from valid bytecode in an executable mmap;
        // the receiver is a live buffer shaped like an object header and the
        // marker helper stores nothing.
        unsafe {
            compiled.call_with_heap(0, &[obj_addr as i64, val_addr as i64]); // Cast: JIT ABI
        }
        assert_eq!(
            HELPER_CALLS.load(Ordering::SeqCst),
            0,
            "before any replacement the guard must pass and the store stay inline"
        );
        assert_eq!(
            obj[cratonvm_types::COMPACT_HEADER_SIZE / 8] as usize, // Cast: stored pointer word
            val_addr,
            "the inline store must have written the compact cell"
        );

        // Now REPLACE a layout. Not by poking the counter -- by doing the thing
        // that bumps it, so the test cannot pass against a guard wired to a
        // number nothing in the VM ever moves.
        let before = cratonvm_types::layout_replace_epoch();
        // A REPLACEMENT is a second `register_class_layout` for a class_id that
        // already has one; a first registration deliberately does not count.
        let cid = 900_001u32;
        let mk = |body: u32| {
            std::sync::Arc::new(cratonvm_types::CompactLayout {
                field_disps: vec![8],
                is_ref: vec![false],
                field_kinds: vec![cratonvm_types::FieldStorageKind::Int],
                ref_disps: Vec::new(),
                total_size: body,
            })
        };
        let (l1, l2) = (mk(4), mk(8));
        cratonvm_types::register_class_layout(cratonvm_types::FIRST_LAYOUT_DOMAIN, cid, l1);
        cratonvm_types::register_class_layout(cratonvm_types::FIRST_LAYOUT_DOMAIN, cid, l2);
        assert!(
            cratonvm_types::layout_replace_epoch() > before,
            "replacing a registered layout must bump the process-wide epoch, or \
             the guard below is comparing against a constant"
        );

        obj[cratonvm_types::COMPACT_HEADER_SIZE / 8] = 0;
        HELPER_CALLS.store(0, Ordering::SeqCst);
        // SAFETY: as above.
        unsafe {
            compiled.call_with_heap(0, &[obj_addr as i64, val_addr as i64]); // Cast: JIT ABI
        }
        assert_eq!(
            HELPER_CALLS.load(Ordering::SeqCst),
            1,
            "a replaced layout must route the already-compiled site to the \
             always-correct helper — its baked cell offset now describes a \
             layout the object no longer has"
        );
        assert_eq!(
            obj[cratonvm_types::COMPACT_HEADER_SIZE / 8],
            0,
            "and the inline store must not have run"
        );
    }

    /// gce e1/f (the cards4 blocker): with the inline card check on
    /// (`CRATONVM_JIT_INLINE_CARD_MARK=1`), a gated reference `putfield` of a
    /// young value into an OLD compact receiver stores inline when the
    /// receiver's card is already dirty and still calls `jit_putfield_object`
    /// on a clean one; an old or null value needs no card; an armed SATB gate
    /// takes the helper. Executed against a real card table over a simulated
    /// old space. A concurrent layout replacement (another test) sends the
    /// site to the helper through its epoch guard, so an inline expectation is
    /// checked only while the epoch is unchanged.
    #[cfg(target_arch = "x86_64")]
    #[test]
    fn gce_e1f_a_dirty_card_spares_the_putfield_helper() {
        use cratonvm_gc::card_table::{CardTable, CardTableOptions, CARD_SIZE};
        // The helper's mark: it stores the value XOR this into the receiver's
        // first field, so the field itself says which path ran (no static
        // counter: the JIT statics ratchet counts test statics too).
        const HELPER_TAG: u64 = 0x5A5A_0000_0000_0000;
        extern "C" fn marker(_vm: i64, obj: i64, _idx: i64, val: i64) {
            // Cast: the receiver's address and the stored word.
            // SAFETY: the test's receiver lies in its leaked old space, and
            // its first field is the word at +8.
            unsafe { ((obj as usize + 8) as *mut u64).write_volatile(val as u64 ^ HELPER_TAG) };
        }
        if !crate::x64::ir_gated_ref_store_enabled()
            || !crate::x64::inline_putfield_enabled()
            || crate::x64::narrow_oops_block_inline_fields()
            || !cratonvm_types::compact_ref_fields_enabled()
            || !cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_IR_INLINE_CARD_CHECK")
        {
            return;
        }
        let old: &'static mut [u64] = Box::leak(vec![0u64; 4096].into_boxed_slice());
        let base = old.as_mut_ptr() as usize; // Cast: leaked address
        let end = base + old.len() * 8;
        let ct = CardTable::with_options(
            base,
            end - base,
            CardTableOptions {
                summary: false,
                precise_ref_array_marks: true,
            },
        );
        // The READ bounds table the receiver check reads: `[lo, hi, ..]`.
        let bounds: &'static mut [usize; 6] = Box::leak(Box::new([base, end, 0, 0, 0, 0]));
        let gates: *mut u8 = Box::leak(Box::new([0u8, 1u8])).as_mut_ptr();
        let mut helpers = no_helpers();
        helpers.putfield_object = marker as *const () as usize; // Cast: fn -> slot
        helpers.read_bounds_addr = bounds.as_ptr() as usize; // Cast: leaked address
        helpers.ref_store_pre_gate = gates as usize; // Cast: leaked address
        helpers.ref_store_post_gate = gates as usize + 1; // Cast: leaked address
        helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;
        helpers.jit_card_table_addr = ct.jit_card_view_addr();
        helpers.jit_card_old_base = base;
        helpers.jit_card_old_end = end;
        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        let schedule = ir_schedule::schedule(&graph);
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        compact.insert((3usize, true), (8u32, true, b'L'));
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let compile = || {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_INLINE_CARD_MARK", Some("1"))],
                || {
                    lower_inner(
                        &graph,
                        &schedule,
                        2,
                        4,
                        &helpers,
                        &empty_hints,
                        &[],
                        None,
                        &no_direct,
                        &no_ic,
                        &compact,
                        &crate::ir::IrInlineFrameSites::default(),
                    )
                    .expect("the gated reference store must compile")
                },
            )
        };
        // The receiver: an old, compact object at byte 1024 of the old space;
        // its first field is the word at +8.
        let obj = base + 1024;
        // SAFETY: the flags byte lies inside the leaked old space.
        unsafe {
            ((obj + cratonvm_types::GC_FLAGS_BYTE_OFFSET) as *mut u8).write_volatile(
                cratonvm_types::GC_FLAG_OLD_GEN | cratonvm_types::GC_FLAG_COMPACT,
            )
        };
        let field = obj + 8;
        let card = (obj - base) / CARD_SIZE;
        // SAFETY: `field` is a word of the leaked old space.
        let read_field = || unsafe { (field as *const u64).read_volatile() };
        // A YOUNG value: a buffer outside the simulated old space.
        let young: &'static mut [u64; 8] = Box::leak(Box::new([0u64; 8]));
        let young_value = young.as_ptr() as i64; // Cast: leaked address
        let old_value = (base + 8192) as i64; // Cast: leaked address
        // Run one store of `v`; `(the helper ran, layout epoch unchanged)`.
        // Inline, the field holds `v`; through the helper, `v ^ HELPER_TAG`.
        let store = |v: i64| {
            let epoch = cratonvm_types::layout_replace_epoch();
            let f = compile();
            // SAFETY: JIT-compiled code from valid bytecode; the receiver, the
            // bounds table and the card table are leaked live buffers, and the
            // marker helper writes only the receiver's first field.
            unsafe { f.call_with_heap(0, &[obj as i64, v]) }; // Cast: JIT ABI
            // Cast: the stored word.
            let word = v as u64;
            let got = read_field();
            assert!(
                got == word || got == word ^ HELPER_TAG,
                "the field holds neither path's store: {got:#x}"
            );
            (got != word, cratonvm_types::layout_replace_epoch() == epoch)
        };

        // Clean card, young value: the helper owns the card.
        let (helper, _) = store(young_value);
        assert!(helper, "clean card: jit_putfield_object");

        // Dirty card: stored inline, no call, the card stays dirty.
        ct.mark_dirty_lockfree(obj);
        let (helper, stable) = store(young_value);
        if stable {
            assert!(!helper, "dirty card: stored inline, no call");
        }
        assert!(ct.is_dirty(card));

        // Old value, clean card: old -> old needs no card.
        ct.clear_all();
        let (helper, stable) = store(old_value);
        if stable {
            assert!(!helper, "old value: stored inline, no call");
        }
        assert!(!ct.is_dirty(card), "compiled code never dirties a card");

        // Null value: no edge.
        let (helper, stable) = store(0);
        if stable {
            assert!(!helper, "null value: stored inline, no call");
        }

        // An armed SATB gate takes the helper even over a dirty card.
        ct.mark_dirty_lockfree(obj);
        // SAFETY: the leaked pre-gate byte.
        unsafe { gates.write_volatile(1) };
        let (helper, _) = store(young_value);
        assert!(helper, "armed SATB gate: the helper");
        // SAFETY: as above.
        unsafe { gates.write_volatile(0) };
    }

    /// The gated arm emits BOTH store shapes and picks between them per object.
    ///
    /// A compact-only arm is an arm that almost never fires. `init_object_header`
    /// — the TLAB fast path serving nearly every allocation for the interpreter
    /// and `jit_new_object` alike — writes a LEGACY header unconditionally, no
    /// `GC_FLAG_COMPACT`, whatever layout the class has registered. Measured on
    /// `RefStoreLoopProbe` with only the compact shape emitted: 16,384,000
    /// executions, `inline=0`, every one bailing at the compactness test, on
    /// Generational and ZGC alike. This asserts the shape that fixed it.
    #[test]
    fn the_gated_arm_emits_the_legacy_cell_store_as_well_as_the_compact_one() {
        let code = lower_compact_ref_putfield(true, 8);
        // The legacy 16-byte `Value` cell for field 0: tag qword then the
        // pointer payload, both at `HEADER_SIZE + 0 * SLOT_SIZE`.
        // `i32::try_from`, not the bare cast: the audit in
        // `flag_and_header_contracts` counts that cast form as an EMISSION
        // site, and a test expectation is not one -- including in this comment,
        // which is why it does not spell the form out.
        let legacy_off = i32::try_from(HEADER_SIZE).expect("the header fits an i32");
        let mut tag_store: Vec<u8> = vec![0x4C, 0x89, 0x90]; // MOV [RAX+disp32], R10
        tag_store.extend_from_slice(
            &(legacy_off + cratonvm_types::FIELD_CELL_TAG_OFFSET as i32).to_le_bytes(),
        );
        assert!(
            contains_seq(&code, &tag_store),
            "the legacy shape must write the cell's TAG — a payload written \
             without it leaves a cell whose discriminant still says whatever \
             the field held before, and the reader believes the discriminant"
        );
        let mut pay_store: Vec<u8> = vec![0x48, 0x89, 0x90]; // MOV [RAX+disp32], RDX
        pay_store
            .extend_from_slice(&(legacy_off + FIELD_CELL_PAYLOAD64_OFFSET as i32).to_le_bytes());
        assert!(
            contains_seq(&code, &pay_store),
            "the legacy shape must write the 64-bit pointer payload"
        );
        // And the compact shape is still there — this is a two-shape arm, not a
        // replacement of one dead shape by another.
        let mut compact_store: Vec<u8> = vec![0x48, 0x89, 0x90];
        compact_store.extend_from_slice(&8i32.to_le_bytes());
        assert!(
            contains_seq(&code, &compact_store),
            "the compact shape must survive: the receiver's own header decides, \
             and a genuinely compact object stores the bare pointer"
        );
    }

    /// The gated arm reads the receiver's flags byte ONCE and asks both
    /// questions of it: compactness, then the post-barrier skip mask.
    ///
    /// Both are `TEST CL, imm8` against a bit in `GC_FLAGS_BYTE_OFFSET`, which
    /// packs `gc_age` in bits 4..7 and the GC flags in bits 0..3. The mask
    /// shape exists because the floor shape cannot express the generational
    /// question: an old-gen object allocated at `gc_age == 0` has flags byte
    /// `0x01` and sorts BELOW a young object that survived three collections
    /// (`0x30`), so an unsigned floor would skip the card the first one needs.
    #[test]
    fn the_gated_arm_tests_the_flags_byte_for_compactness_and_for_the_skip_mask() {
        let code = lower_compact_ref_putfield(true, 8);
        assert!(
            contains_seq(&code, &[0xF6, 0xC1, cratonvm_types::GC_FLAG_COMPACT]),
            "the arm must test GC_FLAG_COMPACT — a class with a registered \
             compact layout can still have legacy-cell instances, and storing \
             a pointer at the packed offset into one of those corrupts a \
             neighbouring field"
        );
        assert!(
            contains_seq(&code, &[0xF6, 0xC1, cratonvm_types::GC_FLAG_OLD_GEN]),
            "the arm must test the published skip mask to rule the post \
             barrier out"
        );
        // MOVZX ECX, byte [RAX + GC_FLAGS_BYTE_OFFSET] — read once, asked
        // twice. A second read would be a second chance for the two answers to
        // come from different bytes.
        let mut read_seq: Vec<u8> = vec![0x0F, 0xB6, 0x88];
        read_seq.extend_from_slice(&(cratonvm_types::GC_FLAGS_BYTE_OFFSET as i32).to_le_bytes());
        assert!(
            contains_seq(&code, &read_seq),
            "the flags byte must be read as a BYTE at its own offset, not as \
             the dword the older arms use — that dword starts 15 bytes into a \
             16-byte header and takes three of its four bytes from the first \
             instance field"
        );
    }

    /// A site with no resolved compact slot keeps the unconditional helper.
    ///
    /// The refusal that matters most: `HEADER_SIZE + field_index * SLOT_SIZE`
    /// is the legacy cell displacement, and emitting a store there for a
    /// compact object would write a pointer over an unrelated field. The
    /// snapshot being absent is the ordinary case for an unresolved site, not
    /// an error.
    #[test]
    fn a_reference_store_with_no_resolved_compact_slot_keeps_the_helper() {
        static PRE_GATE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
        static POST_GATE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(1);
        static READ_BOUNDS: [u64; 6] = [0; 6];
        unsafe extern "C" fn fake_putfield_object(_vm: i64, _obj: i64, _idx: i64, _val: i64) {}

        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.putfield_object = fake_putfield_object as *const () as usize;
        helpers.putfield_int = fake_putfield_object as *const () as usize;
        helpers.read_bounds_addr = std::ptr::addr_of!(READ_BOUNDS) as usize;
        helpers.ref_store_pre_gate = std::ptr::addr_of!(PRE_GATE) as usize;
        helpers.ref_store_post_gate = std::ptr::addr_of!(POST_GATE) as usize;
        helpers.ref_store_post_skip_mask = cratonvm_types::GC_FLAG_OLD_GEN as usize;

        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let code = lower_inner(
            &graph,
            &schedule,
            2,
            4,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("the store must still compile through the helper")
        .code_bytes()
        .to_vec();
        assert!(
            !contains_seq(&code, &[0xF6, 0xC1, cratonvm_types::GC_FLAG_COMPACT]),
            "with no resolved compact slot the gated arm must not be emitted \
             at all, published plan or not"
        );
        assert!(
            contains_seq(
                &code,
                &(fake_putfield_object as *const () as u64).to_le_bytes()
            ),
            "the unconditional `jit_putfield_object` lowering must remain"
        );
    }

    /// A plan is all three gates or none, and the optimizing tier reads that
    /// through the SAME predicate the single-pass backend uses.
    ///
    /// The shared reader is the point. A pre-gate with a dead post-gate would
    /// let compiled code skip the post barrier on the strength of a word nobody
    /// maintains, and two tiers deciding that independently is how one of them
    /// ends up skipping a barrier the other pays.
    #[test]
    fn a_half_published_plan_leaves_the_optimizing_tier_on_the_helper() {
        static PRE_GATE: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(0);
        static READ_BOUNDS: [u64; 6] = [0; 6];
        unsafe extern "C" fn fake_putfield_object(_vm: i64, _obj: i64, _idx: i64, _val: i64) {}

        let graph = ref_or_wide_putfield_graph(b'L', 0x19, IrType::Ref);
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.putfield_object = fake_putfield_object as *const () as usize;
        helpers.putfield_int = fake_putfield_object as *const () as usize;
        helpers.read_bounds_addr = std::ptr::addr_of!(READ_BOUNDS) as usize;
        // Pre-gate only: no post-gate, no post shape.
        helpers.ref_store_pre_gate = std::ptr::addr_of!(PRE_GATE) as usize;

        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        compact.insert((3usize, true), (8u32, true, b'L'));
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let code = lower_inner(
            &graph,
            &schedule,
            2,
            4,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("the store must still compile through the helper")
        .code_bytes()
        .to_vec();
        let mut store_seq: Vec<u8> = vec![0x48, 0x89, 0x90];
        store_seq.extend_from_slice(&8i32.to_le_bytes());
        assert!(
            !contains_seq(&code, &store_seq),
            "a plan missing its post-barrier gate must decline the whole fast \
             path, not emit a store gated only on the half that was published"
        );
    }

    /// Round 11 wave 2 (lane lower, `r11-irlower-no-inline-primitive-putfield`):
    /// a primitive store with a resolved compact cell is stored INLINE in both
    /// layouts, with the width helper kept as the slow path; without a compact
    /// row the site is exactly the helper call it always was.
    #[test]
    fn a_primitive_putfield_with_a_compact_cell_stores_inline() {
        // A heap slot, not a `static`: the statics ratchet counts test ones too.
        let read_bounds: &'static [u64; 6] = Box::leak(Box::new([0u64; 6]));
        unsafe extern "C" fn fake_putfield_long(_obj: i64, _idx: i64, _val: i64) {}
        let graph = ref_or_wide_putfield_graph(b'J', 0x16, IrType::Long);
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.putfield_long = fake_putfield_long as *const () as usize;
        helpers.read_bounds_addr = read_bounds.as_ptr() as usize;
        let lower_with = |compact: &HashMap<(usize, bool), (u32, bool, u8)>| {
            let empty_hints: HashMap<usize, bool> = HashMap::new();
            let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
            let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
            lower_inner(
                &graph,
                &schedule,
                2,
                4,
                &helpers,
                &empty_hints,
                &[],
                None,
                &no_direct,
                &no_ic,
                compact,
                &crate::ir::IrInlineFrameSites::default(),
            )
            .expect("a long store with its helper compiles")
            .code_bytes()
            .to_vec()
        };
        let mut compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        compact.insert((3usize, false), (16u32, false, b'J'));
        let with_row = lower_with(&compact);
        let without_row = lower_with(&HashMap::new());
        let helper = (fake_putfield_long as *const () as u64).to_le_bytes();
        assert!(
            contains_seq(&with_row, &helper),
            "the helper stays the slow path"
        );
        assert!(
            contains_seq(&without_row, &helper),
            "no row: the helper call alone"
        );
        // MOV qword [RAX + 16], RDX -- the compact cell store. The row's
        // displacement is ABSOLUTE (the 8-byte compact header): no
        // `HEADER_SIZE` is added.
        let mut compact_store: Vec<u8> = vec![0x48, 0x89, 0x90];
        compact_store.extend_from_slice(&16i32.to_le_bytes());
        // MOV qword [RAX + HEADER_SIZE], imm32 1 -- the legacy cell's `Long` tag.
        let mut legacy_tag: Vec<u8> = vec![0x48, 0xC7, 0x80];
        legacy_tag.extend_from_slice(&(HEADER_SIZE as i32).to_le_bytes());
        legacy_tag.extend_from_slice(&1u32.to_le_bytes());
        assert!(!contains_seq(&without_row, &compact_store));
        let admitted = cratonvm_types::compact_ref_fields_enabled()
            && crate::x64::inline_putfield_enabled()
            && !crate::x64::narrow_oops_block_inline_fields()
            && cratonvm_types::flags::runtime_flag_default_on("CRATONVM_JIT_INLINE_PRIM_PUTFIELD");
        assert_eq!(
            contains_seq(&with_row, &compact_store),
            admitted,
            "the compact store is emitted exactly when the site is admitted"
        );
        assert_eq!(contains_seq(&with_row, &legacy_tag), admitted);
    }

    /// COV-03 — the same per-kind refusal for the wide widths, each of which
    /// has its own helper. Wired one at a time so a graph is never accepted on
    /// the strength of a DIFFERENT width's helper being present.
    #[test]
    fn a_wide_putfield_lowers_only_through_its_own_width_helper() {
        unsafe extern "C" fn fake_putfield(_obj: i64, _idx: i64, _val: i64) {}
        let addr = fake_putfield as *const () as usize;
        for (tag, load_op, ty) in [
            (b'J', 0x16u8, IrType::Long),
            (b'F', 0x17, IrType::Float),
            (b'D', 0x18, IrType::Double),
        ] {
            let graph = ref_or_wide_putfield_graph(tag, load_op, ty);
            let schedule = ir_schedule::schedule(&graph);
            assert!(
                lower(&graph, &schedule, 2, 4, &no_helpers()).is_none(),
                "a {} store with no width helper must be refused",
                tag as char
            );
            let mut helpers = no_helpers();
            match tag {
                b'J' => helpers.putfield_long = addr,
                b'F' => helpers.putfield_float = addr,
                _ => helpers.putfield_double = addr,
            }
            let cm = lower(&graph, &schedule, 2, 4, &helpers)
                .unwrap_or_else(|| panic!("a {} store with its helper must compile", tag as char));
            assert!(
                contains_seq(cm.code_bytes(), &(addr as u64).to_le_bytes()),
                "the {} store must CALL its width helper",
                tag as char
            );
        }
    }

    /// COV-03 — a wide field READ needs `jit_dispatch_threw`, because
    /// `Long.MIN_VALUE` and the `-0.0` bit pattern are bit-identical to
    /// `jit_getfield`'s deopt/NPE sentinel. Without the out-of-band peek the
    /// lowering would have to either drop a real NPE or bail on a legitimate
    /// value, so it refuses instead.
    ///
    /// A REFERENCE read is the control: no plausible heap pointer equals
    /// `i64::MIN`, so it keeps the plain compare-and-bail and must NOT start
    /// demanding the peek.
    ///
    /// # The two stub bodies must not be identical
    ///
    /// This test decides "was `dispatch_threw`'s address baked into the code?"
    /// by searching the emitted bytes for it, so it is only meaningful while
    /// `dispatch_threw` and `getfield` have DIFFERENT addresses. Both stubs
    /// used to be `-> i64 { 0 }`, which compiles to the same `xor eax,eax; ret`
    /// — and the MSVC linker's identical-COMDAT-folding (`/OPT:ICF`, on in
    /// release, off in debug) then gave them ONE address. The `L` control arm
    /// found `getfield`'s baked address, could not tell it from
    /// `dispatch_threw`'s, and failed: **red in `--release`, green in `debug`,
    /// for a lowering that was correct all along.**
    ///
    /// `fake_getfield` therefore returns a distinct non-zero value (any
    /// non-sentinel value is a legitimate field read), which no linker may fold
    /// with `fake_dispatch_threw`'s semantically-required `0`. The assertion
    /// below pins that: if a future toolchain unifies them anyway, this fails
    /// with the reason instead of silently inverting a byte search.
    #[test]
    fn a_wide_field_read_refuses_without_the_sentinel_disambiguator() {
        unsafe extern "C" fn fake_getfield(_vm: i64, _obj: i64, _idx: i64) -> i64 {
            // NOT `0`: see the doc comment. Any value but `i64::MIN` reads as
            // an ordinary field value here.
            7
        }
        extern "C" fn fake_dispatch_threw() -> i64 {
            // Semantically pinned: `0` means "no out-of-band signal pending".
            0
        }
        assert_ne!(
            fake_getfield as *const () as usize, fake_dispatch_threw as *const () as usize,
            "the two stubs were folded to one address (MSVC /OPT:ICF or an LTO \
             equivalent), so searching the emitted code for `dispatch_threw` \
             cannot distinguish it from `getfield` and this test's control arm \
             is meaningless. Give the stub bodies distinct instructions again."
        );
        for (tag, ret, needs_peek) in [
            (b'J', 0xadu8, true),
            (b'D', 0xaf, true),
            (b'F', 0xae, true),
            (b'L', 0xb0, false),
        ] {
            // aload_0; getfield #2; <x>return
            let code = [0x2a, 0xb4, 0x00, 0x02, ret, 0, 0];
            let mut b = IrBuilder::new(1, 1);
            b.set_param_types(&[IrType::Ref]);
            let mut fi = std::collections::HashMap::new();
            fi.insert(1usize, (0usize, tag));
            b.set_field_info(fi);
            b.set_wide_field_gates(true, true);
            let graph = b.build(&code, 5).expect("wide getfield builds when gated");
            let schedule = ir_schedule::schedule(&graph);

            let mut helpers = no_helpers();
            helpers.getfield = fake_getfield as *const () as usize;
            assert_eq!(
                lower(&graph, &schedule, 1, 1, &helpers).is_none(),
                needs_peek,
                "{}: refusal without `dispatch_threw` should be {needs_peek}",
                tag as char
            );

            helpers.dispatch_threw = fake_dispatch_threw as *const () as usize;
            let cm = lower(&graph, &schedule, 1, 1, &helpers)
                .unwrap_or_else(|| panic!("{} read must compile once wired", tag as char));
            assert_eq!(
                contains_seq(
                    cm.code_bytes(),
                    &(helpers.dispatch_threw as u64).to_le_bytes()
                ),
                needs_peek,
                "{}: the sentinel peek must be emitted iff the width can collide",
                tag as char
            );
        }
    }

    /// A REFERENCE `getfield` must tell the helper that the code after the call
    /// is going to DEREFERENCE what comes back.
    ///
    /// The helper reads a `Value` out of the slot and returns the payload of
    /// whichever variant it finds, and compiled code checks the returned word
    /// against `i64::MIN` and nothing else. Without
    /// `GETFIELD_EXPECT_REFERENCE` a reference field whose slot had been
    /// type-punned to a primitive therefore came back as that primitive's bits
    /// and was followed as a pointer: `SQLChar.rawData` (declared `[C`) read
    /// back as `Int(1)`, and the `arraylength` this arm emits — a plain
    /// `MOV r32,[reg+4]` — faulted at `addr=0x5`.
    ///
    /// This is an EMISSION test on purpose. The miscompiled body was
    /// deterministic (three crashes, byte-identical registers) but its
    /// reachability was not — 3 crashes in 38 runs one hour and 0 in 129 the
    /// next — so running the workload can never distinguish a fix from luck.
    /// What can be pinned is that the flag is in the argument.
    #[test]
    fn a_lowered_reference_getfield_tells_the_helper_it_will_be_dereferenced() {
        // Any non-`i64::MIN` return reads as an ordinary field value; this test
        // never executes the code, it only inspects what was emitted.
        unsafe extern "C" fn stub_getfield(_vm: i64, _obj: i64, _idx: i64) -> i64 {
            7
        }
        let fake_getfield = stub_getfield;

        // aload_0; getfield #2 -> slot 5, `[C`; areturn
        let code = [0x2a, 0xb4, 0x00, 0x02, 0xb0, 0, 0];
        let mut b = IrBuilder::new(1, 1);
        b.set_param_types(&[IrType::Ref]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(1usize, (5usize, b'['));
        b.set_field_info(fi);
        let graph = b.build(&code, 5).expect("a reference getfield builds");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.getfield = fake_getfield as *const () as usize;
        let cm = lower(&graph, &schedule, 1, 1, &helpers).expect("must compile");

        // Two arms can lower this — the main one, which also claims the
        // receiver proof, and the inline-compact fallback, which does not.
        // Either is correct; emitting the BARE index is not.
        //
        // Built from the CONSTANTS, not by calling `getfield_index_arg`. A
        // first version of this test computed its expectation with the same
        // encoder the emitter uses, so disabling the encoder moved both sides
        // together and the assertion below passed while nothing was flagged —
        // it only went red on the int case, by accident. An expectation
        // computed from the thing under test is not an expectation.
        const EXPECT_REF: u64 = cratonvm_jit_api::GETFIELD_EXPECT_REFERENCE;
        const PROVEN: u64 = cratonvm_jit_api::GETFIELD_RECEIVER_PROVEN_OOP;
        let proven = 5u64 | EXPECT_REF | PROVEN;
        let unproven = 5u64 | EXPECT_REF;
        //
        // Accepting either means this pins "the emitted code flags the load",
        // not "every arm flags it" — measured: patching `ref_node` out of the
        // main arm alone leaves this green, because the fallback arm still
        // flags it. Per-arm coverage comes from routing all seven emit sites
        // in both backends through `getfield_index_arg`, plus the control that
        // disables that encoder and turns this red.
        assert!(
            contains_getfield_arg(cm.code_bytes(), proven)
                || contains_getfield_arg(cm.code_bytes(), unproven),
            "no getfield argument in the emitted code carries \
             GETFIELD_EXPECT_REFERENCE, so the helper will hand this \
             dereferencing arm whatever primitive the slot happens to hold"
        );

        // A PRIMITIVE field must not claim it: the flag makes the helper refuse
        // to return a payload, so setting it on an int load would turn every
        // such read into a silent zero.
        let code_i = [0x2a, 0xb4, 0x00, 0x02, 0xac, 0, 0];
        let mut b = IrBuilder::new(1, 1);
        b.set_param_types(&[IrType::Ref]);
        let mut fi = std::collections::HashMap::new();
        fi.insert(1usize, (5usize, b'I'));
        b.set_field_info(fi);
        let graph = b.build(&code_i, 5).expect("an int getfield builds");
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 1, 1, &helpers).expect("must compile");
        assert!(
            !contains_getfield_arg(cm.code_bytes(), proven)
                && !contains_getfield_arg(cm.code_bytes(), unproven),
            "an int field must not claim GETFIELD_EXPECT_REFERENCE"
        );
    }

    fn compile_via_ir_no_opt(
        code: &[u8],
        code_len: usize,
        num_params: usize,
        num_locals: usize,
    ) -> CompiledMethod {
        let builder = IrBuilder::new(num_params, num_locals);
        let graph = builder.build(code, code_len).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        lower(&graph, &schedule, num_params, num_locals, &no_helpers()).expect("lower")
    }

    /// Does the emitted code bake a `jit_getfield` third argument equal to
    /// `want`, ignoring the NPE trap-SITE key?
    ///
    /// A byte-sequence search used to be enough, and stopped being enough when
    /// the argument grew a third passenger: the key is a per-compile monotonic
    /// id, so the eight bytes differ from `want` by a value no expectation can
    /// name without becoming a copy of the emitter. Masking ONE documented
    /// field off keeps the property this test was written for -- the
    /// expectation is built from constants, never from `getfield_index_arg` --
    /// while letting the passenger through.
    fn contains_getfield_arg(hay: &[u8], want: u64) -> bool {
        hay.windows(8).any(|w| {
            let v = u64::from_le_bytes(w.try_into().expect("an 8-byte window"));
            v & !cratonvm_jit_api::GETFIELD_NPE_SITE_MASK == want
        })
    }

    /// True iff `needle` appears as a contiguous subsequence of `hay`.
    fn contains_seq(hay: &[u8], needle: &[u8]) -> bool {
        needle.len() <= hay.len() && hay.windows(needle.len()).any(|w| w == needle)
    }

    /// Count non-overlapping occurrences of `needle` in `hay`.
    fn count_seq(hay: &[u8], needle: &[u8]) -> usize {
        if needle.is_empty() || needle.len() > hay.len() {
            return 0;
        }
        hay.windows(needle.len()).filter(|w| *w == needle).count()
    }

    // ── IR inline caches (jit-inlining-and-ir-calls) ────────────────────

    /// Build → lower a `static int f(Obj o, int n) { return o.g(n); }` shaped
    /// body whose single `invokevirtual` is planned as an inline-cache site.
    ///
    /// `ic` is the `pc → (mic, pic)` map handed to `lower_inner`; passing an
    /// empty map exercises the unchanged generic-dispatch path, which is what
    /// makes the "absent plan is byte-identical" assertion below meaningful.
    ///
    /// The returned code is never EXECUTED — the baked helper/slot addresses
    /// are test sentinels, not real functions. These tests assert on the
    /// emitted instruction stream, which is the part this change owns; the
    /// end-to-end execution coverage for IR call lowering lives in
    /// `jit/tests/ir_vs_singlepass.rs` (see the doc for the cases to add
    /// there — that file is outside this change's ownership).

    /// Every inline-cache hit in this tier restores the innermost-frame mirror
    /// before it does anything else.
    ///
    /// A compiled callee's prologue publishes ITS `(rbp, compile id)` there, and
    /// nothing on the return path of a raw JIT->JIT call restores the caller's.
    /// Until 2026-08-24 neither of this tier's two inline-cache arms — the
    /// monomorphic MIC hit and each rung of the polymorphic PIC cascade — did,
    /// so after any hit the mirror named a frame that had already returned.
    /// `moving_young_frame_coverage_complete` then read
    /// `[stale_rbp - stale_method.sp_id_slot_off]`, matched no map, and refused
    /// the whole collection (`ACTIVE_FRAME_MAP`). Measured on H2
    /// `TestMVStoreTool`: one rbp with ONE saved return address claimed across
    /// collections by four different methods, one of them `RootReference.isLocked`
    /// with `maps=0` — a method that emits no safepoint and therefore cannot be
    /// the frame at a collection at all.
    ///
    /// The single-pass backend republishes at both of its equivalent arms and
    /// the shared hashed/vtable stub is handed `frame_record` for the same
    /// reason; these two were the gap.
    ///
    /// Asserted as "the byte right after the CALL", because that placement is
    /// the property: anything emitted between the return and the republish runs
    /// under a mirror naming a dead frame. The zero-`frame_record` arm is the
    /// control — it proves the assertion can FAIL, so a future edit that drops
    /// the republish cannot leave this test passing vacuously.
    #[test]
    fn every_inline_cache_hit_restores_the_frame_record_before_anything_else() {
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        const FRAME_RECORD: usize = 0x7fff_0000_0000_3000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));

        // `CALL R11` — the cached-entry indirect call, and the ONLY way this
        // tier reaches a compiled Java callee from an inline cache.
        const CALL_R11: [u8; 3] = [0x41, 0xFF, 0xD3];
        let seg = crate::x64::inline_rbp_tls_segment_prefix();

        let sites = |code: &[u8]| -> Vec<usize> {
            (0..code.len().saturating_sub(3))
                .filter(|&i| code[i..i + 3] == CALL_R11)
                .collect()
        };

        let with = lower_virtual_call_with_ic_fr(&ic, FRAME_RECORD);
        let without = lower_virtual_call_with_ic_fr(&ic, 0);

        let with_sites = sites(&with);
        // One MIC arm plus one rung per PIC entry. If this is ever zero the
        // test below is vacuous, which is the failure mode worth naming.
        assert!(
            with_sites.len() >= 1 + crate::JIT_PIC_ENTRIES,
            "expected at least {} cached-entry calls, found {} — the probe cannot fire",
            1 + crate::JIT_PIC_ENTRIES,
            with_sites.len()
        );

        for at in &with_sites {
            let next = with[at + 3];
            // Inline form: `MOV <seg>:[disp32], RBP` opens with the segment
            // prefix. Helper form (no probed TLS displacement): `PUSH RAX`
            // preserves the callee's Java return value first.
            assert!(
                next == seg || next == 0x50,
                "cached-entry CALL at {at} is followed by {next:#04x}, not the \
                 frame-record republish ({seg:#04x} inline / 0x50 helper form)"
            );
        }

        // The control. With no frame-record helper the republish is switched
        // off wholesale, so NONE of the sites may carry it — which is what
        // makes the assertion above discriminating rather than decorative.
        for at in sites(&without) {
            let next = without[at + 3];
            assert!(
                next != seg && next != 0x50,
                "frame_record=0 must emit no republish, but the call at {at} is \
                 followed by {next:#04x}"
            );
        }
    }

    fn lower_virtual_call_with_ic(ic: &HashMap<usize, (usize, usize)>) -> Vec<u8> {
        lower_virtual_call_with_ic_fr(ic, 0)
    }

    /// Round 11 wave 3 (lane lower,
    /// `r11-irlower-ic-hit-republishes-and-tests-the-sentinel-twice`): with the
    /// callee-deopt service wired, each MIC/PIC hit tests the sentinel ONCE.
    /// Its not-sentinel edge (`JNO`) must land at `.hit_join`, i.e. just past
    /// the site's shared sentinel tail (`CMP RAX,1; JO rel32`), not in front
    /// of it, where the hot hit would compare a second time.
    #[test]
    fn r11w3_an_inline_cache_hit_tests_the_sentinel_once() {
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        // aload_0; iload_1; invokevirtual #2; ireturn -- as
        // `lower_virtual_call_with_ic_fr`, plus a wired service.
        let code = [0x2a, 0x1b, 0xb6, 0x00, 0x02, 0xac, 0x00, 0x00];
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/Obj",
            method_name: "g",
            descriptor: "(I)I",
            num_jit_args: 2,
            return_type: b'I',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let info_ptr = info as *const JitInvokeInfo as usize;
        let mut builder = IrBuilder::new(2, 2);
        builder.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(2usize, (info_ptr, 2usize, b'I'));
        builder.set_invoke_info(invoke_info);
        let graph = builder.build(&code, 6).expect("IR build of virtual call");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.invoke_dispatch = 0x1111_2222_3333_4440;
        helpers.invoke_virtual_mic = 0x1111_2222_3333_4441;
        helpers.dispatch_threw = 0x1111_2222_3333_4442;
        helpers.service_callee_deopt = 0x1111_2222_3333_4443;
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let cm = lower_inner(
            &graph,
            &schedule,
            2,
            2,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("virtual-call method must lower");
        let code = cm.code_bytes();

        const CALL_R11: [u8; 3] = [0x41, 0xFF, 0xD3];
        // `CMP RAX, 1 ; JNO rel32` -- no republish in between: `frame_record`
        // is 0 here, which switches it off.
        const HIT_TEST: [u8; 6] = [0x48, 0x83, 0xF8, 0x01, 0x0F, 0x81];
        let hits: Vec<usize> = (0..code.len().saturating_sub(3))
            .filter(|&i| code[i..i + 3] == CALL_R11)
            .take(1 + crate::JIT_PIC_ENTRIES)
            .collect();
        assert_eq!(
            hits.len(),
            1 + crate::JIT_PIC_ENTRIES,
            "one CALL R11 per hit arm"
        );
        for at in hits {
            let t = at + 3;
            assert_eq!(
                &code[t..t + 6],
                &HIT_TEST[..],
                "the hit at {at} must test the sentinel right after its CALL"
            );
            let rel = i32::from_le_bytes(code[t + 6..t + 10].try_into().expect("rel32"));
            let target = (t as i64 + 10 + i64::from(rel)) as usize;
            assert!(
                target >= 6 && code[target - 6..target - 4] == [0x0F, 0x80],
                "the hit at {at} must skip the shared sentinel tail (JNO lands at \
                 {target}, which does not follow the tail's JO)"
            );
        }
    }

    /// As [`lower_virtual_call_with_ic`], with the frame-record helper
    /// pointer set. Zero is what `no_helpers()` gives, and zero switches the
    /// whole frame record off, so a test about the record has to pass a live
    /// one or it is asking a question the emitter never reaches.
    fn lower_virtual_call_with_ic_fr(
        ic: &HashMap<usize, (usize, usize)>,
        frame_record: usize,
    ) -> Vec<u8> {
        lower_virtual_call_with_ic_owner(ic, frame_record, "pkg/Obj")
    }

    /// As [`lower_virtual_call_with_ic_fr`], with the site's constant-pool
    /// owner named: since round 13 wave 11 (lane mega9, M13-6) it decides
    /// whether the cascade screens the receiver's kind.
    fn lower_virtual_call_with_ic_owner(
        ic: &HashMap<usize, (usize, usize)>,
        frame_record: usize,
        owner: &'static str,
    ) -> Vec<u8> {
        // aload_0; iload_1; invokevirtual #2; ireturn
        let code = [0x2a, 0x1b, 0xb6, 0x00, 0x02, 0xac, 0x00, 0x00];
        // A live `JitInvokeInfo` for the site. Leaked deliberately: `Op::Call`
        // bakes its address, and the lowerer dereferences it to read
        // `invoke_kind`.
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: owner,
            method_name: "g",
            descriptor: "(I)I",
            num_jit_args: 2, // receiver + one int
            return_type: b'I',
            invoke_kind: 0, // virtual
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let info_ptr = info as *const JitInvokeInfo as usize;

        let mut builder = IrBuilder::new(2, 2);
        builder.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(2usize, (info_ptr, 2usize, b'I'));
        builder.set_invoke_info(invoke_info);
        let graph = builder.build(&code, 6).expect("IR build of virtual call");
        let schedule = ir_schedule::schedule(&graph);

        let mut helpers = no_helpers();
        // Distinct non-zero sentinels so each path is identifiable in the
        // emitted imm64s.
        helpers.invoke_dispatch = 0x1111_2222_3333_4440;
        helpers.invoke_virtual_mic = 0x1111_2222_3333_4441;
        helpers.dispatch_threw = 0x1111_2222_3333_4442;
        helpers.frame_record = frame_record;

        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        lower_inner(
            &graph,
            &schedule,
            2,
            2,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("virtual-call method must lower")
        .code_bytes()
        .to_vec()
    }

    /// Lower one `invokestatic` with `n` int parameters as a DIRECT call to
    /// `entry`, and return the emitted bytes.
    ///
    /// `needs_ctx` picks whether the callee takes the hidden VM context
    /// pointer in `abi[0]`, which is what decides how many Java arguments are
    /// left for the register file.
    fn lower_direct_call_with_n_args(n: usize, entry: usize, needs_ctx: bool) -> Vec<u8> {
        assert!((1..=8).contains(&n));
        // The arguments are CONSTANTS, not this method's parameters. A caller
        // with `n` parameters would be refused outright by `lower()` when `n`
        // exceeds `incoming_abi_reg_capacity()` — which is exactly the case
        // under test — and the refusal is about the PROLOGUE, a different
        // question from the one these tests ask.
        let mut code: Vec<u8> = Vec::new();
        for _ in 0..n {
            code.push(0x03); // iconst_0
        }
        let invoke_pc = code.len();
        code.extend_from_slice(&[0xb8, 0x00, 0x02]); // invokestatic #2
        code.push(0xac); // ireturn
        let code_len = code.len();
        // `IrBuilder::build` reads a little past the end for operand fetch.
        code.extend_from_slice(&[0x00, 0x00]);

        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/Wide",
            method_name: "f",
            descriptor: "(IIIIIII)I",
            num_jit_args: n,
            return_type: b'I',
            invoke_kind: 3, // static — the statically bound, directly bindable kind
            declaring_class_id: 0,
            owner_class_id: 0,
        }));

        let mut builder = IrBuilder::new(0, 1);
        builder.set_param_types(&[]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(invoke_pc, (info as *const JitInvokeInfo as usize, n, b'I'));
        builder.set_invoke_info(invoke_info);
        let graph = builder
            .build(&code, code_len)
            .expect("IR build of wide call");
        let schedule = ir_schedule::schedule(&graph);

        let mut helpers = no_helpers();
        helpers.invoke_dispatch = 0x1111_2222_3333_4440;

        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let mut direct: HashMap<usize, (usize, bool)> = HashMap::new();
        direct.insert(invoke_pc, (entry, needs_ctx));
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        lower_inner(
            &graph,
            &schedule,
            0,
            1,
            &helpers,
            &empty_hints,
            &[],
            None,
            &direct,
            &no_ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("wide direct call must lower")
        .code_bytes()
        .to_vec()
    }

    /// A direct call whose arguments do not all fit `ENTRY_ABI_REGS` marshals
    /// the remainder on the stack instead of falling back to the dispatch
    /// helper.
    ///
    /// This is the blocker `httpcontentdecompressortest-snappy-varhandle-bind-RETIRED-20260820.md`
    /// named: `emit_direct_cross_call` was register-only, so a site needing
    /// seven incoming slots kept the full `jit_invoke_dispatch` round trip no
    /// matter what the binding side had resolved. The map entry was recorded
    /// and then silently dropped by the lowerer — nothing warned.
    ///
    /// The assertion is structural rather than a byte-for-byte golden: the
    /// block size differs by platform (Win64 reserves 32 bytes of shadow
    /// space below the outgoing arguments, SysV none) and so does how many
    /// arguments are left over, and pinning both would only restate
    /// `stack_arg_block_size`.
    #[test]
    fn a_direct_call_past_the_register_file_marshals_its_tail_on_the_stack() {
        crate::x64::set_moving_young_override(Some(false));
        const ENTRY: usize = 0x7fff_0000_0000_5000;
        let n = ENTRY_ABI_REGS.len() + 2; // context + n args exceeds the file
        let code = lower_direct_call_with_n_args(n, ENTRY, true);

        assert!(
            contains_seq(&code, &(ENTRY as u64).to_le_bytes()),
            "the site must bake the callee entry, not fall back to dispatch"
        );
        assert!(
            !contains_seq(&code, &0x1111_2222_3333_4440u64.to_le_bytes()),
            "a bound direct site must not also emit the dispatch helper call"
        );

        // SUB RSP, imm32 / ADD RSP, imm32 with the SAME immediate: the block
        // is reserved and released around one call, so an unbalanced pair
        // would leave the frame's RSP permanently low.
        //
        // The FIRST `SUB RSP, imm32` in any body is the prologue's own frame
        // allocation, which shares this encoding — hence `skip(1)` rather than
        // `position`. Taking the first would assert against `frame_size` and
        // pass whether or not a stack-argument block was ever emitted.
        let subs: Vec<usize> = code
            .windows(3)
            .enumerate()
            .filter(|(_, w)| *w == [0x48, 0x81, 0xEC])
            .map(|(i, _)| i)
            .collect();
        assert!(
            subs.len() >= 2,
            "the prologue's frame allocation plus a stack-argument block: got {} SUB RSP",
            subs.len()
        );
        let sub_at = subs[1];
        let add_at = code
            .windows(3)
            .position(|w| w == [0x48, 0x81, 0xC4])
            .expect("the stack-argument block must be released");
        let sub_imm = i32::from_le_bytes(code[sub_at + 3..sub_at + 7].try_into().unwrap());
        let add_imm = i32::from_le_bytes(code[add_at + 3..add_at + 7].try_into().unwrap());
        assert_eq!(sub_imm, add_imm, "the reserve and the release must match");
        assert!(sub_imm > 0, "a stack-argument block must be non-empty here");
        assert_eq!(
            sub_imm % 16,
            0,
            "RSP must stay 16-byte aligned at the CALL, so the block is a multiple of 16"
        );
        assert!(add_at > sub_at, "the release must follow the reserve");

        // One `MOV [RSP + disp32], RAX` per argument past the register file.
        let stack_args = n - (ENTRY_ABI_REGS.len() - 1);
        assert_eq!(
            count_seq(&code, &[0x48, 0x89, 0x84, 0x24]),
            stack_args,
            "every argument past the entry-ABI register file must be stored to the block"
        );
    }

    /// The same lowering with arguments that DO fit emits no stack block at
    /// all — the narrow path is unchanged.
    ///
    /// Without this the test above would pass just as well against a backend
    /// that reserved a block on every direct call, which is a pessimisation of
    /// every call site in the tree.
    #[test]
    fn a_direct_call_within_the_register_file_reserves_no_stack_block() {
        crate::x64::set_moving_young_override(Some(false));
        const ENTRY: usize = 0x7fff_0000_0000_5000;
        let code = lower_direct_call_with_n_args(ENTRY_ABI_REGS.len() - 1, ENTRY, true);
        assert!(
            contains_seq(&code, &(ENTRY as u64).to_le_bytes()),
            "the narrow site must still bind directly"
        );
        assert_eq!(
            count_seq(&code, &[0x48, 0x81, 0xEC]),
            1,
            "only the prologue's own frame allocation — a call whose arguments \
             all fit registers must add no second SUB RSP"
        );
        assert_eq!(
            count_seq(&code, &[0x48, 0x89, 0x84, 0x24]),
            0,
            "a call whose arguments all fit registers must store nothing to the stack"
        );
    }

    /// A self-recursive call must not PUBLISH to the shadow stack.
    ///
    /// That route bypasses `emit_call_return_check`, the one site that emits
    /// the matching reload, so a push emitted here is never retracted: the
    /// thread's shadow `top` advances once per execution of the site and a
    /// recursive method walks it off the end of the shadow stack, after which
    /// the next push writes through into whatever follows the mapping. It
    /// presented as a SIGSEGV inside the C allocator's free list, on an
    /// unrelated thread, the moment reference field reads made
    /// `BinTreesClassic.itemCheck` IR-eligible.
    ///
    /// The lowerer used to emit the push and then "withdraw the claim" by
    /// clearing `pending_shadow` — which suppressed the RELOAD, not the push.
    #[test]
    fn self_recursive_call_balances_its_shadow_push_and_reload() {
        // The PER-CALL protocol is this test's subject; the frame block
        // publishes once per activation and has no reload to find.
        let _per_call = FrameBlockForce::set(false);
        crate::x64::set_moving_young_override(Some(false));
        // static int f(Obj o, int n) { return f(o, n); }
        // aload_0; iload_1; invokestatic #2; ireturn
        let code = [0x2a, 0x1b, 0xb8, 0x00, 0x02, 0xac, 0x00, 0x00];
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/Obj",
            method_name: "f",
            descriptor: "(Lpkg/Obj;I)I",
            num_jit_args: 2,
            return_type: b'I',
            invoke_kind: 4, // the direct self-recursive route
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let mut builder = IrBuilder::new(2, 2);
        builder.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(
            2usize,
            (info as *const JitInvokeInfo as usize, 2usize, b'I'),
        );
        builder.set_invoke_info(invoke_info);
        let graph = builder
            .build(&code, 6)
            .expect("IR build of self-recursive call");
        let schedule = ir_schedule::schedule(&graph);

        // The shadow machinery is live only when the thread helper is wired,
        // so a stub table with a zero `get_current_thread` would make this
        // test vacuous. Give it sentinels.
        let mut helpers = no_helpers();
        helpers.get_current_thread = 0x7fff_0000_0000_3000;
        helpers.shadow_stack_offset_in_thread = 0x40;
        helpers.self_call_stack_guard = 0x7fff_0000_0000_4000;

        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let cm = lower_inner(
            &graph,
            &schedule,
            2,
            2,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect(
            "the self-recursive body must lower — an imbalance now makes \
             lower_inner discard it, so a None here means the push came back",
        );
        // Lowering at all is most of the assertion: `lower_inner` counts the
        // emitted pushes against the emitted reloads and DISCARDS the body when
        // they disagree, so a `None` above is exactly the bug this test exists
        // for. What remains to check is that the retraction is really emitted
        // on this route rather than inherited from a choke point it never
        // reaches: `MOV RCX, [R11]` reads a published value back, and only the
        // reload does that. (Deliberately not an exact count — the prologue's
        // own `top` watermark shares the push's encoding, so counting pushes
        // here measures the prologue too.)
        let bytes = cm.code_bytes();
        assert!(
            count_seq(bytes, &[0x49, 0x8B, 0x0B]) >= 1,
            "the self-recursive route bypasses emit_call_return_check, so it \
             must emit its own shadow reload — without it every execution of \
             the site advances the thread's shadow top and nothing retracts it"
        );
        assert!(
            !cm.shadow_frame_block,
            "a per-call body must not tell the collector's frame walk to stand down"
        );
        crate::x64::set_moving_young_override(None);
    }

    /// The same self-recursive body under the FRAME BLOCK: the reference
    /// parameter's home is published once, as an indirect entry, and the call
    /// neither pushes nor copies back a value.
    ///
    /// What each assertion pins:
    ///
    ///   * `CMP qword [rbp - savebase], 0` — the once-per-activation test;
    ///   * `LEA RCX, [rbp - off + 1]` for the parameter home — the entry is
    ///     the home's ADDRESS with `ShadowStack::INDIRECT_TAG`, not its value;
    ///   * no `MOV RCX, [R11]` — nothing is read back from the shadow stack
    ///     after the call, because the collector rewrites the home in place;
    ///   * `shadow_frame_block` — the flag the collector's frame walk reads to
    ///     leave these homes to the shadow-stack remap.
    #[test]
    fn a_frame_block_publishes_the_homes_once_and_never_reloads() {
        let _block = FrameBlockForce::set(true);
        crate::x64::set_moving_young_override(Some(false));
        let code = [0x2a, 0x1b, 0xb8, 0x00, 0x02, 0xac, 0x00, 0x00];
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/Obj",
            method_name: "f",
            descriptor: "(Lpkg/Obj;I)I",
            num_jit_args: 2,
            return_type: b'I',
            invoke_kind: 4,
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let mut builder = IrBuilder::new(2, 2);
        builder.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(
            2usize,
            (info as *const JitInvokeInfo as usize, 2usize, b'I'),
        );
        builder.set_invoke_info(invoke_info);
        let graph = builder
            .build(&code, 6)
            .expect("IR build of self-recursive call");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.get_current_thread = 0x7fff_0000_0000_3000;
        helpers.shadow_stack_offset_in_thread = 0x40;
        helpers.self_call_stack_guard = 0x7fff_0000_0000_4000;
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let cm = lower_inner(
            &graph,
            &schedule,
            2,
            2,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("the self-recursive body must lower under the frame block");
        crate::x64::set_moving_young_override(None);

        assert!(cm.shadow_frame_block, "the body published a frame block");
        let bytes = cm.code_bytes();
        let savebase = -cm.shadow_savebase_slot_off;
        let mut ensure = vec![0x48, 0x83, 0xBD];
        ensure.extend_from_slice(&savebase.to_le_bytes());
        ensure.push(0);
        assert!(
            count_seq(bytes, &ensure) >= 1,
            "every safepoint that names a reference tests the saved-base flag"
        );
        // Parameter 0 is homed at [rbp - 8]: its entry is `rbp - 8 + 1`.
        let mut tagged_home = vec![0x48, 0x8D, 0x8D];
        tagged_home.extend_from_slice(&(1i32 - 8).to_le_bytes());
        assert!(
            count_seq(bytes, &tagged_home) >= 1,
            "the parameter home is published by ADDRESS, tagged"
        );
        assert_eq!(
            count_seq(bytes, &[0x49, 0x8B, 0x0B]),
            0,
            "nothing is read back from the shadow stack after the call"
        );
    }

    /// A planned inline-cache site must emit the full three-tier cascade:
    /// the receiver null check, ONE class-id load, the monomorphic guard, three
    /// polymorphic guards, four `CALL R11` cached-entry calls, and the
    /// `jit_invoke_virtual_mic` miss path — NOT the blind `jit_invoke_dispatch`
    /// helper the pre-2026-07-26 lowerer used for every virtual call.
    #[test]
    fn ic_site_emits_mic_pic_cascade_not_blind_dispatch() {
        // This test exercises the optimizing IR pipeline, which is gated off
        // whenever the young generation can relocate. Pin the policy so the
        // test covers IR lowering regardless of DEFAULT_MOVING_YOUNG.
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        let code = lower_virtual_call_with_ic(&ic);

        // Receiver null check + the single class-id load feeding every guard.
        assert!(
            contains_seq(&code, &[0x48, 0x85, 0xC0]),
            "TEST RAX,RAX receiver null check must be emitted"
        );
        assert_eq!(
            count_seq(&code, &[0x8B, 0x00]),
            1,
            "the receiver class id must be loaded exactly ONCE for the whole cascade"
        );
        // Both slot base pointers are baked as imm64 (`MOV R10, imm64` = 49 BA).
        assert!(
            contains_seq(&code, &[0x49, 0xBA]) && contains_seq(&code, &MIC.to_le_bytes()),
            "the MIC slot address must be baked into the guard"
        );
        assert!(
            contains_seq(&code, &PIC.to_le_bytes()),
            "the PIC slot address must be baked into the cascade"
        );
        // MIC + four PIC entries + the hashed stub all call via R11. Since
        // round 9 wave 3 (invoke2 X2) the two hashed ways share ONE tail, so
        // the stub contributes one `CALL R11`, not one per way.
        assert_eq!(
            count_seq(&code, &[0x41, 0xFF, 0xD3]),
            1 + crate::JIT_PIC_ENTRIES + 1,
            "one cached-entry CALL R11 per MIC/PIC entry plus the hashed stub's shared tail"
        );
        // The miss path resolves AND populates via `jit_invoke_virtual_mic`.
        assert!(
            contains_seq(&code, &0x1111_2222_3333_4441u64.to_le_bytes()),
            "the inline-cache miss path must call jit_invoke_virtual_mic"
        );
        assert!(
            !contains_seq(&code, &0x1111_2222_3333_4440u64.to_le_bytes()),
            "a planned IC site must NOT also emit the blind jit_invoke_dispatch helper"
        );
    }

    /// Every cached entry below is selected by the 4-byte
    /// `ObjectHeader.class_id`, and a reference array stores its COMPONENT
    /// class id in that same word — so `Foo[]` and `Foo` are indistinguishable
    /// to a class-id-only guard, and a site warmed on a `Foo` receiver
    /// dispatched a later `Foo[]` receiver into `Foo`'s own body (whose first
    /// `checkcast Foo` threw `class [LFoo; cannot be cast to class Foo`).
    /// `ObjectHeader.kind` is what separates them.
    #[test]
    fn ic_cascade_rejects_array_receivers_before_the_class_id_guard() {
        // This test exercises the optimizing IR pipeline, which is gated off
        // whenever the young generation can relocate. Pin the policy so the
        // test covers IR lowering regardless of DEFAULT_MOVING_YOUNG.
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        // Round 13 wave 11 (lane mega9, M13-6): an `Object`-owned site, which
        // an array CAN reach; a `pkg/Obj`-owned `invokevirtual` no longer
        // screens (`r13w11_mega9_ic_kind_screen_follows_the_static_owner`).
        let code = lower_virtual_call_with_ic_owner(&ic, 0, "java/lang/Object");

        // TEST BYTE [RAX+KIND_TAGS_BYTE_OFFSET], KIND_TAG_BYTE_MASK (F6 /0 ib: kind bits only)
        let guard = [
            0xF6u8,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8,
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ];
        assert!(
            contains_seq(&code, &guard),
            "the cascade must reject a non-object receiver kind before trusting the class id"
        );
        // ... and it must come BEFORE the single class-id load it protects.
        let guard_at = code
            .windows(guard.len())
            .position(|w| w == guard)
            .expect("guard present");
        let load_at = code
            .windows(2)
            .position(|w| w == [0x8B, 0x00])
            .expect("class-id load present");
        assert!(
            guard_at < load_at,
            "the kind guard must precede the class-id load (guard@{guard_at}, load@{load_at})"
        );
    }

    /// Round 13 wave 11 (lane mega9, proposal M13-6): the cascade screens the
    /// receiver's kind exactly where an array can be the receiver. A
    /// `pkg/Obj`-owned `invokevirtual` emits one screen fewer than an
    /// `Object`-owned one (the hashed stub keeps its own, for its null edge);
    /// under `CRATONVM_JIT_IR_IC_KIND_SCREEN_ELIDE=0` both emit the same
    /// bytes. Counted as a difference so the stub's presence does not matter.
    #[test]
    fn r13w11_mega9_ic_kind_screen_follows_the_static_owner() {
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        let guard = [
            0xF6u8,
            0x40,
            cratonvm_types::KIND_TAGS_BYTE_OFFSET as u8,
            cratonvm_types::KIND_TAG_BYTE_MASK,
        ];
        let screens = |owner: &'static str| {
            count_seq(&lower_virtual_call_with_ic_owner(&ic, 0, owner), &guard)
        };
        let object = screens("java/lang/Object");
        let class = screens("pkg/Obj");
        assert!(object >= 1, "an Object-owned site screens");
        assert_eq!(object, class + 1, "a class-owned invokevirtual skips the cascade's screen");
        for may_be_array in ["[I", "java/lang/Cloneable", "java/io/Serializable", ""] {
            assert_eq!(screens(may_be_array), object, "owner {may_be_array:?} screens");
        }
        let (object_off, class_off) = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_IC_KIND_SCREEN_ELIDE", Some("0"))],
            || (screens("java/lang/Object"), screens("pkg/Obj")),
        );
        assert_eq!(object_off, object, "switched off: unchanged for Object");
        assert_eq!(class_off, object, "switched off: every site screens");
        crate::x64::set_moving_young_override(None);
    }

    /// The guards must read the MIC/PIC fields at the offsets the shared slot
    /// types publish, not at hand-copied literals — this is what keeps the IR
    /// cascade layout-compatible with the single-pass one and with the runtime
    /// helper that populates both.
    #[test]
    fn ic_guards_use_published_slot_offsets() {
        // This test exercises the optimizing IR pipeline, which is gated off
        // whenever the young generation can relocate. Pin the policy so the
        // test covers IR lowering regardless of DEFAULT_MOVING_YOUNG.
        crate::x64::set_moving_young_override(Some(false));
        use crate::{JitMICSlot, JitPICSlot};
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        let code = lower_virtual_call_with_ic(&ic);

        // MIC: class id at offset 0 → `CMP EAX,[R10]` = 41 3B 02;
        // tagged entry word at 8 → `MOV R11,[R10+8]` = 4D 8B 5A 08.
        assert_eq!(JitMICSlot::CACHED_CLASS_ID_OFFSET, 0);
        assert!(contains_seq(&code, &[0x41, 0x3B, 0x02]));
        assert!(contains_seq(
            &code,
            &[
                0x4D,
                0x8B,
                0x5A,
                crate::x64::disp::disp8_const(JitMICSlot::CACHED_ENTRY_PTR_OFFSET as i64) as u8,
            ]
        ));

        // PIC: one guard + one entry-word load per entry.
        for i in 0..crate::JIT_PIC_ENTRIES {
            let cid = JitPICSlot::CLASS_ID_OFFSETS[i] as u8;
            if cid == 0 {
                assert!(contains_seq(&code, &[0x41, 0x3B, 0x02]));
            } else {
                assert!(
                    contains_seq(&code, &[0x41, 0x3B, 0x42, cid]),
                    "PIC entry {i} class-id guard at offset {cid} must be emitted"
                );
            }
            assert!(
                contains_seq(
                    &code,
                    &[
                        0x4D,
                        0x8B,
                        0x5A,
                        crate::x64::disp::disp8_const(JitPICSlot::ENTRY_PTR_OFFSETS[i] as i64)
                            as u8,
                    ]
                ),
                "PIC entry {i} entry-word load must be emitted"
            );
        }

        // Every cached-entry call — the MIC, the four PIC ways and the two
        // hashed ways — tests the word it loaded for zero (a class-only profile
        // seed, or a withdrawn target) and strips the context tag from THAT
        // word. One of each per `CALL R11`.
        //
        // Round 9 wave 3 (invoke2 X2): the two hashed ways share one tail, so
        // they share its one `CALL R11` and its one `BTR` -- but each way
        // still loads, and so still zero-tests, its OWN word.
        let calls = count_seq(&code, &[0x41, 0xFF, 0xD3]);
        assert_eq!(calls, 1 + crate::JIT_PIC_ENTRIES + 1);
        // The hashed stub's out-of-line probes join that same tail, and each
        // tests what it loaded itself too (round 12 wave 4, lane mega3, who
        // read this count after wave 3 moved it from 7 to 11): the shared
        // table's probe (wave 3) loads and zero-tests the word of each of its
        // four ways before `JNZ tail`; the class-slot probe (wave 4) tests the
        // directory root, the receiver's array and the cell's word, each right
        // after the `MOV R11` that loaded it. None of them tests a register it
        // did not load, and none calls: `calls` and the `BTR` count stay put.
        let mega_table = crate::runtime_lowering::hashed_stub_mega_table_enabled();
        let class_slots =
            mega_table && crate::runtime_lowering::hashed_stub_class_slots_enabled();
        let probe_tests = if mega_table { crate::MEGA_DISPATCH_WAYS } else { 0 }
            + if class_slots { 3 } else { 0 };
        assert_eq!(
            count_seq(&code, &[0x4D, 0x85, 0xDB]),
            1 + crate::JIT_PIC_ENTRIES + crate::JIT_MEGA_WAYS + probe_tests,
            "every cached-entry load must reject a zero word it loaded itself"
        );
        assert_eq!(
            count_seq(&code, &[0x49, 0x0F, 0xBA, 0xF3, 0x00]),
            calls,
            "every cached-entry call must take its ABI from the word it calls"
        );
        // And nothing may still read a separate needs-context byte: the MIC's
        // old flag at offset 16, or the PIC's at 48..=51.
        for off in [16u8, 48, 49, 50, 51] {
            assert!(
                !contains_seq(&code, &[0x41, 0x80, 0x7A, off, 0x00]),
                "a separate needs-context byte at offset {off} must not be read"
            );
        }
        // Offset 48 is the megamorphic flag since round 12 wave 6 (lane
        // mega5, W5-4): ONE gate reads it as a dword (`83 /7`), after the MIC
        // and in front of the four rungs.
        let gate = [0x41u8, 0x83, 0x7A, JitPICSlot::MEGAMORPHIC_OFFSET as u8, 0x00];
        if crate::runtime_lowering::megamorphic_gate_admitted(PIC, 2) {
            assert_eq!(count_seq(&code, &gate), 1, "one megamorphic gate");
            let gate_at = code.windows(gate.len()).position(|w| w == gate);
            let rung1 = [0x41u8, 0x3B, 0x42, JitPICSlot::CLASS_ID_OFFSETS[1] as u8];
            let rung1_at = code.windows(rung1.len()).position(|w| w == rung1);
            assert!(gate_at < rung1_at, "the gate precedes the rungs");
        } else {
            assert_eq!(count_seq(&code, &gate), 0, "no stub, no gate");
        }
    }

    /// Round 13 wave 5 (lane callcost2, M13-2): the megamorphic region's
    /// class-id-carrying edges stage through R11 and jump to the hashed stub's
    /// gate entry (`MOV EDX, EAX; JMP`), exactly once per site; the raw edges
    /// (null, kind) keep the full entry. Structural: the executed stub tests in
    /// `runtime_lowering` cover the gate entry's own behaviour.
    #[test]
    fn r13w5_screened_megamorphic_edges_enter_the_stub_gate_entry() {
        crate::x64::set_moving_young_override(Some(false));
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        let code = lower_virtual_call_with_ic(&ic);
        let on = Lowerer::ir_mega_gate_entry_enabled()
            && crate::runtime_lowering::mega_gate_fast_entry_enabled()
            && crate::runtime_lowering::hashed_stub_admitted(PIC, 2);
        // The stub's gate entry: `MOV EDX, EAX` then `JMP rel32` back.
        let entries: Vec<usize> = (0..code.len().saturating_sub(3))
            .filter(|&i| code[i..i + 3] == [0x89, 0xC2, 0xE9])
            .collect();
        // Every `JMP rel32` that lands on one of them.
        let jumps_in: Vec<usize> = (0..code.len().saturating_sub(5))
            .filter(|&i| {
                code[i] == 0xE9 && {
                    let rel = i32::from_le_bytes(code[i + 1..i + 5].try_into().expect("rel32"));
                    let target = i as i64 + 5 + i64::from(rel);
                    entries.iter().any(|&e| e as i64 == target)
                }
            })
            .collect();
        if !on {
            assert!(jumps_in.is_empty(), "switched off: nothing enters a gate entry");
            return;
        }
        assert_eq!(entries.len(), 1, "one stub, one gate entry");
        assert_eq!(jumps_in.len(), 1, "the screened edges share one jump to it");
        // That jump is preceded by the R11 staging store of the last argument:
        // `MOV [RBP - disp8], R11` (`4C 89 5D d8`) or its disp32 form
        // (`4C 89 9D d32`).
        let j = jumps_in[0];
        assert!(
            (j >= 4 && code[j - 4..j - 1] == [0x4C, 0x89, 0x5D])
                || (j >= 7 && code[j - 7..j - 4] == [0x4C, 0x89, 0x9D]),
            "the gate edge stages through R11, keeping EAX (bytes before the \
             jump: {:02x?})",
            &code[j.saturating_sub(4)..j]
        );
    }

    /// No plan ⇒ the historical generic-dispatch lowering, unchanged. This is
    /// the guarantee that every un-planned call site in every method is
    /// byte-identical to the pre-2026-07-26 backend.
    #[test]
    fn absent_ic_plan_keeps_generic_dispatch() {
        let empty: HashMap<usize, (usize, usize)> = HashMap::new();
        let code = lower_virtual_call_with_ic(&empty);
        assert!(
            contains_seq(&code, &0x1111_2222_3333_4440u64.to_le_bytes()),
            "an unplanned virtual site must still route through jit_invoke_dispatch"
        );
        assert!(
            !contains_seq(&code, &0x1111_2222_3333_4441u64.to_le_bytes()),
            "an unplanned site must NOT reach the inline-cache miss helper"
        );
        assert_eq!(
            count_seq(&code, &[0x41, 0xFF, 0xD3]),
            0,
            "an unplanned site must emit no cached-entry CALL R11"
        );
    }

    /// Every branch the inline-cache cascade emits is patched before the
    /// emitter returns, so no `rel32` operand is left as its `00 00 00 00`
    /// placeholder. A stale placeholder would jump to the instruction
    /// immediately after itself — a silent fall-through into the next cache
    /// entry's body rather than to `.pic` / `.slow` / `.done`.
    ///
    /// (`patch_rel32_to_here` swallows patch errors by design, because they are
    /// only reachable on an overflowed buffer that `lower_inner` discards — so
    /// this test is what proves the non-overflow path really does patch.)
    #[test]
    fn ic_cascade_leaves_no_unpatched_branch() {
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut ic = HashMap::new();
        ic.insert(2usize, (MIC, PIC));
        let code = lower_virtual_call_with_ic(&ic);

        // Scan for a Jcc rel32 / JMP rel32 whose displacement is still zero.
        for w in 0..code.len().saturating_sub(6) {
            let is_jcc = code[w] == 0x0F && (code[w + 1] == 0x84 || code[w + 1] == 0x85);
            if is_jcc && code[w + 2..w + 6] == [0, 0, 0, 0] {
                panic!("unpatched Jcc rel32 placeholder at native offset {w}");
            }
        }
        for w in 0..code.len().saturating_sub(5) {
            if code[w] == 0xE9 && code[w + 1..w + 5] == [0, 0, 0, 0] {
                panic!("unpatched JMP rel32 placeholder at native offset {w}");
            }
        }
    }

    /// A site whose receiver + arguments + hidden VM context pointer overflow
    /// the entry ABI register file must fall back to the helper rather than
    /// emit a call with garbage in an unwritten register. On Win64 the file is
    /// 4 registers wide, so a 4-argument virtual site (receiver + 3) already
    /// needs 5 and must decline; SysV has 6, so the same shape fits there and
    /// the assertion is platform-specific by construction.
    #[test]
    fn ic_declines_when_args_overflow_the_abi_register_file() {
        // Since round 11 wave 13 the guard is `ir_ic_admits_arity`: the file
        // plus `ir_ic_max_stack_words()` context-ABI stack words. Pin the
        // constants rather than re-deriving them, so a future ABI change has
        // to visit this test.
        #[cfg(target_os = "windows")]
        assert_eq!(ENTRY_ABI_REGS.len(), 4);
        #[cfg(not(target_os = "windows"))]
        assert_eq!(ENTRY_ABI_REGS.len(), 6);
        // The shared planner bound must agree with the lowerer's.
        assert_eq!(crate::ir_entry_abi_reg_count(), ENTRY_ABI_REGS.len());
        let regs = ENTRY_ABI_REGS.len();
        assert!(
            !ir_ic_admits_arity(0),
            "a virtual site always has a receiver"
        );
        for n in 1..regs {
            assert!(
                ir_ic_admits_arity(n),
                "n={n} fits the file with the context word"
            );
            assert_eq!(
                Lowerer::ic_wide_stack_block(n),
                None,
                "n={n} needs no stack block"
            );
        }
        // `HashMap.newNode` on Win64 (receiver + 4): two context-ABI words.
        for n in regs..=(regs + ir_ic_max_stack_words() - 1) {
            assert!(ir_ic_admits_arity(n), "n={n} overflows by at most the cap");
            let (total, base) =
                Lowerer::ic_wide_stack_block(n).expect("an admitted over-wide site has a block");
            let words = (n + 1 - regs) as i32;
            assert_eq!(total % 16, 0, "n={n}: the CALL must stay 16-aligned");
            assert!(
                total >= base + words * 8,
                "n={n}: the block holds every word"
            );
            assert_eq!((total, base), stack_arg_block_size(n + 1 - regs));
        }
        // Past the cap the site keeps the helper, in the planner and here.
        let too_wide = regs + ir_ic_max_stack_words();
        assert!(!ir_ic_admits_arity(too_wide));
        assert_eq!(Lowerer::ic_wide_stack_block(too_wide), None);
    }

    /// Lower `aload_0; iconst_0 x (n-1); invokevirtual #2; ireturn` with the
    /// site's MIC/PIC planned, the callee-deopt service wired, and return the
    /// bytes. `n` counts the receiver.
    fn lower_wide_virtual_call_with_ic(n: usize) -> Vec<u8> {
        const MIC: usize = 0x7fff_0000_0000_1000;
        const PIC: usize = 0x7fff_0000_0000_2000;
        let mut code: Vec<u8> = vec![0x2a]; // aload_0
        for _ in 1..n {
            code.push(0x03); // iconst_0
        }
        let invoke_pc = code.len();
        code.extend_from_slice(&[0xb6, 0x00, 0x02, 0xac]); // invokevirtual #2; ireturn
        let code_len = code.len();
        code.extend_from_slice(&[0x00, 0x00]);
        let descriptor: &'static str =
            Box::leak(format!("({})I", "I".repeat(n - 1)).into_boxed_str());
        let info: &'static JitInvokeInfo = Box::leak(Box::new(JitInvokeInfo {
            class_name: "pkg/Wide",
            method_name: "newNode",
            descriptor,
            num_jit_args: n,
            return_type: b'I',
            invoke_kind: 0,
            declaring_class_id: 0,
            owner_class_id: 0,
        }));
        let mut builder = IrBuilder::new(1, 1);
        builder.set_param_types(&[IrType::Ref]);
        let mut invoke_info = HashMap::new();
        invoke_info.insert(invoke_pc, (info as *const JitInvokeInfo as usize, n, b'I'));
        builder.set_invoke_info(invoke_info);
        let graph = builder
            .build(&code, code_len)
            .expect("IR build of a wide virtual call");
        let schedule = ir_schedule::schedule(&graph);
        let mut helpers = no_helpers();
        helpers.invoke_dispatch = 0x1111_2222_3333_4440;
        helpers.invoke_virtual_mic = 0x1111_2222_3333_4441;
        helpers.dispatch_threw = 0x1111_2222_3333_4442;
        helpers.service_callee_deopt = 0x1111_2222_3333_4443;
        let mut ic = HashMap::new();
        ic.insert(invoke_pc, (MIC, PIC));
        let empty_hints: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        lower_inner(
            &graph,
            &schedule,
            1,
            1,
            &helpers,
            &empty_hints,
            &[],
            None,
            &no_direct,
            &ic,
            &no_compact,
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("a wide virtual call must lower")
        .code_bytes()
        .to_vec()
    }

    /// Round 11 wave 13 (lane `icwide`): an inline cache for a site one
    /// register past the file (`HashMap.newNode`'s receiver + 4 on Win64).
    /// Its MIC and four PIC rungs share ONE marshalling tail: one `CALL R11`,
    /// one `SUB RSP` per ABI branch and one `ADD RSP` after the call, the
    /// overflow words written to `[RSP + base + 8k]`, the hashed stub after
    /// them (stack words too since round 12 wave 2), and the miss path on
    /// `jit_invoke_virtual_mic`, never the blind dispatch.
    #[test]
    fn r11w13_an_over_wide_site_gets_an_inline_cache_with_one_stack_tail() {
        crate::x64::set_moving_young_override(Some(false));
        let regs = ENTRY_ABI_REGS.len();
        let n = regs + 1;
        let code = lower_wide_virtual_call_with_ic(n);
        crate::x64::set_moving_young_override(None);

        assert!(
            contains_seq(&code, &0x1111_2222_3333_4441u64.to_le_bytes()),
            "the miss path must call jit_invoke_virtual_mic"
        );
        assert!(
            !contains_seq(&code, &0x1111_2222_3333_4440u64.to_le_bytes()),
            "an admitted over-wide site must not keep the blind dispatch"
        );
        // Round 12 wave 2 (lane calls): the hashed stub now serves an
        // over-wide site too, with its own CALL R11 and its own `BTR`.
        let stub = usize::from(
            crate::runtime_lowering::hashed_stub_wide_enabled()
                && crate::direct_jit_callee_calls_enabled(),
        );
        assert_eq!(
            count_seq(&code, &[0x41, 0xFF, 0xD3]),
            1 + stub,
            "the MIC and every PIC rung share one CALL R11 (and the hashed stub has its own)"
        );
        assert_eq!(
            count_seq(&code, &[0x49, 0x0F, 0xBA, 0xF3, 0x00]),
            1 + crate::JIT_PIC_ENTRIES + stub,
            "every cached entry still takes its ABI from the word it loaded"
        );
        let (total, base) = stack_arg_block_size(n + 1 - regs);
        let mut sub = vec![0x48, 0x81, 0xEC];
        sub.extend_from_slice(&total.to_le_bytes());
        let mut add = vec![0x48, 0x81, 0xC4];
        add.extend_from_slice(&total.to_le_bytes());
        // The hit tail: from the receiver's class-id load (after the
        // prologue, whose own frame `SUB RSP` must not be counted) to just
        // past the shared CALL's release.
        let load_at = code
            .windows(2)
            .position(|w| w == [0x8B, 0x00])
            .expect("class-id load");
        let call_at = code
            .windows(3)
            .position(|w| w == [0x41, 0xFF, 0xD3])
            .expect("CALL R11");
        assert!(
            load_at < call_at,
            "the MIC arm's tail follows the class-id load"
        );
        let tail = &code[load_at..call_at + 3 + add.len()];
        assert_eq!(count_seq(tail, &sub), 2, "one SUB RSP on each ABI branch");
        assert_eq!(
            count_seq(tail, &add),
            1,
            "one ADD RSP after the shared CALL"
        );
        // Context ABI: arguments regs-1 and regs go to base and base+8;
        // context-free ABI: argument regs goes to base.
        let store = |disp: i32| {
            let mut s = vec![0x48, 0x89, 0x84, 0x24];
            s.extend_from_slice(&disp.to_le_bytes());
            s
        };
        assert_eq!(
            count_seq(tail, &store(base)),
            2,
            "the first stack word, both ABIs"
        );
        assert_eq!(
            count_seq(tail, &store(base + 8)),
            1,
            "the context ABI's second word"
        );
        // The release follows the CALL (with nothing in between: no frame
        // record and no spliced body, so no row is recorded either).
        assert_eq!(
            &code[call_at + 3..call_at + 10],
            &add[..],
            "ADD RSP right after the CALL"
        );
        // Every PIC rung's jump back lands on the tail's `JNC`.
        for w in 0..code.len().saturating_sub(6) {
            let is_jcc = code[w] == 0x0F && matches!(code[w + 1], 0x83 | 0x84 | 0x85);
            if is_jcc && code[w + 2..w + 6] == [0, 0, 0, 0] {
                panic!("unpatched Jcc rel32 placeholder at native offset {w}");
            }
        }
        let back_to_jnc = (0..code.len().saturating_sub(5))
            .filter(|&w| code[w] == 0xE9)
            .filter_map(|w| {
                let rel = i32::from_le_bytes(code[w + 1..w + 5].try_into().ok()?);
                let target = usize::try_from(w as i64 + 5 + i64::from(rel)).ok()?;
                (rel < 0 && code.get(target..target + 2) == Some(&[0x0Fu8, 0x83][..]))
                    .then_some(target)
            })
            .collect::<Vec<usize>>();
        assert!(
            back_to_jnc.len() >= crate::JIT_PIC_ENTRIES,
            "each PIC rung must jump back to the shared tail's JNC (found {})",
            back_to_jnc.len()
        );
        assert!(
            back_to_jnc.windows(2).all(|w| w[0] == w[1]),
            "every rung must land on the SAME tail"
        );
    }

    /// Past `ir_ic_max_stack_words()` the site keeps the blind dispatch even when
    /// a plan hands it slots: the lowerer's gate is the planner's.
    #[test]
    fn r11w13_a_site_past_the_stack_word_cap_keeps_the_dispatch_helper() {
        crate::x64::set_moving_young_override(Some(false));
        let n = ENTRY_ABI_REGS.len() + ir_ic_max_stack_words();
        let code = lower_wide_virtual_call_with_ic(n);
        crate::x64::set_moving_young_override(None);
        assert!(contains_seq(&code, &0x1111_2222_3333_4440u64.to_le_bytes()));
        assert_eq!(count_seq(&code, &[0x41, 0xFF, 0xD3]), 0);
    }

    /// The context shift moves arguments in DESCENDING order, so no argument is
    /// overwritten before it has been read.
    ///
    /// `emit_ic_premarshal_no_context` builds the no-context layout once, ahead
    /// of the whole inline-cache cascade, and a context-needing arm converts it
    /// by shifting every argument up one register. Ascending order would write
    /// `ENTRY_ABI_REGS[1]` from `[0]` before reading `[1]`, so argument 1 would
    /// become a second copy of argument 0 and every argument above it the same
    /// — silently, and only for callees that need the context pointer.
    ///
    /// Asserted on the decoded `(dst, src)` pairs rather than on literal bytes,
    /// because `ENTRY_ABI_REGS` differs between Win64 and System V and a
    /// byte-literal test would pin one platform's answer as the property.
    #[test]
    fn the_context_shift_moves_arguments_from_the_top_down() {
        for num_args in 1..=(ENTRY_ABI_REGS.len() - 1) {
            let mut lo = lowerer_with_resident_xmm(4096, None);
            let at = lo.buf.pos();
            lo.emit_ic_shift_for_context(num_args);
            let code = lo.buf.as_slice()[at..].to_vec();

            // `MOV r64, r64` is `REX.W(+R+B) 89 ModRM(mod=11)`. Decode every one
            // in order; the trailing context load is `8B` and is skipped.
            let mut moves: Vec<(u8, u8)> = Vec::new();
            let mut i = 0usize;
            while i + 2 < code.len() {
                if (0x48..=0x4F).contains(&code[i]) && code[i + 1] == 0x89 && code[i + 2] >= 0xC0 {
                    let rex = code[i];
                    let modrm = code[i + 2];
                    let src = ((modrm >> 3) & 7) | (((rex >> 2) & 1) << 3);
                    let dst = (modrm & 7) | ((rex & 1) << 3);
                    moves.push((dst, src));
                    i += 3;
                } else {
                    i += 1;
                }
            }

            let want: Vec<(u8, u8)> = (0..num_args)
                .rev()
                .map(|k| (ENTRY_ABI_REGS[k + 1], ENTRY_ABI_REGS[k]))
                .collect();
            assert_eq!(
                moves, want,
                "num_args={num_args}: the shift must run from the top down, so \
                 every destination holds a value that has already been moved",
            );

            // …and the context lands in ABI[0], after the shift has vacated it.
            // `MOV r64, [rbp - disp]` is `REX.W 8B ModRM`, and ABI[0]'s encoding
            // appears in the ModRM `reg` field.
            let ctx = ENTRY_ABI_REGS[0];
            let ctx_loaded = code.windows(3).any(|w| {
                (0x48..=0x4F).contains(&w[0])
                    && w[1] == 0x8B
                    && ((w[2] >> 3) & 7) == (ctx & 7)
                    && (w[2] & 0xC0) != 0xC0
            });
            assert!(
                ctx_loaded,
                "num_args={num_args}: the context pointer must be loaded into \
                 ABI[0] once the shift has vacated it",
            );
        }
    }

    /// The optimizing tier may not be opened to allocation-bearing methods
    /// while it still lowers `Op::New` through the out-of-line stub.
    ///
    /// # The coupling this enforces
    ///
    /// `emit_new_object_stub` is three register loads and a `CALL` into
    /// `jit_new_object`. The single-pass backend has
    /// `x64::objects::emit_inline_tlab_new` and pays no call on the common
    /// path. So an escaping allocation compiles WORSE at the optimizing tier
    /// than at the baseline tier — which is one of the two independent causes
    /// of the July 2026 Binary Trees 4x regression, and the reason
    /// `IR_MAX_ALLOCATIONS` is pinned at 16 while every neighbouring cap is 64.
    ///
    /// It costs nothing today only because `c2_alloc_upgrade_enabled()` is
    /// opt-in, so no method containing a `new` is ever promoted to this tier.
    /// That was a sentence in a comment. It is a test now, because the edit
    /// that breaks it — flipping the gate on, in `lib.rs`, to widen the
    /// optimizing tier's population — does not look like it touches allocation
    /// at all, and its symptom is a throughput regression on exactly the
    /// workloads nobody re-measures after a policy change.
    ///
    /// # What discharges it
    ///
    /// Giving this tier an inline TLAB bump. That is not a copy of the
    /// single-pass sequence: `jit_post_tlab_init` derives `shape` and the
    /// object's total size from `class_layout(class_id)` **itself**, so a
    /// caller that sizes the allocation as `HEADER_SIZE + num_fields *
    /// SLOT_SIZE` while the class carries a registered compact layout hands the
    /// helper a size mismatch and corrupts the heap. A correct implementation
    /// needs the compact snapshot AND the runtime layout-version guard the
    /// single-pass emitter carries for a layout that is REPLACED between
    /// compile and execution. One shared sequence is the right answer; the
    /// obstacle is that the header-write contract is policed by source scans of
    /// `emit_inline_tlab_new`'s own body, so moving it means rewriting the
    /// oracle in the same change as the code it polices.
    ///
    /// When that lands, delete this test — do not weaken it.
    #[test]
    fn the_optimizing_tier_stays_shut_to_allocation_while_it_has_no_inline_tlab() {
        let ir_src = include_str!("ir_lower.rs");
        // The `Op::New` arm's lowering, as it stands.
        let uses_stub = ir_src.contains("runtime_lowering::emit_new_object_stub");
        let has_inline_bump = ir_src.contains("emit_inline_tlab_new_ir");
        assert!(
            uses_stub || has_inline_bump,
            "the `Op::New` arm lowers through neither the stub nor an inline \
             bump — this test can no longer see what it is guarding"
        );
        if has_inline_bump {
            // The gap is closed; the coupling below has nothing to protect.
            return;
        }

        // Still stub-only. Then the gate must be OPT-IN: `runtime_flag_on(..)`
        // is off unless the variable is set to a truthy value, whereas a
        // `map_or(true, ..)` or a `!matches!(.., Ok("0"))` would be default-on.
        // (It was a presence-only `.is_some()` read until 2026-09-12, and this
        // needle matched that; see `jit-presence-only-flag-reads-FIXED.md`.)
        let lib_src = include_str!("lib.rs");
        let body = lib_src
            .split("fn c2_alloc_upgrade_enabled() -> bool {")
            .nth(1)
            .expect("c2_alloc_upgrade_enabled is in lib.rs")
            .split("\n}")
            .next()
            .expect("the function ends");
        assert!(
            body.contains("runtime_flag_on("),
            "`c2_alloc_upgrade_enabled` is no longer opt-in, but the optimizing \
             tier still lowers `Op::New` through `emit_new_object_stub` — every \
             promoted allocation now pays a CALL where the single-pass backend \
             pays an inline TLAB bump. Give this tier the bump first (see this \
             test's doc comment for why it is not a copy-paste), or leave the \
             gate shut.\n\nbody was:\n{body}"
        );
    }

    // ── wire-tiered-manager Step 4: PGO branch-bias in the IR (C2) path ──

    /// The optimizing IR lowerer must consume the profiled branch bias: the two
    /// hints emit opposite branch polarities, and a hint outranks the block
    /// layout.
    ///
    /// # What this test used to assert, and why it changed on 2026-09-11
    ///
    /// It used to pin the UNHINTED emission as the reference — "no hint ⇒ the
    /// historical `JE` layout, and a usually-taken hint reproduces it
    /// byte-for-byte". That reference moved deliberately: with no hint the arm
    /// now takes its fall-through edge from the block layout
    /// (`ir_branch_layout_polarity_enabled`), because the previous fallback —
    /// "the `true` edge is the near one" — is inverted for every javac counted
    /// loop and cost one taken branch and one `JMP rel32` per iteration.
    ///
    /// On THIS fixture the layout happens to agree with the not-taken hint, so
    /// the old assertion ("a not-taken hint must invert the baseline") could no
    /// longer hold however the code behaved: baseline and hinted arm are now
    /// the same bytes. That is the change working, not the hint failing.
    ///
    /// **So the property is restated against the two hints rather than against
    /// the baseline**, which is what the test was always about and is immune to
    /// the default moving again: the two hints must disagree with each other,
    /// in opposite polarities, and each must be reachable. The unhinted arm is
    /// still asserted — against the LAYOUT's answer, and equal to whichever
    /// hint agrees with it, which is the fact that would otherwise be silently
    /// lost.
    #[test]
    fn step4_ir_lower_consumes_branch_bias_hint() {
        // iload_0; ifeq +5 (→pc6); iconst_1; ireturn; iconst_0; ireturn.
        // One conditional branch (the `ifeq` at pc 1) with two successor
        // edges, no phis, no calls, no guards → the ONLY Jcc in the emitted
        // body is the `Op::If` terminator.
        let code = [0x1a, 0x99, 0x00, 0x05, 0x04, 0xac, 0x03, 0xac];
        let code_len = 8;

        let build = || {
            let builder = IrBuilder::new(1, 1);
            let mut graph = builder.build(&code, code_len).expect("IR build");
            ir_optimize::optimize(&mut graph);
            let schedule = ir_schedule::schedule(&graph);
            (graph, schedule)
        };

        // The entry fast return (round 12 wave 8) would open this fixture with
        // its own `CMP; Jcc` on the same `ifeq`, a second Jcc whose polarity
        // no hint governs; off here, so the `Op::If` stays the only one.
        let lower_hinted = |bias: Option<bool>| {
            let (g, sch) = build();
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_ENTRY_FAST_RETURN", Some("0"))],
                || match bias {
                    None => lower(&g, &sch, 1, 1, &no_helpers()).expect("lower baseline"),
                    Some(b) => {
                        let mut hints = HashMap::new();
                        hints.insert(1usize, b);
                        lower_with_branch_hints(&g, &sch, 1, 1, &no_helpers(), &hints)
                            .expect("lower hinted")
                    }
                },
            )
            .code_bytes()
            .to_vec()
        };

        let base_code = lower_hinted(None);
        let not_taken = lower_hinted(Some(false));
        let taken = lower_hinted(Some(true));

        // Both polarities must actually appear across the arms, or the
        // "inversion" being checked is vacuous.
        let polarity = |code: &[u8]| {
            if contains_seq(code, &[0x0F, 0x84]) {
                0x84u8
            } else {
                assert!(
                    contains_seq(code, &[0x0F, 0x85]),
                    "an IR branch emitted neither JE nor JNE"
                );
                0x85u8
            }
        };
        assert_eq!(
            polarity(&not_taken),
            polarity(&taken) ^ 1,
            "the two hints must emit OPPOSITE branch polarities; that is the \
             whole of what consuming a branch bias means"
        );
        assert_ne!(
            not_taken, taken,
            "the two hints must produce different code buffers"
        );

        // And the unhinted arm follows the LAYOUT, which on this fixture puts
        // the false edge physically next. Asserted rather than left implicit:
        // if the layout tie-break is ever switched off, the baseline goes back
        // to matching the taken arm, and the reader should be told which of
        // the two it is.
        let expected_base = if super::ir_branch_layout_polarity_enabled() {
            &not_taken
        } else {
            &taken
        };
        assert_eq!(
            &base_code,
            expected_base,
            "with no hint the fall-through edge comes from the block layout \
             (`ir_branch_layout_polarity_enabled` = {}), and this fixture's \
             layout agrees with the not-taken hint",
            super::ir_branch_layout_polarity_enabled(),
        );
    }

    /// A hint for an UNRELATED bytecode PC must not perturb codegen — only the
    /// branch whose own PC is marked not-taken inverts.
    #[test]
    fn step4_ir_lower_branch_bias_keyed_by_pc() {
        let code = [0x1a, 0x99, 0x00, 0x05, 0x04, 0xac, 0x03, 0xac];
        let build = || {
            let builder = IrBuilder::new(1, 1);
            let mut graph = builder.build(&code, 8).expect("IR build");
            ir_optimize::optimize(&mut graph);
            let schedule = ir_schedule::schedule(&graph);
            (graph, schedule)
        };
        let (g0, s0) = build();
        let base = lower(&g0, &s0, 1, 1, &no_helpers())
            .expect("lower")
            .code_bytes()
            .to_vec();
        // Hint a PC that does not correspond to this method's branch (7).
        let mut hints = HashMap::new();
        hints.insert(7usize, false);
        let (g1, s1) = build();
        let other = lower_with_branch_hints(&g1, &s1, 1, 1, &no_helpers(), &hints)
            .expect("lower")
            .code_bytes()
            .to_vec();
        assert_eq!(
            base, other,
            "a hint for an unrelated PC must not change codegen"
        );
    }

    // ── real-frame-deopt step 2: deopt points + lookup ───────────────────

    #[test]
    fn test_deopt_points_resolve_consts_and_slots() {
        use crate::deopt::FrameValue;
        // iconst_5; iconst_3; iadd; iconst_2; imul; ireturn
        //   pc0       pc1      pc2    pc3       pc4    pc5
        // Only the Add (pc2) and Mul (pc4) are data nodes carrying a
        // bytecode_pc, so exactly those two bcis anchor a deopt point.
        let code = [0x08, 0x06, 0x60, 0x05, 0x68, 0xac, 0, 0];
        let cm = compile_via_ir_no_opt(&code, 6, 0, 0);

        assert_eq!(cm.deopt_points.len(), 2, "deopt points for bci 2 and 4");
        // Sorted ascending by native_offset (emission order pc2 < pc4).
        assert!(cm.deopt_points[0].native_offset <= cm.deopt_points[1].native_offset);

        let p2 = cm.deopt_points.iter().find(|p| p.bci == 2).unwrap();
        // Before iadd: the two constants 5 and 3 are on the stack, encoded
        // directly (no machine location needed).
        assert_eq!(
            p2.frame_state.stack,
            vec![FrameValue::Int(5), FrameValue::Int(3)],
        );

        let p4 = cm.deopt_points.iter().find(|p| p.bci == 4).unwrap();
        // Before imul: [Add result, const 2]. The Add lives in a spill slot;
        // the constant is encoded directly.
        assert_eq!(p4.frame_state.stack.len(), 2);
        assert!(matches!(p4.frame_state.stack[0], FrameValue::StackSlot(off) if off < 0));
        assert_eq!(p4.frame_state.stack[1], FrameValue::Int(2));

        // The offsets themselves, asserted directly. This used to go through
        // `CompiledMethod::find_deopt_point`, which was deleted in round 10 —
        // it had no production caller and `native_offset` is not a unique key,
        // so an offset-keyed search could not have made the stronger of these
        // two claims. What the test is really about is the lowerer's emitted
        // offset table, and this says so without an oracle in between.
        let off = p2.native_offset;
        assert_eq!(
            cm.deopt_points
                .iter()
                .filter(|p| p.native_offset == off)
                .count(),
            1,
            "bci 2's native offset must name exactly one point",
        );
        assert!(
            !cm.deopt_points
                .iter()
                .any(|p| p.native_offset == off + 9999),
            "a bogus offset must name no point",
        );
    }

    // ── real-frame-deopt step 3: route one guard end-to-end ──────────────

    #[test]
    fn test_guard_deopt_reconstructs_live_frame() {
        use crate::deopt::{take_last_deopt, FrameValue};
        use crate::ir::SafepointSnapshot;

        // Hand-build: i64 f(i64 cond, i64 val) {
        //     guard(cond != 0) [bci 5];   // deopt if cond == 0
        //     return val;
        // }
        // Node layout mirrors IrBuilder::new.
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let cond = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let val = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        let _guard = graph.add(Op::Guard { bci: 5 }, IrType::Void, vec![ctrl, cond], None);
        let ret = graph.add(Op::Return, IrType::Void, vec![ctrl, val], None);
        graph.exit = ret;

        // Safepoint at the guard's bci: locals = [cond, val], empty stack.
        graph.safepoints.push(SafepointSnapshot::new(
            5,
            vec![cond, val],
            vec![],
            Vec::new(),
        ));

        let schedule = ir_schedule::schedule(&graph);
        let method = lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lower guarded method");

        // Guard passes (cond != 0): normal return of `val`.
        let _ = take_last_deopt(); // clear any stale state
                                   // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let ok = unsafe { method.try_call(&[1, 777]).expect("call (guard ok)") };
        assert_eq!(ok, 777, "guard passes → returns val");
        assert!(take_last_deopt().is_none(), "no deopt when guard passes");

        // Guard fails (cond == 0): deopt sentinel returned, frame reconstructed
        // from the LIVE machine frame — locals resolved to the actual argument
        // values sitting in their spill slots.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sentinel = unsafe { method.try_call(&[0, 777]).expect("call (guard fail)") };
        assert_eq!(sentinel, i64::MIN, "guard fails → deopt sentinel");
        let frame = take_last_deopt().expect("deopt reconstructed a frame");
        assert_eq!(frame.bci, 5, "resumes at the guard's bci");
        assert_eq!(
            frame.locals,
            vec![FrameValue::Int(0), FrameValue::Int(777)],
            "locals read back from the live native frame",
        );
        assert!(frame.stack.is_empty());
        assert!(frame.caller_frames.is_empty());
    }

    // ── Guard-surviving scalar replacement (producer) ────────────────────

    /// Build a 3-block graph modelling a scalar-replaced object live at a guard:
    ///
    /// ```text
    /// block0 (entry):  o = new Foo(); o.x = 7; if (cond) ...   (New + store here)
    /// block1 (taken):  guard(cond != 0) [bci 10]; return o.x   (deopt point here)
    /// block2 (else):   return 0
    /// ```
    ///
    /// `same_block_guard` puts the guard in block0 instead (no `If`), created
    /// BEFORE the New/store — so the allocation neither dominates the guard's
    /// block nor precedes the guard inside it: the temporal-hazard bail case.
    /// `dup_local` puts the object in TWO local slots (sharing → `VirtualObjectRef`).
    /// Returns `(graph, sr_map, new_id)`; the New + store are marked `Op::Dead`
    /// (simulating `apply_ea_to_ir`) and `sr_map` captures their control inputs.
    fn build_sr_deopt_graph(
        same_block_guard: bool,
        dup_local: bool,
    ) -> (Graph, ScalarReplacementMap, NodeId) {
        use crate::ir::CmpOp;
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
        // Same-block mode: the guard comes FIRST, so in block0's execution order
        // the deopt fires before the object exists.
        if same_block_guard {
            let _guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, cond], None);
        }
        // o = new Foo(); o.x = 7  (both controlled by c0 → block0)
        let newo = g.add(
            Op::New {
                class_id: 7,
                num_fields: 1,
            },
            IrType::Ref,
            vec![c0, mem],
            None,
        );
        let f0 = g.add(Op::Const(0), IrType::Int, vec![], None); // field index 0
        let v7 = g.add(Op::Const(7), IrType::Int, vec![], None); // field value
        let store = g.add(
            Op::Store(MemKind::Int),
            IrType::Memory,
            vec![c0, mem, newo, f0, v7],
            None,
        );
        let new_ctrl = c0;
        let store_ctrl = c0;

        // Locals at the guard's safepoint: [cond, o] (or [cond, o, o] for sharing).
        let locals = if dup_local {
            vec![cond, newo, newo]
        } else {
            vec![cond, newo]
        };

        let guard_ctrl = if same_block_guard {
            // Guard already in block0 (before the New), no branch → same block.
            let ret = g.add(Op::Return, IrType::Void, vec![c0, v7], None);
            g.exit = ret;
            c0
        } else {
            // if (cond) → block1 (taken) / block2 (else); guard in block1.
            let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
            let cmp = g.add(Op::Cmp(CmpOp::Ne), IrType::Int, vec![cond, zero], None);
            let iff = g.add(Op::If, IrType::Control, vec![c0, cmp], None);
            let t = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
            let e = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
            let guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![t, cond], None);
            let _ = guard;
            let ret1 = g.add(Op::Return, IrType::Void, vec![t, v7], None);
            let ret2 = g.add(Op::Return, IrType::Void, vec![e, v7], None);
            g.exit = ret1;
            let _ = ret2;
            t
        };
        let _ = guard_ctrl;

        g.safepoints
            .push(SafepointSnapshot::new(10, locals, vec![], Vec::new()));

        // Simulate `apply_ea_to_ir`: mark the New + store dead (their inputs are
        // cleared), exactly as the production path does before scheduling.
        g.nodes[newo as usize].op = Op::Dead;
        g.nodes[newo as usize].inputs.clear();
        g.nodes[store as usize].op = Op::Dead;
        g.nodes[store as usize].inputs.clear();

        let mut objects = HashMap::new();
        objects.insert(
            newo,
            VirtualObjectInfo {
                array_element_type: None,
                class_id: 7,
                num_fields: 1,
                field_values: vec![Some(v7)],
                new_ctrl,
                store_ctrls: vec![store_ctrl],
                store_nodes: vec![store],
                store_fields: Vec::new(),
            },
        );
        (g, ScalarReplacementMap { objects }, newo)
    }

    /// Find the deopt point at `bci` among a lowered method's baked guard boxes
    /// (`_deopt_point_boxes` — the runtime-used frame states; an `Op::Guard`
    /// emits its box there via `emit_deopt_unless`, NOT into the `bci_native`-keyed
    /// `deopt_points` list).
    fn deopt_locals_at(cm: &CompiledMethod, bci: u32) -> Vec<FrameValue> {
        cm._deopt_point_boxes
            .iter()
            .find(|p| p.bci == bci)
            .unwrap_or_else(|| panic!("no deopt box at bci {bci}"))
            .frame_state
            .locals
            .clone()
    }

    /// Every deopt emitted inside a SPLICED body must record the enclosing
    /// `invoke`'s bci, never the relocated one.
    ///
    /// This is the regression test for the argument `lower_inner_with_array_list`
    /// used to drop: it received `spliced_ranges` and passed `Lowerer::new` a
    /// literal `&[]`, so `resume_bci` was the identity and every inlined deopt
    /// named a bci that is not a program point of the method. The interpreter
    /// then found no deopt point at that bci, defaulted the reason to
    /// `UnreachedCode`, and refused to resume — turning netty's
    /// `IndexOutOfBoundsException` into an `InternalError`.
    ///
    /// The shape is netty's, reduced: a caller whose `invokestatic` at bci 5
    /// has been replaced by a relocated body starting at bci 9, containing an
    /// array load whose bounds check must resume at 5.
    #[test]
    fn a_deopt_inside_a_spliced_body_resumes_at_the_enclosing_invoke() {
        // caller: 0: aload_0  1: iload_1  2: <the spliced region stands in for
        // the invoke at bci 5>  ... the graph below is hand-built, so only the
        // bcis matter, not a decodable byte string.
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let arr = g.add(Op::Param(0), IrType::Ref, vec![start], None);
        let idx = g.add(Op::Param(1), IrType::Int, vec![start], None);
        // The array load lives at bci 36 — inside the relocated body.
        let load = g.add(
            Op::ArrayLoad(MemKind::Byte),
            IrType::Int,
            vec![ctrl, mem, arr, idx],
            Some(36),
        );
        let ret = g.add(Op::Return, IrType::Void, vec![ctrl, load], Some(8));
        g.exit = ret;
        // The caller's own snapshot at the invoke it replaced.
        g.safepoints.push(SafepointSnapshot::new(
            5,
            vec![arr, idx],
            vec![arr, idx],
            Vec::new(),
        ));
        let schedule = ir_schedule::schedule(&g);

        // The caller's bytecode is 9 bytes; the relocated body occupies 9..43,
        // standing in for the `invoke` at bci 5.
        let spliced = [(9usize, 43usize, 5usize)];
        let cm = lower_inner(
            &g,
            &schedule,
            2,
            2,
            &no_helpers(),
            &HashMap::new(),
            &spliced,
            None,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("lower");

        assert!(
            !cm._deopt_point_boxes.is_empty(),
            "the array access must emit its null/bounds guards",
        );
        for p in &cm._deopt_point_boxes {
            assert_eq!(
                p.bci, 5,
                "a deopt at relocated bci 36 must resume at the enclosing \
                 invoke (5), not at a bci the method does not have; got {}",
                p.bci,
            );
            assert_eq!(
                p.frame_state.bci, 5,
                "and its frame state must be the caller's snapshot at 5",
            );
        }

        // The control: with no spliced ranges, the same graph names the raw
        // bci 36, which has no snapshot. That used to resume with an EMPTY
        // frame -- what the production lowering was doing for every inlined
        // method -- and is a refused compile since round 11 (lane lower,
        // `r11-irlower-deopt-at-bci-zero-when-a-node-has-no-pc`).
        let raw = lower_inner(
            &g,
            &schedule,
            2,
            2,
            &no_helpers(),
            &HashMap::new(),
            &[],
            None,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            &crate::ir::IrInlineFrameSites::default(),
        );
        assert!(
            raw.is_none(),
            "without ranges bci 36 has no snapshot: the compile must be refused, \
             not resumed with an empty frame",
        );
    }

    /// A division the bytecode reaches on only one arm must deopt from its
    /// control-anchored `Op::Guard`, not from the floating `Op::Div` the
    /// scheduler placed wherever its operands happened to be available.
    ///
    /// Before this, `MemoryEstimator.estimateMemory` (H2's `MVMap` key/value
    /// size estimator) had its `ldiv` hoisted above the branch that guarantees
    /// a positive divisor, and the lowerer's own guard then deopted on a path
    /// the interpreter never takes — which the interpreter faithfully resumed
    /// into, throwing `ArithmeticException: / by zero` out of a program that
    /// cannot divide by zero.
    #[test]
    fn a_guarded_divisions_trap_comes_from_the_guard_not_the_floating_div() {
        // 0: iload_0  1: ifne +7 (→8)  4: iload_1  5: iload_2  6: idiv
        // 7: ireturn  8: iconst_0  9: ireturn
        let code = [
            0x1a, 0x9a, 0x00, 0x07, 0x1b, 0x1c, 0x6c, 0xac, 0x03, 0xac, 0, 0,
        ];
        let graph = crate::ir::IrBuilder::new(3, 3)
            .build(&code, 10)
            .expect("IR build failed");
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower_inner(
            &graph,
            &schedule,
            3,
            3,
            &no_helpers(),
            &HashMap::new(),
            &[],
            None,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("lower");

        let at_div: Vec<_> = cm
            ._deopt_point_boxes
            .iter()
            .filter(|p| p.bci == 6)
            .collect();
        assert_eq!(
            at_div.len(),
            1,
            "one deopt point at the idiv's bci, not one per emitter"
        );
        assert_eq!(
            at_div[0].reason,
            DeoptReason::UncommonTrap,
            "the surviving trap is the control-anchored Op::Guard's; a \
             `DivByZero` here means the floating div still deopts"
        );
        assert!(
            !cm._deopt_point_boxes
                .iter()
                .any(|p| p.reason == DeoptReason::DivByZero),
            "the lowerer must not emit its own div-by-zero deopt once the \
             builder anchored a guard"
        );
    }

    /// Round 12 wave 3 (lane replay): an IR SITE TRAP's point carries
    /// `ResumeSemantics::first_arrival` (the VM's replay rule reads it), and a
    /// conditional guard in the same body does not — here the div-by-zero
    /// guard, whose `UncommonTrap` reason and `REEXECUTE` resume are the same.
    #[test]
    fn r12w3_only_a_site_trap_point_is_first_arrival() {
        // 0: invokedynamic #1 (void, no arguments)
        // 5: iload_0  6: iload_1  7: idiv  8: ireturn
        let code = [0xba, 0x00, 0x01, 0x00, 0x00, 0x1a, 0x1b, 0x6c, 0xac, 0, 0];
        let mut builder = crate::ir::IrBuilder::new(2, 2);
        let mut sites = HashMap::new();
        sites.insert(0usize, (0usize, b'V'));
        builder.set_indy_trap_sites(sites);
        let graph = builder.build(&code, 9).expect("IR build failed");
        assert_eq!(graph.site_trap_pcs, vec![0], "the builder lists its trap");
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower_inner(
            &graph,
            &schedule,
            2,
            2,
            &no_helpers(),
            &HashMap::new(),
            &[],
            None,
            &HashMap::new(),
            &HashMap::new(),
            &HashMap::new(),
            &crate::ir::IrInlineFrameSites::default(),
        )
        .expect("lower");
        let trap = cm
            ._deopt_point_boxes
            .iter()
            .find(|p| p.bci == 0)
            .expect("the site trap's point");
        assert!(trap.semantics.first_arrival);
        assert_eq!(trap.semantics.resume_kind(), ResumeSemantics::REEXECUTE);
        let div = cm
            ._deopt_point_boxes
            .iter()
            .find(|p| p.bci == 7)
            .expect("the div guard's point");
        assert_eq!(div.reason, DeoptReason::UncommonTrap);
        assert!(
            !div.semantics.first_arrival,
            "a conditional guard may fire on a later arrival"
        );
    }

    /// Round 12 wave 3 (lane replay; `r12w2-iropt-osr-entry-skips-range-predicate`):
    /// an ordinary OSR entry at a loop header never runs the pre-header range
    /// predicate (`n <= a.length`) whose fact elides the loop's bounds check,
    /// so no entry is emitted there.
    ///
    /// `static int sum(int[] a, int n) { int s = 0; for (int i = 0; i < n; i++)
    /// s += a[i]; return s; }`, optimized with a de-spec registry in scope (the
    /// production condition for `ir_optimize::plant_range_check_predicates`).
    /// The predicate is the only `Op::Guard` at the header bci 4 this body can
    /// have (`iload_3` carries none); when the pipeline declines to plant it
    /// the question does not arise and the test says so.
    #[test]
    fn r12w3_no_osr_entry_jumps_past_a_range_predicate() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_2   2: iconst_0   3: istore_3
        //  4: iload_3    5: iload_1    6: if_icmpge 21
        //  9: iload_2   10: aload_0   11: iload_3   12: iaload   13: iadd
        // 14: istore_2  15: iinc 3,1  18: goto 4    21: iload_2  22: ireturn
        let code = [
            0x03, 0x3d, 0x03, 0x3e, 0x1d, 0x1b, 0xa2, 0x00, 0x0f, 0x1c, 0x2a, 0x1d, 0x2e, 0x60,
            0x3d, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf2, 0x1c, 0xac, 0, 0,
        ];
        let mut builder = IrBuilder::new(2, 4);
        builder.set_param_types(&[IrType::Ref, IrType::Int]);
        let mut graph = builder.build(&code, 23).expect("IR build");
        let despec = crate::deopt::DespecRegistry::new();
        ir_optimize::optimize_with(
            &mut graph,
            ir_optimize::OptimizeContext {
                despec: Some(&despec),
                method_key: "R12W3.sum:([II)I",
            },
        );
        let planted = graph
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::Guard { bci: 4 }));
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 2, 4, &no_helpers()).expect("the loop lowers");
        if !planted {
            // No predicate, nothing for an entry to skip.
            return;
        }
        assert!(
            cm.ir_osr_entry_addr(4).is_none(),
            "an entry at the header would run the loop with its bounds check \
             elided on a bound nobody checked"
        );
    }

    #[test]
    fn test_scalar_deopt_emits_virtual_object() {
        // A scalar-replaced object whose New + (constant) field store strictly
        // dominate the guard's block lowers to a `VirtualObject` with the stored
        // value as its field — the guard-surviving case.
        let (g, sr_map, newo) = build_sr_deopt_graph(false, false);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        // local[1] is the object → VirtualObject{ class_id:7, field_values:[Int(7)] }.
        match &locals[1] {
            FrameValue::VirtualObject(state) => {
                assert_eq!(state.id, newo as usize);
                assert_eq!(state.class_id, 7);
                assert_eq!(state.num_fields, 1);
                assert_eq!(state.field_values, vec![FrameValue::Int(7)]);
            }
            other => panic!("expected VirtualObject, got {other:?}"),
        }
    }

    /// The commonest shape there is: `o = new Foo(); o.x = 7; ...; guard` in ONE
    /// straight-line block. Strict block dominance cannot answer (same block),
    /// and until 2026-09-12 that alone refused the recipe — so an object live at
    /// a guard in a branch-free method could never be described. The allocation
    /// and its store precede the guard in the block's execution order, which is
    /// the builder's node-id order, and the recipe is emitted.
    #[test]
    fn test_scalar_deopt_describes_an_object_stored_earlier_in_the_guards_block() {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let newo = g.add(
            Op::New {
                class_id: 7,
                num_fields: 1,
            },
            IrType::Ref,
            vec![c0, mem],
            None,
        );
        let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
        let v7 = g.add(Op::Const(7), IrType::Int, vec![], None);
        let store = g.add(
            Op::Store(MemKind::Int),
            IrType::Memory,
            vec![c0, mem, newo, f0, v7],
            None,
        );
        // AFTER the store, same control → same block, later in it.
        let _guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, cond], None);
        let ret = g.add(Op::Return, IrType::Void, vec![c0, v7], None);
        g.exit = ret;
        g.safepoints.push(SafepointSnapshot::new(
            10,
            vec![cond, newo],
            vec![],
            Vec::new(),
        ));
        g.nodes[newo as usize].op = Op::Dead;
        g.nodes[newo as usize].inputs.clear();
        g.nodes[store as usize].op = Op::Dead;
        g.nodes[store as usize].inputs.clear();
        let mut objects = HashMap::new();
        objects.insert(
            newo,
            VirtualObjectInfo {
                array_element_type: None,
                class_id: 7,
                num_fields: 1,
                field_values: vec![Some(v7)],
                new_ctrl: c0,
                store_ctrls: vec![c0],
                store_nodes: vec![store],
                store_fields: Vec::new(),
            },
        );
        let sr_map = ScalarReplacementMap { objects };

        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        match &deopt_locals_at(&cm, 10)[1] {
            FrameValue::VirtualObject(state) => {
                assert_eq!(state.id, newo as usize);
                assert_eq!(state.field_values, vec![FrameValue::Int(7)]);
            }
            other => panic!("expected VirtualObject, got {other:?}"),
        }
    }

    #[test]
    fn test_scalar_deopt_bails_when_store_not_dominating() {
        // Guard in the SAME block as the New/store but BEFORE them → neither
        // strict dominance nor the in-block order proves the object existed
        // when the guard fires. The bail names the
        // eliminated allocation instead of claiming the slot is undefined, so
        // the resume is REFUSED (safe whole-method re-run) rather than served a
        // fabricated `Int(0)` — which for this reference local would be `null`.
        let (g, sr_map, newo) = build_sr_deopt_graph(true, false);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        assert_eq!(
            locals[1],
            FrameValue::MaterializationRequired(EliminatedValue::allocation(
                newo,
                7,
                EliminationCause::ScalarReplacedObject,
            )),
            "a non-dominating store must bail to MaterializationRequired, naming \
             the producer node and the class it allocated"
        );
        let fs = &cm
            ._deopt_point_boxes
            .iter()
            .find(|p| p.bci == 10)
            .expect("deopt box at bci 10")
            .frame_state;
        assert!(
            !crate::deopt::frame_state_is_resumable(fs),
            "the frame must be unresumable, which is what turns the old silent \
             null into a refused deopt"
        );
        assert_eq!(crate::deopt::count_materialization_required(fs), 1);
    }

    /// Round 11 wave 5 (lane lower): `o = new Foo(); guard; o.x = 7; o.y = 8`
    /// in one block. At the guard the allocation has run and neither store
    /// has, so the object is its zero-initialised self: a `VirtualObject` with
    /// zero fields, not a refusal. With `o.x = 7` moved BEFORE the guard the
    /// stores are mixed (one ran, one did not). Wave 6: with a complete
    /// `store_fields` that is `{x: 7, y: 0}`; without one it still refuses.
    #[test]
    fn r11w5_a_store_after_the_deopt_in_the_allocating_block_describes_zero() {
        for (x_before_guard, with_store_fields) in [(false, false), (true, false), (true, true)] {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
            let newo = g.add(
                Op::New {
                    class_id: 7,
                    num_fields: 2,
                },
                IrType::Ref,
                vec![c0, mem],
                None,
            );
            let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
            let f1 = g.add(Op::Const(1), IrType::Int, vec![], None);
            let v7 = g.add(Op::Const(7), IrType::Int, vec![], None);
            let v8 = g.add(Op::Const(8), IrType::Int, vec![], None);
            let mut store_x = NO_NODE;
            if x_before_guard {
                store_x = g.add(
                    Op::Store(MemKind::Int),
                    IrType::Memory,
                    vec![c0, mem, newo, f0, v7],
                    None,
                );
            }
            let _guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, cond], None);
            if !x_before_guard {
                store_x = g.add(
                    Op::Store(MemKind::Int),
                    IrType::Memory,
                    vec![c0, mem, newo, f0, v7],
                    None,
                );
            }
            let store_y = g.add(
                Op::Store(MemKind::Int),
                IrType::Memory,
                vec![c0, mem, newo, f1, v8],
                None,
            );
            let ret = g.add(Op::Return, IrType::Void, vec![c0, v7], None);
            g.exit = ret;
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![cond, newo],
                vec![],
                Vec::new(),
            ));
            for dead in [newo, store_x, store_y] {
                g.nodes[dead as usize].op = Op::Dead;
                g.nodes[dead as usize].inputs.clear();
            }
            let mut objects = HashMap::new();
            objects.insert(
                newo,
                VirtualObjectInfo {
                    array_element_type: None,
                    class_id: 7,
                    num_fields: 2,
                    field_values: vec![Some(v7), Some(v8)],
                    new_ctrl: c0,
                    store_ctrls: vec![c0, c0],
                    store_nodes: vec![store_x, store_y],
                    store_fields: if with_store_fields {
                        vec![Some((0, Some(v7))), Some((1, Some(v8)))]
                    } else {
                        Vec::new()
                    },
                },
            );
            let sr_map = ScalarReplacementMap { objects };
            let schedule = ir_schedule::schedule(&g);
            let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
                .expect("lower");
            let got = &deopt_locals_at(&cm, 10)[1];
            if x_before_guard && with_store_fields {
                match got {
                    FrameValue::VirtualObject(state) => {
                        assert_eq!(state.id, newo as usize);
                        assert_eq!(
                            state.field_values,
                            vec![FrameValue::Int(7), FrameValue::Int(0)],
                            "x's store ran at the guard and y's did not"
                        );
                    }
                    other => panic!("expected VirtualObject, got {other:?}"),
                }
            } else if x_before_guard {
                assert_eq!(
                    *got,
                    FrameValue::MaterializationRequired(EliminatedValue::allocation(
                        newo,
                        7,
                        EliminationCause::ScalarReplacedObject,
                    )),
                    "mixed run/pending stores without a store_fields list must still refuse"
                );
            } else {
                match got {
                    FrameValue::VirtualObject(state) => {
                        assert_eq!(state.id, newo as usize);
                        assert_eq!(
                            state.field_values,
                            vec![FrameValue::Int(0), FrameValue::Int(0)],
                            "no store has run at the guard: every field is its zero default"
                        );
                    }
                    other => panic!("expected VirtualObject, got {other:?}"),
                }
            }
        }
    }

    /// Round 11 wave 6 (lane lower): `o = new Foo(); o.x = 7; o.x = 9; guard;
    /// o.y = 8; o.x = 5` in one block. At the guard `x` holds its last RUN
    /// store's value, 9 -- not the earlier 7, and not the final 5 that
    /// `field_values` records -- and `y` is still its zero default. One entry
    /// of `store_fields` unknown makes the object refuse again.
    #[test]
    fn r11w6_a_field_holds_its_last_run_store_at_a_mixed_deopt() {
        for complete in [true, false] {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
            let newo = g.add(
                Op::New {
                    class_id: 7,
                    num_fields: 2,
                },
                IrType::Ref,
                vec![c0, mem],
                None,
            );
            let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
            let f1 = g.add(Op::Const(1), IrType::Int, vec![], None);
            let v7 = g.add(Op::Const(7), IrType::Int, vec![], None);
            let v9 = g.add(Op::Const(9), IrType::Int, vec![], None);
            let v8 = g.add(Op::Const(8), IrType::Int, vec![], None);
            let v5 = g.add(Op::Const(5), IrType::Int, vec![], None);
            let store = |g: &mut Graph, field: NodeId, value: NodeId| {
                g.add(
                    Op::Store(MemKind::Int),
                    IrType::Memory,
                    vec![c0, mem, newo, field, value],
                    None,
                )
            };
            let sx1 = store(&mut g, f0, v7);
            let sx2 = store(&mut g, f0, v9);
            let _guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, cond], None);
            let sy = store(&mut g, f1, v8);
            let sx3 = store(&mut g, f0, v5);
            let ret = g.add(Op::Return, IrType::Void, vec![c0, v5], None);
            g.exit = ret;
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![cond, newo],
                vec![],
                Vec::new(),
            ));
            for dead in [newo, sx1, sx2, sy, sx3] {
                g.nodes[dead as usize].op = Op::Dead;
                g.nodes[dead as usize].inputs.clear();
            }
            let mut store_fields = vec![
                Some((0, Some(v7))),
                Some((0, Some(v9))),
                Some((1, Some(v8))),
                Some((0, Some(v5))),
            ];
            if !complete {
                // `o.x = 7`'s entry unknown.
                store_fields[0] = None;
            }
            let mut objects = HashMap::new();
            objects.insert(
                newo,
                VirtualObjectInfo {
                    array_element_type: None,
                    class_id: 7,
                    num_fields: 2,
                    field_values: vec![Some(v5), Some(v8)],
                    new_ctrl: c0,
                    store_ctrls: vec![c0, c0, c0, c0],
                    store_nodes: vec![sx1, sx2, sy, sx3],
                    store_fields,
                },
            );
            let sr_map = ScalarReplacementMap { objects };
            // Every store value is pinned, not only the final field values.
            let walked: Vec<NodeId> = scalar_replacement_field_values(&sr_map).collect();
            for v in [v5, v8, v9] {
                assert!(
                    walked.contains(&v),
                    "store value n{v} is not in the pin walk"
                );
            }
            assert_eq!(walked.contains(&v7), complete);
            let schedule = ir_schedule::schedule(&g);
            let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
                .expect("lower");
            let got = &deopt_locals_at(&cm, 10)[1];
            if complete {
                match got {
                    FrameValue::VirtualObject(state) => {
                        assert_eq!(state.id, newo as usize);
                        assert_eq!(
                            state.field_values,
                            vec![FrameValue::Int(9), FrameValue::Int(0)],
                            "x is its last run store's value and y has not been stored"
                        );
                    }
                    other => panic!("expected VirtualObject, got {other:?}"),
                }
            } else {
                assert_eq!(
                    *got,
                    FrameValue::MaterializationRequired(EliminatedValue::allocation(
                        newo,
                        7,
                        EliminationCause::ScalarReplacedObject,
                    )),
                    "an unknown store_fields entry must refuse the mixed object"
                );
            }
        }
    }

    /// Round 11 wave 6 (`r11w6-lower-sr-recipe-values-scheduled-after-the-deopt`):
    /// `o = new Foo(); o.x = cond + 1; guard` in one block, all stores run.
    /// The field's value `cond + 1` is read by nothing once the store is
    /// eliminated, so the scheduler may put it after the guard. The schedule is
    /// edited to place it on either side: before the guard the object is
    /// described, after it the object refuses, because its home word is not
    /// written when the deopt fires.
    #[test]
    fn r11w6_a_recipe_value_computed_after_the_site_refuses_the_object() {
        for value_after_site in [false, true] {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
            let newo = g.add(
                Op::New {
                    class_id: 7,
                    num_fields: 1,
                },
                IrType::Ref,
                vec![c0, mem],
                None,
            );
            let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
            let one = g.add(Op::Const(1), IrType::Int, vec![], None);
            let t = g.add(Op::Add, IrType::Int, vec![cond, one], None);
            let store = g.add(
                Op::Store(MemKind::Int),
                IrType::Memory,
                vec![c0, mem, newo, f0, t],
                None,
            );
            let guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, cond], None);
            let ret = g.add(Op::Return, IrType::Void, vec![c0, cond], None);
            g.exit = ret;
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![cond, newo],
                vec![],
                Vec::new(),
            ));
            for dead in [newo, store] {
                g.nodes[dead as usize].op = Op::Dead;
                g.nodes[dead as usize].inputs.clear();
            }
            let mut objects = HashMap::new();
            objects.insert(
                newo,
                VirtualObjectInfo {
                    array_element_type: None,
                    class_id: 7,
                    num_fields: 1,
                    field_values: vec![Some(t)],
                    new_ctrl: c0,
                    store_ctrls: vec![c0],
                    store_nodes: vec![store],
                    store_fields: vec![Some((0, Some(t)))],
                },
            );
            let sr_map = ScalarReplacementMap { objects };
            let mut schedule = ir_schedule::schedule(&g);
            let db = schedule.node_to_block[guard as usize];
            schedule.node_to_block[t as usize] = db;
            for block in schedule.blocks.iter_mut() {
                block.nodes.retain(|&n| n != t);
            }
            let nodes = &mut schedule.blocks[db].nodes;
            let at = nodes
                .iter()
                .position(|&n| n == guard)
                .expect("the guard is a node of its block");
            nodes.insert(if value_after_site { at + 1 } else { at }, t);
            let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
                .expect("lower");
            let got = &deopt_locals_at(&cm, 10)[1];
            if value_after_site {
                assert_eq!(
                    *got,
                    FrameValue::MaterializationRequired(EliminatedValue::allocation(
                        newo,
                        7,
                        EliminationCause::ScalarReplacedObject,
                    )),
                    "a field value computed after the deopt site must refuse the object"
                );
            } else {
                match got {
                    FrameValue::VirtualObject(state) => assert!(
                        !matches!(
                            state.field_values[0],
                            FrameValue::MaterializationRequired(_)
                                | FrameValue::Undefined
                                | FrameValue::Unsupported
                        ),
                        "the field is described: {:?}",
                        state.field_values[0]
                    ),
                    other => panic!("expected VirtualObject, got {other:?}"),
                }
            }
        }
    }

    /// Round 11 wave 8 (`r11w7-mid-sr-store-after-deopt-outside-the-allocation-block`):
    /// `o = new Foo(); o.x = 1; if (cond) { guard; o.y = 8; return } return`.
    /// The allocation is in the entry block, which strictly dominates the
    /// guard's; at the guard `x`'s store ran and `y`'s did not, so with a
    /// complete `store_fields` the object is `{x: 1, y: 0}`. It used to refuse,
    /// because a store after the site was accepted only on an object allocated
    /// in the deopt block itself. Without `store_fields` it still refuses.
    #[test]
    fn r11w8_a_store_after_the_deopt_below_the_allocating_block_is_pending() {
        use crate::ir::CmpOp;
        for with_store_fields in [true, false] {
            let mut g = Graph::empty(0);
            let start = g.add(Op::Start, IrType::Control, vec![], None);
            let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
            let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
            let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
            let newo = g.add(
                Op::New {
                    class_id: 7,
                    num_fields: 2,
                },
                IrType::Ref,
                vec![c0, mem],
                None,
            );
            let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
            let f1 = g.add(Op::Const(1), IrType::Int, vec![], None);
            let v1 = g.add(Op::Const(1), IrType::Int, vec![], None);
            let v8 = g.add(Op::Const(8), IrType::Int, vec![], None);
            let store_x = g.add(
                Op::Store(MemKind::Int),
                IrType::Memory,
                vec![c0, mem, newo, f0, v1],
                None,
            );
            let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
            let cmp = g.add(Op::Cmp(CmpOp::Ne), IrType::Int, vec![cond, zero], None);
            let iff = g.add(Op::If, IrType::Control, vec![c0, cmp], None);
            let t = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
            let e = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
            let _guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![t, cond], None);
            let store_y = g.add(
                Op::Store(MemKind::Int),
                IrType::Memory,
                vec![t, mem, newo, f1, v8],
                None,
            );
            let ret1 = g.add(Op::Return, IrType::Void, vec![t, v1], None);
            let _ret2 = g.add(Op::Return, IrType::Void, vec![e, v1], None);
            g.exit = ret1;
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![cond, newo],
                vec![],
                Vec::new(),
            ));
            for dead in [newo, store_x, store_y] {
                g.nodes[dead as usize].op = Op::Dead;
                g.nodes[dead as usize].inputs.clear();
            }
            let mut objects = HashMap::new();
            objects.insert(
                newo,
                VirtualObjectInfo {
                    array_element_type: None,
                    class_id: 7,
                    num_fields: 2,
                    field_values: vec![Some(v1), Some(v8)],
                    new_ctrl: c0,
                    store_ctrls: vec![c0, t],
                    store_nodes: vec![store_x, store_y],
                    store_fields: if with_store_fields {
                        vec![Some((0, Some(v1))), Some((1, Some(v8)))]
                    } else {
                        Vec::new()
                    },
                },
            );
            let sr_map = ScalarReplacementMap { objects };
            let schedule = ir_schedule::schedule(&g);
            assert_ne!(
                schedule.node_to_block[c0 as usize], schedule.node_to_block[t as usize],
                "the fixture allocates outside the deopt block"
            );
            let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
                .expect("lower");
            let got = &deopt_locals_at(&cm, 10)[1];
            if with_store_fields {
                match got {
                    FrameValue::VirtualObject(state) => {
                        assert_eq!(state.id, newo as usize);
                        assert_eq!(
                            state.field_values,
                            vec![FrameValue::Int(1), FrameValue::Int(0)],
                            "x's store ran above the guard and y's did not"
                        );
                    }
                    other => panic!("expected VirtualObject, got {other:?}"),
                }
            } else {
                assert_eq!(
                    *got,
                    FrameValue::MaterializationRequired(EliminatedValue::allocation(
                        newo,
                        7,
                        EliminationCause::ScalarReplacedObject,
                    )),
                    "mixed run/pending stores without a store_fields list must still refuse"
                );
            }
        }
    }

    /// Round 12 wave 2 (lane irback, proposal R12-4): a reachable block with no
    /// terminator and no successor is refused. It used to emit no transfer and
    /// run on into whichever block the layout put next -- here the `true` arm
    /// of a diamond, whose `goto` to the join is dropped from the schedule the
    /// way a lost `goto` back edge would drop it.
    #[test]
    fn r12w2_a_reachable_block_that_ends_nowhere_is_refused() {
        use crate::ir::CmpOp;
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let p = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
        let one = g.add(Op::Const(1), IrType::Int, vec![], None);
        let cmp = g.add(Op::Cmp(CmpOp::Ne), IrType::Int, vec![p, zero], None);
        let iff = g.add(Op::If, IrType::Control, vec![c0, cmp], None);
        let t = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
        let e = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
        let join = g.add(Op::Merge, IrType::Control, vec![t, e], None);
        let phi = g.add(Op::Phi, IrType::Int, vec![join, one, zero], None);
        let ret = g.add(Op::Return, IrType::Void, vec![join, phi], None);
        g.exit = ret;
        let intact = ir_schedule::schedule(&g);
        assert!(
            lower(&g, &intact, 1, 1, &no_helpers()).is_some(),
            "the fixture lowers with its CFG intact"
        );
        let mut broken = ir_schedule::schedule(&g);
        let arm = broken.node_to_block[t as usize];
        assert!(
            broken.blocks[arm].terminator.is_none() && !broken.blocks[arm].successors.is_empty(),
            "the true arm is a goto block"
        );
        broken.blocks[arm].successors.clear();
        assert!(
            lower(&g, &broken, 1, 1, &no_helpers()).is_none(),
            "a reachable goto block that names no successor must be refused, not fall through"
        );
    }

    /// Round 11 wave 8 (`r11w7-mid-sr-deopt-block-is-chosen-per-bci-not-per-snapshot`):
    /// two snapshots at bci 10, the original unnamed (index 0) and a copy
    /// (index 1) named by the only site there, a guard. The copy is described
    /// at the guard; the original, which no site publishes, is not described
    /// at the COPY's program point any more — it refuses the object, the
    /// answer for a table point nothing traps at.
    #[test]
    fn r11w8_a_scalar_replaced_object_is_described_per_snapshot_not_per_bci() {
        use crate::ir::CmpOp;
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let newo = g.add(
            Op::New {
                class_id: 7,
                num_fields: 1,
            },
            IrType::Ref,
            vec![c0, mem],
            None,
        );
        let f0 = g.add(Op::Const(0), IrType::Int, vec![], None);
        let v7 = g.add(Op::Const(7), IrType::Int, vec![], None);
        let store = g.add(
            Op::Store(MemKind::Int),
            IrType::Memory,
            vec![c0, mem, newo, f0, v7],
            None,
        );
        let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
        let cmp = g.add(Op::Cmp(CmpOp::Ne), IrType::Int, vec![cond, zero], None);
        let iff = g.add(Op::If, IrType::Control, vec![c0, cmp], None);
        let t = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
        let e = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
        let guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![t, cond], Some(10));
        let ret1 = g.add(Op::Return, IrType::Void, vec![t, v7], None);
        let _ret2 = g.add(Op::Return, IrType::Void, vec![e, v7], None);
        g.exit = ret1;
        for _ in 0..2 {
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![cond, newo],
                vec![],
                Vec::new(),
            ));
        }
        assert!(
            g.set_node_frame_snapshot(guard, 1),
            "the copy is at the guard's bci"
        );
        for dead in [newo, store] {
            g.nodes[dead as usize].op = Op::Dead;
            g.nodes[dead as usize].inputs.clear();
        }
        let mut objects = HashMap::new();
        objects.insert(
            newo,
            VirtualObjectInfo {
                array_element_type: None,
                class_id: 7,
                num_fields: 1,
                field_values: vec![Some(v7)],
                new_ctrl: c0,
                store_ctrls: vec![c0],
                store_nodes: vec![store],
                store_fields: vec![Some((0, Some(v7)))],
            },
        );
        let sr_map: &'static ScalarReplacementMap =
            Box::leak(Box::new(ScalarReplacementMap { objects }));
        let schedule = ir_schedule::schedule(&g);
        let graph: &'static Graph = Box::leak(Box::new(g));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
        let mut lo = lowerer_over(graph, schedule, plan, 4096);
        lo.sr_map = Some(sr_map);
        let copy = lo.resolve_frame_state(1, &graph.safepoints[1]);
        match &copy.locals[1] {
            FrameValue::VirtualObject(state) => {
                assert_eq!(state.field_values, vec![FrameValue::Int(7)]);
            }
            other => panic!("the guard's own frame describes the object, got {other:?}"),
        }
        let original = lo.resolve_frame_state(0, &graph.safepoints[0]);
        assert_eq!(
            original.locals[1],
            FrameValue::MaterializationRequired(EliminatedValue::allocation(
                newo,
                7,
                EliminationCause::ScalarReplacedObject,
            )),
            "no site publishes the original, so it is not described at the copy's point"
        );
    }

    /// Round 11 wave 8: the loop half of the rule above. `o = new Foo();
    /// while (cond) { guard; o.y = 8 }` — the allocation is outside the loop,
    /// so at the guard of the second iteration `o.y = 8` HAS run on this very
    /// object: the store must not be classified pending. The same store is
    /// pending when the allocation is the loop header's own (every trip
    /// allocates a new object), and `block_reaches_avoiding` is what tells the
    /// two apart.
    #[test]
    fn r11w8_a_store_after_the_deopt_in_a_loop_around_it_is_not_pending() {
        use crate::ir::CmpOp;
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        g.entry = start;
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let cond = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let newo = g.add(
            Op::New {
                class_id: 7,
                num_fields: 2,
            },
            IrType::Ref,
            vec![c0, mem],
            None,
        );
        let f1 = g.add(Op::Const(1), IrType::Int, vec![], None);
        let v8 = g.add(Op::Const(8), IrType::Int, vec![], None);
        let region = g.add(Op::Region, IrType::Control, vec![c0, NO_NODE], None);
        let zero = g.add(Op::Const(0), IrType::Int, vec![], None);
        let cmp = g.add(Op::Cmp(CmpOp::Ne), IrType::Int, vec![cond, zero], None);
        let iff = g.add(Op::If, IrType::Control, vec![region, cmp], None);
        let body = g.add(Op::Proj(0), IrType::Control, vec![iff], None);
        let exit = g.add(Op::Proj(1), IrType::Control, vec![iff], None);
        let guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![body, cond], None);
        let store_y = g.add(
            Op::Store(MemKind::Int),
            IrType::Memory,
            vec![body, mem, newo, f1, v8],
            None,
        );
        g.nodes[region as usize].inputs[1] = body;
        let ret = g.add(Op::Return, IrType::Void, vec![exit, v8], None);
        g.exit = ret;
        let schedule = ir_schedule::schedule(&g);
        let graph: &'static Graph = Box::leak(Box::new(g));
        let schedule: &'static Schedule = Box::leak(Box::new(schedule));
        let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
        let lo = lowerer_over(graph, schedule, plan, 4096);
        let db = schedule.node_to_block[body as usize];
        let entry_block = schedule.node_to_block[c0 as usize];
        let header_block = schedule.node_to_block[region as usize];
        assert!(
            entry_block != db && schedule.dom.dominates(entry_block, db),
            "the fixture allocates in a block strictly dominating the deopt block"
        );
        assert!(
            !lo.eliminated_store_pending_after_alloc(
                body,
                Some(store_y),
                db,
                Some(guard),
                entry_block
            ),
            "the back edge carries the store to the next trip's guard on the same object"
        );
        assert!(
            lo.eliminated_store_pending_after_alloc(
                body,
                Some(store_y),
                db,
                Some(guard),
                header_block
            ),
            "with the allocation in the header every trip's object is new"
        );
        assert!(
            !lo.eliminated_store_pending_after_alloc(
                body,
                Some(guard),
                db,
                Some(guard),
                header_block
            ),
            "a node that is not after the last site is never pending"
        );
    }

    /// Round 11 wave 6 (lane lower; the `ir_lower` half of
    /// `r11w5-mid-named-frame-copies-collide-with-the-by-bci-snapshot`): two
    /// snapshots at bci 10, the original unnamed and a copy named by the only
    /// data node at that bci (LICM's pre-header frame has this shape). The
    /// named node anchors its copy through `snapshot_native` and no longer
    /// anchors the bci, so the unnamed original cannot land on the same offset
    /// and win `build_deopt_points`' dedup: the table's one point at bci 10 is
    /// the copy's frame.
    #[test]
    fn r11w6_a_node_named_frame_copy_is_the_deopt_point_at_its_bci() {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let p0 = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let p1 = g.add(Op::Param(1), IrType::Int, vec![start], None);
        let c5 = g.add(Op::Const(5), IrType::Int, vec![], None);
        let c9 = g.add(Op::Const(9), IrType::Int, vec![], None);
        let sum = g.add(Op::Add, IrType::Int, vec![p0, p1], Some(10));
        // Two uses, so `sum` is lowered at its own position rather than
        // carried into a single consumer.
        let twice = g.add(Op::Add, IrType::Int, vec![sum, sum], None);
        let _guard = g.add(Op::Guard { bci: 20 }, IrType::Void, vec![c0, p0], None);
        let ret = g.add(Op::Return, IrType::Void, vec![c0, twice], None);
        g.exit = ret;
        for (bci, local1) in [(10, c5), (10, c9), (20, p1)] {
            g.safepoints.push(SafepointSnapshot::new(
                bci,
                vec![p0, local1],
                vec![],
                Vec::new(),
            ));
        }
        assert!(
            g.set_node_frame_snapshot(sum, 1),
            "the copy is at sum's own bci"
        );
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 2, 2, &no_helpers()).expect("lower");
        let at10: Vec<&DeoptimizationPoint> =
            cm.deopt_points.iter().filter(|p| p.bci == 10).collect();
        assert_eq!(at10.len(), 1, "one point at bci 10: {at10:?}");
        assert_eq!(
            at10[0].frame_state.locals.get(1),
            Some(&FrameValue::Int(9)),
            "the unnamed original (local 1 = 5) took the named copy's anchor"
        );
    }

    /// irlower proposal W8-1 (round 11 wave 9): the unnamed original at a bci
    /// gets no table point when the only deopt site there publishes a
    /// node-named copy — even when an unnamed non-site node still anchors the
    /// bci (which is what kept it alive past wave 6's anchor rule above).
    /// Before, bci 10 carried the original's frame (local 1 = 5), which no trap
    /// publishes, beside or instead of the guard's (local 1 = 9).
    #[test]
    fn r11w9_a_table_point_no_site_publishes_is_not_built_beside_one_that_is() {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let c0 = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let p0 = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let p1 = g.add(Op::Param(1), IrType::Int, vec![start], None);
        let c5 = g.add(Op::Const(5), IrType::Int, vec![], None);
        let c9 = g.add(Op::Const(9), IrType::Int, vec![], None);
        // An unnamed, non-trapping node at bci 10: it anchors `bci_native`.
        let sum = g.add(Op::Add, IrType::Int, vec![p0, p1], Some(10));
        let twice = g.add(Op::Add, IrType::Int, vec![sum, sum], None);
        // The only deopt site at bci 10, naming the copy (snapshot 1).
        let guard = g.add(Op::Guard { bci: 10 }, IrType::Void, vec![c0, p0], Some(10));
        let ret = g.add(Op::Return, IrType::Void, vec![c0, twice], None);
        g.exit = ret;
        for local1 in [c5, c9] {
            g.safepoints.push(SafepointSnapshot::new(
                10,
                vec![p0, local1],
                vec![],
                Vec::new(),
            ));
        }
        assert!(
            g.set_node_frame_snapshot(guard, 1),
            "the guard is at bci 10"
        );
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 2, 2, &no_helpers()).expect("lower");
        let at10: Vec<&DeoptimizationPoint> =
            cm.deopt_points.iter().filter(|p| p.bci == 10).collect();
        assert_eq!(at10.len(), 1, "one table point at bci 10: {at10:?}");
        assert_eq!(
            at10[0].frame_state.locals.get(1),
            Some(&FrameValue::Int(9)),
            "the table point at bci 10 must be the frame the guard publishes"
        );
    }

    /// A field whose value is itself a scalar-replaced allocation is emitted as
    /// a NESTED `FrameValue::VirtualObject`, not bailed.
    ///
    /// This used to answer `MaterializationRequired(NestedVirtualObject)` -- "the
    /// recipe exists but v1 emits no nested graphs" -- and that restriction is
    /// what stopped a wrapper object and its storage array from both being
    /// deleted: the wrapper's recipe names the array, so the moment the array
    /// became replaceable the wrapper's own recipe was refused and the wrapper
    /// had to stay on the heap. The materializer has always walked nested field
    /// graphs (`collect_virtual_objects` recurses, `field_value_to_value`
    /// resolves a nested state to its shell); only the producer refused.
    #[test]
    fn scalar_deopt_emits_a_nested_virtual_object_for_a_virtual_field() {
        let (mut g, mut sr_map, newo) = build_sr_deopt_graph(false, false);
        // Make field 0's value itself a scalar-replaced object: add a second
        // dead `Op::New` and register it in the map, then point the first
        // object's only field at it.
        let inner = g.add(Op::Dead, IrType::Ref, vec![], None);
        sr_map.objects.insert(
            inner,
            VirtualObjectInfo {
                array_element_type: None,
                class_id: 9,
                num_fields: 0,
                field_values: vec![],
                new_ctrl: 1, // Proj(0) — the entry control, dominates everything
                store_ctrls: vec![],
                store_nodes: vec![],
                store_fields: Vec::new(),
            },
        );
        sr_map
            .objects
            .get_mut(&newo)
            .expect("outer object")
            .field_values = vec![Some(inner)];

        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        let outer = &deopt_locals_at(&cm, 10)[1];
        let FrameValue::VirtualObject(state) = outer else {
            panic!("the outer object must still be a VirtualObject, got {outer:?}");
        };
        assert_eq!(state.field_values.len(), 1);
        assert!(
            matches!(
                &state.field_values[0],
                FrameValue::VirtualObject(inner_state)
                    if inner_state.class_id == 9 && inner_state.num_fields == 0
            ),
            "field 0 must be the nested object's own recipe, got {:?}",
            state.field_values[0]
        );
        let fs = &cm
            ._deopt_point_boxes
            .iter()
            .find(|p| p.bci == 10)
            .expect("deopt box at bci 10")
            .frame_state;
        assert!(
            crate::deopt::frame_state_is_resumable(fs),
            "a nested graph is rebuildable, so the frame must stay resumable"
        );
    }

    /// ...and a nested object that cannot be described refuses the ENCLOSING
    /// one, with the nested cause. Fail-closed one level at a time: the
    /// recursion re-runs every gate on the inner object, so an inner allocation
    /// whose control does not strictly dominate the deopt block takes the outer
    /// object down with it rather than being silently replaced by a null.
    #[test]
    fn scalar_deopt_an_undescribable_nested_field_bails_the_enclosing_object() {
        let (mut g, mut sr_map, newo) = build_sr_deopt_graph(false, false);
        let inner = g.add(Op::Dead, IrType::Ref, vec![], None);
        sr_map.objects.insert(
            inner,
            VirtualObjectInfo {
                array_element_type: None,
                class_id: 9,
                num_fields: 0,
                field_values: vec![],
                // NO_NODE control: unresolvable, so the inner object's own
                // dominance gate refuses it.
                new_ctrl: NO_NODE,
                store_ctrls: vec![],
                store_nodes: vec![],
                store_fields: Vec::new(),
            },
        );
        sr_map
            .objects
            .get_mut(&newo)
            .expect("outer object")
            .field_values = vec![Some(inner)];

        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        assert_eq!(
            deopt_locals_at(&cm, 10)[1],
            FrameValue::MaterializationRequired(EliminatedValue::allocation(
                newo,
                7,
                EliminationCause::NestedVirtualObject,
            )),
            "an undescribable nested field must bail the enclosing object with \
             NestedVirtualObject, not ScalarReplacedObject and not Undefined"
        );
    }

    /// A `NO_NODE` snapshot slot is the one case that is *genuinely* undefined —
    /// the local was never stored on any path reaching this bci, so the verifier
    /// guarantees the interpreter cannot read it and `Value::Int(0)` is correct.
    /// It must keep resolving to `Undefined`; widening the eliminated marker to
    /// cover it would make every method with an unwritten local unresumable.
    #[test]
    fn no_node_snapshot_slot_stays_undefined() {
        let (mut g, sr_map, _newo) = build_sr_deopt_graph(false, false);
        // locals were [cond, o]; append an unwritten slot.
        g.safepoints
            .iter_mut()
            .find(|s| s.bci == 10)
            .expect("snapshot at bci 10")
            .locals
            .push(NO_NODE);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        assert_eq!(
            locals[2],
            FrameValue::Undefined,
            "an unwritten local is genuinely undefined, not eliminated"
        );
        // And it does NOT block the resume — only the eliminated marker does.
        assert!(crate::deopt::frame_state_is_resumable(&FrameState {
            method_key: String::new(),
            bci: 10,
            locals: vec![FrameValue::Undefined],
            stack: vec![],
            monitors: vec![],
            caller: None,
        }));
    }

    /// `frame_value_for` used to index `graph.nodes` directly, so a snapshot slot
    /// naming an id past the end of the arena panicked — on the compiler thread,
    /// which takes the VM down. It must bail to the unresumable marker instead.
    #[test]
    fn out_of_range_snapshot_node_id_bails_instead_of_panicking() {
        let (mut g, _sr_map, _newo) = build_sr_deopt_graph(false, false);
        let past_end = g.nodes.len() as NodeId + 7;
        g.safepoints
            .iter_mut()
            .find(|s| s.bci == 10)
            .expect("snapshot at bci 10")
            .locals
            .push(past_end);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 1, 3, &no_helpers()).expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        assert_eq!(
            locals[2],
            FrameValue::MaterializationRequired(EliminatedValue::unknown(
                EliminationCause::Unclassified,
            )),
            "an out-of-range node id must resolve to the unresumable marker"
        );
    }

    // ── speculation ids on IR-tier deopt points (NOTES-cha.md C2) ────

    /// Every deopt point this tier publishes names WHICH speculation it is,
    /// and names it with the value the CONSUMER computes.
    ///
    /// The consumer is `DespecRegistry::contains_speculation`, asked by the
    /// emitter gates in `lib.rs` / `jit_bridge.rs` before a guard goes down and
    /// fed by the VM's de-spec recording in `deopt_resume.rs`. Both derive the
    /// id from the `(bci, reason)` they recovered, so a producer that stamps
    /// anything else is invisible to the registry — which is exactly what
    /// `speculation_id: 0` at every IR producer meant: a wildcard, matching
    /// (and therefore withdrawing) every other speculation at its bci.
    ///
    /// Asserted over BOTH published lists, because this file has three
    /// producers feeding two of them: `_deopt_point_boxes` (the `Op::Guard` arm
    /// and `emit_deopt_unless`, whose pointers the stubs bake) and
    /// `deopt_points` (the safepoint resume points, keyed by native offset).
    #[test]
    fn an_ir_tier_deopt_point_carries_the_id_the_consumer_derives() {
        let (g, _sr_map, _newo) = build_sr_deopt_graph(false, false);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 1, 3, &no_helpers()).expect("lower");

        let published: Vec<&DeoptimizationPoint> = cm
            ._deopt_point_boxes
            .iter()
            .map(|b| &**b)
            .chain(cm.deopt_points.iter())
            .collect();
        assert!(
            !published.is_empty(),
            "the fixture carries an `Op::Guard`, so the lowering must have \
             published at least one deopt point — without one this test \
             asserts nothing"
        );
        for p in published {
            assert_ne!(
                p.speculation_id,
                crate::deopt::SPECULATION_ID_ANY,
                "an IR-tier point at bci {} ({:?}) still carries the wildcard; \
                 a de-spec recorded against it would withdraw every other \
                 speculation at that bytecode index",
                p.bci,
                p.reason
            );
            assert_eq!(
                p.speculation_id,
                crate::deopt::speculation_id(p.bci, p.reason),
                "the id on the point at bci {} ({:?}) is not the one the \
                 consumer re-derives from the same `(bci, reason)`",
                p.bci,
                p.reason
            );
        }
    }

    /// Two speculations at ONE bci are told apart, and withdrawing one leaves
    /// the other standing — the property M4 exists for, now reached through an
    /// id this tier actually produced rather than one a test made up.
    ///
    /// `osr_exit.rs` calls the two-points-at-one-bci shape ordinary, not
    /// exotic: a protected invoke publishes a `ReceiverTypeChanged` guard and a
    /// `PendingException` frame at the same bytecode index. Under the old
    /// `(method, bci)` key, four traps on the exceptional frame withdrew the
    /// receiver guard too — on evidence about a speculation that had never
    /// failed.
    #[test]
    fn two_speculations_at_one_ir_tier_bci_are_withdrawn_independently() {
        let (g, _sr_map, _newo) = build_sr_deopt_graph(false, false);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 1, 3, &no_helpers()).expect("lower");

        // The guard the fixture builds, as the lowering published it.
        let guard = cm
            ._deopt_point_boxes
            .iter()
            .find(|p| p.bci == 10)
            .expect("the `Op::Guard { bci: 10 }` publishes a boxed point");
        // A second speculation at the SAME bci. Its id is derived the way the
        // VM derives one from a reason it recovered at a trapping bci, so this
        // is the consumer's spelling meeting the producer's.
        let other = crate::deopt::speculation_id(guard.bci, DeoptReason::PendingException);
        assert_ne!(
            guard.reason,
            DeoptReason::PendingException,
            "the fixture's guard must not BE the second speculation, or the \
             two ids are one"
        );
        // FIRST, and load-bearing: the producer must have stamped a real id.
        // An earlier version of this test asserted only `guard.speculation_id
        // != other` and then stored `other`, and it PASSED with the producer
        // reverted to the wildcard -- `0 != other` is true, and
        // `contains_speculation` compares the STORED value against the
        // wildcard, never the queried one. Measured that way: the producer was
        // reverted and this test stayed green. The direction of the store
        // below is what makes the rest of it bite.
        assert_ne!(
            guard.speculation_id,
            crate::deopt::SPECULATION_ID_ANY,
            "the IR tier published a wildcard: a STORED `SPECULATION_ID_ANY` \
             withdraws every speculation at its bci, which is the coarse \
             behaviour M4 exists to end"
        );
        assert_ne!(
            guard.speculation_id, other,
            "two speculations at one bci must be distinguishable, or the \
             third key component buys nothing"
        );

        let registry = crate::deopt::DespecRegistry::new();
        let m = "IrLowerDespec$Protected.call:(I)I";
        // Store the GUARD's own id -- the IR tier's speculation is the one that
        // kept trapping -- and require the OTHER speculation at that bci to
        // survive. Stored this way round, a wildcard producer fails the second
        // assertion, because `SPECULATION_ID_ANY` in the registry answers true
        // for every query at that bci including `other`.
        registry.insert(m, guard.bci, guard.speculation_id);
        assert!(
            registry.contains_speculation(m, guard.bci, guard.speculation_id),
            "the speculation that kept trapping is withdrawn"
        );
        assert!(
            !registry.contains_speculation(m, guard.bci, other),
            "a DIFFERENT speculation at the same bci must survive -- at a \
             protected invoke, four traps on the exceptional frame must not \
             take the receiver guard with them"
        );
        // The coarse question — the one the loop-hoist gates and
        // `recommend_action_at_bci` ask — still answers yes at this bci.
        assert!(registry.contains(m, guard.bci));
    }

    /// No producer in this file may go back to writing the wildcard.
    ///
    /// A source scan rather than a lowering fixture, and deliberately: a FOURTH
    /// producer added later would not be covered by the two tests above, which
    /// can only see the points one fixture happens to publish. The test-module
    /// split is the same one
    /// `every_phi_home_publish_site_is_guarded_against_a_dropped_home` uses.
    #[test]
    fn no_ir_tier_producer_writes_an_unassigned_speculation_id() {
        let src = include_str!("ir_lower.rs");
        let body = src
            .split(
                "
mod tests {",
            )
            .next()
            .unwrap_or(src);
        assert!(
            body.contains("fn emit_deopt_unless"),
            "the scanned region no longer contains the producers — the test \
             module boundary moved"
        );
        let offenders: Vec<&str> = body
            .lines()
            .map(|l| l.trim())
            .filter(|l| {
                l.starts_with("speculation_id:")
                    && (l.contains(": 0") || l.contains("SPECULATION_ID_ANY"))
            })
            .collect();
        assert!(
            offenders.is_empty(),
            "an IR-tier producer writes an unassigned speculation id ({offenders:?}); \
             it knows its own `(bci, reason)`, so it must stamp \
             `crate::deopt::speculation_id(bci, reason)` — a stored wildcard \
             withdraws every other speculation at that bci"
        );
    }

    /// The install-time verifier must reject metadata whose reference slot the
    /// oop map does not cover — the disagreement that leaves a live reference
    /// invisible to a relocating collector. Built here directly (rather than
    /// through `lower_inner`) because this backend does not yet anchor its oop
    /// maps to native offsets, so the agreement lane has nothing to join on in a
    /// real compile; the wiring in `lower_inner` arms the moment it does.
    #[test]
    fn install_verifier_rejects_an_oop_map_deopt_map_disagreement() {
        let point = |locals: Vec<FrameValue>| DeoptimizationPoint {
            native_offset: 0x40,
            bci: 3,
            reason: DeoptReason::NullCheck,
            action: DeoptAction::Reinterpret,
            speculation_id: 0,
            frame_state: FrameState {
                method_key: String::new(),
                bci: 3,
                locals,
                stack: vec![],
                monitors: vec![],
                caller: None,
            },
            semantics: ResumeSemantics::REEXECUTE,
        };
        // The map covers [rbp-40]; deopt spells that word as StackSlotRef(-40).
        let verifier = DeoptVerifier::new().with_oop_map(0x40, OopCoverage::complete([40]));
        assert!(
            verifier
                .verify(std::slice::from_ref(&point(vec![
                    FrameValue::StackSlotRef(-40)
                ])))
                .is_ok(),
            "a covered reference slot must pass"
        );
        let err = verifier
            .verify(std::slice::from_ref(&point(vec![
                FrameValue::StackSlotRef(-48),
            ])))
            .expect_err("an uncovered reference slot must bail the install");
        assert!(
            err.to_string().contains("oop map"),
            "the bailout must say which agreement broke, got: {err}"
        );
    }

    /// A `VirtualObject` recipe may only name a removed node the emitter also
    /// registered as materializable. Naming a node the optimizer retired without
    /// a recipe means the metadata was built from a stale graph, and the artifact
    /// must not install.
    #[test]
    fn install_verifier_rejects_a_recipe_for_an_unmaterializable_removed_node() {
        let point = DeoptimizationPoint {
            native_offset: 0x10,
            bci: 1,
            reason: DeoptReason::DivByZero,
            action: DeoptAction::Reinterpret,
            speculation_id: 0,
            frame_state: FrameState {
                method_key: String::new(),
                bci: 1,
                locals: vec![FrameValue::VirtualObject(VirtualObjectState {
                    array_element_type: None,
                    id: 12,
                    class_id: 3,
                    num_fields: 1,
                    field_values: vec![FrameValue::Int(0)],
                })],
                stack: vec![],
                monitors: vec![],
                caller: None,
            },
            semantics: ResumeSemantics::REEXECUTE,
        };
        assert!(
            DeoptVerifier::new()
                .with_removed_nodes([12u32])
                .with_materializable_nodes([12u32])
                .verify(std::slice::from_ref(&point))
                .is_ok(),
            "a removed node registered as materializable is exactly what a \
             VirtualObject slot is allowed to name"
        );
        assert!(
            DeoptVerifier::new()
                .with_removed_nodes([12u32])
                .verify(std::slice::from_ref(&point))
                .is_err(),
            "a removed node with no recipe must bail the install"
        );
    }

    /// `lower_inner` publishes the slot planner's peak-liveness figure to the
    /// per-compilation report. The number itself is `plan_slots`' business; what
    /// this pins is that the metric is no longer `NotMeasured` after a compile,
    /// which is what made it useless to a reader.
    #[test]
    fn peak_live_values_reaches_the_compilation_report() {
        let _guard = crate::metrics::METRICS_TEST_LOCK.lock();
        crate::metrics::set_enabled_for_test(true);

        // int f(int a, int b) { return a + b; } — two live params at the Add.
        let code = [0x1a, 0x1b, 0x60, 0xac, 0, 0];
        let builder = IrBuilder::new(2, 2);
        let graph = builder.build(&code, 4).expect("build");
        let schedule = ir_schedule::schedule(&graph);
        let expected = plan_slots(&graph, &schedule, None).peak_live;

        let published = {
            let rec = crate::metrics::CompileRecorder::begin("IrLowerPeak", "f", "(II)I", true);
            lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lower");
            rec.snapshot().expect("in-flight snapshot")
        };
        crate::metrics::set_enabled_for_test(false);

        // `Measured::Value(n)` is distinguishable from `NotMeasured` at every
        // `n`, so this equality proves the wiring on its own — the planner's
        // arithmetic is pinned separately by
        // `non_overlapping_values_share_a_frame_slot`.
        assert_eq!(
            published.peak_live_values,
            crate::metrics::Measured::Value(expected as u32),
            "lower_inner must publish SlotPlan::peak_live"
        );
        assert!(published.to_json().contains("\"peak_live_values\":"));
    }

    #[test]
    fn test_scalar_deopt_shares_via_ref() {
        // The same object in two local slots: first occurrence defines the
        // VirtualObject, the second is a VirtualObjectRef to its id.
        let (g, sr_map, newo) = build_sr_deopt_graph(false, true);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower_with_scalar_deopt(&g, &schedule, 1, 3, &no_helpers(), Some(&sr_map))
            .expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        assert!(
            matches!(&locals[1], FrameValue::VirtualObject(s) if s.id == newo as usize),
            "first occurrence defines the object, got {:?}",
            locals[1]
        );
        assert_eq!(
            locals[2],
            FrameValue::VirtualObjectRef(newo as usize),
            "second occurrence is a ref to the same id"
        );
    }

    #[test]
    fn test_scalar_deopt_disabled_without_map() {
        // With `sr_map = None` (the default), no `VirtualObject` recipe is
        // emitted — but the slot still describes an object escape analysis
        // deleted, so it resolves to the unresumable marker rather than to
        // `Undefined`. This is the DEFAULT-configuration half of the silent-null
        // fix: `apply_ea_to_ir` runs whether or not `CRATONVM_SCALAR_DEOPT` is
        // set, so an ordinary production compile reaches exactly this path.
        // `Unclassified` because the generic slot resolver only knows the
        // producer is `Op::Dead`, not which pass retired it.
        let (g, _sr_map, newo) = build_sr_deopt_graph(false, false);
        let schedule = ir_schedule::schedule(&g);
        let cm = lower(&g, &schedule, 1, 3, &no_helpers()).expect("lower");
        let locals = deopt_locals_at(&cm, 10);
        assert_eq!(
            locals[1],
            FrameValue::MaterializationRequired(EliminatedValue::new(
                newo,
                EliminationCause::Unclassified,
            )),
        );
    }

    #[test]
    fn test_deopt_points_params_use_slots() {
        use crate::deopt::FrameValue;
        // int f(int a, int b) { return a + b; } — iload_0;iload_1;iadd;ireturn
        let code = [0x1a, 0x1b, 0x60, 0xac, 0, 0];
        let cm = compile_via_ir_no_opt(&code, 4, 2, 2);
        // The Add (pc2) is the only bci with a data node → one deopt point.
        let p = cm.deopt_points.iter().find(|p| p.bci == 2).unwrap();
        // locals = [a, b], both live params → frame slots (negative off).
        assert_eq!(p.frame_state.locals.len(), 2);
        for v in &p.frame_state.locals {
            assert!(matches!(v, FrameValue::StackSlot(off) if *off < 0));
        }
        // stack at pc2 = [a, b] (same param values).
        assert_eq!(p.frame_state.stack.len(), 2);
    }

    #[test]
    fn test_lower_produces_code() {
        // int f(int x) { return x; }
        let code = [0x1a, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 2, 1, 1);
        assert!(compiled.is_some(), "Should produce compiled code");
        let method = compiled.unwrap();
        assert!(!method.entry_ptr().is_null(), "Code should not be empty");
    }

    #[test]
    fn test_lower_constant_return() {
        // int f() { return 42; }
        // bipush 42; ireturn
        let code = [0x10, 42, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 3, 0, 0);
        assert!(compiled.is_some());
        let method = compiled.unwrap();
        // Execute the compiled code
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let result = unsafe { method.try_call(&[]).expect("test JIT call") };
        assert_eq!(result, 42, "Should return 42");
    }

    #[test]
    fn test_lower_add_constants() {
        // int f() { return 3 + 4; }  → constant-folded to return 7
        let code = [0x06, 0x07, 0x60, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 4, 0, 0);
        assert!(compiled.is_some());
        let method = compiled.unwrap();
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let result = unsafe { method.try_call(&[]).expect("test JIT call") };
        assert_eq!(result, 7, "Should return 7 after constant folding");
    }

    /// Build `f(a, b) = <sop>(a, b)` (or `f(a) = <sop>(a)`) as a graph, lower
    /// it, and return the compiled body. Direct graph construction rather than
    /// bytecode, because reaching `Op::ScalarIntrinsic` from bytecode needs the
    /// invoke planner and a constant pool -- machinery that is tested where it
    /// lives (`ir::try_ir_scalar_intrinsic`), and that would make this a test
    /// of the planner rather than of the emitted instructions.
    fn compile_scalar_intrinsic(sop: ScalarOp) -> CompiledMethod {
        let n = sop.arity();
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let a = graph.add(Op::Param(0), sop.input_ty(0), vec![start], None);
        let mut inputs = vec![a];
        if n == 2 {
            // `input_ty(1)`, not `input_ty(0)`: a rotate takes a `long` value
            // and an `int` distance, and typing the distance as a `long` here
            // would make this harness disagree with the builder.
            let b = graph.add(Op::Param(1), sop.input_ty(1), vec![start], None);
            inputs.push(b);
        }
        let v = graph.add(Op::ScalarIntrinsic(sop), sop.result_type(), inputs, Some(0));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, v], Some(1));
        let schedule = ir_schedule::schedule(&graph);
        lower(&graph, &schedule, n, n, &no_helpers()).expect("the intrinsic body must lower")
    }

    /// The class id every unbox-accessor test object carries, and the constant
    /// the emitted guard compares against. Any value but `0` will do; `0` is
    /// what the recognizer and the layout resolvers treat as "unresolved".
    #[cfg(test)]
    const UNBOX_TEST_CLASS_ID: u32 = 0x00C0_FFEE;

    /// Build `f(recv[, delta]) = <op>(recv[, delta])` as a graph and lower it.
    ///
    /// Direct graph construction rather than bytecode, for the reason
    /// `compile_scalar_intrinsic` gives: reaching `Op::Unbox` from bytecode
    /// needs the invoke planner, a constant pool AND a resolved receiver class
    /// id, and that machinery is tested where it lives. This is a test of the
    /// emitted instructions.
    ///
    /// `unbox_offsets` derives the two offsets from the class id, so the test
    /// object below must be laid out to match whatever it answers -- which is
    /// why the caller reads them back rather than choosing them.
    #[cfg(test)]
    fn compile_unbox(op: crate::ir::UnboxOp) -> Option<(CompiledMethod, i32, i32)> {
        let (compact_off, legacy_off) = crate::ir::unbox_offsets(op, UNBOX_TEST_CLASS_ID)?;
        let n = 1 + op.arity();
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let recv = graph.add(Op::Param(0), IrType::Ref, vec![start], None);
        let mut inputs = vec![ctrl, mem, recv];
        if op.arity() == 1 {
            // The delta is a `long` for the one family that takes one.
            inputs.push(graph.add(Op::Param(1), IrType::Long, vec![start], None));
        }
        let v = graph.add(
            Op::Unbox {
                op,
                class_id: UNBOX_TEST_CLASS_ID,
            },
            op.result_type(),
            inputs,
            Some(0),
        );
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, v], Some(1));
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, n, n, &no_helpers()).expect("the accessor body lowers");
        Some((cm, compact_off, legacy_off))
    }

    /// A 64-byte buffer shaped like an object header, with the class id at
    /// offset 0 and the COMPACT flag set or clear as asked.
    #[cfg(test)]
    fn unbox_test_object(compact: bool) -> Box<[u64; 8]> {
        let mut obj = Box::new([0u64; 8]);
        // SAFETY: `obj` is 64 bytes and 8-byte aligned; the class id is a `u32`
        // at offset 0 and the flags byte is inside the first word, so both
        // writes land well inside it.
        unsafe {
            let p = obj.as_mut_ptr() as *mut u8; // Cast: array base -> byte cursor
            std::ptr::write_unaligned(p as *mut u32, UNBOX_TEST_CLASS_ID); // Cast: header field
            *p.add(cratonvm_types::GC_FLAGS_BYTE_OFFSET) = if compact {
                cratonvm_types::GC_FLAG_COMPACT
            } else {
                0
            };
        }
        obj
    }

    /// The six emitted sequences, EXECUTED against a synthetic receiver, in
    /// BOTH object layouts.
    ///
    /// # Why both layouts, every time
    ///
    /// The compact/legacy branch is per-OBJECT, not per-class, and a
    /// compact-only arm is an arm that almost never fires: `init_object_header`
    /// -- the TLAB fast path serving nearly every allocation -- writes a LEGACY
    /// header unconditionally, whatever layout the class has registered. That
    /// is not hypothetical; `the_gated_arm_emits_both_store_shapes` in this file
    /// records it measured at `inline=0` over 16,384,000 executions when only
    /// the compact shape was emitted.
    ///
    /// When the resolver hands back the SAME offset for both layouts (which it
    /// does when no `CompactLayout` is registered for the forged class id, the
    /// usual case in a unit-test process), the two arms address one word and the
    /// per-layout half of this test is vacuous. It is written to be correct
    /// either way and asserts the arithmetic regardless; the two-arm SELECTION
    /// is pinned by `only_the_read_modify_write_families_carry_a_lock_prefix`,
    /// which counts one access encoding per arm in the emitted image.
    #[test]
    fn the_unbox_sequences_execute_against_both_object_layouts() {
        use crate::ir::UnboxOp as U;
        // (family, starting field value, delta, expected result, expected field)
        let cases: &[(U, i64, i64, i64, i64)] = &[
            // The three loads leave the field alone.
            (
                U::LongValue,
                0x1234_5678_9ABC_DEF0u64 as i64,
                0,
                0x1234_5678_9ABC_DEF0u64 as i64,
                0x1234_5678_9ABC_DEF0u64 as i64,
            ),
            (U::LongValue, -1, 0, -1, -1),
            (U::AtomicLongGet, i64::MIN, 0, i64::MIN, i64::MIN),
            (U::AtomicLongGet, 42, 0, 42, 42),
            // `Integer.intValue` is 32-bit. The IR tier's `Int` convention
            // ZERO-extends the upper half, so a negative field reads back as
            // its unsigned 32-bit image in the full slot -- checked below by
            // comparing the low half, which is the half every consumer reads.
            (U::IntValue, -7, 0, -7, -7),
            (U::IntValue, 0x7FFF_FFFF, 0, 0x7FFF_FFFF, 0x7FFF_FFFF),
            (U::IntValue, 7, 0, 7, 7),
            // The three `LOCK XADD` forms. `*AndGet` returns the POST-add
            // value, `getAndAdd` the PRE-add one -- the single place the two
            // differ, and what a fixup emitted for the wrong family breaks.
            (U::AtomicIntIncrementAndGet, 5, 0, 6, 6),
            (U::AtomicIntIncrementAndGet, -1, 0, 0, 0),
            (U::AtomicIntDecrementAndGet, 5, 0, 4, 4),
            (U::AtomicIntDecrementAndGet, 0, 0, -1, -1),
            (
                U::AtomicIntIncrementAndGet,
                i32::MAX as i64,
                0,
                i32::MIN as i64,
                i32::MIN as i64,
            ),
            (U::AtomicLongGetAndAdd, 100, 5, 100, 105),
            (U::AtomicLongGetAndAdd, 100, -5, 100, 95),
            (U::AtomicLongGetAndAdd, 0, 1i64 << 40, 0, 1i64 << 40),
        ];

        for &(op, start, delta, want, want_field) in cases {
            for compact in [true, false] {
                let Some((cm, compact_off, legacy_off)) = compile_unbox(op) else {
                    // No layout for the forged class id: nothing to execute.
                    continue;
                };
                let off = if compact { compact_off } else { legacy_off };
                assert!(
                    off >= 0 && (off as usize) + 8 <= 64,
                    "the resolved offset {off} must leave 8 bytes inside the 64-byte \
                     test object -- the payload plus, for a narrow family, the \
                     poison word above it",
                );
                let mut obj = unbox_test_object(compact);
                // Addressed by BYTE offset, not by word index: a LEGACY
                // int-category payload sits at `cell + FIELD_CELL_PAYLOAD32_
                // OFFSET`, which is not 8-byte aligned, and a first cut of this
                // test that divided by 8 read the wrong half and got its own
                // poison back.
                //
                // The 4 bytes ABOVE a narrow field are poisoned, so a 64-bit
                // load emitted where a 32-bit one belongs returns the poison
                // rather than a plausible answer.
                const POISON: u32 = 0x0BAD_0BAD;
                let base = obj.as_mut_ptr() as *mut u8; // Cast: array base -> byte cursor
                                                        // SAFETY: `off` was asserted to leave 8 bytes inside the
                                                        // 64-byte object, and the writes are unaligned-safe.
                unsafe {
                    let at = base.add(off as usize); // Cast: resolved field offset
                    if op.is_wide() {
                        std::ptr::write_unaligned(at as *mut i64, start);
                    } else {
                        std::ptr::write_unaligned(at as *mut u32, start as u32);
                        std::ptr::write_unaligned(at.add(4) as *mut u32, POISON);
                    }
                }
                let addr = obj.as_mut_ptr() as i64; // Cast: receiver address

                let args: &[i64] = if op.arity() == 1 {
                    &[addr, delta]
                } else {
                    &[addr]
                };
                // SAFETY: the body takes the receiver (and for one family a
                // delta), builds and tears down its own frame, and calls
                // nothing. `obj` is a live 64-byte buffer whose header the
                // emitted guards accept, so no deopt edge is taken.
                let got = unsafe { cm.try_call(args) }.expect("the body runs");

                let layout = if compact { "compact" } else { "legacy" };
                let got = if op.is_wide() { got } else { got as i32 as i64 };
                assert_eq!(
                    got,
                    want,
                    "{} on a {layout} receiver (field={start:#x}, delta={delta})",
                    op.as_str(),
                );
                // SAFETY: same range, same reasoning as the writes above.
                let field = unsafe {
                    let at = base.add(off as usize); // Cast: resolved field offset
                    if op.is_wide() {
                        std::ptr::read_unaligned(at as *const i64)
                    } else {
                        assert_eq!(
                            std::ptr::read_unaligned(at.add(4) as *const u32),
                            POISON,
                            "{} wrote past the 4 bytes a 32-bit field owns",
                            op.as_str(),
                        );
                        i64::from(std::ptr::read_unaligned(at as *const u32) as i32)
                    }
                };
                assert_eq!(
                    field,
                    want_field,
                    "{} left the wrong value in the {layout} field",
                    op.as_str(),
                );
            }
        }
    }

    /// The `LOCK` prefix is on the three read-modify-write families and on
    /// neither of the others, and each access is emitted in BOTH layout arms.
    ///
    /// Executing them proves the ARITHMETIC and cannot prove this: an unlocked
    /// `XADD` computes the identical answer on one thread, and the difference
    /// only appears as a lost update under contention -- the failure a
    /// single-threaded test is structurally unable to see. So the byte is
    /// checked in the emitted image.
    ///
    /// The converse half matters too: a `LOCK` on the loads would be a needless
    /// full barrier on the hottest of the six (`AtomicLong.get`), and the reason
    /// it is not owed -- x86-64 does not reorder loads with older loads, so an
    /// aligned `MOV` already IS the volatile read -- is the kind of claim that
    /// rots silently.
    #[test]
    fn only_the_read_modify_write_families_carry_a_lock_prefix() {
        use crate::ir::UnboxOp as U;
        for op in [
            U::LongValue,
            U::IntValue,
            U::AtomicLongGet,
            U::AtomicIntIncrementAndGet,
            U::AtomicIntDecrementAndGet,
            U::AtomicLongGetAndAdd,
        ] {
            let Some((cm, _, _)) = compile_unbox(op) else {
                continue;
            };
            // SAFETY: the artifact owns an executable mapping of `code_len`
            // bytes at `entry_ptr`; this only reads it.
            let code =
                unsafe { std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len()) };
            // The WHOLE `LOCK XADD` opcode -- with the `REX.W` in the middle at
            // 64 bits -- rather than a bare `0xF0`, which also occurs inside
            // displacements and immediates.
            let want: &[u8] = if op.is_wide() {
                &[0xF0, 0x48, 0x0F, 0xC1]
            } else {
                &[0xF0, 0x0F, 0xC1]
            };
            let locked = code.windows(want.len()).filter(|w| *w == want).count();
            assert_eq!(
                locked,
                if op.is_load() { 0 } else { 2 },
                "{} must emit {} LOCK XADD (one per layout arm)",
                op.as_str(),
                if op.is_load() { 0 } else { 2 },
            );
        }
    }

    /// Both guards and the per-object layout branch are emitted, for every
    /// family.
    ///
    /// The class-id compare cannot be checked by executing a well-formed
    /// receiver: with it missing every assertion above still passes, and what
    /// breaks instead is a receiver of another class reading this one's slot 0.
    #[test]
    fn every_unbox_family_emits_its_guards_and_the_layout_branch() {
        use crate::ir::UnboxOp as U;
        for op in [
            U::LongValue,
            U::IntValue,
            U::AtomicLongGet,
            U::AtomicIntIncrementAndGet,
            U::AtomicIntDecrementAndGet,
            U::AtomicLongGetAndAdd,
        ] {
            let Some((cm, _, _)) = compile_unbox(op) else {
                continue;
            };
            // SAFETY: as above.
            let code =
                unsafe { std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len()) };
            assert!(
                code.windows(3).any(|w| w == [0x48, 0x85, 0xC0]),
                "{} must null-check its receiver (TEST RAX, RAX)",
                op.as_str(),
            );
            let mut cid = vec![0x81, 0x78, 0x00];
            cid.extend_from_slice(&UNBOX_TEST_CLASS_ID.to_le_bytes());
            assert!(
                code.windows(cid.len()).any(|w| w == cid.as_slice()),
                "{} must compare the receiver's header class id against the \
                 constant the planner resolved",
                op.as_str(),
            );
            let mut flags = vec![0xF6, 0x80];
            flags.extend_from_slice(&(cratonvm_types::GC_FLAGS_BYTE_OFFSET as i32).to_le_bytes());
            flags.push(cratonvm_types::GC_FLAG_COMPACT);
            assert!(
                code.windows(flags.len()).any(|w| w == flags.as_slice()),
                "{} must branch on the receiver's own COMPACT flag",
                op.as_str(),
            );
        }
    }

    /// The emitted sequences, EXECUTED, against the answers the JLS specifies.
    ///
    /// The edges are the point. `Math.abs(Integer.MIN_VALUE)` is
    /// `Integer.MIN_VALUE` (JLS 15.15.4) because the negation wraps, and the
    /// branchless `(x ^ (x>>31)) - (x>>31)` reproduces that exactly -- a reader
    /// who "fixes" it to saturate would be introducing a bug, not removing one.
    /// `Math.min`/`max` are SIGNED, so a pair straddling zero separates them
    /// from an unsigned compare, which is the mistake a `CMOVA`/`CMOVB` typo
    /// would make and which no same-sign test could catch.
    #[test]
    fn the_scalar_intrinsic_sequences_execute_to_the_specified_answers() {
        let cases_i: &[(ScalarOp, i64, i64, i64)] = &[
            (ScalarOp::MinI, 3, 7, 3),
            (ScalarOp::MinI, 7, 3, 3),
            (ScalarOp::MinI, -5, 5, -5),
            (ScalarOp::MinI, 5, -5, -5),
            (
                ScalarOp::MinI,
                i32::MIN as i64,
                i32::MAX as i64,
                i32::MIN as i64,
            ),
            (ScalarOp::MaxI, 3, 7, 7),
            (ScalarOp::MaxI, 7, 3, 7),
            (ScalarOp::MaxI, -5, 5, 5),
            (ScalarOp::MaxI, 5, -5, 5),
            (
                ScalarOp::MaxI,
                i32::MIN as i64,
                i32::MAX as i64,
                i32::MAX as i64,
            ),
            (ScalarOp::CompareI, 3, 7, -1),
            (ScalarOp::CompareI, 7, 3, 1),
            (ScalarOp::CompareI, 7, 7, 0),
            // The pair that separates a SIGNED compare from an unsigned one:
            // as unsigned 32-bit values, -1 is the largest there is.
            (ScalarOp::CompareI, -1, 1, -1),
            (ScalarOp::CompareI, i32::MIN as i64, i32::MAX as i64, -1),
        ];
        for &(sop, a, b, want) in cases_i {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: the body takes two integer arguments, builds and tears
            // down its own frame, and calls nothing.
            let got = unsafe { cm.try_call(&[a, b]) }.expect("the body runs");
            // The `Int` slot convention zero-extends, so compare the low half.
            assert_eq!(got as i32, want as i32, "{}({a}, {b})", sop.as_str(),);
        }

        let cases_l: &[(ScalarOp, i64, i64, i64)] = &[
            (ScalarOp::MinL, 3, 7, 3),
            (ScalarOp::MinL, -5, 5, -5),
            (ScalarOp::MinL, i64::MIN, i64::MAX, i64::MIN),
            (ScalarOp::MaxL, 3, 7, 7),
            (ScalarOp::MaxL, 5, -5, 5),
            (ScalarOp::MaxL, i64::MIN, i64::MAX, i64::MAX),
        ];
        for &(sop, a, b, want) in cases_l {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[a, b]) }.expect("the body runs");
            assert_eq!(got, want, "{}({a}, {b})", sop.as_str());
        }

        // `Long.compare` returns an INT from LONG operands -- the case that
        // catches sizing the CMP from the result type, which would compare the
        // low halves and answer 0 for these.
        for &(a, b, want) in &[
            (1i64 << 40, 1i64, 1i64),
            (1i64, 1i64 << 40, -1),
            (i64::MIN, i64::MAX, -1),
            (0x1_0000_0000i64, 0i64, 1),
        ] {
            let cm = compile_scalar_intrinsic(ScalarOp::CompareL);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[a, b]) }.expect("the body runs");
            assert_eq!(got as i32, want as i32, "Long.compare({a}, {b})");
        }

        for &(sop, x, want) in &[
            (ScalarOp::AbsI, 5i64, 5i64),
            (ScalarOp::AbsI, -5, 5),
            (ScalarOp::AbsI, 0, 0),
            // JLS 15.15.4: abs(MIN_VALUE) == MIN_VALUE.
            (ScalarOp::AbsI, i32::MIN as i64, i32::MIN as i64),
            (ScalarOp::AbsI, i32::MAX as i64, i32::MAX as i64),
        ] {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: one integer argument; as above.
            let got = unsafe { cm.try_call(&[x, 0]) }.expect("the body runs");
            assert_eq!(got as i32, want as i32, "Math.abs({x})");
        }

        for &(x, want) in &[
            (5i64, 5i64),
            (-5, 5),
            (0, 0),
            (i64::MIN, i64::MIN),
            (i64::MAX, i64::MAX),
        ] {
            let cm = compile_scalar_intrinsic(ScalarOp::AbsL);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[x, 0]) }.expect("the body runs");
            assert_eq!(got, want, "Math.abs({x}L)");
        }
    }

    /// The bit-scan sequences, EXECUTED, against the answers `java.lang.Integer`
    /// and `java.lang.Long` specify.
    ///
    /// ZERO is the case every one of these has and the one a reader is most
    /// likely to break: `BSR`/`BSF` leave their destination UNDEFINED on a zero
    /// source, so a sequence that reads the destination without first
    /// consulting ZF returns whatever the register happened to hold. Each
    /// family is therefore tested at zero, and `highestOneBit` — whose shift
    /// runs on that undefined count and is masked away afterwards — is tested
    /// at zero on both widths.
    ///
    /// The other trap is width. `Long.numberOfLeadingZeros` takes a `long` and
    /// returns an `int`, so a sequence that sized its scan from the RESULT type
    /// would scan the low half and answer 32 for every value above 2^32; the
    /// `1 << 40` cases catch exactly that.
    #[test]
    fn the_bit_scan_sequences_execute_to_the_specified_answers() {
        // (op, input, expected) — 32-bit families, compared on the low half.
        let unary_i: &[(ScalarOp, i64, i64)] = &[
            (ScalarOp::NlzI, 0, 32),
            (ScalarOp::NlzI, 1, 31),
            (ScalarOp::NlzI, -1, 0),
            (ScalarOp::NlzI, i32::MIN as i64, 0),
            (ScalarOp::NlzI, 0x0000_FFFF, 16),
            (ScalarOp::NtzI, 0, 32),
            (ScalarOp::NtzI, 1, 0),
            (ScalarOp::NtzI, -1, 0),
            (ScalarOp::NtzI, i32::MIN as i64, 31),
            (ScalarOp::NtzI, 0x0001_0000, 16),
            (ScalarOp::ReverseBytesI, 0x0102_0304, 0x0403_0201),
            (ScalarOp::ReverseBytesI, 0, 0),
            (ScalarOp::LowestOneBitI, 0, 0),
            (ScalarOp::LowestOneBitI, 0x0000_00FF, 1),
            (ScalarOp::LowestOneBitI, i32::MIN as i64, i32::MIN as i64),
            (ScalarOp::HighestOneBitI, 0, 0),
            (ScalarOp::HighestOneBitI, 0x0000_00FF, 0x80),
            (ScalarOp::HighestOneBitI, -1, i32::MIN as i64),
            (ScalarOp::HighestOneBitI, 1, 1),
        ];
        for &(sop, x, want) in unary_i {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: one integer argument; the body builds and tears down its
            // own frame and calls nothing.
            let got = unsafe { cm.try_call(&[x, 0]) }.expect("the body runs");
            assert_eq!(got as i32, want as i32, "{}({x})", sop.as_str());
        }

        // 64-bit input families whose ANSWER is an `int`.
        let unary_l_to_i: &[(ScalarOp, i64, i64)] = &[
            (ScalarOp::NlzL, 0, 64),
            (ScalarOp::NlzL, 1, 63),
            (ScalarOp::NlzL, -1, 0),
            (ScalarOp::NlzL, i64::MIN, 0),
            // The case that separates a 64-bit scan from a 32-bit one.
            (ScalarOp::NlzL, 1i64 << 40, 23),
            (ScalarOp::NtzL, 0, 64),
            (ScalarOp::NtzL, 1, 0),
            (ScalarOp::NtzL, i64::MIN, 63),
            (ScalarOp::NtzL, 1i64 << 40, 40),
        ];
        for &(sop, x, want) in unary_l_to_i {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[x, 0]) }.expect("the body runs");
            assert_eq!(got as i32, want as i32, "{}({x})", sop.as_str());
        }

        // 64-bit input AND answer.
        let unary_l: &[(ScalarOp, i64, i64)] = &[
            (
                ScalarOp::ReverseBytesL,
                0x0102_0304_0506_0708,
                0x0807_0605_0403_0201,
            ),
            (ScalarOp::ReverseBytesL, 0, 0),
            (ScalarOp::LowestOneBitL, 0, 0),
            (ScalarOp::LowestOneBitL, 0x00FF_0000_0000_0000, 1i64 << 48),
            (ScalarOp::LowestOneBitL, i64::MIN, i64::MIN),
            (ScalarOp::HighestOneBitL, 0, 0),
            (ScalarOp::HighestOneBitL, 0x0000_00FF, 0x80),
            (ScalarOp::HighestOneBitL, -1, i64::MIN),
            (ScalarOp::HighestOneBitL, 1i64 << 40, 1i64 << 40),
        ];
        for &(sop, x, want) in unary_l {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[x, 0]) }.expect("the body runs");
            assert_eq!(got, want, "{}({x})", sop.as_str());
        }

        // Rotates. A NEGATIVE distance is the case the JLS defines by masking
        // and x86 implements by masking, so it is the one that proves the two
        // agree rather than merely both being plausible.
        let rot_i: &[(ScalarOp, i64, i64, i64)] = &[
            (ScalarOp::RotateLeftI, 1, 1, 2),
            (ScalarOp::RotateLeftI, i32::MIN as i64, 1, 1),
            (ScalarOp::RotateLeftI, 1, 32, 1),
            (ScalarOp::RotateLeftI, 1, -1, i32::MIN as i64),
            (ScalarOp::RotateRightI, 1, 1, i32::MIN as i64),
            (ScalarOp::RotateRightI, 1, -1, 2),
            (
                ScalarOp::RotateRightI,
                0x0000_00FF,
                4,
                0xF000_000F_u32 as i32 as i64,
            ),
        ];
        for &(sop, x, d, want) in rot_i {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: two integer arguments; as above.
            let got = unsafe { cm.try_call(&[x, d]) }.expect("the body runs");
            assert_eq!(got as i32, want as i32, "{}({x}, {d})", sop.as_str());
        }

        let rot_l: &[(ScalarOp, i64, i64, i64)] = &[
            (ScalarOp::RotateLeftL, 1, 1, 2),
            (ScalarOp::RotateLeftL, i64::MIN, 1, 1),
            (ScalarOp::RotateLeftL, 1, 64, 1),
            (ScalarOp::RotateLeftL, 1, -1, i64::MIN),
            (ScalarOp::RotateRightL, 1, 1, i64::MIN),
            (ScalarOp::RotateRightL, 1, -1, 2),
            // Distances 32 and 40 separate a 64-bit rotate from a 32-bit one.
            (ScalarOp::RotateLeftL, 1, 40, 1i64 << 40),
            (ScalarOp::RotateLeftL, 1, 32, 1i64 << 32),
        ];
        for &(sop, x, d, want) in rot_l {
            let cm = compile_scalar_intrinsic(sop);
            // SAFETY: as above.
            let got = unsafe { cm.try_call(&[x, d]) }.expect("the body runs");
            assert_eq!(got, want, "{}({x}, {d})", sop.as_str());
        }
    }

    #[test]
    fn test_lower_add_params() {
        // int f(int a, int b) { return a + b; }
        let code = [0x1a, 0x1b, 0x60, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 4, 2, 2);
        assert!(compiled.is_some());
        let method = compiled.unwrap();
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let result = unsafe { method.try_call(&[10, 20]).expect("test JIT call") };
        assert_eq!(result, 30, "10 + 20 = 30");
    }

    #[test]
    fn test_lower_sub_params() {
        // int f(int a, int b) { return a - b; }
        let code = [0x1a, 0x1b, 0x64, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 4, 2, 2);
        assert!(compiled.is_some());
        let method = compiled.unwrap();
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let result = unsafe { method.try_call(&[30, 12]).expect("test JIT call") };
        assert_eq!(result, 18, "30 - 12 = 18");
    }

    #[test]
    fn test_lower_mul_params() {
        // int f(int a, int b) { return a * b; }
        let code = [0x1a, 0x1b, 0x68, 0xac, 0, 0];
        let compiled = compile_via_ir(&code, 4, 2, 2);
        assert!(compiled.is_some());
        let method = compiled.unwrap();
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let result = unsafe { method.try_call(&[6, 7]).expect("test JIT call") };
        assert_eq!(result, 42, "6 * 7 = 42");
    }

    // ── Regression: BUG FIX [jit-irlower #1 + #3] — Op::Cmp SETcc ────────
    //
    // Hand-build a single-block graph whose Return value is a bare
    // `Op::Cmp(Lt)`, so the SETcc store is the only thing producing the
    // result. Two bugs had to be fixed: #1 the opcode (`+ 0x10` → `0F 9C` =
    // SETL, not the old `- 0x10` MMX byte), and #3 the MISSING ModRM byte —
    // SETcc is a /digit form, so `0F 9C` without `0xC0` desynced the stream
    // (the next `0F B6` MOVZX was partly consumed as the ModRM) and AL/RAX
    // were never written, so the Cmp returned the first operand (`a`) instead
    // of the 0/1 boolean. With `0F 9C C0` the boolean is correct.
    #[test]
    fn test_lower_cmp_lt_setcc() {
        use crate::ir::{CmpOp, Graph, IrType, Op};

        // Mirror IrBuilder::new node layout: Start, Proj(0)=ctrl, Proj(1)=mem,
        // Param(0), Param(1).
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let b = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        // cmp = (a < b) ? 1 : 0
        let cmp = graph.add(Op::Cmp(CmpOp::Lt), IrType::Int, vec![a, b], None);
        // Return [ctrl, cmp]
        let ret = graph.add(Op::Return, IrType::Void, vec![ctrl, cmp], None);
        graph.exit = ret;

        let schedule = ir_schedule::schedule(&graph);
        let method = lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lower cmp graph");

        // a < b  → 1
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_true = unsafe { method.try_call(&[3, 7]).expect("test JIT call") };
        assert_eq!(r_true, 1, "3 < 7 should set the boolean to 1");
        // a >= b → 0
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_false = unsafe { method.try_call(&[7, 3]).expect("test JIT call") };
        assert_eq!(r_false, 0, "7 < 3 is false → 0");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_eq = unsafe { method.try_call(&[5, 5]).expect("test JIT call") };
        assert_eq!(r_eq, 0, "5 < 5 is false → 0");
    }

    // ── Regression: BUG FIX [jit-irlower #1 + #2] — ternary via IR path ──
    //
    // int f(int a, int b) { return a < b ? 1 : 0; }
    //
    // javac lowers the ternary to a compare-and-branch joined by a phi:
    //   iload_0; iload_1; if_icmpge else; iconst_1; goto end;
    //   else: iconst_0; end: ireturn
    // This exercises the fixes end-to-end: the `Op::Cmp(Ge)` feeding the `If`
    // (#1 + #3 SETcc) and the edge-split parallel copy that materialises the
    // phi value 1/0 at each branch edge (#2). The earlier "always resolves to
    // the else value" symptom was a downstream effect of the SETcc desync (#3):
    // the `If` branched on the first operand instead of the comparison, so it
    // always took the same edge. With the SETcc ModRM fix the phi/branch path
    // is correct.
    #[test]
    fn test_lower_ternary_lt_phi() {
        // PCs:
        //  0: iload_0      1a
        //  1: iload_1      1b
        //  2: if_icmpge 9  a2 00 07   (offset 7 from pc 2 → pc 9)
        //  5: iconst_1     04
        //  6: goto 10      a7 00 04   (offset 4 from pc 6 → pc 10)
        //  9: iconst_0     03
        // 10: ireturn      ac
        let code = [
            0x1a, 0x1b, 0xa2, 0x00, 0x07, 0x04, 0xa7, 0x00, 0x04, 0x03, 0xac, 0, 0,
        ];
        let compiled = compile_via_ir(&code, 11, 2, 2);
        assert!(compiled.is_some(), "ternary should compile via IR path");
        let method = compiled.unwrap();

        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_true = unsafe { method.try_call(&[3, 7]).expect("test JIT call") };
        assert_eq!(r_true, 1, "3 < 7 → 1");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_false = unsafe { method.try_call(&[7, 3]).expect("test JIT call") };
        assert_eq!(r_false, 0, "7 < 3 → 0");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let r_eq = unsafe { method.try_call(&[5, 5]).expect("test JIT call") };
        assert_eq!(r_eq, 0, "5 == 5, not < → 0");
    }

    // ── Regression: the canonical production SIGSEGV shape — a pure,
    // call-free branchy predicate (e.g. `Modifier.isStatic`). Before the
    // SETcc ModRM fix (#3) this exact shape emitted a stray `SETcc [rdi]`
    // (write through a near-null base) → SIGSEGV, which is why
    // `jit/src/lib.rs` declined branchy call-free methods from the IR path.
    #[test]
    fn test_lower_and_predicate_isstatic_shape() {
        // static boolean f(int m) { return (m & 8) != 0; }
        //  0: iload_0     1a
        //  1: bipush 8    10 08
        //  3: iand        7e
        //  4: ifeq 11     99 00 07   (m&8 == 0 → pc 11)
        //  7: iconst_1    04
        //  8: goto 12     a7 00 04
        // 11: iconst_0    03
        // 12: ireturn     ac
        let code = [
            0x1a, 0x10, 0x08, 0x7e, 0x99, 0x00, 0x07, 0x04, 0xa7, 0x00, 0x04, 0x03, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 13, 1, 1).expect("branchy predicate compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |m: i64| unsafe { cm.try_call(&[m]).expect("call") };
        assert_eq!(f(8), 1, "8 & 8 != 0 → true");
        assert_eq!(f(0), 0, "0 & 8 == 0 → false");
        assert_eq!(f(7), 0, "7 & 8 == 0 → false");
        assert_eq!(f(15), 1, "15 & 8 != 0 → true");
    }

    // ── Regression: a phi that merges non-constant operand values (param a
    // vs param b) across the two branch edges, not just 0/1 constants —
    // exercises the edge-split parallel copy with live values.
    #[test]
    fn test_lower_max_phi_merges_params() {
        // int max(int a, int b) { return a >= b ? a : b; }
        //  0: iload_0     1a
        //  1: iload_1     1b
        //  2: if_icmplt 9 a1 00 07   (a < b → pc 9, return b)
        //  5: iload_0     1a
        //  6: goto 10     a7 00 04
        //  9: iload_1     1b
        // 10: ireturn     ac
        let code = [
            0x1a, 0x1b, 0xa1, 0x00, 0x07, 0x1a, 0xa7, 0x00, 0x04, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 11, 2, 2).expect("max compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let max = |a: i64, b: i64| unsafe { cm.try_call(&[a, b]).expect("call") };
        assert_eq!(max(3, 7), 7, "max(3,7)=7");
        assert_eq!(max(7, 3), 7, "max(7,3)=7");
        assert_eq!(max(5, 5), 5, "max(5,5)=5");
        assert_eq!(max(-2, -9), -2, "max(-2,-9)=-2");
    }

    // ── Gate-flip readiness probe: a COUNTED LOOP (loop-carried phi over a
    // back-edge). If this fails, the IR builder/lowerer does not yet handle
    // loop phis, and branchy call-free methods (which include loops) must NOT
    // be routed to the IR path — i.e. the lib.rs gate cannot be flipped on the
    // SETcc fix alone.
    #[test]
    fn test_lower_counted_loop_sum() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 19
        //  9: iload_1  10: iload_2  11: iadd  12: istore_1
        // 13: iinc 2,1 16: goto 4   19: iload_1 20: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sum = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(sum(5), 10, "0+1+2+3+4 = 10");
        assert_eq!(sum(0), 0, "empty loop = 0");
        assert_eq!(sum(10), 45, "sum 0..9 = 45");
    }

    /// A partially unrolled loop offers **one** OSR entry at its header bci,
    /// and entering through it finishes the loop the interpreter started.
    ///
    /// # The defect
    ///
    /// `emit_osr_entry_stubs` plans one entry per BLOCK and
    /// `ir_osr_entry_addr` resolves one per BCI with `.find()`, so a bci two
    /// blocks claim silently resolves to whichever came first in block order.
    /// Nothing could claim a bci twice until a transform cloned a CONTROL node.
    /// The partial unroller gives every copy its own `If`/`Proj` triple at the
    /// loop test's own bci — it has to, because the pc is also the site key —
    /// so a factor-4 unroll offers four blocks at the header bci and three of
    /// them are mid-group.
    ///
    /// Entering mid-group re-runs the copies after it, which the interpreter
    /// has already run. Measured on `C2PartialUnrollProbe` before the fix: the
    /// probe returned `sum(trip + factor - 1)` on roughly 40% of runs — the
    /// wrong answer and a 3x slowdown arriving together, and both vanishing
    /// under `CRATONVM_JIT_IR_OSR_ENTRY=0`.
    ///
    /// # Why this test is an entry and not a count
    ///
    /// The count alone (`one entry at bci 4`) is what a wrong version can also
    /// have: keeping the first plan rather than the header's gives exactly one
    /// entry too, and it is the mid-group one. So this ENTERS, from a state the
    /// method could not have reached on its own — `i` already at 3 with `s`
    /// holding a value no prefix of this loop produces — and asks for the
    /// answer the interpreter would have finished with. A mid-group door
    /// returns a larger sum, because it runs the copies below it before
    /// reaching the test that should have stopped it.
    #[test]
    fn a_partially_unrolled_loop_has_one_osr_door_and_it_is_the_header() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_PER_COPY_FRAMES", Some("1")),
                ("CRATONVM_JIT_IR_PARTIAL_UNROLL", Some("1")),
                ("CRATONVM_JIT_IR_PARTIAL_UNROLL_FACTOR", Some("4")),
            ],
            || compile_via_ir(&code, 21, 1, 3).expect("the partially unrolled loop compiles"),
        );

        // Cast: the low 32 bits of RAX are this method's `int` result.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sum = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32;
        for n in 0..24i64 {
            let want: i32 = (0..n as i32).sum();
            assert_eq!(sum(n), want, "the ordinary door got sum({n}) wrong");
        }

        let at_header = cm
            .ir_osr_entries
            .iter()
            .filter(|(bci, _, _)| *bci == 4)
            .count();
        assert!(
            at_header <= 1,
            "bci 4 is claimed by {at_header} OSR entries; `ir_osr_entry_addr` \
             resolves one by `.find()`, so the others are unreachable and the \
             one that wins is whichever block order put first",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // Refusing the bci outright is the other correct answer, and the
            // one the filter falls back to when the header cannot be singled
            // out. Nothing else may hold a door.
            assert!(
                cm.ir_osr_entries.is_empty(),
                "the header bci was refused but some other bci kept a door",
            );
            return;
        };

        // Enter as the interpreter would, mid-loop, in a state no prefix of
        // this loop produces: `s = 1000` with `i = 3`. Finishing correctly
        // means adding 3..n-1 and nothing else.
        for n in [4i64, 7, 12, 24] {
            let want: i32 = 1000 + (3..n as i32).sum::<i32>();
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            let got = unsafe { cm.ir_osr_enter(4, 0, &[n, 1000, 3]) }
                .expect("the header door accepts three locals");
            assert_eq!(
                got as i32, want,
                "entered at the header with (s=1000, i=3, n={n}) — a mid-group \
                 door re-runs the copies below it and reads larger",
            );
        }
    }

    /// **The one that matters: enter the loop part-way and finish it.**
    ///
    /// `int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }`, whose
    /// loop header is bci 4. The stub is called the way an OSR trigger would
    /// call it — with an interpreter locals array, not with the method's
    /// arguments — carrying a state the method could never have reached from
    /// its own entry: `n=10, s=100, i=7`. A correct entry finishes the loop
    /// from there and returns `100 + 7 + 8 + 9 = 124`.
    ///
    /// Nothing else proves this. The frame build, the callee-saved saves, the
    /// clean-frame zeroing, the ORDER of that zeroing against the seeding
    /// (`zero_ref_phi_slots` would erase a seeded reference), the parked
    /// locals pointer surviving `emit_frame_record`'s call, the seeding
    /// itself and the jump are six independent chances to be wrong, and every
    /// one of them fails by returning a plausible number.
    #[test]
    fn an_osr_entry_finishes_a_loop_it_did_not_start() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 19
        //  9: iload_1  10: iload_2  11: iadd  12: istore_1
        // 13: iinc 2,1 16: goto 4   19: iload_1 20: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        // The ordinary entry still works, unchanged.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // Not every configuration admits the header (the refusal census
            // says which clause declined). Assert the shape that IS guaranteed:
            // a refusal is silent and total, never a half-emitted stub.
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // The interpreter's locals at bci 4: local 0 = n, 1 = s, 2 = i.
        let locals: [i64; 3] = [10, 100, 7];
        // Through the artifact's own entry point, which is what the VM calls:
        // it re-checks the bci and refuses a locals slice shorter than the stub
        // reads, so the test exercises the admission as well as the code.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&locals),
            Some(124),
            "entering at the header with s=100 i=7 n=10 must run i=7,8,9 and \
             return 100+7+8+9",
        );
        // A second entry, to catch a stub that works once because it left the
        // frame or a callee-saved register in a state the next entry inherits.
        let again: [i64; 3] = [5, 0, 2];
        assert_eq!(entered(&again), Some(9), "i=2,3,4 from s=0 is 2+3+4");
        // And the admission: a locals slice shorter than the stub reads is
        // refused rather than read past.
        assert_eq!(
            entered(&again[..1]),
            None,
            "a short locals snapshot must be refused, not read past",
        );
    }

    /// Round 11 wave 14 (lane osrmerge): the same loop and the same states,
    /// entered through an OPAQUE arm (`CRATONVM_JIT_OSR_OPAQUE_ENTRY`,
    /// `IrBuilder::build_opaque_osr_merge`). The stub now seeds nothing: the
    /// arm's `Op::OsrLocal`s read the parked locals pointer out of the
    /// phi-copy scratch word and its edge copies write the merge's φs, and the
    /// loop's `+ 1` constant is live into the arm, so the stub's constant
    /// seeding runs too. The ordinary door must be unchanged by the arm.
    ///
    /// Round 11 wave 17 (lane tier): CORRECTION. `compile_via_ir` never calls
    /// `IrBuilder::set_osr_opaque_liveness` (only `lib.rs` does), and the
    /// builder reads no environment switch, so this graph has NO opaque arm:
    /// the thread override below changes nothing and the entry exercised is
    /// the ordinary one. Kept as the "the switch alone changes nothing" pin;
    /// the arm is built and entered by
    /// `r11w17_tier_an_opaque_arm_is_entered_and_publishes_its_bci`.
    #[test]
    fn r11w14_an_opaque_osr_entry_finishes_a_loop_it_did_not_start() {
        let _osr = OsrEntryForce::on();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OSR_OPAQUE_ENTRY", Some("1"))],
            || compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR"),
        );
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
        // SAFETY: as above.
        assert_eq!(unsafe { cm.try_call(&[0]).expect("call") }, 0);
        assert_eq!(
            cm.ir_osr_entries
                .iter()
                .filter(|(bci, _, _)| *bci == 4)
                .count(),
            1,
            "one header, one opaque arm, one door: {:?}",
            cm.ir_osr_entries
        );
        let (_addr, needed) = cm
            .ir_osr_entry_addr(4)
            .expect("the opaque arm is the door at the header bci");
        assert_eq!(needed, 3, "the arm reads locals 0..3");
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]` through its arm, and returns the method's `int`.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(entered(&[10, 100, 7]), Some(124), "100+7+8+9");
        assert_eq!(entered(&[5, 0, 2]), Some(9), "2+3+4");
        // Already past the bound: the loop test runs first on the arm path.
        assert_eq!(entered(&[3, 41, 9]), Some(41));
        assert_eq!(
            entered(&[5, 0, 2][..1]),
            None,
            "a short snapshot is refused"
        );
        // No arm was built (see the doc), so no bci is published as opaque.
        assert!(cm.ir_osr_opaque_entry_bcis.is_empty());
    }

    /// Round 11 wave 17 (lane tier): the loop of the test above, built the way
    /// `lib.rs` builds it under `CRATONVM_JIT_OSR_OPAQUE_ENTRY` (the builder is
    /// handed `regalloc::live_locals_per_pc_all`), so the header really gets
    /// an opaque arm. Pins the door's per-entry bit
    /// (`CompiledMethod::ir_osr_opaque_entry_bcis`, read by
    /// `jit_bridge::build_osr_optimizing_artifact`'s handler-reach refusal):
    /// an emitted arm is published, and every published bci is an entry. When
    /// the lowerer emits the arm, entering it must finish the loop.
    #[test]
    fn r11w17_tier_an_opaque_arm_is_entered_and_publishes_its_bci() {
        let _osr = OsrEntryForce::on();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let mut builder = IrBuilder::new(1, 3);
        let (rows, covered, words) =
            crate::regalloc::live_locals_per_pc_all(&code, 21, 1, &[], &[], 3);
        builder.set_osr_opaque_liveness(rows, covered, words);
        let mut graph = builder.build(&code, 21).expect("the loop builds");
        assert!(
            graph
                .nodes
                .iter()
                .any(|n| matches!(n.op, Op::OsrEntryFlag { header_bci: 4 })),
            "the builder put an opaque arm in front of the header"
        );
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_OSR_OPAQUE_ENTRY", Some("1"))],
            || lower(&graph, &schedule, 1, 3, &no_helpers()).expect("the loop lowers"),
        );
        // SAFETY: compiled by this test for one `int` argument, run on this thread.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
        // Every published opaque bci is one of the body's entries.
        for &b in cm.ir_osr_opaque_entry_bcis.iter() {
            assert!(
                cm.ir_osr_entries.iter().any(|&(e, _, _)| e == b),
                "opaque bci {b} is not an entry: {:?}",
                cm.ir_osr_entries
            );
        }
        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            // The lowerer may refuse the header (its refusal census says why);
            // then nothing may be published as opaque either.
            assert!(cm.ir_osr_opaque_entry_bcis.is_empty());
            return;
        };
        assert_eq!(
            &*cm.ir_osr_opaque_entry_bcis,
            &[4u32][..],
            "the header's only entry is its opaque arm, and the door must see it"
        );
        // SAFETY: the stub builds and tears down its own frame, reads at most
        // `locals[0..3]`, and returns the method's `int`.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(entered(&[10, 100, 7]), Some(124), "100+7+8+9");
        assert_eq!(entered(&[5, 0, 2]), Some(9), "2+3+4");
        assert_eq!(entered(&[3, 41, 9]), Some(41));
    }

    /// **The entered body may not read a constant nobody wrote.**
    ///
    /// `int f(int n){ int s=0; for(int i=0;i<n;i++){ int r; if(i<3) r=100;
    /// else r=900; s+=r; } return s; }` — a counted loop whose body carries an
    /// in-loop MERGE, and whose two arms are literals.
    ///
    /// That last detail is the whole test. A constant reached only by ALU code
    /// is folded into an immediate at every use, so it needs no frame word; a
    /// constant that flows into a PHI does not get that treatment — the merge
    /// store and `emit_phi_copies` read it from its HOME WORD, which its own
    /// `Op::Const` definition writes once, in the entry block. An OSR stub
    /// jumps past that block, so before 2026-09-09 the entered body read
    /// `[rbp - const_slot]` for `100` and got whatever the previous frame at
    /// that address had left there: a wrong, run-to-run VARYING answer from a
    /// deterministic program (`probes/Min0.java`, 8x800 000: three runs, three
    /// different sums, none of them HotSpot's 5 134 452 788).
    ///
    /// `emit_osr_entry_stubs` re-materialises those constants now. The check
    /// that let them through — the `Op::Const` arm of the live-in test — was
    /// correct to let them through, and wrong to do so without emitting them.
    #[test]
    fn an_osr_entry_seeds_the_constants_its_merge_arms_read() {
        let _osr = OsrEntryForce::on();
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 35        <- header, bci 4
        //  9: iload_2   10: iconst_3  11: if_icmpge 21
        // 14: sipush 100 17: istore_3 18: goto 25
        // 21: sipush 900 24: istore_3
        // 25: iload_1   26: iload_3   27: iadd     28: istore_1
        // 29: iinc 2,1  32: goto 4    35: iload_1  36: ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1d, 0x1c, 0x06, 0xa2, 0x00, 0x0a,
            0x11, 0x00, 0x64, 0x3e, 0xa7, 0x00, 0x07, 0x11, 0x03, 0x84, 0x3e, 0x1b, 0x1d, 0x60,
            0x3c, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xe4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 37, 1, 4).expect("clamp loop compiles via IR");
        // The ordinary entry, which never skipped the constants and was always
        // right. `i < 3` on three iterations, `i >= 3` on two.
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { cm.try_call(&[5]).expect("test JIT call") },
            3 * 100 + 2 * 900,
            "the method-entry door: 100,100,100,900,900",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(4) else {
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // Enter at the header in a state the method could not have reached from
        // its own entry: n=10, s=1000, i=4. Every remaining iteration takes the
        // `i >= 3` arm, so the answer is 1000 + 6*900 and it names the `900`
        // constant's home word directly.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&[10, 1000, 4]),
            Some(1000 + 6 * 900),
            "the `900` arm must come from the constant this stub seeded, not \
             from whatever the previous frame left in its word",
        );
        // And the other arm, from a state whose remaining iterations are all
        // `i < 3` — so a stub that seeded one constant and not the other is not
        // reported as a pass.
        assert_eq!(
            entered(&[3, 0, 0]),
            Some(3 * 100),
            "the `100` arm, on its own, from i=0",
        );
        // Both arms in one entry, which is also the shape that would catch a
        // seed emitted INSIDE the loop rather than before it.
        assert_eq!(
            entered(&[6, 7, 1]),
            Some(7 + 2 * 100 + 3 * 900),
            "i=1,2 take the 100 arm and i=3,4,5 take the 900 arm",
        );
    }

    /// **The entered body may not read an XMM register nobody wrote.**
    ///
    /// The constants defect above, in the other register file, and reached
    /// without a merge, a literal arm or a splice:
    ///
    /// ```java
    /// int f(int n) { double a = (double) n; int s = 0;
    ///                for (int i = 0; i < n; i++) {
    ///                    s += (int) (a + i);
    ///                    s += (int) (a + s);
    ///                }
    ///                return s; }
    /// ```
    ///
    /// `a` is an ordinary JVM local. It is not a phi -- nothing reassigns it
    /// in the loop -- so at the header the snapshot names the `Op::I2D` that
    /// computed it, the eligibility test is satisfied, and the stub seeds it.
    /// Seeded into its HOME WORD, which was the whole of the seeding: and an
    /// FP definition does not stop at the home word. `fp_store_value` copies
    /// the result into the value's assigned XMM and marks it resident, after
    /// which every reader in the body takes the REGISTER (`fp_load_value` ->
    /// `resident_xmm`) and never looks at the frame again. The stub jumps past
    /// that definition, so the body read whatever floating-point register the
    /// previous frame happened to leave behind.
    ///
    /// **Observable on Windows only, and that is a property of the defect
    /// rather than of the test.** A value is register-resident across a
    /// safepoint only if its register survives one, and `IR_PROLOGUE_SAVED` --
    /// the XMMs this prologue saves -- is `[6, 7]` on Win64 and EMPTY on
    /// System V, where the ABI makes every XMM volatile. So on Linux every
    /// register in `IR_LINEAR_SCAN` is caller-saved, an FP value live across
    /// the safepoint at a loop header is split rather than promoted, and there
    /// is no stale register for the entry to leave behind. The byte scan below
    /// is what establishes which of the two a given run is, instead of letting
    /// System V report a pass it did not earn.
    ///
    /// Three details of the fixture are load-bearing, and every one of them
    /// was found by watching an earlier fixture fail to reproduce:
    ///
    /// * `a` read TWICE, because residency is `static_uses >= 2`
    ///   (`ir_residency_pays_here`, whose loop weighting is default-off). A
    ///   value read once per trip gets no register, stays in its frame word,
    ///   and is seeded correctly by the unfixed emitter.
    /// * the two reads adding `i` and `s`, not `i` twice: GVN merges two
    ///   `(double) i` conversions into ONE node with two uses of its own, and
    ///   that one -- defined in the loop, with the shorter range -- takes the
    ///   register instead of `a`.
    /// * neither read loop-invariant, because LICM hoists an invariant
    ///   `(int) a` out of the loop and the hoisted `Op::D2I` is then an
    ///   unnamed integer live across the header, which the eligibility test
    ///   refuses outright -- a test that never enters, passing for the wrong
    ///   reason.
    ///
    /// The byte scan below is what turned each of those from a false pass into
    /// a failure, and it is why this test is worth more than its assertion.
    #[test]
    fn an_osr_entry_seeds_the_fp_registers_its_body_reads() {
        let _osr = OsrEntryForce::on();
        //  0: iload_0  1: i2d  2: dstore_1        (a = (double) n)
        //  3: iconst_0 4: istore_3                (s = 0)
        //  5: iconst_0 6: istore 4                (i = 0)
        //  8: iload 4 10: iload_0 11: if_icmpge 37   <- header, bci 8
        // 14: iload_3 15: dload_1 16: iload 4 18: i2d 19: dadd 20: d2i
        // 21: iadd    22: istore_3
        // 23: iload_3 24: dload_1 25: iload_3 26: i2d 27: dadd 28: d2i
        // 29: iadd    30: istore_3
        // 31: iinc 4,1 34: goto 8  37: iload_3  38: ireturn
        let code = [
            0x1a, 0x87, 0x48, 0x03, 0x3e, 0x03, 0x36, 0x04, 0x15, 0x04, 0x1a, 0xa2, 0x00, 0x1a,
            0x1d, 0x27, 0x15, 0x04, 0x87, 0x63, 0x8e, 0x60, 0x3e, 0x1d, 0x27, 0x1d, 0x87, 0x63,
            0x8e, 0x60, 0x3e, 0x84, 0x04, 0x01, 0xa7, 0xff, 0xe6, 0x1d, 0xac, 0, 0,
        ];
        // The bytecode's own arithmetic, in Rust, so the expected answers are
        // derived rather than hand-computed: `d2i` truncates toward zero and
        // `iadd` is 32-bit, which `as i32` and `wrapping_add` reproduce.
        let expect = |n: i32, a: f64, s0: i32, i0: i32| -> i32 {
            let (mut s, mut i) = (s0, i0);
            while i < n {
                s = s.wrapping_add((a + f64::from(i)) as i32);
                s = s.wrapping_add((a + f64::from(s)) as i32);
                i += 1;
            }
            s
        };

        let cm = compile_via_ir(&code, 39, 1, 5).expect("the FP-invariant loop compiles via IR");
        // The ordinary entry, which never skipped the definition and was always
        // right. `a` is `(double) n` here, because that is what the method's
        // own prologue computes.
        // Cast: both doors hand back RAX, whose low 32 bits are this method's
        // `int` result; the upper half is not sign-extended, so the comparison
        // is made on the 32 bits the body actually wrote.
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { cm.try_call(&[5]).expect("test JIT call") } as i32,
            expect(5, 5.0, 0, 0),
            "the method-entry door",
        );

        let Some((_addr, _needed)) = cm.ir_osr_entry_addr(8) else {
            assert!(
                cm.ir_osr_entries.is_empty(),
                "an entry for some other bci while the loop header was refused \
                 means the eligibility test and the emitter disagree",
            );
            return;
        };
        // Cast: as above.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(8, 0, l) }.map(|v| v as i32);
        // Enter at the header in a state the method could not have reached
        // from its own entry -- `a` is 2.5, which `(double) n` never produces,
        // so a stub that leaves the register alone cannot accidentally hold
        // the right bits. The fraction also makes `d2i`'s truncation part of
        // the answer, so a register holding SOME double is not enough either.
        //
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..5]`, and returns the method's `int` result in RAX.
        // Cast: an IEEE-754 bit pattern into the locals array's word.
        let locals: [i64; 5] = [6, 2.5f64.to_bits() as i64, 0, 3, 2];
        assert_eq!(
            entered(&locals),
            Some(expect(6, 2.5, 3, 2)),
            "`a` must come from the XMM this stub seeded, not from whatever \
             floating-point register the previous frame left behind",
        );
        // A second entry, with a DIFFERENT `a`, from a frame the first entry
        // has just used: a stub that seeds the register once, or that passes
        // because the right value happened to still be there, fails here.
        // Cast: as above.
        let again: [i64; 5] = [4, (-1.75f64).to_bits() as i64, 0, 0, 0];
        assert_eq!(
            entered(&again),
            Some(expect(4, -1.75, 0, 0)),
            "a second entry must re-seed the register rather than inherit it",
        );

        // The vacuity guard, LAST: the two entries above are the claim, and
        // this is the evidence that they were asked anything at all. If the
        // allocator gave `a` no register there is no stale register to read,
        // the body loads it from its frame word, and both entries pass on the
        // unfixed emitter too. This graph builds no `Op::ConstF` and the
        // stub's other work is integer stores, so a MOVSD inside the stub can
        // only be the FP publish this test exists to check.
        let bytes = cm.code_bytes();
        let (_, stub_off, _) = *cm
            .ir_osr_entries
            .first()
            .expect("the header entry was found above");
        assert_eq!(cm.ir_osr_entries.len(), 1, "one entry, so one stub to scan");
        let movsd = |b: &[u8]| b.windows(3).filter(|w| *w == [0xF2, 0x0F, 0x10]).count();
        let (in_body, in_stub) = (
            movsd(&bytes[..stub_off as usize]),
            movsd(&bytes[stub_off as usize..]),
        );
        if IR_LOWER_SAVED_XMMS.is_empty() && !ir_poll_preserves_fp() {
            // System V with the back-edge poll still clobbering the XMM bank:
            // every register in `IR_LINEAR_SCAN` is caller-saved, so an FP
            // value live across the header's poll is split rather than
            // promoted and there is no stale register for the entry to leave
            // behind.
            assert_eq!(
                in_stub, 0,
                "an FP value is register-resident across a clobbering back-edge \
                 poll ({in_body} MOVSD in the body)",
            );
            return;
        }
        if IR_LOWER_SAVED_XMMS.is_empty() && in_stub == 0 {
            // System V since round 11 wave 6: the poll reloads the caller-saved
            // file (`ir_poll_preserves_fp`), so `a` MAY now hold a register
            // across the header, but any call the loop makes still splits it.
            // Both are legal; the two entries above were asked either way.
            return;
        }
        assert!(
            in_stub > 0,
            "the stub publishes no XMM register ({in_body} MOVSD in the body, \
             {in_stub} in the stub): the allocator gave `a` none, so this \
             fixture no longer reproduces the defect it was written for and \
             must be repaired rather than believed",
        );
    }

    /// Interpreter round i1 wave 10: every optimizing OSR entry publishes the
    /// kind each seeded local is read as, and `ir_osr_entry_kind_mismatch`
    /// refuses an offer whose tags disagree. The fixture is the loop above:
    /// `n` (int, 0), `a` (double, 1-2), `s` (int, 3), `i` (int, 4).
    #[test]
    fn an_osr_entry_publishes_the_kind_of_every_local_it_seeds() {
        use cratonvm_types::{VTAG_DOUBLE, VTAG_INT, VTAG_NULL, VTAG_OBJECT, VTAG_UNINIT};
        let _osr = OsrEntryForce::on();
        let code = [
            0x1a, 0x87, 0x48, 0x03, 0x3e, 0x03, 0x36, 0x04, 0x15, 0x04, 0x1a, 0xa2, 0x00, 0x1a,
            0x1d, 0x27, 0x15, 0x04, 0x87, 0x63, 0x8e, 0x60, 0x3e, 0x1d, 0x27, 0x1d, 0x87, 0x63,
            0x8e, 0x60, 0x3e, 0x84, 0x04, 0x01, 0xa7, 0xff, 0xe6, 0x1d, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 39, 1, 5).expect("the FP-invariant loop compiles via IR");
        assert_eq!(
            cm.ir_osr_entries.len(),
            cm.ir_osr_entry_kinds.len(),
            "one kind row per entry"
        );
        for &(bci, _, needed) in &cm.ir_osr_entries {
            let row = cm
                .ir_osr_entry_kinds
                .iter()
                .find(|(b, _)| *b == bci)
                .map(|(_, k)| k);
            assert_eq!(row.map(|k| k.len()), Some(needed as usize), "bci {bci}");
        }
        let Some((_addr, needed)) = cm.ir_osr_entry_addr(8) else {
            return; // the header was refused; the rows above are the claim
        };
        let (_, kinds) = cm
            .ir_osr_entry_kinds
            .iter()
            .find(|(b, _)| *b == 8)
            .expect("an entry at 8 has a kind row");
        // `a` is a double read from local 1, and local 2 is its reserved half.
        if needed >= 3 && kinds[1] != 0 {
            assert_eq!(kinds[1], b'D');
            assert_eq!(kinds[2], 0, "the high half of a double is not seeded");
        }
        if needed >= 5 && kinds[4] != 0 {
            assert_eq!(kinds[4], b'I');
        }
        let good = [VTAG_INT, VTAG_DOUBLE, VTAG_UNINIT, VTAG_INT, VTAG_INT];
        assert_eq!(
            cm.ir_osr_entry_kind_mismatch(8, |i| good.get(i).copied()),
            None
        );
        // Any seeded local offered as a reference is refused, at that local.
        for (i, &kind) in kinds.iter().enumerate() {
            if kind == 0 || kind == b'L' {
                continue;
            }
            let mut bad = good;
            bad[i] = if i % 2 == 0 { VTAG_OBJECT } else { VTAG_NULL };
            assert_eq!(
                cm.ir_osr_entry_kind_mismatch(8, |j| bad.get(j).copied()),
                Some(i),
                "local {i} ({}) offered as a reference",
                kind as char
            );
        }
        // A frame shorter than the row is refused rather than read past.
        if kinds.iter().any(|&k| k != 0) {
            assert!(cm.ir_osr_entry_kind_mismatch(8, |_| None).is_some());
        }
        // No row, no constraint.
        assert_eq!(cm.ir_osr_entry_kind_mismatch(9999, |_| None), None);
    }

    /// The kind vocabulary against the interpreter's tags.
    #[test]
    fn the_osr_slot_kinds_admit_exactly_their_own_tags() {
        use crate::ir::IrType;
        use cratonvm_types::{
            VTAG_DOUBLE, VTAG_FLOAT, VTAG_INT, VTAG_LONG, VTAG_NULL, VTAG_OBJECT, VTAG_RETADDR,
            VTAG_UNINIT,
        };
        let admits = crate::ir_osr_slot_kind_admits;
        let kind = crate::ir_osr_slot_kind;
        assert!(admits(kind(IrType::Ref), VTAG_OBJECT));
        assert!(admits(kind(IrType::Ref), VTAG_NULL));
        assert!(!admits(kind(IrType::Ref), VTAG_INT));
        assert!(!admits(kind(IrType::Ref), VTAG_LONG));
        assert!(!admits(kind(IrType::Ref), VTAG_UNINIT));
        assert!(admits(kind(IrType::Int), VTAG_INT));
        assert!(!admits(kind(IrType::Int), VTAG_NULL));
        assert!(admits(kind(IrType::Long), VTAG_LONG));
        assert!(!admits(kind(IrType::Long), VTAG_DOUBLE));
        assert!(admits(kind(IrType::Float), VTAG_FLOAT));
        assert!(!admits(kind(IrType::Float), VTAG_INT));
        assert!(admits(kind(IrType::Double), VTAG_DOUBLE));
        assert!(!admits(kind(IrType::Double), VTAG_LONG));
        for tag in [VTAG_INT, VTAG_OBJECT, VTAG_UNINIT, VTAG_RETADDR] {
            assert!(admits(kind(IrType::Void), tag), "no constraint");
        }
        for k in [b'I', b'J', b'F', b'D', b'L'] {
            assert!(!admits(k, VTAG_RETADDR));
        }
    }

    /// **Every shape the eligibility test excuses must have an emission arm.**
    ///
    /// The mechanical half of `osr_entry_can_produce`'s doc comment. The
    /// defect it was extracted from was not a wrong predicate -- excusing a
    /// constant is right -- but two lists in two places that had to agree and
    /// were only checked by hand. This checks them.
    ///
    /// Textual, in the idiom of
    /// `every_droppable_op_writes_its_home_once_through_store_rax` above: the
    /// alternative is a runtime scan, and there is nothing to scan at runtime
    /// -- the failure is a shape that never gets emitted, which is precisely
    /// the case that produces no node to look at.
    #[test]
    fn an_osr_entry_emits_every_shape_its_eligibility_test_excuses() {
        let src = include_str!("ir_lower.rs");
        // The FIRST occurrence of each needle is the code; the second is this
        // test quoting it.
        let excused_src = src
            .split("fn osr_entry_can_produce(op: &Op) -> bool {")
            .nth(1)
            .expect("`osr_entry_can_produce` is in this file")
            .split("\n    }")
            .next()
            .expect("the function ends");
        let mut excused = std::collections::BTreeSet::new();
        collect_op_names(excused_src, &mut excused);
        assert!(
            !excused.is_empty(),
            "the predicate scan found nothing -- `osr_entry_can_produce` \
             changed shape and this test would now pass vacuously",
        );

        let emitted_src = src
            .split("let (bits, is_fp, is_double) = match self.graph.nodes.get(id as usize) {")
            .nth(1)
            .expect("the seed emission is in this file")
            .split("None => continue,")
            .next()
            .expect("the match ends");
        let mut emitted = std::collections::BTreeSet::new();
        collect_op_names(emitted_src, &mut emitted);

        assert_eq!(
            excused, emitted,
            "the OSR entry excuses {excused:?} from being seeded but emits \
             {emitted:?}. A shape excused and not emitted is a value the \
             entered body reads out of a frame word nothing wrote -- see \
             `an_osr_entry_seeds_the_constants_its_merge_arms_read`.",
        );
    }

    /// The page's own reproducer, at unit scale: `Min1.clamp` spliced into a
    /// counted loop, entered through BOTH doors.
    ///
    /// `int clamp(int v){ int r; if (v < 100) r = 100; else r = v; return r; }`
    /// relocated to a combined-buffer offset, which is what
    /// `ir-splice-branch` admits and what `SPLICED_MERGE_SEEN` used to bar from
    /// the optimizing OSR door. The bar is off; this is what has to hold
    /// without it.
    ///
    /// The OSR half is the half that failed. Its two arms are LITERALS, so the
    /// merge store reads them from their home words, and the entry stub jumps
    /// past the block that writes those words — see
    /// `an_osr_entry_seeds_the_constants_its_merge_arms_read` for the same
    /// defect with nothing spliced at all.
    fn splice_branch_fixture() -> (Vec<u8>, usize, HashMap<usize, crate::ir::IrInlineSite>) {
        // Caller: `int f(int n){ int s=0; for(int i=0;i<n;i++) s += clamp(i);
        //          return s; }`   locals: 0=n, 1=s, 2=i
        //  0: iconst_0   1: istore_1   2: iconst_0   3: istore_2
        //  4: iload_2    5: iload_0    6: if_icmpge 22        <- header, bci 4
        //  9: iload_1   10: iload_2   11: invokestatic #1   14: iadd
        // 15: istore_1  16: iinc 2,1  19: goto 4
        // 22: iload_1   23: ireturn
        let caller = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x10, 0x1b, 0x1c, 0xb8, 0x00, 0x01,
            0x60, 0x3c, 0x84, 0x02, 0x01, 0xa7, 0xff, 0xf1, 0x1b, 0xac,
        ];
        const CALLER_LEN: usize = 24;
        // Callee: locals 0=v, 1=r
        //  0: iload_0    1: sipush 100   4: if_icmpge 14
        //  7: sipush 100 10: istore_1   11: goto 16
        // 14: iload_0   15: istore_1
        // 16: iload_1   17: ireturn                       <- single trailing return
        let callee = [
            0x1a, 0x11, 0x00, 0x64, 0xa2, 0x00, 0x0a, 0x11, 0x00, 0x64, 0x3c, 0xa7, 0x00, 0x05,
            0x1a, 0x3c, 0x1b, 0xac,
        ];
        let mut combined = caller.to_vec();
        let base = combined.len();
        combined.extend_from_slice(&callee);
        // The two trailing sentinel bytes every method's code carries.
        combined.extend_from_slice(&[0, 0]);
        let mut sites = HashMap::new();
        sites.insert(
            11,
            crate::ir::IrInlineSite {
                base,
                code_len: callee.len(),
                num_args: 1,
                max_locals: 2,
                arg_local_slots: vec![0],
                returns_value: true,
                receiver_is_arg0: false,
                method_key: "P.clamp:(I)I".to_string(),
                class_id: 0,
            },
        );
        (combined, CALLER_LEN, sites)
    }

    /// A callee whose loop ECJ rotated, spliced into its caller: built, optimized,
    /// lowered and run. `f(n) = sumTo(n) + 1`, `sumTo(n) = 0 + 1 + … + (n-1)`.
    #[test]
    fn a_spliced_callee_with_a_rotated_loop_runs() {
        let caller = [0x1a, 0xb8, 0x00, 0x01, 0x04, 0x60, 0xac];
        // sumTo: 0: s = 0; 2: i = 0; 4: goto 14; 7: s += i; 11: iinc 2, 1;
        // 14: iload_2; 15: iload_0; 16: if_icmplt 7; 19: iload_1; 20: ireturn
        let callee = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x0a, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01,
            0x1c, 0x1a, 0xa1, 0xff, 0xf7, 0x1b, 0xac,
        ];
        let mut combined = caller.to_vec();
        let base = combined.len();
        combined.extend_from_slice(&callee);
        combined.extend_from_slice(&[0, 0]);
        let mut sites = HashMap::new();
        sites.insert(
            1,
            crate::ir::IrInlineSite {
                base,
                code_len: callee.len(),
                num_args: 1,
                max_locals: 3,
                arg_local_slots: vec![0],
                returns_value: true,
                receiver_is_arg0: false,
                method_key: "P.sumTo:(I)I".to_string(),
                class_id: 0,
            },
        );
        let mut builder = IrBuilder::new(1, 1);
        builder.set_inline_sites(sites);
        let mut graph = builder
            .build(&combined, caller.len())
            .expect("a callee body with a rotated loop must splice");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("the graph must lower");
        // SAFETY: the body was compiled by this test for one `int` argument and runs on this thread with no helper calls.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("test JIT call") };
        assert_eq!(f(0), 1, "an empty loop sums to zero");
        assert_eq!(f(1), 1);
        assert_eq!(f(5), 11, "0+1+2+3+4, plus one");
        assert_eq!(f(100), 4951);
    }

    #[test]
    fn a_spliced_body_may_branch_and_its_phi_carries_a_combined_pc() {
        let (combined, caller_len, sites) = splice_branch_fixture();
        let mut builder = IrBuilder::new(1, 3);
        builder.set_inline_sites(sites);
        let graph = builder
            .build(&combined, caller_len)
            .expect("a spliced body with a forward branch must build");
        let spliced_phi = graph
            .nodes
            .iter()
            .any(|n| matches!(n.op, Op::Phi) && n.bytecode_pc.is_some_and(|pc| pc >= caller_len));
        assert!(
            spliced_phi,
            "the callee's if/else must produce a phi, and it must carry the \
             COMBINED-buffer pc every node in a relocated region carries",
        );
        // And no `Op::Call` survives at the spliced site: a body that was
        // spliced AND dispatched would run twice.
        assert!(
            !graph.nodes.iter().any(|n| matches!(n.op, Op::Call { .. })),
            "the spliced call must be gone, not emitted alongside the body",
        );
    }

    #[test]
    fn a_spliced_branchy_body_runs_from_both_doors() {
        let _osr = OsrEntryForce::on();
        let (combined, caller_len, sites) = splice_branch_fixture();
        let mut builder = IrBuilder::new(1, 3);
        builder.set_inline_sites(sites);
        let mut graph = builder
            .build(&combined, caller_len)
            .expect("a spliced body with a forward branch must build");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm =
            lower(&graph, &schedule, 1, 3, &no_helpers()).expect("the spliced graph must lower");

        // The method-entry door. `clamp(i)` is 100 for every i below 100.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("test JIT call") };
        assert_eq!(f(5), 500, "clamp(0..4) is 100 each");
        assert_eq!(f(0), 0, "an empty loop sums to zero");
        assert_eq!(
            f(105),
            100 * 100 + (100 + 101 + 102 + 103 + 104),
            "i<100 clamps to 100; i>=100 passes through",
        );

        // The OSR door, into the same body, at the loop header. This is the one
        // the containment used to withhold, so its PRESENCE is asserted rather
        // than tolerated: a silent absence is how the containment would come
        // back without anyone noticing, and this test would then "pass" by
        // never entering.
        assert!(
            cm.ir_osr_entry_addr(4).is_some(),
            "the loop header must carry an optimizing OSR entry even though a \
             spliced body contributed the merge inside it (entries: {:?})",
            cm.ir_osr_entries
                .iter()
                .map(|(b, _, _)| *b)
                .collect::<Vec<_>>(),
        );
        // SAFETY: the stub builds and tears down its own frame, reads exactly
        // `locals[0..3]`, and returns the method's `int` result in RAX.
        let entered = |l: &[i64]| unsafe { cm.ir_osr_enter(4, 0, l) };
        assert_eq!(
            entered(&[5, 1000, 2]),
            Some(1000 + 3 * 100),
            "entering at i=2 with s=1000 must run i=2,3,4 through the spliced \
             clamp and add 100 each",
        );
        assert_eq!(
            entered(&[103, 0, 100]),
            Some(100 + 101 + 102),
            "the OTHER arm of the spliced branch, from i=100",
        );
    }

    /// A body the door cannot enter carries no stubs, and the escape hatch
    /// puts them back.
    ///
    /// # What this is protecting
    ///
    /// `try_osr`'s admission is `ir_osr_entry_addr(pc).is_some() &&
    /// ir_osr_sentinel_free` — BOTH — so every stub in a body that is not
    /// sentinel-free is unreachable: bytes in the code cache, a `JMP` to
    /// patch, a published `(bci, offset, needed)` triple, and a whole
    /// `build_live_model` pass, for a door that will refuse the artifact on
    /// the second conjunct. And it is the COMMON case, not a corner:
    /// sentinel-free means no deopt stub and no call-exception stub, so any
    /// method containing a call fails it.
    ///
    /// The loop below is sentinel-free, so it is the control: it must still
    /// carry entries under the production rule. Making a body that is NOT
    /// sentinel-free is what `assert` on `ir_osr_sentinel_free` checks, so
    /// this test cannot silently degrade into asserting nothing.
    #[test]
    fn a_body_the_door_cannot_enter_carries_no_osr_stubs() {
        // `for (i = 0; i < n; i++) s += i; return s;` — no call, no guard, so
        // no deopt stub and no call-exception stub: sentinel-free.
        let sentinel_free_loop = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        {
            let _on = OsrEntryForce::on_but_not_always();
            let cm = compile_via_ir(&sentinel_free_loop, 21, 1, 3).expect("loop compiles via IR");
            assert!(
                cm.ir_osr_sentinel_free,
                "the control body must be sentinel-free, or this test proves \
                 nothing about the skip"
            );
            assert!(
                !cm.ir_osr_entries.is_empty(),
                "a sentinel-free body still gets its entries — the skip is \
                 about the door's SECOND conjunct, not about turning OSR off"
            );
        }
        // And the escape hatch is what the twenty-odd older stub-shape tests
        // ride on, so it has to actually restore the old behaviour.
        {
            let _always = OsrEntryForce::on();
            let cm = compile_via_ir(&sentinel_free_loop, 21, 1, 3).expect("loop compiles via IR");
            assert!(!cm.ir_osr_entries.is_empty());
        }
    }

    /// The kill switch really removes them: with `CRATONVM_JIT_IR_OSR_ENTRY=0`
    /// an artifact carries no entry stub at all.
    ///
    /// Until 2026-09-05 this asserted the same thing about the DEFAULT, which
    /// is what it was. The switch is on now, so the property worth pinning is
    /// that turning it off still works — a default-on codegen change is only as
    /// good as its way back.
    #[test]
    fn the_osr_entry_kill_switch_emits_no_stub() {
        let _off = OsrEntryForce::off();
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        assert!(
            cm.ir_osr_entries.is_empty(),
            "with the kill switch set an artifact must carry no entry stub",
        );
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[10]).expect("call") }, 45);
    }

    /// Round 12 wave 1 (lane osr, irback proposal W18-2): an ordinary OSR
    /// entry is planned only at a loop header. The door enters only at the
    /// target of a taken backward branch, which here is bci 4 alone; a stub
    /// at the loop exit (19) or any other block start is dead code the door
    /// can never ask for.
    #[test]
    fn r12w1_ordinary_osr_entries_are_planned_only_at_loop_headers() {
        let _always = OsrEntryForce::on();
        // `for (i = 0; i < n; i++) s += i; return s;` -- header at 4.
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("loop compiles via IR");
        let bcis: Vec<u32> = cm.ir_osr_entries.iter().map(|&(b, _, _)| b).collect();
        assert!(
            !bcis.is_empty(),
            "the header lost its entry too: this fixture no longer asks anything",
        );
        assert!(
            bcis.iter().all(|&b| b == 4),
            "OSR entries at {bcis:?}; bci 4 is the only back-edge target",
        );
    }

    /// `Lowerer::first_safepoint_index_by_bci` gives, for every bci, the answer
    /// of the by-bci scan it replaced: the FIRST snapshot at that bci. That
    /// holds when several snapshots share a bci, as an unrolled body's copies
    /// do, and for a bci with no snapshot at all.
    #[test]
    fn the_safepoint_index_names_the_first_snapshot_at_each_bci() {
        // iconst_0; istore_1; iload_1; ireturn
        let code = [0x03, 0x3c, 0x1b, 0xac, 0, 0];
        let mut graph = IrBuilder::new(1, 2).build(&code, 4).expect("builds");
        for bci in [2usize, 0, 2, 7, 3, 7] {
            graph.safepoints.push(crate::ir::SafepointSnapshot::new(
                bci,
                Vec::new(),
                Vec::new(),
                Vec::new(),
            ));
        }
        let index = Lowerer::first_safepoint_index_by_bci(&graph);
        for bci in 0..10usize {
            assert_eq!(
                index.get(&bci).copied(),
                graph.safepoints.iter().position(|s| s.bci == bci),
                "bci {bci}"
            );
        }
        let distinct: std::collections::HashSet<usize> =
            graph.safepoints.iter().map(|s| s.bci).collect();
        assert_eq!(index.len(), distinct.len(), "one entry per distinct bci");
    }

    // ── Bottom-tested (rotated) loops ────────────────────────────────────
    //
    // ECJ, Kotlin and Scala jump forward to a loop's test and branch back to
    // its body. The IR builder refused every such method until it learned to
    // walk one in reverse post-order. Each test compiles the shape through the
    // whole IR pipeline and checks the answer the obvious Java gives. The byte
    // layouts are annotated beside the same fixtures in `ir.rs`.

    /// `int f(int n) { int s = 0; for (int i = 0; i < n; i++) s += i; return s; }`, ECJ-shaped.
    #[test]
    fn a_rotated_for_loop_compiles_via_ir_and_sums() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x0a, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01,
            0x1c, 0x1a, 0xa1, 0xff, 0xf7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 1, 3).expect("a rotated for loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        for (n, want) in [(0i64, 0i64), (1, 0), (5, 10), (10, 45), (-3, 0)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { do { n = n - 3; } while (n > 0); return n; }`: the loop
    /// header is pc 0.
    #[test]
    fn a_do_while_at_the_method_entry_compiles_via_ir() {
        let code = [
            0x1a, 0x06, 0x64, 0x3b, 0x1a, 0x9d, 0xff, 0xfb, 0x1a, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 10, 1, 1).expect("a do/while at pc 0 compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32 as i64;
        for (n, want) in [(10i64, -2i64), (0, -3), (3, 0), (1, -2), (-5, -8)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { int c = 0; for (int i = 0; i < n; i++) for (int j = 0; j < i; j++) c += j; return c; }`:
    /// a javac-shaped outer loop around an ECJ-shaped inner one.
    #[test]
    fn a_rotated_loop_nested_in_a_javac_loop_compiles_via_ir() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0xa7, 0x00, 0x0a,
            0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0x1d, 0x1c, 0xa1, 0xff, 0xf7, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 34, 1, 4).expect("a nested rotated loop compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        // sum over i < n of (0 + 1 + ... + (i - 1))
        for (n, want) in [(0i64, 0i64), (1, 0), (4, 4), (5, 10), (6, 20)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    /// `int f(int n) { int s = 0; for (int i = 0; i < n; i++) { if ((i & 1) == 0) s += i; else s -= 1; } return s; }`,
    /// ECJ-shaped: a forward if/else join inside a rotated body.
    #[test]
    fn a_rotated_loop_with_an_if_else_join_compiles_via_ir() {
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0xa7, 0x00, 0x16, 0x1c, 0x04, 0x7e, 0x9a, 0x00, 0x0a, 0x1b,
            0x1c, 0x60, 0x3c, 0xa7, 0x00, 0x06, 0x84, 0x01, 0xff, 0x84, 0x02, 0x01, 0x1c, 0x1a,
            0xa1, 0xff, 0xeb, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 33, 1, 3)
            .expect("a rotated loop with an if/else compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") } as i32 as i64;
        for (n, want) in [(0i64, 0i64), (1, 0), (2, -1), (3, 1), (5, 4), (6, 3)] {
            assert_eq!(f(n), want, "f({n})");
        }
    }

    // do-while: the back-edge is an `if_icmplt` (not a goto), and the loop
    // header self-loops (the condition is at the bottom). Exercises the
    // if-as-back-edge path + a block whose true edge targets its own head.
    #[test]
    fn test_lower_do_while_sum() {
        // int f(int n){ int s=0,i=0; do { s+=i; i++; } while(i<n); return s; }
        //  0:iconst_0 1:istore_1 2:iconst_0 3:istore_2
        //  4:iload_1 5:iload_2 6:iadd 7:istore_1 8:iinc 2,1
        // 11:iload_2 12:iload_0 13:if_icmplt 4  16:iload_1 17:ireturn
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02, 0x01, 0x1c, 0x1a, 0xa1,
            0xff, 0xf7, 0x1b, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 18, 1, 3).expect("do-while compiles via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(f(5), 10, "runs i=0..4 → 0+1+2+3+4 = 10");
        assert_eq!(f(1), 0, "runs once (i=0) → 0");
        assert_eq!(f(0), 0, "do-while runs once even at n=0 → s=0");
    }

    // Nested counted loops: two loop headers, the inner nested in the outer.
    #[test]
    fn test_lower_nested_loops() {
        // int f(int n){ int c=0; for(i=0;i<n;i++) for(j=0;j<n;j++) c++; return c; }
        //  0:iconst_0 1:istore_1            // c=0
        //  2:iconst_0 3:istore_2            // i=0
        //  4:iload_2 5:iload_0 6:if_icmpge 28   // outer header
        //  9:iconst_0 10:istore_3           // j=0
        // 11:iload_3 12:iload_0 13:if_icmpge 22 // inner header
        // 16:iinc 1,1  19:iinc 3,1  22? ...
        // Layout carefully below.
        //  0:03 1:3c 2:03 3:3d
        //  4:1c 5:1a 6:a2 00 16(=22? we need offset) ...
        // Compute: outer if_icmpge at 6 must exit past the outer iinc/goto.
        //  4: iload_2        1c            outer header
        //  5: iload_0        1a
        //  6: if_icmpge 31   a2 00 19       (6+25=31)
        //  9: iconst_0       03            j=0
        // 10: istore_3       3e
        // 11: iload_3        1d            inner header
        // 12: iload_0        1a
        // 13: if_icmpge 25   a2 00 0c       (13+12=25)
        // 16: iinc 1,1       84 01 01       c++
        // 19: iinc 3,1       84 03 01       j++
        // 22: goto 11        a7 ff f5       (22-11=11)
        // 25: iinc 2,1       84 02 01       i++
        // 28: goto 4         a7 ff e8       (28-24=4)
        // 31: iload_1        1b
        // 32: ireturn        ac
        let code = [
            0x03, 0x3c, 0x03, 0x3d, // 0..3
            0x1c, 0x1a, 0xa2, 0x00, 0x19, // 4: outer header, if_icmpge 31
            0x03, 0x3e, // 9: j=0
            0x1d, 0x1a, 0xa2, 0x00, 0x0c, // 11: inner header, if_icmpge 25
            0x84, 0x01, 0x01, // 16: iinc c
            0x84, 0x03, 0x01, // 19: iinc j
            0xa7, 0xff, 0xf5, // 22: goto 11
            0x84, 0x02, 0x01, // 25: iinc i
            0xa7, 0xff, 0xe8, // 28: goto 4
            0x1b, 0xac, // 31: iload_1; ireturn
            0, 0,
        ];
        let cm = compile_via_ir(&code, 33, 1, 4).expect("nested loops compile via IR");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let f = |n: i64| unsafe { cm.try_call(&[n]).expect("call") };
        assert_eq!(f(3), 9, "3*3 = 9");
        assert_eq!(f(5), 25, "5*5 = 25");
        assert_eq!(f(0), 0, "no iterations");
        assert_eq!(f(1), 1, "1*1 = 1");
    }

    // ── real-frame-deopt fires end-to-end: div-by-zero guard ─────────────
    // Proves the trigger half: an IR-compiled `a/b` deopts (instead of the raw
    // IDIV faulting) when b==0, with the reconstructed frame carrying the live
    // operands at the idiv bci so the interpreter can re-execute and throw
    // ArithmeticException. (The VM-side resume is wired separately, gated.)
    #[test]
    fn test_lower_div_by_zero_deopts() {
        use crate::deopt::{take_last_deopt, FrameValue};
        // int f(int a, int b){ return a / b; }  — iload_0; iload_1; idiv; ireturn
        let code = [0x1a, 0x1b, 0x6c, 0xac, 0, 0];
        let cm = compile_via_ir(&code, 4, 2, 2).expect("div compiles via IR");

        let _ = take_last_deopt(); // clear any stale state
                                   // divisor != 0 → normal result, no deopt.
                                   // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let ok = unsafe { cm.try_call(&[20, 4]).expect("call (b != 0)") };
        assert_eq!(ok, 5, "20 / 4 = 5");
        assert!(take_last_deopt().is_none(), "no deopt when divisor != 0");

        // divisor == 0 → deopt (sentinel + reconstructed frame), NOT a #DE fault.
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sentinel = unsafe { cm.try_call(&[20, 0]).expect("call (b == 0)") };
        assert_eq!(sentinel, i64::MIN, "div by zero → deopt sentinel");
        let frame = take_last_deopt().expect("deopt reconstructed a frame");
        // idiv is at bci 2; resume there with [a, b] live on the operand stack
        // so the interpreter re-executes the division and throws.
        assert_eq!(frame.bci, 2, "resume at the idiv bci");
        assert_eq!(
            frame.stack,
            vec![FrameValue::Int(20), FrameValue::Int(0)],
            "operands restored for re-execution",
        );
    }

    #[test]
    fn test_lower_ldiv_by_zero_reconstructs_long_frame() {
        use crate::deopt::{take_last_deopt, FrameValue};
        use crate::ir::{IrBuilder, IrType};
        // long f(long a, long b){ return a / b; }
        //   lload_0; lload_2; ldiv; lreturn   (+ 2 trailing padding bytes)
        // Proves a `long` live at the div guard reconstructs as a full-64-bit
        // FrameValue::Long (cat-2 width on resume), not a truncated Int.
        let code = [0x1e, 0x20, 0x6d, 0xad, 0, 0];
        let mut builder = IrBuilder::new(2, 4); // 2 long params (a@0-1, b@2-3)
        builder.set_param_types(&[IrType::Long, IrType::Long]);
        let mut graph = builder.build(&code, 4).expect("ldiv IR build");
        ir_optimize::optimize(&mut graph);
        let schedule = ir_schedule::schedule(&graph);
        let cm = lower(&graph, &schedule, 2, 4, &no_helpers()).expect("lower ldiv");

        let _ = take_last_deopt(); // clear any stale state
                                   // divisor != 0 → normal full-64-bit result, no deopt. A 32-bit IDIV
                                   // would mishandle this dividend (> i32::MAX).
                                   // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let ok = unsafe { cm.try_call(&[0x1_0000_0000, 2]).expect("call (b != 0)") };
        assert_eq!(ok, 0x8000_0000, "0x1_0000_0000 / 2 (genuinely 64-bit)");
        assert!(take_last_deopt().is_none(), "no deopt when divisor != 0");

        // divisor == 0 → deopt; the reconstructed frame must carry the two LONG
        // operands as FrameValue::Long (full 64 bits) so the interpreter resumes
        // at the ldiv bci and re-executes it (throwing ArithmeticException).
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        let sentinel = unsafe { cm.try_call(&[0x7_0000_0000, 0]).expect("call (b == 0)") };
        assert_eq!(sentinel, i64::MIN, "ldiv by zero → deopt sentinel");
        let frame = take_last_deopt().expect("deopt reconstructed a frame");
        assert_eq!(frame.bci, 2, "resume at the ldiv bci");
        assert_eq!(
            frame.stack,
            vec![FrameValue::Long(0x7_0000_0000), FrameValue::Long(0)],
            "long operands restored as full-64-bit FrameValue::Long",
        );
        // Locals: a@0 and b@2 are longs (StackSlotLong → Long); the high-half
        // slots 1/3 are dummies (never read by the interpreter).
        assert_eq!(frame.locals[0], FrameValue::Long(0x7_0000_0000));
        assert_eq!(frame.locals[2], FrameValue::Long(0));
    }

    // ── `[rbp - 0]` sentinel removal + resource bounds ───────────────────

    /// `int f(int a) { return a + 1; }` as a hand-built graph, plus its
    /// schedule. The smallest shape that has a real data edge to verify.
    fn add_one_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let sum = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// `void f(int a) { a + 1; }` — the same shape as [`add_one_graph`] with the
    /// value dropped from the `Return`, so the only difference between the two
    /// lowerings is the void exit itself.
    fn void_return_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let _sum = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// Laying out a jump table on an OVERFLOWED buffer must return, not spin.
    ///
    /// `emit_switch_tables` pads to a 4-byte boundary with `emit_byte` until
    /// `pos() % 4 == 0`. Once the buffer has overflowed, every write is a
    /// sticky no-op and `pos()` is frozen. If it froze at an unaligned offset,
    /// the loop never ended. That hung the compiling thread, and with it the
    /// whole VM: Spring tests using Mockito's inline mock maker hung in
    /// ByteBuddy's agent self-attach (`JarInputStream.<init>` compiling
    /// a switch-bearing method at the IR tier) until the watchdog fired.
    ///
    /// Run on a worker with a deadline, so a regression FAILS this test
    /// rather than hanging the test binary.
    #[test]
    fn a_switch_table_on_an_overflowed_buffer_returns_instead_of_spinning() {
        let (tx, rx) = std::sync::mpsc::channel();
        std::thread::spawn(move || {
            let (graph, schedule) = add_one_graph();
            let graph: &'static Graph = Box::leak(Box::new(graph));
            let schedule: &'static Schedule = Box::leak(Box::new(schedule));
            let plan: &'static SlotPlan = Box::leak(Box::new(plan_slots(graph, schedule, None)));
            let mut lo = lowerer_over(graph, schedule, plan, 64);
            // Three bytes in, then a write that does not fit: the buffer is
            // overflowed with `pos()` frozen at 3, which no padding can align.
            lo.buf.emit(&[0x90; 3]);
            lo.buf.emit(&[0x90; 128]);
            assert!(lo.buf.overflowed() && lo.buf.pos() % 4 != 0);
            lo.switch_tables.push(SwitchTablePlan {
                lea_patch: 0,
                targets: vec![0, 0],
            });
            lo.emit_switch_tables();
            let _ = tx.send(lo.buf.pos());
        });
        let pos = rx
            .recv_timeout(std::time::Duration::from_secs(10))
            .expect("emit_switch_tables did not return on an overflowed buffer: it is spinning");
        assert_eq!(pos, 3, "nothing may be written past the overflow");
    }

    /// A VOID return must leave a defined value in the return register.
    ///
    /// `i64::MIN` there is the VM-wide "the callee trapped" sentinel, and every
    /// consumer reads the raw register: the single-pass inline MIC/PIC
    /// cascade's `emit_inline_callee_deopt_check`, the megamorphic hashed
    /// stub's, `jit_invoke_virtual_mic`'s `rc == i64::MIN`, and the
    /// interpreter's post-JIT drain. A void method has no return value, so
    /// unless the exit writes one, RAX carries whatever the last operation left
    /// there and can equal the sentinel by accident — on behalf of a call that
    /// neither threw nor deopted. The single-pass backend has always zeroed it
    /// (`x64/bytecode_walk.rs`, the `0xb1` arm); this backend did not.
    ///
    /// Asserted on the BYTES, and as a DIFFERENCE against the value-returning
    /// twin, so it cannot pass by accident: `try_call` returning 0 would be
    /// satisfied by an undefined register that merely happened to hold 0.
    #[test]
    fn a_void_return_writes_the_return_register() {
        const XOR_EAX_EAX: [u8; 2] = [0x31, 0xC0];

        let (vg, vs) = void_return_graph();
        let void_method = lower(&vg, &vs, 1, 1, &no_helpers()).expect("void method must lower");
        let (ag, as_) = add_one_graph();
        let value_method = lower(&ag, &as_, 1, 1, &no_helpers()).expect("a+1 must lower");

        let void_zeroes = count_seq(void_method._buffer_slice_for_debug(), &XOR_EAX_EAX);
        let value_zeroes = count_seq(value_method._buffer_slice_for_debug(), &XOR_EAX_EAX);
        assert_eq!(
            void_zeroes,
            value_zeroes + 1,
            "the void exit must contribute exactly one `XOR EAX,EAX` the \
             value-returning exit does not (void={void_zeroes}, value={value_zeroes})",
        );
        assert_eq!(
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            unsafe { void_method.try_call(&[41]) },
            Ok(0),
            "a void method must not hand its caller the deopt sentinel",
        );
    }

    /// The verifier must not refuse a graph the lowerer handles — otherwise the
    /// "bail before emission" fix would silently cost JIT coverage.
    #[test]
    fn verification_accepts_a_well_formed_graph() {
        let (graph, schedule) = add_one_graph();
        assert!(verify_data_locations(&graph, &schedule).is_ok());
        let method = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("a+1 must lower");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { method.try_call(&[41]) }, Ok(42));
    }

    /// Acceptance test for the `[rbp - 0]` defect (report: "replace
    /// zero-initialized `node_slot` with verified optional locations").
    ///
    /// A data input that no emitted node defines — here an `Op::Dead` node,
    /// which the scheduler never places, exactly like the GVN-collapsed
    /// `ArrayLoad(Double)` observed in `DualPivotQuicksort.insertionSort` —
    /// must refuse the compile *before* emission, not be detected afterwards by
    /// a sticky bit. Before this change the use lowered to `[rbp - 0]`, reading
    /// the saved caller frame pointer as a `double`.
    #[test]
    fn an_unallocated_data_input_refuses_the_compile_before_emission() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        // Scheduler omission, modelled: `Op::Dead` is never placed into a
        // block, so nothing ever allocates a location for it.
        let ghost = graph.add(Op::Dead, IrType::Int, vec![], None);
        let sum = graph.add(Op::Add, IrType::Int, vec![a, ghost], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], None);

        let schedule = ir_schedule::schedule(&graph);
        assert_eq!(
            schedule.node_to_block[ghost as usize],
            usize::MAX,
            "precondition: the ghost node is in no emitted block",
        );

        let err = verify_data_locations(&graph, &schedule)
            .expect_err("an unallocated data input must be refused");
        assert_eq!(err.reason, BailoutReason::UnallocatedValue { node: ghost });
        assert_eq!(err.category(), "unallocated_value");

        // …and the public entry point turns that into the historical "run in a
        // lower tier" answer rather than emitting or panicking.
        assert!(lower(&graph, &schedule, 1, 1, &no_helpers()).is_none());
    }

    /// The slot accessor has no encoding for "unallocated", so it can never
    /// hand back `0` — the offset that means `[rbp - 0]`, the saved caller RBP.
    #[test]
    fn slot_accessor_never_yields_the_rbp_zero_sentinel() {
        let (graph, schedule) = add_one_graph();
        let a = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Param(0)))
            .expect("param node") as NodeId;
        let sum = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Add))
            .expect("add node") as NodeId;

        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact_fields: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let plan = plan_slots(&graph, &schedule, None);
        let mut lowerer = Lowerer::new(
            &graph,
            &schedule,
            buf,
            1,
            1,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact_fields,
            &no_frame_sites,
        );

        // Unallocated is an error, not an offset.
        assert!(lowerer.slot_of_checked(a).is_err());
        assert!(lowerer.node_slot.iter().all(|slot| slot.is_none()));

        let off = lowerer.alloc_slot_checked(a).expect("first spill slot");
        assert!(
            off >= lowerer.first_spill,
            "{off} < {}",
            lowerer.first_spill
        );
        assert_ne!(off, 0);
        assert_eq!(lowerer.slot_of_checked(a).expect("allocated"), off);
        // Non-zero by type, not by convention: every occupied entry is a
        // `NonZeroU32`, so `0` is not a representable location at all.
        assert!(lowerer
            .node_slot
            .iter()
            .flatten()
            .all(|located| located.get() > 0));

        // The infallible façade the emission sites use latches a structured
        // reason and still never returns 0.
        let poison = lowerer.slot_of(sum);
        assert_ne!(poison, 0, "the façade must never emit [rbp - 0]");
        assert!(lowerer.unallocated_slot_use.get());
        let latched = lowerer.take_latched_bailout().expect("a latched reason");
        assert_eq!(
            latched.reason,
            BailoutReason::UnallocatedValue { node: sum }
        );
        // An out-of-range id is an error too — it used to index-panic.
        assert!(lowerer.slot_of_checked(NO_NODE).is_err());
    }

    /// Report: "bound graph and frame memory before allocation" — an
    /// over-budget node count is refused with `GraphTooLarge`.
    #[test]
    fn an_over_limit_node_count_bails_with_graph_too_large() {
        assert!(check_graph_size(0, DEFAULT_MAX_NODES).is_ok());
        assert!(check_graph_size(DEFAULT_MAX_NODES, DEFAULT_MAX_NODES).is_ok());
        let err = check_graph_size(DEFAULT_MAX_NODES + 1, DEFAULT_MAX_NODES)
            .expect_err("over the node budget");
        assert_eq!(
            err.reason,
            BailoutReason::GraphTooLarge {
                nodes: DEFAULT_MAX_NODES + 1,
                limit: DEFAULT_MAX_NODES,
            }
        );
        assert_eq!(err.category(), "graph_too_large");
    }

    /// Report: "bound graph and frame memory before allocation" — the frame is
    /// estimated (spill reservation + locals + staged outgoing args) and
    /// refused with `FrameTooLarge` before a byte of it is reserved.
    #[test]
    fn an_over_limit_frame_estimate_bails_with_frame_too_large() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };

        // A normal method is nowhere near the bound.
        let small = estimate_frame_bytes(4, 32, &plain);
        assert!(small < DEFAULT_MAX_FRAME_BYTES, "{small}");
        assert!(check_frame_size(small, DEFAULT_MAX_FRAME_BYTES).is_ok());
        assert_eq!(small % 16, 0, "the estimate is 16-byte aligned");

        // Each of the three terms the report names moves the estimate.
        assert!(estimate_frame_bytes(64, 32, &plain) > small); // locals
        assert!(estimate_frame_bytes(4, 512, &plain) > small); // spills
        assert!(
            estimate_frame_bytes(
                4,
                32,
                &FrameNeeds {
                    needs_context: true,
                    max_call_args: 8,
                },
            ) > small,
            "staged outgoing arguments must count",
        );

        // A method whose PEAK LIVE set is as wide as the node budget still has
        // to be refused: 20_000 simultaneously live values is ~160 KiB, five
        // times the 32 KiB oop-map bound. What changed with liveness reuse is
        // that reaching this now takes 20_000 values live *at once*, not merely
        // 20_000 values in the arena — see
        // `a_previously_declined_large_method_now_compiles`.
        let huge = estimate_frame_bytes(0, DEFAULT_MAX_NODES, &plain);
        assert!(huge > DEFAULT_MAX_FRAME_BYTES, "{huge}");
        let err =
            check_frame_size(huge, DEFAULT_MAX_FRAME_BYTES).expect_err("over the frame budget");
        assert_eq!(
            err.reason,
            BailoutReason::FrameTooLarge {
                bytes: huge,
                limit: DEFAULT_MAX_FRAME_BYTES,
            }
        );
        assert_eq!(err.category(), "frame_too_large");

        // Saturating, not wrapping: a pathological count reports "enormous"
        // instead of overflowing into a small (or negative) frame.
        assert_eq!(
            estimate_frame_bytes(0, usize::MAX, &plain),
            usize::MAX & !15usize,
        );

        // End to end: the public entry point refuses instead of reserving a
        // frame whose slot offsets the oop map could not even encode.
        let (graph, schedule) = add_one_graph();
        assert!(
            lower(&graph, &schedule, 1, 10_000, &no_helpers()).is_none(),
            "10_000 locals is an 80 KiB frame — refuse, do not build it",
        );
        // The same graph with a sane local count still compiles.
        assert!(lower(&graph, &schedule, 1, 1, &no_helpers()).is_some());
    }

    // ── Liveness-based frame-slot reuse ──────────────────────────────────

    /// An empty graph shell, so each test below only writes the shape it cares
    /// about.
    fn empty_graph() -> Graph {
        Graph::empty(0)
    }

    /// `int f(int a) { a += 1; a += 1; … }` with `len` increments: a chain in
    /// which every temporary is dead the instant the next one consumes it. The
    /// shape the old one-slot-per-node reservation was worst on.
    fn straight_line_chain(len: usize) -> (Graph, Schedule) {
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let mut cur = a;
        for _ in 0..len {
            cur = graph.add(Op::Add, IrType::Int, vec![cur, one], None);
        }
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, cur], None);
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    /// Re-derive the linear emission positions [`plan_slots`] numbers, so a
    /// test can assert *where* a value is live. Deliberately a separate
    /// implementation of the numbering the module comment documents: if the two
    /// ever disagree, the loop test below is the one that notices.
    #[allow(clippy::type_complexity)]
    fn emission_positions(
        graph: &Graph,
        schedule: &Schedule,
    ) -> (Vec<Option<usize>>, Vec<(usize, usize)>) {
        let mut pos = vec![None; graph.nodes.len()];
        let mut span = Vec::with_capacity(schedule.blocks.len());
        let mut seq = 0usize;
        for block in &schedule.blocks {
            let start = seq;
            for &nid in &block.nodes {
                pos[nid as usize] = Some(seq);
                seq += 1;
            }
            if let Some(term) = block.terminator {
                pos[term as usize] = Some(seq);
                seq += 1;
            }
            span.push((start, seq));
            seq += 1;
        }
        (pos, span)
    }

    /// How many values the plan gives a slot to at all — the number the old
    /// reservation would have needed (one word each, forever).
    fn slotted_value_count(plan: &SlotPlan) -> usize {
        plan.node_color.iter().flatten().count()
    }

    /// The colouring's whole point: values that are never live at the same time
    /// land on the same frame word.
    #[test]
    fn non_overlapping_values_share_a_frame_slot() {
        let (graph, schedule) = straight_line_chain(64);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let slotted = slotted_value_count(&plan);
        assert_eq!(slotted, 66, "param + const + 64 adds each want a slot");
        // Successive links of the chain overlap at one position (the consumer's
        // own position), so the chain alternates between two words; the
        // constant and the parameter account for the rest.
        assert!(
            plan.slots <= 8,
            "64 chained temporaries should collapse to a handful of slots, got {}",
            plan.slots,
        );
        assert!(
            plan.slots < slotted,
            "no reuse happened at all: {} slots for {slotted} values",
            plan.slots,
        );
        assert!(
            plan.peak_live <= plan.slots,
            "peak live ({}) is the floor the colouring cannot beat, slots = {}",
            plan.peak_live,
            plan.slots,
        );
    }

    /// …and values that ARE live at the same time never do. The endpoint-
    /// inclusive overlap rule means a value whose last use is at position `p`
    /// also keeps its word against a value defined at `p`.
    #[test]
    fn overlapping_values_never_share_a_frame_slot() {
        // int f(int a, int b) { int s = a + b; return a + s; }  — `a` is live
        // across `s`, so the two cannot share; `b` dies at `s`, so it can be
        // recycled by the value defined last.
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Int, vec![start], None);
        let b = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        let s = graph.add(Op::Add, IrType::Int, vec![a, b], None);
        let t = graph.add(Op::Add, IrType::Int, vec![a, s], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, t], None);
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        let color = |id: NodeId| plan.node_color[id as usize].expect("a coloured value");

        assert_ne!(color(a), color(b), "both live into the first add");
        assert_ne!(color(a), color(s), "a outlives s's definition");
        assert_ne!(color(a), color(t), "a is live where t is defined");
        assert_ne!(color(s), color(t), "s is live where t is defined");
        // Four values, one legitimate sharing pair (b dies before t is defined).
        assert_eq!(slotted_value_count(&plan), 4);
        assert!(
            plan.slots < 4,
            "a dead-before-t value must be recycled, got {} slots",
            plan.slots,
        );

        // End to end, the code still computes a + (a + b).
        let cm = lower(&graph, &schedule, 2, 2, &no_helpers()).expect("lowers");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[3, 4]) }, Ok(10));
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[-1, 5]) }, Ok(3));
    }

    /// A value used anywhere in a loop is live across the WHOLE loop, not just
    /// up to its textually last use — otherwise the second iteration reads a
    /// word some later definition has overwritten.
    ///
    /// The liveness fixed point produces this without knowing what a loop is:
    /// the back edge makes the header's uses reach every block on the path back
    /// to it. This test pins that it actually happens.
    #[test]
    fn a_loop_carried_value_stays_live_across_the_whole_loop() {
        // int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; } —
        // `n` is compared every iteration, so it must survive the back edge.
        let code = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84,
            0x02, 0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
        ];
        let mut graph = IrBuilder::new(1, 3).build(&code, 21).expect("IR build");
        ir_optimize::optimize(&mut graph);
        // Drop the deopt snapshots: every node they name is deliberately pinned
        // to a dedicated slot, which would make this test pass for the wrong
        // reason. The pinning itself is covered by
        // `a_deopt_visible_value_keeps_a_dedicated_slot`.
        graph.safepoints.clear();
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let (_pos, span) = emission_positions(&graph, &schedule);
        // The loop: the last back edge (a successor at or before its own block
        // index — the same test `lower_block` uses to place a safepoint poll)
        // and the header it returns to.
        let mut back_edge: Option<(usize, usize)> = None;
        for (b, block) in schedule.blocks.iter().enumerate() {
            for &s in &block.successors {
                if s <= b {
                    back_edge = Some((s, b));
                }
            }
        }
        let (header, latch) = back_edge.expect("the counted loop has a back edge");
        assert!(
            header < latch,
            "precondition: the loop spans more than one block ({header}..={latch})",
        );

        let n_node = graph
            .nodes
            .iter()
            .position(|node| matches!(node.op, Op::Param(0)))
            .expect("the loop bound is a parameter") as NodeId;
        let n_range = plan.range[n_node as usize].expect("the loop bound has a live range");
        assert!(
            n_range.lo <= span[header].0 && n_range.hi >= span[latch].1,
            "the loop bound is live [{}, {}] but the loop spans [{}, {}]",
            n_range.lo,
            n_range.hi,
            span[header].0,
            span[latch].1,
        );

        // …and therefore nothing defined inside the loop took its word.
        let n_color = plan.node_color[n_node as usize].expect("a coloured value");
        for (id, color) in plan.node_color.iter().enumerate() {
            if id as NodeId == n_node || *color != Some(n_color) {
                continue;
            }
            let block = schedule.node_to_block[id];
            assert!(
                block == usize::MAX || block < header || block > latch,
                "n{id} is inside the loop (block {block}) and reused the loop \
                 bound's frame slot",
            );
        }

        // The behavioural proof is `test_lower_counted_loop_sum`, which runs
        // this exact method; keep the compile working here too.
        assert!(lower(&graph, &schedule, 1, 3, &no_helpers()).is_some());
    }

    /// A reference and a primitive never share a frame word.
    ///
    /// `emit_safepoint_map` publishes a slot as a GC root because *some* `Ref`
    /// value was defined into it, and `defined_nodes` never un-sets. If a
    /// primitive could inherit that word, the collector would follow an `int`
    /// as an object pointer. The two free lists are disjoint, so this is a
    /// property of the representation, not of the schedule.
    #[test]
    fn a_reference_is_never_aliased_with_a_non_reference() {
        // Object f(Object r, int a) { int t = a + 1; int u = t + 1; return r; }
        // `r` is live to the return; `a`, `t`, `u` die in sequence, so the
        // primitive pool recycles while the reference pool does not.
        let mut graph = empty_graph();
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let r = graph.add(Op::Param(0), IrType::Ref, vec![start], None);
        let a = graph.add(Op::Param(1), IrType::Int, vec![start], None);
        let one = graph.add(Op::Const(1), IrType::Int, vec![], None);
        let t = graph.add(Op::Add, IrType::Int, vec![a, one], None);
        let u = graph.add(Op::Add, IrType::Int, vec![t, one], None);
        let v = graph.add(Op::Add, IrType::Int, vec![u, one], None);
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, r], None);
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        // Reuse did happen among the primitives…
        assert!(
            plan.slots < slotted_value_count(&plan),
            "the primitive chain should have recycled a word",
        );
        // …and no word holds both classes.
        let mut class_of_color: HashMap<u32, SlotClass> = HashMap::new();
        for (id, color) in plan.node_color.iter().enumerate() {
            let (color, class) = match (color, plan.class[id]) {
                (Some(color), Some(class)) => (*color, class),
                _ => continue,
            };
            match class_of_color.get(&color) {
                Some(seen) => assert_eq!(
                    *seen, class,
                    "slot {color} mixes {seen:?} and {class:?} (n{id})",
                ),
                None => {
                    class_of_color.insert(color, class);
                }
            }
        }
        // The reference genuinely got a word of its own, not merely a word no
        // primitive happened to want.
        let r_color = plan.node_color[r as usize].expect("a coloured reference");
        assert_eq!(class_of_color.get(&r_color), Some(&SlotClass::Ref));
        for id in [a, t, u, v] {
            assert_ne!(
                plan.node_color[id as usize],
                Some(r_color),
                "n{id} is a primitive on the reference's word",
            );
        }

        // …and the stale-word oracle's view of the same plan agrees: every
        // primitive's colour is offered as "provably not a reference", and the
        // reference's colour is not. This is what an IR frame publishes as
        // `OopMapEntry::non_oop_stack_slots`, and a colour wrongly listed here
        // would let the residue report call a live root dead storage.
        let prim = plan.prim_colors();
        for id in [a, t, u, v] {
            let c = plan.node_color[id as usize].expect("a coloured primitive");
            assert!(
                prim.contains(&c),
                "n{id}'s word {c} is missing from prim_colors"
            );
        }
        assert!(
            !prim.contains(&r_color),
            "the reference's word {r_color} must never be offered as a non-reference",
        );
    }

    /// COV-02: an `aaload` result is a GC ROOT, and this is the executed proof.
    ///
    /// `emit_safepoint_map` decides what to publish by scanning
    /// `graph.nodes[id].ty != IrType::Ref`, and `plan_slots` decides which pool
    /// a node's frame word comes from. Both answers hang on the ONE thing the
    /// `aaload` builder arm chooses: the node's `IrType`. Typing it `Int`
    /// compiles, passes every value-differential in
    /// `jit/tests/ir_vs_singlepass.rs`, and loses the element at the first
    /// relocating collection — a failure that surfaces nowhere near here.
    ///
    /// The brief's own suggestion for proving this — run it under
    /// `CRATONVM_MOVING_YOUNG` — cannot work: `JIT_PUBLISHES_RELOCATION_CONTRACT`
    /// is `false`, so a young collection that meets an unprovable compiled frame
    /// falls back to the non-moving sweep instead of relocating, and an
    /// unpublished root produces no observable stale pointer. See
    /// `cov-02-array-element-access-RETIRED-20260803.md`. So the
    /// property is asserted where it is actually decided.
    ///
    /// **Anti-vacuity, executed rather than argued.** The mutation was run:
    /// with `0x32`'s arm in `ir.rs` changed to `(MemKind::Ref, IrType::Int)`,
    /// this test fails with `left: Int, right: Ref` and nothing else in the
    /// crate's 1,869 lib tests notices. That is the edit to repeat if this test
    /// is ever suspected of measuring something else.
    ///
    /// It has already been wrong once in the other direction: it first asserted
    /// `class == SlotClass::Ref` and failed on an honest tree, because in a
    /// method this short the element is still deopt-visible and gets pinned.
    /// See the comment at the assertion.
    #[test]
    fn an_aaload_result_is_reference_typed_and_takes_a_reference_slot() {
        use crate::ir::{IrBuilder, MemKind};

        // static Object get(Object[] a, int i) { return a[i]; }
        //   aload_0; iload_1; aaload; areturn      (+2 bytes of padding)
        let code = [0x2a, 0x1b, 0x32, 0xb0, 0x00, 0x00];
        let graph = IrBuilder::new(2, 2)
            .build(&code, 4)
            .expect("the aaload corpus must build");

        let loads: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::ArrayLoad(MemKind::Ref)))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert_eq!(
            loads.len(),
            1,
            "precondition: exactly one `aaload` node, or this test is measuring \
             something else"
        );
        let load = loads[0];
        assert_eq!(
            graph.nodes[load as usize].ty,
            IrType::Ref,
            "an `aaload` result is a reference; `emit_safepoint_map` skips every \
             node whose `ty` is not `Ref`, so an `Int` here is an unpublished \
             root at every later safepoint"
        );

        // …and no primitive may ever inherit the word it lands in, because
        // `emit_safepoint_map` will name that word as a root.
        //
        // Asserted as an ALIASING property rather than as `class ==
        // SlotClass::Ref`, which is what this test tried first and which is
        // wrong: in a method this short the element is still on the operand
        // stack at the `areturn` bci, so a safepoint snapshot names it and
        // `plan_slots` pins it (`SlotClass::Pinned` — shares with nothing at
        // all, strictly stronger than the reference pool). Which of the two it
        // gets depends on where the value dies, i.e. on the fixture. What must
        // hold for every fixture is that no `Prim` sits on its colour.
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        let class = plan.class[load as usize].expect("the element must get a frame word");
        assert_ne!(
            class,
            SlotClass::Prim,
            "an `aaload` result took a word from the PRIMITIVE pool; the \
             collector would then follow whatever int recycled it as an object \
             pointer"
        );
        let color = plan.node_color[load as usize].expect("a coloured element");
        for (id, other) in plan.node_color.iter().enumerate() {
            if id == load as usize || *other != Some(color) {
                continue;
            }
            assert_ne!(
                plan.class[id],
                Some(SlotClass::Prim),
                "n{id} is a primitive sharing the `aaload` element's frame word",
            );
        }
    }

    /// Every value a deopt frame names keeps a dedicated slot: the deopt
    /// producer reads it at a native offset chosen at run time, so "dead by
    /// then" is not a question this file can answer.
    #[test]
    fn a_deopt_visible_value_keeps_a_dedicated_slot() {
        let (mut graph, _) = straight_line_chain(8);
        // Name the first two adds in a snapshot, exactly as `IrBuilder` would
        // for a bytecode boundary whose locals hold them.
        let adds: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id as NodeId)
            .take(2)
            .collect();
        graph.safepoints.push(SafepointSnapshot::new(
            0,
            vec![adds[0]],
            vec![adds[1]],
            Vec::new(),
        ));
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        for &pinned in &adds {
            assert_eq!(
                plan.class[pinned as usize],
                Some(SlotClass::Pinned),
                "n{pinned} is named by a deopt frame and must not share",
            );
            let color = plan.node_color[pinned as usize].expect("a coloured value");
            let sharers = plan
                .node_color
                .iter()
                .filter(|c| **c == Some(color))
                .count();
            assert_eq!(sharers, 1, "n{pinned}'s word is shared by {sharers} values");
        }
    }

    /// Round 14 wave 1 (lane chain): a value only a CHAIN snapshot names is
    /// not pinned (`CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS`, default on);
    /// its colouring range reaches the node that could publish the chain, and
    /// no value whose range meets that one takes its word. With the switch at
    /// `0` it is pinned, as before.
    #[test]
    fn r14w1_chain_named_value_is_ranged_to_its_reader_not_pinned() {
        let (mut graph, _) = straight_line_chain(8);
        let adds: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id as NodeId)
            .collect();
        // A chain snapshot at combined pc 40 naming the first add, and the
        // sixth add sitting at pc 40 (a node a guard could be lowered for).
        let mut sp = SafepointSnapshot::new(40, vec![adds[0]], Vec::new(), Vec::new());
        sp.splice_scope = Some(Box::new(crate::ir::SpliceScopeChain { scopes: Vec::new() }));
        graph.safepoints.push(sp);
        graph.nodes[adds[5] as usize].bytecode_pc = Some(40);
        let schedule = ir_schedule::schedule(&graph);
        let (pos, _) = emission_positions(&graph, &schedule);
        let reader = pos[adds[5] as usize].expect("the reader is scheduled");
        let first = adds[0] as usize;

        let plan = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS", None)],
            || plan_slots(&graph, &schedule, None),
        );
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        assert_ne!(plan.class[first], Some(SlotClass::Pinned));
        assert_eq!(plan.chain_ranged, 1);
        let value = plan.range[first].expect("a value range");
        assert!(value.hi < reader, "precondition: its last value use is earlier");
        let widened = plan.colouring_ranges()[first].expect("a colouring range");
        assert!(widened.lo <= value.lo && widened.hi >= reader);
        let color = plan.node_color[first].expect("a coloured value");
        for (id, c) in plan.node_color.iter().enumerate() {
            if id == first || *c != Some(color) {
                continue;
            }
            let other = plan.colouring_ranges()[id].expect("a colouring range");
            assert!(
                !other.overlaps(widened),
                "n{id} [{}, {}] took the chain-named word inside [{}, {}]",
                other.lo,
                other.hi,
                widened.lo,
                widened.hi
            );
        }

        let pinned = cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_CHAIN_SNAPSHOT_RANGE_PINS", Some("0"))],
            || plan_slots(&graph, &schedule, None),
        );
        assert_eq!(pinned.class[first], Some(SlotClass::Pinned));
        assert_eq!(pinned.chain_ranged, 0);
        assert!(pinned.colour_range.is_empty());
    }

    /// The colouring verifier is a real check, not a comment: each way a
    /// colouring could go wrong is refused.
    #[test]
    fn the_colouring_verifier_rejects_an_aliased_plan() {
        let (graph, schedule) = straight_line_chain(8);
        let good = plan_slots(&graph, &schedule, None);
        assert!(verify_slot_colouring(&graph, &schedule, &good).is_ok());

        let adds: Vec<usize> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::Add))
            .map(|(id, _)| id)
            .collect();

        // (a) Two values that ARE live together forced onto one word — the
        //     silent-wrong-code case.
        let mut aliased = plan_slots(&graph, &schedule, None);
        let (first, second) = (adds[0], adds[1]);
        assert!(
            aliased.range[first]
                .expect("range")
                .overlaps(aliased.range[second].expect("range")),
            "precondition: consecutive chain links overlap",
        );
        let (donor_color, donor_class) = (aliased.node_color[first], aliased.class[first]);
        aliased.node_color[second] = donor_color;
        aliased.class[second] = donor_class;
        let err = verify_slot_colouring(&graph, &schedule, &aliased)
            .expect_err("an aliased pair must be refused");
        assert_eq!(err.category(), "internal");
        assert!(
            err.to_string().contains("simultaneously live"),
            "unexpected reason: {err}",
        );

        // (b) A reference on a primitive's word.
        let mut mixed = plan_slots(&graph, &schedule, None);
        let shared = mixed.node_color[adds[0]];
        mixed.node_color[adds[2]] = shared;
        mixed.class[adds[2]] = Some(SlotClass::Ref);
        mixed.class[adds[0]] = Some(SlotClass::Prim);
        let err = verify_slot_colouring(&graph, &schedule, &mixed)
            .expect_err("a mixed-class word must be refused");
        assert!(
            err.to_string().contains("reference and primitive"),
            "unexpected reason: {err}",
        );

        // (c) A value the lowerer will allocate for, left uncoloured — the
        //     scheduler-omission class `verify_data_locations` guards, restated
        //     for the plan.
        let mut missing = plan_slots(&graph, &schedule, None);
        missing.node_color[adds[0]] = None;
        let err = verify_slot_colouring(&graph, &schedule, &missing)
            .expect_err("an uncoloured scheduled value must be refused");
        assert_eq!(err.category(), "unallocated_value");

        // (d) A colour outside the reservation the frame was sized from.
        let mut oversized = plan_slots(&graph, &schedule, None);
        let beyond = oversized.slots as u32 + 1;
        oversized.node_color[adds[0]] = Some(beyond);
        assert!(verify_slot_colouring(&graph, &schedule, &oversized).is_err());
    }

    /// The measurement the report asks for: frame bytes against node count on a
    /// long straight-line method.
    #[test]
    fn frame_bytes_track_peak_liveness_not_node_count() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };
        let (graph, schedule) = straight_line_chain(512);
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");

        let before = estimate_frame_bytes(0, graph.nodes.len(), &plain);
        let after = estimate_frame_bytes(0, plan.slots, &plain);
        assert!(
            after * 8 < before,
            "frame bytes only fell from {before} to {after} on a 512-link chain",
        );
        // The residual is the fixed part of the frame — bookkeeping slots, the
        // stack-arg reserve, the ABI shadow space and, since the register file
        // went default-on (2026-09-02), the estimate's reservation for the
        // callee-saved GP save area — not spill.
        // The 2026-09-05 default-on of the deopt register image adds its 256
        // bytes to the same fixed part. Read from the function the frame is
        // laid out with rather than folded into the literal, so the bound
        // still means "no spill" on a configuration that reserves neither.
        //
        // The GP save area is now read the same way, for the same reason: it
        // is 40 bytes on System V and 56 on Win64, where RSI/RDI joined
        // `IR_GP_LINEAR_SCAN` (2026-09-10). It had been folded into the 192,
        // which made this bound a Windows-vs-Linux coin the moment the file
        // stopped being the same width on both.
        let fixed = 152 + ir_saved_gpr_bytes() as usize + ir_deopt_regs_bytes() as usize;
        assert!(
            after <= fixed,
            "{after} bytes for a 4-slot working set (fixed part is {fixed})",
        );
    }

    /// The node ceiling the frame bound implies, before and after.
    ///
    /// One 8-byte slot per node put the ceiling at ~4 000 nodes: past that the
    /// frame estimate crossed `DEFAULT_MAX_FRAME_BYTES` and the optimizing tier
    /// declined the method outright. Sized by peak liveness instead, a long
    /// method is bounded by `DEFAULT_MAX_NODES` again.
    #[test]
    fn a_previously_declined_large_method_now_compiles() {
        let plain = FrameNeeds {
            needs_context: false,
            max_call_args: 0,
        };

        // Where the old accounting stopped: the largest node count whose
        // one-slot-per-node frame still fit.
        let old_ceiling = (1..=DEFAULT_MAX_NODES)
            .take_while(|&n| estimate_frame_bytes(0, n, &plain) <= DEFAULT_MAX_FRAME_BYTES)
            .last()
            .expect("some node count fits");
        assert!(
            (4000..4200).contains(&old_ceiling),
            "the old ceiling was ~4 000 nodes, computed {old_ceiling}",
        );

        let (graph, schedule) = straight_line_chain(5_000);
        assert!(
            graph.nodes.len() > old_ceiling,
            "precondition: this method was over the old ceiling",
        );
        assert!(
            check_frame_size(
                estimate_frame_bytes(0, graph.nodes.len(), &plain),
                DEFAULT_MAX_FRAME_BYTES,
            )
            .is_err(),
            "precondition: one slot per node would still be refused",
        );

        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("a sound colouring");
        assert!(
            check_frame_size(
                estimate_frame_bytes(1, plan.slots, &plain),
                DEFAULT_MAX_FRAME_BYTES,
            )
            .is_ok(),
            "{} slots should fit comfortably",
            plan.slots,
        );

        // And it really compiles and really runs.
        let cm = lower(&graph, &schedule, 1, 1, &no_helpers()).expect("a 5 000-node method lowers");
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[0]) }, Ok(5_000));
        // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
        assert_eq!(unsafe { cm.try_call(&[42]) }, Ok(5_042));
    }

    // ── Phi parallel copy (the swap-loop wrong-code fix) ─────────────────
    //
    // `prealloc_phi_slots` gives every phi its OWN frame word, so the copies on
    // one CFG edge are a parallel assignment over distinct words. Emitted in
    // gather order through RAX — which is what this file did — a loop that
    // swaps two locals makes each phi the other's back-edge value, the second
    // copy reads the word the first just overwrote, and both locals end up
    // holding the same value. These tests execute the emitted bytes, because
    // that bug is invisible to any assertion about the copy *list*.

    /// Value seeded into the reserved scratch word before every harness run, so
    /// a test can prove an acyclic copy never touched it.
    const SCRATCH_SENTINEL: i64 = 0x0BAD_5C7A_0000_1234;

    /// Emit `push rbp; mov rbp,rsp; sub rsp,frame`, seed the named frame words
    /// (plus the scratch, with [`SCRATCH_SENTINEL`]), run `copies` through the
    /// REAL sequencer and the REAL emitter, load one word into RAX and return.
    /// Then execute it.
    ///
    /// `read_back == None` reads the reserved scratch word itself.
    ///
    /// The frame is a genuine `Lowerer` frame (so the offsets, the scratch
    /// reservation and `frame_size` are the ones production uses); only the
    /// prologue/epilogue are hand-rolled, because the real ones fetch a thread
    /// and touch the shadow stack that this fixture has no helpers for.
    fn parallel_copy_harness(
        seed: &[(i32, i64)],
        copies: &[(i32, i32)],
        read_back: Option<i32>,
    ) -> (i64, Vec<CopyOp>) {
        // Eight locals so the harness has plenty of frame words BELOW the
        // bookkeeping reservation to use as stand-in phi slots.
        const HARNESS_LOCALS: usize = 8;

        let (graph, schedule) = add_one_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let mut lowerer = Lowerer::new(
            &graph,
            &schedule,
            buf,
            0,
            HARNESS_LOCALS,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &no_frame_sites,
        );
        let scratch = lowerer.phi_copy_scratch_slot_off;
        let frame = lowerer.frame_size;
        for &(off, _) in seed {
            assert!(
                off > 0 && off < frame && off != scratch,
                "the fixture must name a real frame word other than the scratch: {off}",
            );
        }

        // push rbp ; mov rbp, rsp ; sub rsp, frame_size
        lowerer.buf.emit_byte(0x55);
        lowerer.buf.emit(&[0x48, 0x89, 0xE5]);
        lowerer.buf.emit(&[0x48, 0x81, 0xEC]);
        lowerer.buf.emit(&frame.to_le_bytes());

        let scratch_seed = [(scratch, SCRATCH_SENTINEL)];
        for &(off, val) in seed.iter().chain(scratch_seed.iter()) {
            lowerer.emit_mov_reg_imm64(RAX, val as u64);
            lowerer.store_rax(off);
        }

        let ops = phi_copy_sequence(copies).expect("the fixture's copies sequentialise");
        for op in ops.iter().copied() {
            lowerer
                // No `defer_publish`: this fixture drives the memory path only
                // (`src_node_of`/`phi_of_dst` are empty, so nothing publishes a
                // register and nothing can alias one).
                .emit_copy_op(op, &HashMap::new(), &HashMap::new(), &[], &mut Vec::new())
                .expect("every location in this backend is a frame word");
        }

        lowerer.load_to_rax(read_back.unwrap_or(scratch));
        // add rsp, frame_size ; pop rbp ; ret
        lowerer.buf.emit(&[0x48, 0x81, 0xC4]);
        lowerer.buf.emit(&frame.to_le_bytes());
        lowerer.buf.emit_byte(0x5D);
        lowerer.buf.emit_byte(0xC3);
        assert!(!lowerer.buf.overflowed(), "the harness body must fit");

        let cm = CompiledMethod::new(lowerer.buf);
        // SAFETY: the emitted body takes no arguments, reads only its own
        // frame, calls nothing and returns an i64 in RAX.
        let value = unsafe { cm.try_call(&[]) }.expect("the harness body runs");
        (value, ops)
    }

    fn count_kind(ops: &[CopyOp], f: impl Fn(&CopyOp) -> bool) -> usize {
        ops.iter().copied().filter(|o| f(o)).count()
    }

    /// The swap loop's back edge, at the machine level: `a <- b, b <- a`.
    ///
    /// Sequential emission through RAX put `b`'s value in BOTH words. This is
    /// the wrong-code witness, asserted by running the bytes.
    #[test]
    fn a_two_element_phi_cycle_really_swaps_the_two_frame_words() {
        let (a, b) = (8i32, 16i32);
        let seed = [(a, 0x1111_1111i64), (b, 0x2222_2222i64)];
        let copies = [(a, b), (b, a)];

        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        assert_eq!(got_a, 0x2222_2222, "a must receive b's PRE-copy value");
        assert_eq!(
            got_b, 0x1111_1111,
            "b must receive a's PRE-copy value — 0x22222222 here is the old \
             sequential-emission bug, in which both words ended up holding b",
        );

        // One save/restore pair breaks the cycle; the third op is the move.
        assert_eq!(ops.len(), 3, "{ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Restore { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Move { .. })), 1);

        // …and the scratch word really is where the parked value went.
        let (scratch_after, _) = parallel_copy_harness(&seed, &copies, None);
        assert_ne!(
            scratch_after, SCRATCH_SENTINEL,
            "a cycle must go through the reserved scratch word",
        );
    }

    /// A three-element cycle rotates; the last move IS the restore, so it costs
    /// one save, two moves and one restore.
    #[test]
    fn a_three_element_phi_cycle_rotates_the_frame_words() {
        let (a, b, c) = (8i32, 16i32, 24i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64)];
        // a <- b, b <- c, c <- a
        let copies = [(a, b), (b, c), (c, a)];

        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        assert_eq!((got_a, got_b, got_c), (2, 3, 1), "{ops:?}");

        assert_eq!(ops.len(), 4, "one save, two moves, one restore: {ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 1);
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Restore { .. })), 1);
    }

    /// The acyclic majority — every merge that is not a permutation — must be
    /// unchanged: one load + one store per copy, and the scratch word untouched.
    #[test]
    fn an_acyclic_phi_chain_emits_the_minimal_moves_and_no_scratch() {
        let (a, b, c) = (8i32, 16i32, 24i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64)];
        // b <- a, c <- b. Gather order would overwrite b before c reads it.
        let copies = [(b, a), (c, b)];

        let (got_b, ops) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        assert_eq!(got_b, 1, "b <- a");
        assert_eq!(got_c, 2, "c must read b's PRE-copy value: {ops:?}");

        assert_eq!(
            ops,
            vec![
                CopyOp::Move {
                    from: frame_word_loc(b).expect("a frame word"),
                    to: frame_word_loc(c).expect("a frame word"),
                },
                CopyOp::Move {
                    from: frame_word_loc(a).expect("a frame word"),
                    to: frame_word_loc(b).expect("a frame word"),
                },
            ],
            "an acyclic web must cost exactly one move per copy",
        );

        let (scratch_after, _) = parallel_copy_harness(&seed, &copies, None);
        assert_eq!(
            scratch_after, SCRATCH_SENTINEL,
            "an acyclic web must not touch the reserved scratch word",
        );
    }

    /// A copy to itself is not a move: it must emit nothing at all, so a merge
    /// whose phi already lives in its source's word costs zero instructions.
    #[test]
    fn a_self_copy_emits_nothing() {
        let ops = phi_copy_sequence(&[(8, 8), (16, 16)]).expect("sequentialises");
        assert!(ops.is_empty(), "{ops:?}");
    }

    /// ONE scratch word is enough however many cycles an edge contains: the
    /// sequencer always consumes a save before it starts the next cycle. If
    /// that ever stopped being true the saves would nest and the single
    /// reserved word would be clobbered, so pin it here — this file's frame
    /// reservation is what depends on it.
    #[test]
    fn disjoint_phi_cycles_never_nest_their_saves() {
        let (a, b, c, d) = (8i32, 16i32, 24i32, 32i32);
        let seed = [(a, 1i64), (b, 2i64), (c, 3i64), (d, 4i64)];
        let copies = [(a, b), (b, a), (c, d), (d, c)];

        let mut saved = false;
        let (got_a, ops) = parallel_copy_harness(&seed, &copies, Some(a));
        for op in &ops {
            match op {
                CopyOp::Save { .. } => {
                    assert!(!saved, "a second save before the first restore: {ops:?}");
                    saved = true;
                }
                CopyOp::Restore { .. } => {
                    assert!(saved, "a restore with nothing saved: {ops:?}");
                    saved = false;
                }
                CopyOp::Move { .. } => {}
            }
        }
        assert!(!saved, "an unconsumed save: {ops:?}");
        assert_eq!(count_kind(&ops, |o| matches!(o, CopyOp::Save { .. })), 2);

        let (got_b, _) = parallel_copy_harness(&seed, &copies, Some(b));
        let (got_c, _) = parallel_copy_harness(&seed, &copies, Some(c));
        let (got_d, _) = parallel_copy_harness(&seed, &copies, Some(d));
        assert_eq!((got_a, got_b, got_c, got_d), (2, 1, 4, 3));
    }

    /// A register is representable in the shared `ValueLoc` but unreachable
    /// here — this backend keeps every value in its home frame word. Refused,
    /// not mis-emitted as an offset.
    #[test]
    fn a_register_location_is_refused_rather_than_emitted_as_an_offset() {
        let err = frame_word_off(ValueLoc::Reg(crate::regalloc::PhysReg::gp(3)))
            .expect_err("a register is not a frame word");
        assert!(matches!(err.reason, BailoutReason::Internal(_)), "{err:?}",);
        // …and offset 0 (`[rbp - 0]` is the saved caller RBP) is not a location.
        assert!(frame_word_loc(0).is_err());
        assert!(frame_word_loc(-8).is_err());
    }

    /// The scratch is a BOOKKEEPING word: it sits below `first_spill`, so no
    /// colour `plan_slots` hands out can ever land on it, and the five reserved
    /// words are contiguous with no gap for a coloured slot to hide in.
    ///
    /// Also the frame arithmetic: `estimate_frame_bytes` (which `lower_inner`
    /// bounds against) must still equal the frame `Lowerer::new` lays out. The
    /// constructor pins that with a `debug_assert_eq!`; this asserts it in a
    /// release build too, and from the published offsets rather than from a
    /// repetition of the same sum.
    #[test]
    fn the_phi_scratch_word_is_reserved_below_the_spill_band() {
        for &num_locals in &[0usize, 1, 8] {
            let (graph, schedule) = add_one_graph();
            let plan = plan_slots(&graph, &schedule, None);
            let empty: HashMap<usize, bool> = HashMap::new();
            let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
            let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
            let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
            let no_frame_sites = crate::ir::IrInlineFrameSites::default();
            let buf = ExecutableBuffer::new(4096).expect("executable buffer");
            let helpers = no_helpers();
            let lowerer = Lowerer::new(
                &graph,
                &schedule,
                buf,
                0,
                num_locals,
                &plan,
                &helpers,
                &empty,
                &[],
                None,
                &no_direct,
                &no_ic,
                &no_compact,
                &no_frame_sites,
            );

            // The five bookkeeping words are contiguous and end at first_spill.
            assert_eq!(lowerer.shadow_thread_slot_off, lowerer.sp_id_slot_off + 8);
            assert_eq!(
                lowerer.shadow_savebase_slot_off,
                lowerer.shadow_thread_slot_off + 8
            );
            assert_eq!(
                lowerer.shadow_savetop_slot_off,
                lowerer.shadow_savebase_slot_off + 8
            );
            assert_eq!(
                lowerer.phi_copy_scratch_slot_off,
                lowerer.shadow_savetop_slot_off + 8,
                "the scratch is the fifth reserved word",
            );
            assert_eq!(
                lowerer.first_spill,
                lowerer.phi_copy_scratch_slot_off + 8,
                "the spill band starts one word above the scratch",
            );

            // No coloured slot can collide with it.
            for color in 0..plan.slots as i32 {
                assert_ne!(
                    lowerer.first_spill + color * 8,
                    lowerer.phi_copy_scratch_slot_off,
                );
            }
            assert!(lowerer.first_spill <= lowerer.spill_cap_off);

            // The estimate `lower_inner` bounds against is the frame that got
            // built — including the fifth reserved word.
            let needs = scan_frame_needs(&graph, &helpers);
            assert_eq!(
                lowerer.frame_size,
                estimate_frame_bytes(num_locals, plan.slots, &needs) as i32,
            );
            // …and that number really does account for locals + 5 bookkeeping
            // words + the spill band + the callee-saved save bands + the
            // 16-byte stack-arg reserve + the 32-byte ABI shadow.
            // `add_one_graph` needs no context slot and stages no call
            // arguments.
            //
            // The two save bands are read from the same functions the frame
            // was laid out with rather than spelled as literals: they are
            // platform- and flag-dependent (`IR_LOWER_SAVED_XMMS` is empty on
            // System V; both are empty with the linear-scan path off), and a
            // literal here would pin this test to one configuration.
            let locals_size = (num_locals as i32) * 8;
            let bookkeeping = 8 * 5;
            // `ir_deopt_regs_bytes` joined the other two on 2026-09-05, when
            // the register image went default-on. Read, not spelled, for the
            // reason the comment above gives.
            let saved = ir_saved_xmm_bytes() + ir_saved_gpr_bytes() + ir_deopt_regs_bytes();
            let tail = 32 + 16;
            assert_eq!(
                lowerer.frame_size,
                ((locals_size + bookkeeping + (plan.slots as i32) * 8 + saved + tail) + 15) & !15,
            );
            assert_eq!(lowerer.spill_cap_off, lowerer.frame_size - tail - saved);
            // Offsets are 1-based — `[rbp - 0]` is the saved caller RBP — so the
            // first spill word sits one word past the locals + bookkeeping bytes.
            assert_eq!(lowerer.first_spill, locals_size + bookkeeping + 8);
        }
    }

    /// End to end, on the shape the fix exists for.
    ///
    /// ```java
    /// static int f(int a, int b, int n) {
    ///     for (int i = 0; i < n; i++) { int t = a; a = b; b = t; }
    ///     return a - b;
    /// }
    /// ```
    ///
    /// The two loop-header phis are each other's back-edge value, so the back
    /// edge's parallel copy is a two-element cycle. Before the scratch word this
    /// method REFUSED to compile (`UnsupportedShape("cyclic phi parallel
    /// copy")`) and dropped to a lower tier; before that it compiled to wrong
    /// code. `a - b` is the sharp readout: `0` is what both duplication bugs
    /// (both words ending up with `a`, or both with `b`) produce.
    #[test]
    fn the_swap_loop_compiles_and_swaps() {
        //  0: iconst_0     03
        //  1: istore_3     3e          i = 0
        //  2: iload_3      1d      ← loop header
        //  3: iload_2      1c
        //  4: if_icmpge 17 a2 00 0d
        //  7: iload_1      1b          swap through the operand stack:
        //  8: iload_0      1a          stack = [b, a]
        //  9: istore_1     3c          b = a
        // 10: istore_0     3b          a = b
        // 11: iinc 3,1     84 03 01
        // 14: goto 2       a7 ff f4
        // 17: iload_0      1a
        // 18: iload_1      1b
        // 19: isub         64
        // 20: ireturn      ac
        let code = [
            0x03, 0x3e, 0x1d, 0x1c, 0xa2, 0x00, 0x0d, 0x1b, 0x1a, 0x3c, 0x3b, 0x84, 0x03, 0x01,
            0xa7, 0xff, 0xf4, 0x1a, 0x1b, 0x64, 0xac, 0, 0,
        ];
        let cm = compile_via_ir(&code, 21, 3, 4).expect(
            "the swap loop must COMPILE — a None here is the cyclic-parallel-copy \
             refusal coming back, which drops the method a tier",
        );
        // `ireturn` leaves a 32-bit value in the return register, so the raw
        // i64 readout carries an untouched upper half and a negative result
        // reads as its u32 bit pattern (-4 as 0xFFFF_FFFC). Sign-extend before
        // comparing, or a correct swap reports as a failure.
        let f = |a: i64, b: i64, n: i64| {
            // SAFETY: the body was compiled by this test for exactly these argument kinds, and runs on this thread against the test's own live data and helper table.
            let raw = unsafe { cm.try_call(&[a, b, n]).expect("call") };
            raw as i32 as i64
        };
        assert_eq!(f(3, 7, 0), -4, "no iterations: 3 - 7");
        assert_eq!(f(3, 7, 1), 4, "one swap: 7 - 3 (0 would mean a == b)");
        assert_eq!(f(3, 7, 2), -4, "two swaps: back to 3 - 7");
        assert_eq!(f(3, 7, 3), 4, "three swaps");
        assert_eq!(f(-9, 5, 1), 14, "5 - (-9)");
    }

    // ── Inlined caller scopes → `FrameState::caller` ─────────────────────

    /// A trivially lowerable graph (`Start → Proj ctrl/mem → Param(0) →
    /// Const(7) → Return`) with no safepoints; the caller pushes whatever
    /// snapshots the test needs. Returns the `Const` node id, which resolves to
    /// `FrameValue::Int(7)` with no machine location — the simplest slot a
    /// snapshot can name.
    fn scope_fixture_graph() -> (Graph, NodeId) {
        let mut g = Graph::empty(0);
        let start = g.add(Op::Start, IrType::Control, vec![], None);
        let ctrl = g.add(Op::Proj(0), IrType::Control, vec![start], None);
        let _mem = g.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let p0 = g.add(Op::Param(0), IrType::Int, vec![start], None);
        let k = g.add(Op::Const(7), IrType::Int, vec![], None);
        let ret = g.add(Op::Return, IrType::Void, vec![ctrl, p0], None);
        g.exit = ret;
        (g, k)
    }

    /// Resolve `graph.safepoints[index]` through a real `Lowerer`, i.e. exactly
    /// the path `build_deopt_points` takes.
    fn resolve_snapshot(graph: &Graph, index: usize) -> FrameState {
        let schedule = ir_schedule::schedule(graph);
        let plan = plan_slots(graph, &schedule, None);
        let empty: HashMap<usize, bool> = HashMap::new();
        let no_direct: HashMap<usize, (usize, bool)> = HashMap::new();
        let no_ic: HashMap<usize, (usize, usize)> = HashMap::new();
        let no_compact: HashMap<(usize, bool), (u32, bool, u8)> = HashMap::new();
        let buf = ExecutableBuffer::new(4096).expect("executable buffer");
        let helpers = no_helpers();
        let no_frame_sites = crate::ir::IrInlineFrameSites::default();
        let lowerer = Lowerer::new(
            graph,
            &schedule,
            buf,
            1,
            1,
            &plan,
            &helpers,
            &empty,
            &[],
            None,
            &no_direct,
            &no_ic,
            &no_compact,
            &no_frame_sites,
        );
        lowerer.resolve_frame_state(index, &graph.safepoints[index])
    }

    /// A held monitor lowers with `relock` saying whether the compiled code
    /// took the lock itself. A live monitor op on the object ⇒ `false` (the
    /// thread already holds it). Every monitor op on it killed, the way
    /// `apply_ea_to_ir`'s lock elision leaves them ⇒ `true` (the resume must
    /// acquire it).
    #[test]
    fn a_held_monitor_is_marked_relock_only_when_its_ops_were_elided() {
        // aload_0; monitorenter; aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc3, 0xb1, 0, 0];
        let live = IrBuilder::new(1, 1).build(&code, 5).expect("build");
        let index = live
            .safepoints
            .iter()
            .position(|s| s.bci == 3)
            .expect("a snapshot at the monitorexit");

        let fs = resolve_snapshot(&live, index);
        assert_eq!(fs.monitors.len(), 1, "the lock is recorded");
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock, "a live lock is not re-acquired");

        let mut elided = IrBuilder::new(1, 1).build(&code, 5).expect("build");
        let monitor_ops: Vec<NodeId> = elided
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.op, Op::MonitorEnter | Op::MonitorExit))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert_eq!(monitor_ops.len(), 2);
        for id in monitor_ops {
            elided.kill(id);
        }
        let fs = resolve_snapshot(&elided, index);
        assert_eq!(fs.monitors.len(), 1, "an elided lock is still recorded");
        assert!(
            fs.monitors[0].relock,
            "no live monitor op names the object, so the resume must acquire it"
        );
    }

    /// Re-entrant locking of one object is ONE `MonitorInfo` with
    /// `lock_depth` 2 — the install verifier refuses two entries on one object.
    #[test]
    fn a_reentrant_lock_coalesces_into_one_entry_with_its_depth() {
        // aload_0; monitorenter; aload_0; monitorenter; aload_0; monitorexit;
        // aload_0; monitorexit; return
        let code = [0x2a, 0xc2, 0x2a, 0xc2, 0x2a, 0xc3, 0x2a, 0xc3, 0xb1, 0, 0];
        let g = IrBuilder::new(1, 1).build(&code, 9).expect("build");
        let index = g
            .safepoints
            .iter()
            .position(|s| s.bci == 5)
            .expect("a snapshot at the inner monitorexit");
        assert_eq!(g.safepoints[index].monitors.len(), 2, "two enters recorded");
        let fs = resolve_snapshot(&g, index);
        assert_eq!(fs.monitors.len(), 1);
        assert_eq!(fs.monitors[0].lock_depth, 2);
    }

    /// Round 11 wave 14 (lane fib): once `ir_optimize::elide_nested_monitors`
    /// deleted the inner region, a frame inside it is TWO entries on the one
    /// object -- the level the compiled code holds (`relock == false`), then
    /// the elided one (`relock == true`) -- and a frame outside it is the
    /// ordinary single held entry. The resume enters the second entry once, so
    /// the thread holds the object twice, as the interpreter frame expects.
    #[test]
    fn r11w14_a_nested_elided_lock_splits_into_held_and_relock_entries() {
        let code = [0x2a, 0xc2, 0x2a, 0xc2, 0x2a, 0xc3, 0x2a, 0xc3, 0xb1, 0, 0];
        let mut g = IrBuilder::new(1, 1).build(&code, 9).expect("build");
        assert_eq!(crate::ir_optimize::elide_nested_monitors(&mut g), 1);
        let inner = g
            .safepoints
            .iter()
            .position(|s| s.bci == 5)
            .expect("a snapshot at the inner monitorexit");
        let fs = resolve_snapshot(&g, inner);
        assert_eq!(fs.monitors.len(), 2, "held and elided levels are split");
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock, "the outer level is still held");
        assert_eq!(fs.monitors[1].lock_depth, 1);
        assert!(
            fs.monitors[1].relock,
            "the elided level must be re-acquired"
        );
        assert_eq!(fs.monitors[0].object, fs.monitors[1].object);

        let outer = g
            .safepoints
            .iter()
            .position(|s| s.bci == 7)
            .expect("a snapshot at the outer monitorexit");
        let fs = resolve_snapshot(&g, outer);
        assert_eq!(fs.monitors.len(), 1);
        assert_eq!(fs.monitors[0].lock_depth, 1);
        assert!(!fs.monitors[0].relock);
    }

    /// Every deopt frame this tier lowers is FLAT — one scope, `caller: None`.
    ///
    /// That was already true of every compile before round 10 wave 9; what
    /// changed is that it is now true by construction rather than because the
    /// scope table nobody populated happened to be empty. `ir::InlineScopeTable`
    /// and `Lowerer::caller_chain_for` were retired together (the read side was
    /// wired to production and the write side had no caller outside
    /// `#[cfg(test)]`, which made a `rg` for the table report inlined scope
    /// support this tier has never had). The tests that exercised chain
    /// building went with them; what they were really covering — that an
    /// unresumable CALLER sinks the whole point, and that the walk is bounded —
    /// is `deopt.rs`'s own coverage of `frame_state_is_resumable`, which still
    /// walks `FrameState::caller` because the single-pass producer can build
    /// one.
    #[test]
    fn every_lowered_frame_is_flat() {
        let (mut g, _k) = scope_fixture_graph();
        g.safepoints
            .push(SafepointSnapshot::new(4, vec![NO_NODE], vec![], Vec::new()));
        let fs = resolve_snapshot(&g, 0);
        assert_eq!(fs.bci, 4);
        assert!(
            fs.caller.is_none(),
            "this tier publishes no caller chains, and says so in \
             `resolve_frame_state`"
        );
        assert!(crate::deopt::frame_state_is_resumable(&fs));
    }

    /// Every `DeoptimizationPoint` this file builds carries
    /// `ResumeSemantics::for_reason(reason)` — the convention, written down
    /// instead of re-derived by each consumer. `build_deopt_points` is the
    /// site under test; the two guard sites (`Op::Guard`, `emit_deopt_unless`)
    /// box their points into code and are covered by the source witness below.
    #[test]
    fn every_deopt_point_stamps_for_reason() {
        // iconst_5; iconst_3; iadd; iconst_2; imul; ireturn — two deopt points
        // (bci 2 and bci 4), the same fixture `test_deopt_points_resolve_*` uses.
        let code = [0x08, 0x06, 0x60, 0x05, 0x68, 0xac, 0, 0];
        let cm = compile_via_ir_no_opt(&code, 6, 0, 0);
        assert!(
            !cm.deopt_points.is_empty(),
            "fixture must emit deopt points"
        );
        for p in &cm.deopt_points {
            assert_eq!(
                p.semantics,
                ResumeSemantics::for_reason(p.reason),
                "deopt point at +{:#x} (reason {:?})",
                p.native_offset,
                p.reason
            );
            assert_eq!(
                p.semantics,
                ResumeSemantics::REEXECUTE,
                "a resume point before the bytecode re-executes it"
            );
        }
    }

    /// Source witness: no `DeoptimizationPoint` literal in this file may omit
    /// `semantics`. The two guard sites bake their point's *address* into
    /// emitted code and are never handed back to a test, so the field's
    /// presence there cannot be asserted behaviourally.
    #[test]
    fn every_deopt_point_literal_names_its_semantics() {
        let src = include_str!("ir_lower.rs");
        let literals = src.matches("DeoptimizationPoint {").count();
        let stamped = src.matches("semantics: ResumeSemantics::").count();
        assert!(
            stamped >= literals,
            "{literals} `DeoptimizationPoint` literal(s) but only {stamped} \
             `semantics:` initialiser(s) — a construction site is inferring \
             the re-execute convention again instead of recording it"
        );
    }

    // ── Linear-scan register residency ──────────────────────────────────

    /// `double f(double a) { return a * a * 2.0 + a; }` as a hand-built graph.
    ///
    /// Hand-built rather than compiled from `dload_0; dmul; …`, because the
    /// point of these tests is the ALLOCATION, and a bytecode-built graph
    /// carries a `SafepointSnapshot` per bci whose interaction with pinning is
    /// the subject of its own test below.
    fn fp_chain_graph() -> (Graph, Schedule) {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let a = graph.add(Op::Param(0), IrType::Double, vec![start], Some(0));
        let sq = graph.add(Op::Mul, IrType::Double, vec![a, a], Some(1));
        let two = graph.add(
            Op::ConstF(2.0f64.to_bits()),
            IrType::Double,
            vec![],
            Some(2),
        );
        let scaled = graph.add(Op::Mul, IrType::Double, vec![sq, two], Some(3));
        let sum = graph.add(Op::Add, IrType::Double, vec![scaled, a], Some(4));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum], Some(5));
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    #[test]
    fn linear_scan_promotes_fp_values_and_nothing_else() {
        let (graph, schedule) = fp_chain_graph();
        let plan = plan_slots(&graph, &schedule, None);
        verify_slot_colouring(&graph, &schedule, &plan).expect("the colouring verifies");

        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("an FP arithmetic chain has something to promote");

        assert!(residency.promoted > 0);
        assert_eq!(
            residency.demoted, 0,
            "the two liveness models must agree on a straight-line graph"
        );
        for (id, reg) in residency.reg_of.iter().enumerate() {
            let Some(reg) = reg else { continue };
            assert!(
                IR_LOWER_LS_XMMS.contains(reg),
                "n{id} was given xmm{reg}, which is outside the file this \
                 backend may clobber"
            );
            assert!(
                matches!(graph.nodes[id].ty, IrType::Float | IrType::Double),
                "n{id} is {:?} — only FP values may take a register here, which \
                 is what makes a reference at a safepoint unrepresentable",
                graph.nodes[id].ty
            );
        }
    }

    /// A value named by a deopt frame state must still be promotable, and its
    /// home word must still be written.
    ///
    /// This is the regression witness for the check that nearly made the whole
    /// wiring inert: `plan_slots` marks every deopt-named value
    /// `SlotClass::Pinned` (= never shares a frame word), and refusing to
    /// promote that class would have undone `release_deopt_pins` for exactly
    /// the values it exists to release. `IrBuilder` names essentially every
    /// value in some frame state, so this is not a corner case — it is the
    /// common case on real bytecode.
    #[test]
    fn a_deopt_named_value_is_still_promotable() {
        let (mut graph, _) = fp_chain_graph();
        // Name every FP value in a frame state, as `IrBuilder` would.
        let fp: Vec<NodeId> = graph
            .nodes
            .iter()
            .enumerate()
            .filter(|(_, n)| matches!(n.ty, IrType::Float | IrType::Double))
            .map(|(id, _)| id as NodeId)
            .collect();
        assert!(!fp.is_empty());
        graph.safepoints.push(SafepointSnapshot::new(
            3,
            fp.clone(),
            fp.clone(),
            Vec::new(),
        ));
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        // Precondition: the colourer really does pin them, so this test is
        // asserting against the state it means to.
        assert!(
            fp.iter()
                .any(|&id| plan.class[id as usize] == Some(SlotClass::Pinned)),
            "the colourer must pin a deopt-named value"
        );

        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect(
                "a deopt-named FP value must still be promotable — write-through \
                 keeps its home word correct at every bci",
            );
        assert!(residency.promoted > 0);
    }

    /// Round 11 wave 6 (`r11w5-ircore-back-edge-poll-evicts-fp-loop-values`):
    /// the `double` accumulator of a counted loop keeps ONE register across
    /// the back edge, and when that register is caller-saved the latch's poll
    /// reloads it. Before the fix the poll clobbered every caller-saved XMM,
    /// so on System V the accumulator was split at the edge and then refused
    /// (split residency is off), and every read in the loop went to memory.
    #[test]
    fn r11w6_a_carried_double_keeps_its_register_across_the_poll() {
        if !ir_poll_preserves_fp() {
            return;
        }
        // static double f(int n) { double s = 0; for (int i = 0; i < n; i++) s += i; return s; }
        //  0: dconst_0  1: dstore_1  2: iconst_0  3: istore_3
        //  4: iload_3   5: iload_0   6: if_icmpge 20
        //  9: dload_1  10: iload_3  11: i2d  12: dadd  13: dstore_1
        // 14: iinc 3,1  17: goto 4  20: dload_1  21: dreturn
        let code = [
            0x0e, 0x48, 0x03, 0x3e, 0x1d, 0x1a, 0xa2, 0x00, 0x0e, 0x27, 0x1d, 0x87, 0x63, 0x48,
            0x84, 0x03, 0x01, 0xa7, 0xff, 0xf3, 0x27, 0xaf, 0, 0,
        ];
        // Unoptimized, like the model test above: the back edge is the subject.
        let graph = IrBuilder::new(1, 4).build(&code, 22).expect("IR build");
        let schedule = ir_schedule::schedule(&graph);
        let plan = plan_slots(&graph, &schedule, None);
        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("the loop has something to promote");
        let phi = graph
            .nodes
            .iter()
            .position(|n| matches!(n.op, Op::Phi) && n.ty == IrType::Double)
            .expect("the accumulator is a double phi at the loop header");
        let reg = residency.reg_of[phi]
            .expect("the carried double is resident, not split at the back edge");
        if !IR_LOWER_SAVED_XMMS.contains(&reg) {
            assert!(
                residency
                    .poll_fp_reloads
                    .values()
                    .any(|ids| ids.contains(&(phi as NodeId))),
                "xmm{reg} is caller-saved, so the latch's poll must reload n{phi}: \
                 {:?}",
                residency.poll_fp_reloads
            );
        }
    }

    /// A RIP-relative displacement must resolve to the word it names.
    ///
    /// The one property both RIP emitters rest on, and the one whose failure
    /// is silent: x86-64 adds the displacement to the address of the NEXT
    /// instruction, so `here + len + disp` has to BE the target. A `len` that
    /// forgets the trailing immediate — 6 instead of 7 for the poll's `imm8`,
    /// or 6 instead of 10 for the guard's `imm32` — still assembles, still
    /// runs, and reads a neighbouring global forever.
    #[test]
    fn a_rip_displacement_resolves_to_its_target() {
        // Both encoded lengths in use: the poll's `F6 05 <disp32> <imm8>` and
        // the epoch guard's `81 3D <disp32> <imm32>`.
        for len in [7usize, 10] {
            for (here, target) in [
                (0x1_0000usize, 0x2_0000usize), // forward
                (0x2_0000, 0x1_0000),           // backward
                (0x1000, 0x1000),               // degenerate: names itself
                (0usize, i32::MAX as usize),    // the far positive edge
            ] {
                let disp = rip_disp32(here, len, target)
                    .unwrap_or_else(|| panic!("len={len} here={here:#x} should be in reach"));
                let next = here.wrapping_add(len);
                // Cast: two's-complement re-add of a signed displacement.
                let resolved = (next as i64).wrapping_add(disp as i64) as usize;
                assert_eq!(
                    resolved, target,
                    "len={len}: disp {disp} from {here:#x} resolved to {resolved:#x}, \
                     not {target:#x}",
                );
            }
        }
        // Out of ±2GB in both directions is refused, so the caller emits its
        // materialize-the-address fallback rather than a truncated disp32.
        assert!(rip_disp32(0, 10, u32::MAX as usize + 1).is_none());
        assert!(rip_disp32(usize::MAX / 2, 10, 0).is_none());
    }

    /// The GP file may not name a register this emitter uses for a FIXED
    /// purpose, on either ABI.
    ///
    /// The argument that RSI/RDI are promotable on Win64 rests entirely on
    /// them being neither an argument register nor a deopt-trampoline
    /// argument THERE, while being both on System V — a claim about six
    /// `#[cfg]`-selected constants that no compiler checks and that a reader
    /// has to assemble by hand. It is checked here instead, and it is checked
    /// on whichever platform the tests run on, so the arm that is wrong is the
    /// arm that fails.
    ///
    /// This is the invariant whose absence produced the two clobber gaps
    /// `docs/jit/linear-scan-wiring.md` records under "Calls the op model does
    /// not see": a register the allocator believed survived a call, destroyed
    /// by an emitter that never told the model it writes there.
    #[test]
    fn the_gp_file_names_no_register_this_emitter_reserves() {
        let mut reserved: Vec<(u8, &str)> = vec![
            (RAX, "RAX — the GP value tier"),
            (RCX, "RCX — the GP value tier"),
            (RDX, "RDX — IDIV and FCmp's SETcc"),
            (R10, "R10 — thread pointer / shadow-stack scratch"),
            (R11, "R11 — safepoint flag and epoch-guard scratch"),
            (DEOPT_ARG0, "DEOPT_ARG0"),
            (DEOPT_ARG1, "DEOPT_ARG1"),
            (DEOPT_ARG2, "DEOPT_ARG2"),
        ];
        for &r in CALL_ARG_REGS.iter() {
            reserved.push((r, "CALL_ARG_REGS"));
        }
        for &r in ENTRY_ABI_REGS.iter() {
            reserved.push((r, "ENTRY_ABI_REGS"));
        }
        for &f in IR_LOWER_LS_GPRS.iter() {
            if let Some((_, why)) = reserved.iter().find(|(r, _)| *r == f) {
                panic!(
                    "IR_GP_LINEAR_SCAN names r{f}, which this emitter reserves: {why}. \
                     A value promoted there is destroyed by an emission the \
                     MachineModel does not model as a clobber."
                );
            }
        }
        // …and the file is exactly as wide as the platform's callee-saved set
        // allows, so a future edit that adds a register has to come here.
        let expected = if cfg!(windows) { 7 } else { 5 };
        assert_eq!(
            IR_LOWER_LS_GPRS.len(),
            expected,
            "the GP file is {} on this platform, expected {expected}",
            IR_LOWER_LS_GPRS.len(),
        );
        // The narrow prefix the kill switch restores must be a PREFIX, or
        // `ir_gp_file()`'s slice is not the historical file.
        assert_eq!(
            &IR_LOWER_LS_GPRS[..crate::regalloc::xmm_roles::IR_GP_LINEAR_SCAN_NARROW],
            &[3u8, 12, 13, 14, 15][..],
            "the narrow prefix is no longer RBX + R12-R15",
        );
    }

    /// The GC cliff, stated as a property rather than a comment: no reference
    /// can be register-resident, so `emit_safepoint_map`'s frame-slot-only
    /// publication stays complete.
    #[test]
    fn a_reference_is_never_register_resident() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        // A live array reference and an int index, both genuinely read.
        let arr = graph.add(Op::Param(0), IrType::Ref, vec![start], Some(0));
        let idx = graph.add(Op::Param(1), IrType::Int, vec![start], Some(1));
        let elem = graph.add(
            Op::ArrayLoad(MemKind::Double),
            IrType::Double,
            vec![ctrl, mem, arr, idx],
            Some(2),
        );
        let doubled = graph.add(Op::Add, IrType::Double, vec![elem, elem], Some(3));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, doubled], Some(4));
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        let residency = plan_register_residency(&graph, &schedule, &plan)
            .expect("the allocation verifies")
            .expect("the FP values are promotable");
        assert_eq!(
            residency.reg_of[arr as usize], None,
            "a reference took a register; `emit_safepoint_map` publishes frame \
             slots only, so the collector could neither see nor relocate it"
        );
        assert_eq!(
            residency.reg_of[idx as usize], None,
            "an int took a register, but this file's register set is XMM-only"
        );
        // `elem`, not `doubled`: since `ir_residency_pays_enabled` a value read
        // ONCE is not promoted (its register cannot repay the prologue save it
        // costs), and `doubled` is read once, by the return. `elem` is read
        // twice — it is both inputs of the `Add` — so it is the FP value this
        // graph can promote, and asserting on it keeps the two checks above
        // non-vacuous for the reason they were written.
        assert!(
            residency.reg_of[elem as usize].is_some(),
            "the FP value must be promoted, or the two assertions above are \
             vacuous"
        );
        let _ = doubled;
    }

    /// The GP half of the same invariant, at its DEFAULT.
    ///
    /// The bank match in `plan_register_residency` names
    /// `a_reference_is_never_promoted_into_the_gp_file` as what pins it, and
    /// until 2026-09-09 the name pointed at nothing. It does now, and it pins
    /// the DEFAULT rather than an absolute: `CRATONVM_JIT_IR_REF_RESIDENCY=1`
    /// admits a reference deliberately, and `invalidate_ref_residency` is what
    /// it owes for that. With the flag at its default the answer must be the
    /// old one, whatever else has changed around it.
    #[test]
    fn a_reference_is_never_promoted_into_the_gp_file() {
        let mut graph = Graph::empty(0);
        let start = graph.add(Op::Start, IrType::Control, vec![], None);
        graph.entry = start;
        let ctrl = graph.add(Op::Proj(0), IrType::Control, vec![start], None);
        let mem = graph.add(Op::Proj(1), IrType::Memory, vec![start], None);
        let obj = graph.add(Op::Param(0), IrType::Ref, vec![start], Some(0));
        // Two reads of `obj`, so `ir_residency_pays_enabled` cannot decline it
        // for the unrelated reason that a once-read value never repays the
        // prologue save. Both are `Op::Cmp`, which reaches no helper — so
        // nothing but the type is keeping this value out of the file.
        let a = graph.add(
            Op::Cmp(crate::ir::CmpOp::Ne),
            IrType::Int,
            vec![obj, obj],
            Some(1),
        );
        let b = graph.add(
            Op::Cmp(crate::ir::CmpOp::Eq),
            IrType::Int,
            vec![obj, obj],
            Some(2),
        );
        let sum = graph.add(Op::Add, IrType::Int, vec![a, b], Some(3));
        let sum2 = graph.add(Op::Add, IrType::Int, vec![sum, sum], Some(4));
        graph.exit = graph.add(Op::Return, IrType::Void, vec![ctrl, sum2], Some(5));
        let _ = mem;
        let schedule = ir_schedule::schedule(&graph);

        let plan = plan_slots(&graph, &schedule, None);
        let Some(residency) =
            plan_register_residency(&graph, &schedule, &plan).expect("the allocation verifies")
        else {
            return;
        };
        assert_eq!(
            residency.gp_reg_of[obj as usize], None,
            "a reference took a GP register at the DEFAULT setting; the oop map \
             names frame slots only, so a collector could neither see nor \
             relocate it, and nothing invalidates the copy"
        );
        assert!(
            residency.gp_reg_of[sum as usize].is_some(),
            "the int must be promoted, or the assertion above is vacuous"
        );
    }

    // ── Phi residency ────────────────────────────────────────────────
    //
    // A loop counter and a loop accumulator are `Op::Phi` at the loop header.
    // While phis were excluded from the residency plan, the optimizing tier
    // read both out of a frame word on every iteration while the baseline tier
    // it supersedes coloured them into callee-saved GPRs -- the measured
    // inversion `docs/JIT_OPTIMIZATION.md` tabulates at 2.7-3.2x on array
    // kernels. These five tests pin what admitting them means, in the order the
    // obligations fall due: the population moves, the sub-flag still takes it
    // back, the GC obligation does not move, the parallel copy still leaves one
    // home and one register per phi, and the emitted code computes the same
    // answer either way.

    /// `int sum(int n){ int s=0; for(int i=0;i<n;i++) s+=i; return s; }`
    ///
    /// The smallest program with the shape this whole line of work is about:
    /// exactly two loop-carried values, and both of them a phi at the header.
    const COUNTED_LOOP_SUM: [u8; 23] = [
        0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x0d, 0x1b, 0x1c, 0x60, 0x3c, 0x84, 0x02,
        0x01, 0xa7, 0xff, 0xf4, 0x1b, 0xac, 0, 0,
    ];

    /// `int f(int n){ int a=1,b=2; for(int i=0;i<n;i++){ int t=a; a=b; b=t; } return a; }`
    ///
    /// The swap runs on the operand stack (`iload_1; iload_2; istore_1;
    /// istore_2`), so it needs no temporary local -- which makes the loop
    /// header's two phis each other's back-edge value, i.e. a copy CYCLE.
    /// `f(n)` is 2 for odd `n` and 1 for even `n`.
    const SWAP_LOOP: [u8; 25] = [
        0x04, 0x3c, // 0: iconst_1; istore_1        a = 1
        0x05, 0x3d, // 2: iconst_2; istore_2        b = 2
        0x03, 0x3e, // 4: iconst_0; istore_3        i = 0
        0x1d, 0x1a, // 6: iload_3; iload_0          loop header
        0xa2, 0x00, 0x0d, // 8: if_icmpge 21
        0x1b, 0x1c, // 11: iload_1; iload_2         push a, then b
        0x3c, 0x3d, // 13: istore_1; istore_2       a = b; b = old a
        0x84, 0x03, 0x01, // 15: iinc 3, 1
        0xa7, 0xff, 0xf4, // 18: goto 6
        0x1b, 0xac, // 21: iload_1; ireturn
        0, 0,
    ];

    /// Every VALUE-typed `Op::Phi` in `graph`, in node order.
    ///
    /// `is_value_ty` and not "every phi": `IrBuilder` builds a `Memory` phi at
    /// every merge it builds a value phi at, and a counted loop therefore has
    /// one at its header. It carries no runtime value (`RegClass::of` answers
    /// `None` for `Memory`), it is never a residency candidate, and
    /// `PhiCensus` excludes it for the same reason -- so a test that counted it
    /// would be asserting against a different set from the one the census
    /// reports.
    fn phis_of(graph: &Graph) -> Vec<usize> {
        (0..graph.nodes.len())
            .filter(|&id| matches!(graph.nodes[id].op, Op::Phi) && is_value_ty(graph.nodes[id].ty))
            .collect()
    }

    /// Run `f` with the phi sub-flag pinned, so no test in this group depends
    /// on the ambient environment or on whether the flag has been declared in
    /// this process yet.
    ///
    /// `with_thread_overrides` and not `std::env::set_var`: the flag is
    /// declared (`types/src/flag_groups.rs`, `jit/ir-phi-residency`), the
    /// override mechanism reaches it, and a process-wide env write would race
    /// every other test in this binary. `ir_phi_residency_enabled` deliberately
    /// does NOT cache its answer in a `OnceLock`, which is what makes a
    /// per-thread override work at all -- if someone adds that cache, these
    /// tests start reading whichever value the first test in the binary set.
    fn with_phi_residency<R>(on: bool, f: impl FnOnce() -> R) -> R {
        cratonvm_types::flags::with_thread_overrides(
            &[(
                "CRATONVM_JIT_IR_PHI_RESIDENCY",
                Some(if on { "1" } else { "0" }),
            )],
            f,
        )
    }

    /// The induction phi and the accumulator phi of a counted `int` loop are
    /// BOTH register-resident, and the census reports nothing refused.
    ///
    /// This is the claim the admission exists to make, on the smallest program
    /// that carries it. Asserted through `plan_register_residency`'s own output
    /// rather than through emitted bytes, because the plan names *which node*
    /// moved and a byte scan cannot -- "the body got shorter" is consistent
    /// with a transient being promoted and the loop counter still reloading
    /// from `[rbp-…]` every iteration, which is exactly the state this is meant
    /// to detect the return of. The bytes are the subject of
    /// `a_counted_loop_computes_the_same_sum_with_phi_residency_forced_on`.
    ///
    /// Unoptimized on purpose, like the other residency fixtures over this same
    /// bytecode: the optimizer is free to reshape a loop header, and the
    /// subject here is the allocator's verdict on the phis the builder emits.
    ///
    /// # Why `refused() == 0` is assertable rather than optimistic
    ///
    /// Every other value in this graph declines for a reason that has nothing
    /// to do with pressure: the `Op::Const`s are materialised as immediates by
    /// every reader (`skip_const`), and `Param(0)`, `s+i`, `i+1` and the
    /// compare are each read exactly once, which `ir_residency_pays_here`
    /// refuses (`skip_single_use`). The phis are exempt from that rule and are
    /// the only values left, so they compete with nobody for a file of five
    /// GPRs — and a failure here is a real regression rather than a heuristic
    /// that moved.
    #[test]
    fn a_counted_loops_induction_and_accumulator_phis_are_both_resident() {
        with_phi_residency(true, || {
            let graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = plan_register_residency(&graph, &schedule, &plan)
                .expect("the allocation verifies")
                .expect("a counted loop promotes something");

            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the fixture must carry an induction phi AND an accumulator phi; \
                 found {phis:?}"
            );
            for &id in &phis {
                assert_eq!(
                    graph.nodes[id].ty,
                    IrType::Int,
                    "n{id} is not the `int` phi this fixture is about"
                );
                assert!(
                    residency.gp_reg_of[id].is_some(),
                    "phi n{id} reached no register, so this loop still reads its \
                     carried value out of a frame word every iteration; census {:?}",
                    residency.phi_census
                );
            }
            assert_eq!(
                residency.phi_census.resident,
                phis.len(),
                "the census disagrees with the per-node assertions above: {:?}",
                residency.phi_census
            );
            assert_eq!(
                residency.phi_census.refused(),
                0,
                "nothing in this graph competes with the phis for a register; a \
                 refusal here is a regression, not a tuning decision: {:?}",
                residency.phi_census
            );
        });
    }

    /// With the sub-flag off, the SAME fixture refuses both phis and the census
    /// says why — which is the A/B the switch exists for.
    ///
    /// Without this the test above cannot distinguish "phi admission works"
    /// from "phis were always resident and the flag does nothing".
    #[test]
    fn the_phi_sub_flag_off_refuses_the_same_two_phis_and_names_the_cause() {
        with_phi_residency(false, || {
            let graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let phis = phis_of(&graph);
            // With the phis refused this graph may promote NOTHING at all,
            // which `plan_register_residency` reports as a declined plan
            // (`Ok(None)`). That is the same answer said louder, and it is what
            // the pre-admission emitter did on every counted loop — so the
            // assertions below are conditional on there being a plan to assert
            // against.
            if let Some(residency) =
                plan_register_residency(&graph, &schedule, &plan).expect("the allocation verifies")
            {
                assert_eq!(
                    residency.phi_census.disabled,
                    phis.len(),
                    "every phi must be refused, under `PhiRefusal::Disabled` and \
                     under no other cause: {:?}",
                    residency.phi_census
                );
                assert_eq!(
                    residency.phi_census.resident, 0,
                    "a phi took a register with the sub-flag off: {:?}",
                    residency.phi_census
                );
            }
        });
    }

    /// Round 13 wave 11 (lane callcost5, proposal CC4-3): the certain
    /// refusals are the refusal loop's own -- every constant and the once-read
    /// parameter, never a phi -- and with `CRATONVM_JIT_IR_RESIDENCY_PAYS=0`
    /// (which keeps every candidate) nothing in this reference-free graph is
    /// certain to be refused.
    #[test]
    fn r13w11_certain_refusals_are_the_refusal_loops_own() {
        let graph = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let live = crate::regalloc::build_live_model(&graph, &schedule);
        let refusals = |pays: &'static str| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_RESIDENCY_PAYS", Some(pays))],
                || ls_certain_refusals(&graph, &schedule, &live),
            )
        };
        let on = refusals("1");
        assert!(!on.is_empty(), "the constants and `Param(0)` are read at most once");
        for &id in &on {
            assert!(
                !matches!(graph.nodes[id as usize].op, Op::Phi),
                "phi n{id} was listed; its refusals are decided by the phi rules"
            );
        }
        for (id, node) in graph.nodes.iter().enumerate() {
            if matches!(node.op, Op::Const(_)) && live.wants_loc[id] {
                assert!(on.contains(&(id as NodeId)), "constant n{id} was not listed");
            }
        }
        assert!(
            refusals("0").is_empty(),
            "with the pays rule off only a reference is a certain refusal"
        );
    }

    /// Round 14 wave 1 (lane calls, proposal CC5-1): the call-crossing
    /// candidate is exactly "read once, `int`/`long`, one-`store_rax` home, an
    /// `Op::Call` strictly inside its range" -- a call AT the range's end is
    /// the value's own read as an argument, not a crossing -- and the kill
    /// switch empties it.
    #[test]
    fn r14w1_a_single_use_value_is_a_call_crossing_candidate_only_across_a_call() {
        let seed = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let seed_schedule = ir_schedule::schedule(&seed);
        // Any converged model, re-pointed at the hand-built graph below: the
        // predicate reads only `pos_of` and `range`.
        let mut live = crate::regalloc::build_live_model(&seed, &seed_schedule);
        let mut g = Graph::empty(6);
        let crossing = g.add(Op::Sub, IrType::Int, vec![], None); // n0
        let call = g.add(Op::Call { info_ptr: 0 }, IrType::Int, vec![], None); // n1
        let short = g.add(Op::Sub, IrType::Long, vec![], None); // n2
        let float = g.add(Op::Sub, IrType::Float, vec![], None); // n3
        let add = g.add(Op::Add, IrType::Int, vec![], None); // n4
        let range = |lo: usize, hi: usize| Some(crate::regalloc::PosRange { lo, hi });
        live.pos_of = vec![Some(1), Some(3), Some(2), Some(1), Some(5)];
        live.range = vec![range(1, 5), range(3, 5), range(2, 3), range(1, 5), range(5, 6)];
        let positions = |on: &'static str| {
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_RESIDENCY_CALL_CROSSING", Some(on))],
                || ls_call_positions(&g, &live),
            )
        };
        let call_pos = positions("1");
        assert_eq!(call_pos, vec![3]);
        assert!(positions("0").is_empty(), "the kill switch lists no call");
        let ask = |id: NodeId, uses: u32| {
            single_use_crosses_a_call(&g, &live, &call_pos, id as usize, uses)
        };
        assert!(ask(crossing, 1), "`n-2`-shaped value live across the call");
        assert!(!ask(crossing, 2), "a twice-read value is the pays rule's");
        assert!(!ask(short, 1), "the call at the range's end is its own read");
        assert!(!ask(float, 1), "FP values keep their own rules");
        assert!(!ask(add, 1), "no call inside the range");
        assert!(!ask(call, 1), "a call's own result starts at the call");
        assert!(
            !single_use_crosses_a_call(&g, &live, &[], crossing as usize, 1),
            "no listed call (the kill switch), no candidate"
        );
    }

    /// Round 13 wave 13 (lane jitfix;
    /// `r13w12-snapliv-loop-header-snapshot-doubles-as-the-osr-seed-list`): an
    /// OSR entry at the header of `COUNTED_LOOP_SUM` is admitted while the
    /// header snapshot names (seeds) every value the in-loop frame at bci 9
    /// names, and refused once one of them is not seeded -- the shape of a
    /// pruned dead header local whose pre-loop value an in-loop frame still
    /// names. A frame in a block the entry cannot reach is never asked.
    #[test]
    fn r13w13_an_osr_entry_is_refused_when_a_reachable_frame_names_a_skipped_value() {
        let graph = IrBuilder::new(1, 3)
            .build(&COUNTED_LOOP_SUM, 21)
            .expect("the counted loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let header = schedule
            .blocks
            .iter()
            .position(|b| {
                let ctrl = &graph.nodes[b.ctrl as usize];
                ctrl.bytecode_pc == Some(4) && matches!(ctrl.op, Op::Merge | Op::Region)
            })
            .expect("the loop header is a block");
        // Block 0 is the dominator tree's root, the method entry.
        let start = 0usize;
        assert_ne!(start, header, "the header is not the method entry");
        let flat_at = |bci: usize| {
            graph
                .safepoints
                .iter()
                .position(|sp| sp.bci == bci && !sp.is_splice_state())
                .expect("a snapshot at that bci")
        };
        let (at_header, in_loop) = (flat_at(4), flat_at(9));
        let named: std::collections::HashSet<NodeId> = graph.safepoints[at_header]
            .locals
            .iter()
            .copied()
            .filter(|&v| v != NO_NODE)
            .collect();
        let n = graph.safepoints[in_loop].locals[0];
        assert!(named.contains(&n), "`n` is named at the header");
        let ask = |sites: &[(usize, usize)], seeded: &std::collections::HashSet<NodeId>| {
            Lowerer::osr_entry_skipped_frame_value(
                &graph, &schedule, None, sites, header, header, false, seeded,
            )
        };
        let sites = [(header, in_loop)];
        assert_eq!(ask(&sites, &named), None, "every value the in-loop frame names is seeded");
        let mut pruned = named.clone();
        pruned.remove(&n);
        assert_eq!(
            ask(&sites, &pruned),
            Some(n),
            "`n` is defined before the header (or is its unseeded φ) and nothing seeds it"
        );
        assert_eq!(ask(&[], &pruned), None, "no frame, no refusal (the kill switch)");
        assert_eq!(
            ask(&[(start, in_loop)], &std::collections::HashSet::new()),
            None,
            "a frame in the method's entry block is not reachable from the header"
        );
    }

    /// Round 13 wave 13 (lane jitfix): the precise half of the same check. An
    /// entry at the INNER header of a nested loop reaches the outer body's
    /// frames only through the outer header, whose φs are then written by its
    /// back edge -- so a frame there naming the outer `s` φ, which the inner
    /// header does not name, must not refuse the entry (dominance alone would).
    ///
    /// `static int f(int n){ int s=0; for(int i=0;i<n;i++) for(int j=0;j<n;j++) s+=j; return s; }`
    #[test]
    fn r13w13_an_inner_loop_entry_keeps_an_outer_phi_its_frames_name() {
        //  0: iconst_0  1: istore_1  2: iconst_0  3: istore_2
        //  4: iload_2   5: iload_0   6: if_icmpge 32
        //  9: iconst_0 10: istore_3
        // 11: iload_3  12: iload_0  13: if_icmpge 26
        // 16: iload_1  17: iload_3  18: iadd  19: istore_1
        // 20: iinc 3,1 23: goto 11
        // 26: iinc 2,1 29: goto 4   32: iload_1 33: ireturn
        let code: [u8; 36] = [
            0x03, 0x3c, 0x03, 0x3d, 0x1c, 0x1a, 0xa2, 0x00, 0x1a, 0x03, 0x3e, 0x1d, 0x1a, 0xa2,
            0x00, 0x0d, 0x1b, 0x1d, 0x60, 0x3c, 0x84, 0x03, 0x01, 0xa7, 0xff, 0xf4, 0x84, 0x02,
            0x01, 0xa7, 0xff, 0xe7, 0x1b, 0xac, 0, 0,
        ];
        let graph = IrBuilder::new(1, 4)
            .build(&code, 34)
            .expect("the nested loop builds");
        let schedule = ir_schedule::schedule(&graph);
        let header_at = |pc: usize| {
            schedule
                .blocks
                .iter()
                .position(|b| {
                    let ctrl = &graph.nodes[b.ctrl as usize];
                    ctrl.bytecode_pc == Some(pc) && matches!(ctrl.op, Op::Merge | Op::Region)
                })
                .expect("a loop header block")
        };
        let inner = header_at(11);
        let flat_at = |bci: usize| {
            graph
                .safepoints
                .iter()
                .position(|sp| sp.bci == bci && !sp.is_splice_state())
                .expect("a snapshot at that bci")
        };
        let named: std::collections::HashSet<NodeId> = graph.safepoints[flat_at(11)]
            .locals
            .iter()
            .copied()
            .filter(|&v| v != NO_NODE)
            .collect();
        // The outer body, between the outer test and the inner header.
        let outer_body = schedule.dom.idom(inner).expect("the inner header has an idom");
        let at_9 = flat_at(9);
        let s_outer = graph.safepoints[at_9].locals[1];
        assert_eq!(graph.nodes[s_outer as usize].op, Op::Phi, "`s` at bci 9 is the outer φ");
        assert!(!named.contains(&s_outer), "the inner header names its own `s` φ instead");
        assert!(
            !schedule
                .dom
                .dominates(inner, schedule.node_to_block[s_outer as usize]),
            "the fast (dominance) path cannot accept the outer φ"
        );
        // Ask about `s_outer` alone: every other value the frame names counts
        // as seeded, whatever shape the builder gave it.
        let sp9 = &graph.safepoints[at_9];
        let mut seeded = named.clone();
        seeded.extend(
            sp9.locals
                .iter()
                .chain(sp9.stack.iter())
                .chain(sp9.monitors.iter())
                .copied()
                .filter(|&v| v != NO_NODE && v != s_outer),
        );
        let got = Lowerer::osr_entry_skipped_frame_value(
            &graph,
            &schedule,
            None,
            &[(outer_body, at_9)],
            inner,
            inner,
            false,
            &seeded,
        );
        assert_eq!(got, None, "the outer body is reached only through the outer header");
        // The same frame at a site the entered path reaches BEFORE it re-enters
        // the outer header (the inner header block itself) does refuse.
        let before_the_outer_header = Lowerer::osr_entry_skipped_frame_value(
            &graph,
            &schedule,
            None,
            &[(inner, at_9)],
            inner,
            inner,
            false,
            &seeded,
        );
        assert_eq!(before_the_outer_header, Some(s_outer));
    }

    /// Round 13 wave 11 (lane callcost5, proposal CC4-3): with the certain
    /// refusals out of the scan, the two phis of `COUNTED_LOOP_SUM` -- the only
    /// values the refusal loop keeps from it -- hold the FIRST two registers of
    /// the file. Before, the once-read `Param(0)` entered the scan first, took
    /// the first register, was refused, and left the phis one register higher.
    #[test]
    fn r13w11_the_kept_phis_take_the_first_registers_of_the_file() {
        cratonvm_types::flags::with_thread_overrides(
            &[
                ("CRATONVM_JIT_IR_PHI_RESIDENCY", Some("1")),
                ("CRATONVM_JIT_IR_LS_PREPIN_REFUSED", Some("1")),
            ],
            || {
                let graph = IrBuilder::new(1, 3)
                    .build(&COUNTED_LOOP_SUM, 21)
                    .expect("the counted loop builds");
                let schedule = ir_schedule::schedule(&graph);
                let plan = plan_slots(&graph, &schedule, None);
                let residency = plan_register_residency(&graph, &schedule, &plan)
                    .expect("the allocation verifies")
                    .expect("a counted loop promotes something");
                let mut regs: Vec<u8> = phis_of(&graph)
                    .iter()
                    .filter_map(|&id| residency.gp_reg_of[id])
                    .collect();
                regs.sort_unstable();
                // The loop header carries a phi per live local (`n`, `sum`,
                // `i`), so count what is resident rather than assume two.
                assert!(regs.len() >= 2, "the loop phis are resident: {regs:?}");
                let mut first: Vec<u8> = ir_gp_file()[..regs.len()].to_vec();
                first.sort_unstable();
                assert_eq!(
                    regs, first,
                    "the phis must hold the first registers of the file"
                );
            },
        );
    }

    /// A `Ref`-typed phi is refused **by type**, and the census names the type
    /// cause — whatever else is switched on.
    ///
    /// # The property, which is a GC one and not a tuning one
    ///
    /// A root walk reads a frame it did not stop, through RBP, and
    /// `OopMapEntry` names frame slots only. There is no register a collector
    /// could be told about, walk, or update on an evacuation. For ordinary
    /// values `CRATONVM_JIT_IR_REF_RESIDENCY` admits a reference anyway and
    /// pays for it with `invalidate_ref_residency`, whose audit is
    /// `lower_block`'s per-node loop. **A phi is published on the EDGE**, by
    /// `emit_phi_copies`, which is not inside that loop — so the refusal here
    /// is unconditional and does not consult that flag.
    ///
    /// Both arms are exercised, and the flag-on arm is the load-bearing one:
    /// with the flag off a `Ref` phi would fall out of the bank match anyway,
    /// so an assertion at the default alone would pass even if the refusal were
    /// deleted.
    ///
    /// # Why the phi is retyped by hand
    ///
    /// `IrBuilder::new` types every parameter `IrType::Int`, so no bytecode
    /// fixture this test could write produces a `Ref` phi at all. Retyping one
    /// node of the fixture above isolates the TYPE as the single difference
    /// from a graph that is known to promote both of its phis — which is
    /// exactly the comparison the assertion wants, and a stronger one than a
    /// separate hand-built graph could make.
    #[test]
    fn a_reference_typed_phi_is_refused_by_type_whatever_the_flags_say() {
        for ref_residency in ["0", "1"] {
            let mut graph = IrBuilder::new(1, 3)
                .build(&COUNTED_LOOP_SUM, 21)
                .expect("the counted loop builds");
            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the fixture must have a second phi, or the non-vacuity check \
                 below cannot be made"
            );
            let reference = phis[0];
            graph.nodes[reference].ty = IrType::Ref;

            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = cratonvm_types::flags::with_thread_overrides(
                &[
                    ("CRATONVM_JIT_IR_PHI_RESIDENCY", Some("1")),
                    ("CRATONVM_JIT_IR_REF_RESIDENCY", Some(ref_residency)),
                ],
                || {
                    plan_register_residency(&graph, &schedule, &plan)
                        .expect("the allocation verifies")
                        .expect("the remaining int phi is still promotable")
                },
            );

            assert_eq!(
                residency.gp_reg_of[reference], None,
                "a `Ref` phi took a GP register with \
                 CRATONVM_JIT_IR_REF_RESIDENCY={ref_residency}; the oop map names \
                 frame slots only, so a collector could neither see nor relocate it"
            );
            assert_eq!(
                residency.reg_of[reference], None,
                "and it must not be in the FP file either"
            );
            assert_eq!(
                residency.phi_census.ref_type, 1,
                "the census must name the TYPE cause, not fold the refusal into \
                 a generic one: {:?}",
                residency.phi_census
            );
            assert!(
                phis[1..]
                    .iter()
                    .any(|&id| residency.gp_reg_of[id].is_some()),
                "the `int` phi must still be resident, or the assertion above is \
                 vacuous: {:?}",
                residency.phi_census
            );
        }
    }

    /// A phi fed by a different value on each incoming edge still ends up with
    /// ONE home word and ONE register for its whole life.
    ///
    /// The parallel-copy question. `SWAP_LOOP`'s two carried phis are each
    /// other's back-edge value, so the edge's copies are a CYCLE (`a <- b,
    /// b <- a`) rather than a chain: emitted in gather order through one
    /// temporary, the second copy reads the word the first just overwrote and
    /// both locals end up holding `b`. `resolve_parallel_copy` orders them and
    /// breaks the cycle through `phi_copy_scratch_slot_off`; the register layer
    /// adds its own hazard on top (`emit_phi_copies`' `defer_publish`, written
    /// after `java.time.Duration.toNanos()` returned `seconds * 1e9 + seconds`
    /// on 198,356 calls in 200,000).
    ///
    /// What residency must not do to any of that is give one phi two homes or
    /// two registers. Both halves are asserted, plus the answer the loop
    /// actually computes, because a consistency property over an allocation
    /// nothing runs is worth very little.
    #[test]
    fn a_phi_whose_edges_disagree_keeps_one_home_and_one_register() {
        with_phi_residency(true, || {
            let graph = IrBuilder::new(1, 4)
                .build(&SWAP_LOOP, 23)
                .expect("the swap loop builds");
            let schedule = ir_schedule::schedule(&graph);
            let plan = plan_slots(&graph, &schedule, None);
            let residency = plan_register_residency(&graph, &schedule, &plan)
                .expect("the allocation verifies")
                .expect("the swap loop promotes something");

            let phis = phis_of(&graph);
            assert!(
                phis.len() >= 2,
                "the swap loop carries two locals: {phis:?}"
            );
            assert_eq!(
                residency.phi_census.disabled, 0,
                "the sub-flag is forced on for this test"
            );
            assert_eq!(residency.phi_census.ref_type, 0, "no reference here");

            // Every phi that took a register: one register, one home, and
            // neither shared with another phi that is live at the same header.
            let resident: Vec<usize> = phis
                .iter()
                .copied()
                .filter(|&id| residency.gp_reg_of[id].is_some())
                .collect();
            assert!(
                resident.len() >= 2,
                "at least the two swapped locals must be resident, or the \
                 distinctness assertions below are vacuous: {:?}",
                residency.phi_census
            );
            for (i, &a) in resident.iter().enumerate() {
                // `gp_reg_of` holds ONE register per node by construction, and
                // `plan_register_residency` refuses any value the scan gave
                // more than one segment -- so "one register for its whole life"
                // is structural here rather than something to count. What can
                // still go wrong is two phis sharing one, which is what the
                // inner loop checks.
                assert!(
                    residency.reg_of[a].is_none(),
                    "phi n{a} is in both banks at once"
                );
                let home_a = plan.node_color[a].expect("a phi always has a home word");
                for &b in &resident[i + 1..] {
                    assert_ne!(
                        residency.gp_reg_of[a], residency.gp_reg_of[b],
                        "phis n{a} and n{b} are both live at the loop header and \
                         were given the same register"
                    );
                    assert_ne!(
                        home_a,
                        plan.node_color[b].expect("a phi always has a home word"),
                        "phis n{a} and n{b} share a home word; the edge copies \
                         would write each other's value"
                    );
                }
            }

            // And it still swaps. `f(n)` is 2 for odd `n`, 1 for even.
            let _flag = LsForce::on();
            let cm = compile_via_ir(&SWAP_LOOP, 23, 1, 4).expect("the swap loop compiles");
            for (n, want) in [(0i64, 1i64), (1, 2), (2, 1), (3, 2), (10, 1), (11, 2)] {
                // SAFETY: one `int` argument, matching the fixture's signature;
                // the body calls no helper and runs on this thread.
                let got = unsafe { cm.try_call(&[n]).expect("call") };
                assert_eq!(got, want, "swap loop with n={n}");
            }
        });
    }

    /// End to end: the counted loop returns the right sum with phi residency
    /// forced ON, and the same sum with it forced OFF.
    ///
    /// The second arm is not decoration. Write-through means a resident phi is
    /// a CACHE — `emit_phi_copies` writes the home word at every incoming edge
    /// exactly as it always did and then moves the value into the register — so
    /// the two configurations must agree bit for bit on every input. A
    /// disagreement is a wrong-code bug in the publish, not a performance
    /// question, and `n=0` is in the list because a loop that never executes is
    /// the input on which a phi's register is read before any edge published
    /// it.
    #[test]
    fn a_counted_loop_computes_the_same_sum_with_phi_residency_forced_on() {
        let ns = [0i64, 1, 2, 5, 10, 100];
        let run = |on: bool| -> Vec<i64> {
            with_phi_residency(on, || {
                // The outer flag forced on rather than left alone: it is
                // default-ON today, so an unforced arm would be a different
                // configuration the day someone flips it.
                let _flag = LsForce::on();
                let cm = compile_via_ir(&COUNTED_LOOP_SUM, 21, 1, 3)
                    .expect("the counted loop compiles either way");
                ns.iter()
                    // SAFETY: one `int` argument, matching the fixture's
                    // signature; the body calls no helper and runs on this
                    // thread.
                    .map(|&n| unsafe { cm.try_call(&[n]).expect("call") })
                    .collect()
            })
        };
        let want: Vec<i64> = ns.iter().map(|&n| n * (n - 1) / 2).collect();
        let on = run(true);
        assert_eq!(on, want, "sum 0..n-1 with the loop phis in registers");
        let off = run(false);
        assert_eq!(
            on, off,
            "phi residency changed a computed value; write-through means the \
             register is a cache over a home word that is still written at \
             every incoming edge, so these must be identical"
        );
    }

    /// A value live across a helper call must not keep a caller-saved register.
    ///
    /// FP `Op::Rem` is the sharp case: it lowers to `CALL jit_drem`, and
    // ── Shadow instruction selection ─────────────────────────────────
    //
    // `docs/feature-designs/jit-machine-level-and-instruction-selection.md`,
    // increment 0.
    //
    // Increment 0's whole claim is "turning this on changes no emitted byte".
    // These are what hold it up. Note they drive the flag through
    // `flags::with_thread_overrides` and NOT `std::env::set_var`: the flag is
    // declared (`types/src/flag_groups.rs`, `jit/ir-isel-shadow`), so the
    // override mechanism reaches it, and a process-wide env write would race
    // every other test in this binary.

    /// Compile the same method with the shadow pass off and on, and compare
    /// **the emitted bytes**.
    ///
    /// Not "compare the result", not "both compiled" — the bytes. A shadow pass
    /// that perturbed slot numbering, buffer sizing or safepoint ids would still
    /// produce a working method and would still have broken the one property
    /// that makes increment 0 free.
    ///
    /// The exact edit that trips it: make the shadow block do anything to
    /// `lowerer` (allocate a slot, bump `next_sp_id`, touch the buffer).
    #[test]
    fn shadow_selection_changes_no_emitted_byte() {
        // Enabling the flag mutates the process-global shadow counters, so this
        // test owes the same lock as the two that read them.
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        // int f(int a, int b) { return (a + b) * a; } — arithmetic, one block,
        // the shape `isel`'s ALU and LEA rules actually fire on, so the shadow
        // pass has real work to do rather than trivially selecting nothing.
        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];

        let bytes = |on: bool| -> Vec<u8> {
            let value = if on { Some("1") } else { None };
            cratonvm_types::flags::with_thread_overrides(
                &[("CRATONVM_JIT_IR_ISEL_SHADOW", value)],
                || {
                    let cm = compile_via_ir(&code, 6, 2, 2).expect("compiles either way");
                    // SAFETY: the artifact is alive for the duration of this
                    // borrow, and `code_len` is what the emitter wrote.
                    unsafe {
                        std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len())
                            .to_vec()
                    }
                },
            )
        };

        let off = bytes(false);
        let on = bytes(true);
        assert!(
            !off.is_empty(),
            "precondition: the method compiled to bytes"
        );
        assert_eq!(
            off.len(),
            on.len(),
            "shadow selection changed the emitted length"
        );
        assert_eq!(off, on, "shadow selection changed the emitted bytes");
    }

    /// With the flag on, the pass actually ran — and covered every node.
    ///
    /// Without this the byte-identity test above passes vacuously: a shadow
    /// pass that never executes also changes no byte. So this asserts the
    /// counters moved, that `covers()` held on every block, and that the
    /// coverage figure is a real fraction rather than the "no nodes" zero.
    #[test]
    fn shadow_selection_runs_and_covers_every_scheduled_node() {
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        crate::x64::isel::reset_shadow_totals();

        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];
        cratonvm_types::flags::with_thread_overrides(
            &[("CRATONVM_JIT_IR_ISEL_SHADOW", Some("1"))],
            || {
                compile_via_ir(&code, 6, 2, 2).expect("compiles");
            },
        );

        let (methods, stats) = crate::x64::isel::shadow_totals();
        assert_eq!(methods, 1, "exactly one method should have been shadowed");
        assert!(stats.blocks > 0, "no blocks were selected");
        assert!(
            stats.nodes > 0,
            "no data nodes were offered to the selector"
        );
        assert!(stats.tiles >= stats.blocks, "every block yields >= 1 tile");
        assert_eq!(
            stats.coverage_failures, 0,
            "`BlockSelection::covers` failed on {} block(s) — that is an `isel` \
             bug, not a measurement",
            stats.coverage_failures
        );
        assert!(
            stats.matched_tiles > 0,
            "no rule fired on `(a + b) * a`; the corpus this test uses was \
             chosen because the ALU rules match it, so zero means the selector \
             regressed, not that the method is unusual"
        );
        let pct = stats.coverage_pct();
        assert!(
            pct > 0.0 && pct <= 100.0,
            "coverage {pct} is not a fraction"
        );
    }

    /// With the flag OFF — the default, and every compile today — the pass does
    /// not run at all.
    ///
    /// The counter, not the bytes: "changed no byte" and "did not execute" are
    /// different claims and increment 0 makes both.
    #[test]
    fn shadow_selection_is_off_by_default() {
        let _guard = crate::x64::isel::SHADOW_TEST_LOCK.lock();
        crate::x64::isel::reset_shadow_totals();

        let code = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];
        compile_via_ir(&code, 6, 2, 2).expect("compiles");

        let (methods, stats) = crate::x64::isel::shadow_totals();
        assert_eq!(methods, 0, "the shadow pass ran without being asked");
        assert_eq!(stats, crate::x64::isel::ShadowStats::default());
    }

    /// The flag is DECLARED, so `-XX:` and the test override mechanism reach it.
    ///
    /// Rule 4 of `docs/known-issues/c2/README.md`: an undeclared flag is
    /// invisible to both, and the declaration sweep has already had to be re-run
    /// once because a flag was added 21 minutes after it closed at zero. The
    /// two tests above would still pass with an undeclared flag — `runtime_var`
    /// falls through to a live `std::env` read — so this checks the property
    /// they cannot.
    #[test]
    fn the_shadow_flag_is_declared() {
        let declared: Vec<&str> = cratonvm_types::flag_groups::INVENTORY
            .iter()
            .filter_map(|e| e.on_key)
            .collect();
        assert!(
            declared.contains(&"CRATONVM_JIT_IR_ISEL_SHADOW"),
            "`CRATONVM_JIT_IR_ISEL_SHADOW` is not in `types/src/flag_groups.rs`"
        );
        assert!(
            declared.contains(&"CRATONVM_DBG_IR_ISEL"),
            "`CRATONVM_DBG_IR_ISEL` is not in `types/src/flag_groups.rs`"
        );
        // Increment 2's two flags, same rule.
        for key in ["CRATONVM_JIT_IR_ISEL_EMIT", "CRATONVM_JIT_IR_ISEL_VERIFY"] {
            assert!(
                declared.contains(&key),
                "`{key}` is not in `types/src/flag_groups.rs`"
            );
        }
    }

    // ── Increment 2: the machine list emits ───────────────────────────
    //
    // The oracle is byte equality on a corpus: compile a method both ways and
    // compare the emitted bytes. Every `PATTERNS` row carries that property per
    // row — it names the hand-written emitter it reproduces — and these are the
    // same check at method scale.

    /// `int f(int a, int b) { return (a + b) * a; }` — `iload_0; iload_1;
    /// iadd; iload_0; imul; ireturn`, and the length is **6**, the whole
    /// method. (The neighbouring shadow tests pass 4, which truncates after the
    /// `iload_0` and leaves the multiply out of the graph entirely; that costs
    /// them nothing because they only count, but it would make every assertion
    /// below about `Rule::AluReg` vacuous.)
    #[cfg(test)]
    const MIR_ALU_CODE: [u8; 8] = [0x1a, 0x1b, 0x60, 0x1a, 0x68, 0xac, 0, 0];

    /// [`MIR_ALU_CODE`] as a graph and a schedule, for the tests that work on
    /// the machine list directly instead of on the emitted bytes.
    #[cfg(test)]
    fn mir_alu_graph() -> (Graph, Schedule) {
        let builder = IrBuilder::new(2, 2);
        let graph = builder.build(&MIR_ALU_CODE, 6).expect("build");
        let schedule = ir_schedule::schedule(&graph);
        (graph, schedule)
    }

    #[cfg(test)]
    fn mir_emitted_bytes(mode: Option<MirMode>) -> Vec<u8> {
        // Both arms with the register cache OFF. Production makes the two
        // mutually exclusive, so a comparison that left it on for the no-mode
        // arm and off for the MIR arm would measure residency rather than the
        // selector -- and would report the selector as having changed bytes it
        // never touched.
        let _ls = LsForce::off();
        // Same argument for the two emission changes that landed 2026-09-05.
        // Both are ON by default now and neither is known to the tiler, so a
        // comparison that left them on for the no-mode arm would measure THEM
        // rather than the selector -- and would report the selector as having
        // changed bytes it never touched.
        let _carry = CarryForce::off();
        let _imm = AluImmForce::off();
        let _force = mode.map(MirForce::set);
        let cm = compile_via_ir(&MIR_ALU_CODE, 6, 2, 2).expect("compiles");
        // SAFETY: the artifact is alive for the duration of this borrow, and
        // `code_len` is what the emitter wrote.
        unsafe { std::slice::from_raw_parts(cm.entry_ptr() as *const u8, cm.code_len()).to_vec() }
    }

    /// The level-2 encoder reproduces the per-opcode arms **byte for byte**.
    ///
    /// This is increment 2's whole deliverable. `Rule::AluReg`'s seven rows are
    /// anchored to the exact literals `lower_data_node` emits — `01 C8`,
    /// `29 C8`, `0F AF C1`, `48 21 C8` and so on — and the frame-homed
    /// allocation the encoder assumes IS this backend's allocation, so equality
    /// is reachable rather than approximate.
    ///
    /// The exact edit that trips it: change any of those literals in
    /// `lower_data_node`, or change `enc_frame_load`'s displacement-form choice
    /// on one side only.
    #[test]
    fn the_machine_level_emits_the_same_bytes_as_the_per_opcode_arms() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let off = mir_emitted_bytes(None);
        let emit = mir_emitted_bytes(Some(MirMode::Emit));
        assert!(
            !off.is_empty(),
            "precondition: the method compiled to bytes"
        );
        assert_eq!(off, emit, "the level-2 encoder changed the emitted bytes");

        // Not vacuous: tiles were actually taken. A path that declined every
        // tile would satisfy the equality above trivially.
        let (methods, tiles, mismatches) = mir_totals::read();
        assert_eq!(
            methods, 1,
            "exactly one method went through the machine list"
        );
        assert!(
            tiles >= 2,
            "`(a + b) * a` has two AluReg roots; the encoder took {tiles}"
        );
        assert_eq!(mismatches, 0);
    }

    // ── Increment 2: the allocation over the tile list ───────────────

    /// The machine list gets an allocation, and `verify_allocation` accepts it.
    ///
    /// The point of the increment is *which* verifier: the allocator's own,
    /// unmodified. A second checker written for the level-2 form would be a
    /// second model of the same program, and the whole reason the frame-homed
    /// allocation is describable at all is that `Allocation` already has a
    /// shape for "everything in its home word".
    ///
    /// Not vacuous by construction — `located` is asserted non-zero, which is
    /// the difference between "verified" and "there was nothing to verify".
    #[test]
    fn the_machine_list_carries_an_allocation_that_verify_allocation_accepts() {
        let (graph, schedule) = mir_alu_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let mir = build_mir_plan(&graph, &schedule).expect("selection covers every block");

        let verdict =
            verify_mir_allocation(&graph, &schedule, &plan, &mir).expect("the allocation verifies");
        match verdict {
            MirAllocVerdict::Verified { located, .. } => assert!(
                located >= 3,
                "`(a + b) * a` has two params and two results; the allocation \
                 located only {located} values, so this test is close to vacuous"
            ),
            other => panic!("expected a verified allocation, got {other:?}"),
        }
    }

    /// The verifier is REACHED, and it can say no.
    ///
    /// A verification step nothing can fail is indistinguishable from no
    /// verification step. This one runs over an allocation whose every segment
    /// is `reg: None` — the arm where most of `verify_allocation`'s rules go
    /// quiet — so what gets injected against is the rule that does *not* go
    /// quiet: two values whose live ranges overlap, pointed at one home word.
    ///
    /// The violation is planted in the `SlotPlan`, UPSTREAM of
    /// `verify_mir_allocation`, so the whole path is under test rather than
    /// `verify_allocation` in isolation. Only the colour's *value* changes,
    /// never its `Some`-ness, so the liveness-agreement precheck still passes
    /// and the rejection can only have come from the verifier.
    ///
    /// The exact edit that trips it: drop the `verify_allocation` call from
    /// `verify_mir_allocation`.
    #[test]
    fn an_aliased_home_word_is_rejected_by_the_allocation_verifier() {
        use crate::regalloc::build_live_model;

        let (graph, schedule) = mir_alu_graph();
        let plan = plan_slots(&graph, &schedule, None);
        let mir = build_mir_plan(&graph, &schedule).expect("selection covers every block");
        // Precondition: unaliased, this graph verifies. Without it a broken
        // fixture would make the rejection below meaningless.
        assert!(
            matches!(
                verify_mir_allocation(&graph, &schedule, &plan, &mir),
                Ok(MirAllocVerdict::Verified { .. })
            ),
            "the fixture must verify BEFORE the injection"
        );

        // Two values genuinely live at the same position, so the rejection is
        // the aliasing rule and not some other one.
        let live = build_live_model(&graph, &schedule);
        let located: Vec<usize> = (0..graph.nodes.len())
            .filter(|&id| plan.node_color.get(id).copied().flatten().is_some())
            .filter(|&id| live.range.get(id).copied().flatten().is_some())
            .collect();
        let mut pair = None;
        'outer: for (i, &a) in located.iter().enumerate() {
            let ra = live.range[a].expect("located");
            for &b in &located[i + 1..] {
                let rb = live.range[b].expect("located");
                if ra.lo <= rb.hi && rb.lo <= ra.hi {
                    pair = Some((a, b));
                    break 'outer;
                }
            }
        }
        let (a, b) = pair.expect("this graph has two simultaneously live values");

        let mut aliased = plan_slots(&graph, &schedule, None);
        aliased.node_color[b] = aliased.node_color[a];
        let err = verify_mir_allocation(&graph, &schedule, &aliased, &mir)
            .expect_err("two values live together in one home word");
        let text = format!("{err:?}");
        assert!(
            text.contains("home word") || text.contains("slot pools"),
            "rejected for the wrong reason: {text}"
        );
    }

    /// Emit mode refuses a compile whose allocation the verifier rejected;
    /// verify mode does not.
    ///
    /// Asserted as a property of the two modes rather than by forcing a
    /// rejection, because the only way to force one on a real graph is to
    /// introduce the compiler bug it exists to catch. What is checkable without
    /// that is the ASYMMETRY, and the asymmetry is the whole policy: verify
    /// mode's contract is that it changes no emitted byte, which it would break
    /// by also changing which methods compile.
    #[test]
    fn verify_mode_records_the_allocation_and_emit_mode_stakes_the_compile_on_it() {
        let _guard = mir_totals::TEST_LOCK.lock();

        for mode in [MirMode::Verify, MirMode::Emit] {
            mir_totals::reset();
            let bytes = mir_emitted_bytes(Some(mode));
            assert!(!bytes.is_empty(), "{mode:?} must still produce a body");
            let (verified, values, vacuous, indescribable, rejected) = mir_totals::read_alloc();
            assert_eq!(rejected, 0, "{mode:?}: the allocation was rejected");
            assert_eq!(
                verified, 1,
                "{mode:?}: one method, one verdict — got verified={verified} \
                 nothing_to_cover={vacuous} indescribable={indescribable}"
            );
            assert!(
                values > 0,
                "{mode:?}: the verdict was `Verified` over zero values, which \
                 is `NothingToCover` wearing the wrong label"
            );
        }
    }

    /// Verify mode is the same oracle without the risk: the per-opcode arms
    /// still emit, and the encoder's answer is compared against what they wrote.
    #[test]
    fn verify_mode_agrees_and_changes_no_emitted_byte() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let off = mir_emitted_bytes(None);
        let verify = mir_emitted_bytes(Some(MirMode::Verify));
        assert_eq!(off, verify, "verify mode must not change an emitted byte");

        let (methods, tiles, mismatches) = mir_totals::read();
        assert_eq!(methods, 1);
        assert!(tiles >= 2, "verify mode checked {tiles} tiles");
        assert_eq!(mismatches, 0, "the two paths disagreed");
    }

    /// The oracle can FAIL. Injected, because a guard nobody has seen fail is a
    /// guard of unknown polarity — and this one's whole job is to be believed
    /// when it stays silent over a corpus.
    ///
    /// Both halves matter: verify mode must *count* the disagreement, and the
    /// compile must be *refused* rather than shipped with a body nothing
    /// checked. Increment 2 is where fail-closed returns.
    #[test]
    fn an_injected_wrong_byte_is_caught_by_the_oracle() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        let _inject = MirInject::on();
        let _force = MirForce::set(MirMode::Verify);
        let refused = compile_via_ir(&MIR_ALU_CODE, 6, 2, 2);
        assert!(
            refused.is_none(),
            "a disagreeing method must lose its optimized body, not ship it"
        );
        let (_, _, mismatches) = mir_totals::read();
        assert!(
            mismatches >= 1,
            "the byte-equality oracle did not notice a corrupted tile"
        );
    }

    /// With both flags off — the default, and every compile today — the machine
    /// list is not built at all.
    ///
    /// The counter, not the bytes: "changed no byte" and "did not execute" are
    /// different claims, and the equality tests above would pass vacuously on a
    /// path that never ran.
    #[test]
    fn the_machine_level_is_off_by_default() {
        let _guard = mir_totals::TEST_LOCK.lock();
        mir_totals::reset();

        compile_via_ir(&MIR_ALU_CODE, 6, 2, 2).expect("compiles");

        assert_eq!(
            mir_totals::read(),
            (0, 0, 0),
            "the machine list was built without being asked"
        );
    }

    /// A tile that absorbed another node must never reach the encoder.
    ///
    /// `Rule::AluReg` covers exactly its own root, so this guard is insurance
    /// against a future rule rather than a live filter — which is precisely why
    /// it is tested directly instead of through a compile. Driven through one it
    /// would be vacuous: the rules that DO absorb (`Lea`, `AluImm`, the fused
    /// branches) are already refused a line earlier, by rule.
    ///
    /// What it prevents: the caller skips every node a tile covers, so a tile
    /// that absorbed a node the encoder does not actually fold leaves that node
    /// computed nowhere. That is the same failure `BlockSelection::covers`
    /// exists to make unrepresentable, one level lower down.
    ///
    /// The exact edit that trips it: delete the `covered.as_slice() == [id]`
    /// clause from `mir_tile_is_emittable`.
    #[test]
    fn the_encoder_refuses_a_tile_that_absorbed_another_node() {
        use crate::x64::isel::{MInst, Op as SelOp, Rule, Tile, Ty};

        let alu = |dst: NodeId, lhs: NodeId, rhs: NodeId| MInst::AluRR {
            op: SelOp::Add,
            ty: Ty::I32,
            dst,
            lhs,
            rhs,
        };
        // The shape the encoder handles: one root, nothing absorbed.
        let plain = Tile::for_test(5, vec![5], vec![alu(5, 3, 4)], Rule::AluReg);
        assert!(mir_tile_is_emittable(&plain, 5));

        // The same tile, having absorbed node 4.
        let absorbing = Tile::for_test(5, vec![5, 4], vec![alu(5, 3, 4)], Rule::AluReg);
        assert!(
            !mir_tile_is_emittable(&absorbing, 5),
            "a tile that absorbed node 4 would leave it computed nowhere"
        );

        // And a rule the encoder has not been proved byte-equal for, however
        // ordinary its cover list.
        let other = Tile::for_test(5, vec![5], vec![alu(5, 3, 4)], Rule::AluImm);
        assert!(!mir_tile_is_emittable(&other, 5));
        // A tile rooted somewhere else is never this node's answer.
        assert!(!mir_tile_is_emittable(&plain, 4));
    }

    /// The two frame-access encoders are the ONE producer of these bytes.
    ///
    /// `load_to_rax` / `load_to_rcx` / `store_rax` delegate to them, so the
    /// level-2 encoder and the per-opcode arms cannot drift apart. This pins the
    /// literals those methods used to hold inline, in both displacement forms.
    #[test]
    fn the_frame_access_encoders_reproduce_the_inline_literals() {
        let bytes = |f: fn(u8, i32, &mut FrameAccess), reg: u8, off: i32| -> Vec<u8> {
            let mut a = FrameAccess::new();
            f(reg, off, &mut a);
            a.as_slice().to_vec()
        };
        // disp8: mod=01, r/m=RBP(101).
        assert_eq!(bytes(enc_frame_load, RAX, 8), vec![0x48, 0x8B, 0x45, 0xF8]);
        assert_eq!(bytes(enc_frame_load, RCX, 8), vec![0x48, 0x8B, 0x4D, 0xF8]);
        assert_eq!(bytes(enc_frame_store, RAX, 8), vec![0x48, 0x89, 0x45, 0xF8]);
        // disp32: mod=10.
        let mut want = vec![0x48u8, 0x8B, 0x85];
        want.extend_from_slice(&(-4096i32).to_le_bytes());
        assert_eq!(bytes(enc_frame_load, RAX, 4096), want);
        let mut want = vec![0x48u8, 0x89, 0x85];
        want.extend_from_slice(&(-4096i32).to_le_bytes());
        assert_eq!(bytes(enc_frame_store, RAX, 4096), want);
        // A register these encodings cannot express is a refusal, not a
        // silently truncated `reg & 7` — which would encode R8 as RAX.
        assert!(bytes(enc_frame_load, 8, 8).is_empty());
        assert!(bytes(enc_frame_store, 8, 8).is_empty());
    }

    // ── The three `ir::Op` enumerations, checked against each other ──
    //
    // `docs/feature-designs/jit-machine-level-and-instruction-selection.md`,
    // "The cheap alternative". One set of operations is enumerated
    // in three places, in two different vocabularies:
    //
    //   1. `lower_data_node`'s match arms          — 48 of 53 `ir::Op` variants
    //   2. `op_defines_result_slot`                — 37
    //   3. `ir::ir_compatible`                     — in the BYTECODE's
    //      vocabulary (`scan.anewarray_ops`, …), not `Op`'s
    //
    // (1) and (2) are checked here. (3) cannot be: it answers a different
    // question about a different type, which is precisely why the catch-all's
    // old claim — "bail in `ir_compatible` prevents reaching here" — was not
    // checkable where it was written, and why `lower_data_node`'s final arm now
    // refuses instead of asserting.
    //
    // WHAT TRIPS THESE (rule 5 of `docs/known-issues/c2/README.md`: write down
    // the exact edit, or the test is decoration):
    //
    //   * Add a variant to `ir::Op`. `declared_lowering` is an exhaustive match
    //     with NO wildcard arm, so the crate stops compiling until the author
    //     classifies it. That is the primary forcing function and it fires at
    //     build time, not test time.
    //   * Classify it `Lowered*` but forget the `lower_data_node` arm.
    //     `every_ir_op_is_lowered_or_declared_unlowerable` fails: the source
    //     scan finds no arm naming it.
    //   * Add the arm but forget `op_defines_result_slot`.
    //     `op_defines_result_slot_matches_the_arms_that_allocate` fails.
    //   * Remove a variant from `ir::Op` and leave it here.
    //     `the_op_representatives_cover_every_declared_variant` fails.
    //
    // All three scans read the source with `include_str!`, the same idiom as
    // `the_register_read_path_is_gated_on_publication` above.

    /// What `lower_data_node` does with one `ir::Op`.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum OpLowering {
        /// Has an arm, and that arm allocates a result slot. Must therefore
        /// also be named by `op_defines_result_slot`.
        LoweredValue,
        /// Has an arm, but produces no value anyone can read: a control node, a
        /// memory-only effect, or a terminator handled by `lower_terminator`.
        LoweredEffect,
        /// No arm. Reaching `lower_data_node` with one refuses the compile.
        Unlowerable,
    }

    /// The variants with no lowering arm — the explicit list the catch-all
    /// used to leave implicit.
    ///
    /// Each is unreachable from a real compile today (see the catch-all's own
    /// comment for the evidence per op). This is a statement about the tree,
    /// not a permission: a variant added here is a variant the optimizing tier
    /// silently declines to compile, and the edit should be visible in review.
    ///
    /// `NewArray` left this list in cov-06: it now has a real arm below (the
    /// shared `emit_new_array_stub`, mirroring `Op::New`).
    const UNLOWERABLE: [&str; 3] = ["I2B", "I2C", "I2S"];

    /// **Exhaustive on purpose — do not add a wildcard arm.**
    ///
    /// This match is the forcing function. A new `ir::Op` variant makes the
    /// crate fail to compile here, which is the only mechanism that catches the
    /// author *before* the tests run.
    fn declared_lowering(op: &Op) -> OpLowering {
        use OpLowering::{LoweredEffect, LoweredValue, Unlowerable};
        match op {
            // Control and terminator nodes: an arm exists and does nothing,
            // because `lower_terminator` owns them.
            Op::Start
            | Op::Return
            | Op::Throw
            | Op::If
            | Op::Switch { .. }
            | Op::Merge
            | Op::Region
            | Op::Proj(_)
            | Op::Dead => LoweredEffect,
            // Values.
            Op::Const(_)
            | Op::ConstF(_)
            | Op::Param(_)
            | Op::Phi
            | Op::ScalarIntrinsic(_)
            | Op::Add
            | Op::Sub
            | Op::Mul
            | Op::Div
            | Op::Rem
            | Op::Neg
            | Op::And
            | Op::Or
            | Op::Xor
            | Op::Shl
            | Op::Shr
            | Op::UShr
            | Op::Cmp(_)
            | Op::LCmp
            | Op::FCmp { .. }
            | Op::I2L
            | Op::L2I
            | Op::I2F
            | Op::I2D
            | Op::L2F
            | Op::L2D
            | Op::F2I
            | Op::F2L
            | Op::F2D
            | Op::D2I
            | Op::D2L
            | Op::D2F
            | Op::Load(_)
            | Op::ArrayLoad(_)
            | Op::ArrayStore(_)
            | Op::ArrayLength
            | Op::New { .. }
            | Op::NewArray { .. }
            | Op::Call { .. }
            | Op::ConstString { .. }
            | Op::ConstClass { .. }
            | Op::LoadStatic { .. }
            | Op::LambdaIntToDouble
            | Op::InstanceOf { .. }
            | Op::Unbox { .. }
            | Op::ExactClassIs { .. }
            | Op::OsrEntryFlag { .. }
            | Op::OsrLocal(_)
            | Op::CheckCast { .. } => LoweredValue,
            // Effects with an arm but no result slot.
            Op::Store(_)
            | Op::StoreStatic { .. }
            | Op::MonitorEnter
            | Op::MonitorExit
            | Op::OsrMemory
            | Op::Guard { .. } => LoweredEffect,
            // No arm. Keep in step with `UNLOWERABLE`; the tests check it.
            Op::I2B | Op::I2C | Op::I2S => Unlowerable,
        }
    }

